    private const string TYPED_NARROW_GROUPS_ASSEMBLY_SOURCE = """
        windvale-assembly 1
        symbol export function Main in .text
        section code .text align 16
        define Main
        add_i8 al -128
        subtract_i8 cl 127
        and_i8 dl -1
        or_i8 bl 1
        xor_i8 spl 2
        compare_i8 r8b 3
        test_i8 r15b -128
        add_i16 ax -32768
        subtract_i16 cx 32767
        and_i16 dx -1
        or_i16 bx 1
        xor_i16 sp 2
        compare_i16 r8w 3
        test_i16 r15w -32768
        rotate_left al 0
        rotate_right spl 7
        shift_left r8b 1
        shift_right r15b 6
        shift_right_signed cl 7
        rotate_left ax 0
        rotate_right sp 15
        shift_left r8w 1
        shift_right r15w 14
        shift_right_signed cx 15
        return
        end define
        end section
        """;

