        static ImmutableArray<byte> Replaceˉu32(
            ImmutableArray<byte> input,
            int offset,
            uint value)
        {
            var Result = input.ToArray();
            BinaryPrimitives.WriteUInt32LittleEndian(Result.AsSpan(offset), value);
            return Result.ToImmutableArray();
        }

        static void Expectˉrequestˉfailure(
            ImmutableArray<byte> request,
            Consoleˉapplicationˉplanˉstatus status,
            uint failureˉoffset)
        {
            var Response = Consoleˉapplicationˉlayout.Evaluateˉrequest(request);
            Equal(Consoleˉapplicationˉlayout.RESPONSE_BYTES, Response.Length);
            Equal(
                Consoleˉapplicationˉlayout.RESPONSE_MAGIC,
                BinaryPrimitives.ReadUInt32LittleEndian(Response.AsSpan()));
            Equal(
                Consoleˉapplicationˉlayout.FORMAT_VERSION,
                BinaryPrimitives.ReadUInt32LittleEndian(Response.AsSpan()[4..]));
            Equal(
                (uint)Consoleˉapplicationˉlayout.RESPONSE_BYTES,
                BinaryPrimitives.ReadUInt32LittleEndian(Response.AsSpan()[8..]));
            Equal(
                (uint)status,
                BinaryPrimitives.ReadUInt32LittleEndian(Response.AsSpan()[12..]));
            Equal(
                failureˉoffset,
                BinaryPrimitives.ReadUInt32LittleEndian(Response.AsSpan()[16..]));
            for (var Offset = 20; Offset < Consoleˉapplicationˉlayout.RESPONSE_BYTES; Offset += 4)
            {
                Equal(0u, BinaryPrimitives.ReadUInt32LittleEndian(Response.AsSpan()[Offset..]));
            }
        }

        static void Expectˉresponseˉfailure(
            ImmutableArray<byte> response,
            string description)
        {
            var Rejected = false;
            try
            {
                _ = Consoleˉapplicationˉlayout.Verifyˉresponse(
                    Consoleˉapplicationˉtarget.Windowsˉx64,
                    nativeˉimageˉbytes: 5,
                    nativeˉentryˉoffset: 2,
                    response);
            }
            catch (Consoleˉapplicationˉplanˉexception)
            {
                Rejected = true;
            }
            True(Rejected, $"The {description} console-application plan was accepted.");
        }

        var Request = Consoleˉapplicationˉlayout.Buildˉrequest(
            Consoleˉapplicationˉtarget.Windowsˉx64,
            nativeˉimageˉbytes: 5,
            nativeˉentryˉoffset: 2);
        var Response = Consoleˉapplicationˉlayout.Evaluateˉrequest(Request);
        Sequenceˉequal(Response, Consoleˉapplicationˉlayout.Evaluateˉrequest(Request));
        Equal(
            Windows,
            Consoleˉapplicationˉlayout.Verifyˉresponse(
                Consoleˉapplicationˉtarget.Windowsˉx64,
                nativeˉimageˉbytes: 5,
                nativeˉentryˉoffset: 2,
                Response));

        Expectˉrequestˉfailure([], Consoleˉapplicationˉplanˉstatus.Invalidˉsize, 0);
        Expectˉrequestˉfailure(
            Request.AsSpan(0, 31).ToArray().ToImmutableArray(),
            Consoleˉapplicationˉplanˉstatus.Invalidˉsize,
            31);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 0, 0),
            Consoleˉapplicationˉplanˉstatus.Invalidˉmagic,
            0);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 4, 2),
            Consoleˉapplicationˉplanˉstatus.Invalidˉversion,
            4);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 8, 33),
            Consoleˉapplicationˉplanˉstatus.Invalidˉsize,
            8);
        Expectˉrequestˉfailure(
            Request.Add(0),
            Consoleˉapplicationˉplanˉstatus.Invalidˉsize,
            8);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 12, 0),
            Consoleˉapplicationˉplanˉstatus.Invalidˉtarget,
            12);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 12, 3),
            Consoleˉapplicationˉplanˉstatus.Invalidˉtarget,
            12);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 16, 0),
            Consoleˉapplicationˉplanˉstatus.Invalidˉnativeˉimage,
            16);
        Expectˉrequestˉfailure(
            Replaceˉu32(
                Request,
                16,
                Consoleˉapplicationˉlayout.MAXIMUM_NATIVE_IMAGE_BYTES + 1u),
            Consoleˉapplicationˉplanˉstatus.Invalidˉnativeˉimage,
            16);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 20, 5),
            Consoleˉapplicationˉplanˉstatus.Invalidˉentry,
            20);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 24, 1),
            Consoleˉapplicationˉplanˉstatus.Invalidˉreserved,
            24);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 28, 1),
            Consoleˉapplicationˉplanˉstatus.Invalidˉreserved,
            28);

        Expectˉresponseˉfailure(default, "uninitialized");
        Expectˉresponseˉfailure(
            Response.AsSpan(0, Consoleˉapplicationˉlayout.RESPONSE_BYTES - 1)
                .ToArray()
                .ToImmutableArray(),
            "truncated");
        Expectˉresponseˉfailure(Response.Add(0), "extended");

        for (var Offset = 0; Offset < Consoleˉapplicationˉlayout.RESPONSE_BYTES; Offset += 4)
        {
            var Original = BinaryPrimitives.ReadUInt32LittleEndian(Response.AsSpan()[Offset..]);
            var Mutated = Replaceˉu32(Response, Offset, Original == uint.MaxValue ? 0 : Original + 1);
            Expectˉresponseˉfailure(Mutated, $"changed field at offset {Offset}");
        }

        static void Expectˉconstructionˉfailure(
            ImmutableArray<byte> response,
            byte[] nativeˉimage,
            Consoleˉapplicationˉplan plan,
            byte[] recoveryˉimage,
            string description)
        {
            var Rejected = false;
            try
            {
                _ = Consoleˉapplicationˉconstruction.Verifyˉandˉmaterialize(
                    Consoleˉapplicationˉtarget.Windowsˉx64,
                    nativeˉimage,
                    nativeˉentryˉoffset: 2,
                    plan,
                    response,
                    recoveryˉimage);
            }
            catch (Consoleˉapplicationˉconstructionˉexception)
            {
                Rejected = true;
            }
            True(Rejected, $"The {description} console-application construction was accepted.");
        }

        byte[] Nativeˉimage = [0x11, 0x22, 0x33, 0x44, 0x55];
        var Windowsˉrecovery = Windowsˉconsoleˉapplicationˉwriter.Buildˉrecoveryˉimage(
            Nativeˉimage,
            nativeˉentryˉoffset: 2,
            Windows);
        var Windowsˉconstruction = Consoleˉapplicationˉconstruction.Evaluateˉrequest(Request);
        Equal(
            Consoleˉapplicationˉconstruction.WINDOWS_RESPONSE_BYTES,
            Windowsˉconstruction.Length);
        Sequenceˉequal(
            Windowsˉconstruction,
            Consoleˉapplicationˉconstruction.Evaluateˉrequest(Request));
        Sequenceˉequal(
            Windowsˉrecovery,
            Consoleˉapplicationˉconstruction.Verifyˉandˉmaterialize(
                Consoleˉapplicationˉtarget.Windowsˉx64,
                Nativeˉimage,
                nativeˉentryˉoffset: 2,
                Windows,
                Windowsˉconstruction,
                Windowsˉrecovery));

        var Linuxˉrequest = Consoleˉapplicationˉlayout.Buildˉrequest(
            Consoleˉapplicationˉtarget.Linuxˉx64,
            nativeˉimageˉbytes: Nativeˉimage.Length,
            nativeˉentryˉoffset: 2);
        var Linuxˉconstruction = Consoleˉapplicationˉconstruction.Evaluateˉrequest(
            Linuxˉrequest);
        Equal(
            Consoleˉapplicationˉconstruction.LINUX_RESPONSE_BYTES,
            Linuxˉconstruction.Length);
        var Linuxˉrecovery = Linuxˉconsoleˉapplicationˉwriter.Buildˉrecoveryˉimage(
            Nativeˉimage,
            nativeˉentryˉoffset: 2,
            Linux);
        Sequenceˉequal(
            Linuxˉrecovery,
            Consoleˉapplicationˉconstruction.Verifyˉandˉmaterialize(
                Consoleˉapplicationˉtarget.Linuxˉx64,
                Nativeˉimage,
                nativeˉentryˉoffset: 2,
                Linux,
                Linuxˉconstruction,
                Linuxˉrecovery));

        var Windowsˉverificationˉevaluation =
            Consoleˉapplicationˉverification.Evaluateˉchunks(
                Windowsˉrecovery.ToImmutableArray(),
                []);
        Sequenceˉequal(
            Windowsˉverificationˉevaluation.Evidence,
            Consoleˉapplicationˉverification.Evaluateˉchunks(
                Windowsˉrecovery.ToImmutableArray(),
                []).Evidence);
        var Windvaleˉverifiedˉwindows = Consoleˉapplicationˉverification.Verifyˉevidence(
            Windowsˉrecovery.Length,
            Windowsˉverificationˉevaluation.Evidence,
            Windowsˉverificationˉevaluation.Writes);
        Equal(Consoleˉapplicationˉtarget.Windowsˉx64, Windvaleˉverifiedˉwindows.Target);
        Equal(2u, Windvaleˉverifiedˉwindows.Nativeˉentryˉoffset);
        Sequenceˉequal(Nativeˉimage, Windvaleˉverifiedˉwindows.Nativeˉimageˉbytes);

        var Windvaleˉverifiedˉlinux = Consoleˉapplicationˉverification.Verify(
            Linuxˉrecovery);
        Equal(Consoleˉapplicationˉtarget.Linuxˉx64, Windvaleˉverifiedˉlinux.Target);
        Equal(2u, Windvaleˉverifiedˉlinux.Nativeˉentryˉoffset);
        Sequenceˉequal(Nativeˉimage, Windvaleˉverifiedˉlinux.Nativeˉimageˉbytes);

        static void Expectˉverificationˉevidenceˉfailure(
            ImmutableArray<byte> evidence,
            ImmutableArray<Consoleˉapplicationˉverificationˉwrite> writes,
            int applicationˉbytes,
            string description)
        {
            var Rejected = false;
            try
            {
                _ = Consoleˉapplicationˉverification.Verifyˉevidence(
                    applicationˉbytes,
                    evidence,
                    writes);
            }
            catch (InvalidOperationException)
            {
                Rejected = true;
            }
            True(Rejected, $"The {description} verification evidence was accepted.");
        }

        Expectˉverificationˉevidenceˉfailure(
            default,
            Windowsˉverificationˉevaluation.Writes,
            Windowsˉrecovery.Length,
            "uninitialized");
        Expectˉverificationˉevidenceˉfailure(
            Windowsˉverificationˉevaluation.Evidence.RemoveAt(
                Consoleˉapplicationˉverification.EVIDENCE_BYTES - 1),
            Windowsˉverificationˉevaluation.Writes,
            Windowsˉrecovery.Length,
            "truncated");
        Expectˉverificationˉevidenceˉfailure(
            Windowsˉverificationˉevaluation.Evidence.Add(0),
            Windowsˉverificationˉevaluation.Writes,
            Windowsˉrecovery.Length,
            "extended");
        Expectˉverificationˉevidenceˉfailure(
            Replaceˉu32(Windowsˉverificationˉevaluation.Evidence, 0, 0),
            Windowsˉverificationˉevaluation.Writes,
            Windowsˉrecovery.Length,
            "changed-magic");

        static void Expectˉverificationˉrejection(
            Consoleˉapplicationˉverificationˉevaluation evaluation,
            int applicationˉbytes,
            Consoleˉapplicationˉverificationˉstatus status,
            uint failureˉoffset,
            string description)
        {
            Equal(0, evaluation.Writes.Length);
            try
            {
                _ = Consoleˉapplicationˉverification.Verifyˉevidence(
                    applicationˉbytes,
                    evaluation.Evidence,
                    evaluation.Writes);
                throw new InvalidOperationException(
                    $"The {description} console application was accepted.");
            }
            catch (Consoleˉapplicationˉverificationˉexception Exception)
            {
                Equal(status, Exception.Status);
                Equal(failureˉoffset, Exception.Failureˉoffset);
            }
        }

        Expectˉverificationˉrejection(
            Consoleˉapplicationˉverification.Evaluateˉchunks([0x7F], [0x45]),
            2,
            Consoleˉapplicationˉverificationˉstatus.Invalidˉchunk,
            1u,
            "noncanonical segmented");

        var Maximumˉnativeˉimage = new byte[Consoleˉapplicationˉlayout.MAXIMUM_NATIVE_IMAGE_BYTES];
        Maximumˉnativeˉimage[0] = 0x31;
        Maximumˉnativeˉimage[^1] = 0xC3;
        var Maximumˉentry = (uint)Maximumˉnativeˉimage.Length - 1u;
        var Maximumˉwindowsˉplan = Consoleˉapplicationˉlayout.Plan(
            Consoleˉapplicationˉtarget.Windowsˉx64,
            Maximumˉnativeˉimage.Length,
            Maximumˉentry);
        var Maximumˉwindowsˉimage = Windowsˉconsoleˉapplicationˉwriter.Buildˉrecoveryˉimage(
            Maximumˉnativeˉimage,
            Maximumˉentry,
            Maximumˉwindowsˉplan);
        var Maximumˉverifiedˉwindows = Consoleˉapplicationˉverification.Verify(
            Maximumˉwindowsˉimage);
        Equal(Consoleˉapplicationˉtarget.Windowsˉx64, Maximumˉverifiedˉwindows.Target);
        Equal(Maximumˉentry, Maximumˉverifiedˉwindows.Nativeˉentryˉoffset);
        Sequenceˉequal(Maximumˉnativeˉimage, Maximumˉverifiedˉwindows.Nativeˉimageˉbytes);

        var Maximumˉlinuxˉplan = Consoleˉapplicationˉlayout.Plan(
            Consoleˉapplicationˉtarget.Linuxˉx64,
            Maximumˉnativeˉimage.Length,
            Maximumˉentry);
        var Maximumˉlinuxˉimage = Linuxˉconsoleˉapplicationˉwriter.Buildˉrecoveryˉimage(
            Maximumˉnativeˉimage,
            Maximumˉentry,
            Maximumˉlinuxˉplan);
        var Maximumˉverifiedˉlinux = Consoleˉapplicationˉverification.Verify(
            Maximumˉlinuxˉimage);
        Equal(Consoleˉapplicationˉtarget.Linuxˉx64, Maximumˉverifiedˉlinux.Target);
        Equal(Maximumˉentry, Maximumˉverifiedˉlinux.Nativeˉentryˉoffset);
        Sequenceˉequal(Maximumˉnativeˉimage, Maximumˉverifiedˉlinux.Nativeˉimageˉbytes);

        var Oversizedˉsecondˉchunk = Maximumˉlinuxˉimage
            .AsSpan(Consoleˉapplicationˉverification.FIRST_CHUNK_BYTES)
            .ToArray()
            .ToImmutableArray()
            .Add(0);
        Expectˉverificationˉrejection(
            Consoleˉapplicationˉverification.Evaluateˉchunks(
                Maximumˉlinuxˉimage
                    .AsSpan(0, Consoleˉapplicationˉverification.FIRST_CHUNK_BYTES)
                    .ToArray()
                    .ToImmutableArray(),
                Oversizedˉsecondˉchunk),
            Consoleˉapplicationˉverification.FIRST_CHUNK_BYTES +
                Oversizedˉsecondˉchunk.Length,
            Consoleˉapplicationˉverificationˉstatus.Invalidˉchunk,
            Consoleˉapplicationˉverification.FIRST_CHUNK_BYTES,
            "oversized second-chunk");

        var Maximumˉwindowsˉconstruction = Consoleˉapplicationˉconstruction.Evaluateˉrequest(
            Consoleˉapplicationˉlayout.Buildˉrequest(
                Consoleˉapplicationˉtarget.Windowsˉx64,
                Consoleˉapplicationˉlayout.MAXIMUM_NATIVE_IMAGE_BYTES,
                Consoleˉapplicationˉlayout.MAXIMUM_NATIVE_IMAGE_BYTES - 1u));
        Equal(
            (uint)Windowsˉconsoleˉapplicationˉcontract.MAX_APPLICATION_BYTES,
            BinaryPrimitives.ReadUInt32LittleEndian(
                Maximumˉwindowsˉconstruction.AsSpan()[24..]));
        Equal(
            (uint)Consoleˉapplicationˉlayout.MAXIMUM_NATIVE_IMAGE_BYTES,
            BinaryPrimitives.ReadUInt32LittleEndian(
                Maximumˉwindowsˉconstruction.AsSpan()[72..]));

        var Maximumˉlinuxˉconstruction = Consoleˉapplicationˉconstruction.Evaluateˉrequest(
            Consoleˉapplicationˉlayout.Buildˉrequest(
                Consoleˉapplicationˉtarget.Linuxˉx64,
                Consoleˉapplicationˉlayout.MAXIMUM_NATIVE_IMAGE_BYTES,
                Consoleˉapplicationˉlayout.MAXIMUM_NATIVE_IMAGE_BYTES - 1u));
        Equal(
            (uint)Linuxˉconsoleˉapplicationˉcontract.MAX_APPLICATION_BYTES,
            BinaryPrimitives.ReadUInt32LittleEndian(
                Maximumˉlinuxˉconstruction.AsSpan()[24..]));
        Equal(
            (uint)Consoleˉapplicationˉlayout.MAXIMUM_NATIVE_IMAGE_BYTES,
            BinaryPrimitives.ReadUInt32LittleEndian(
                Maximumˉlinuxˉconstruction.AsSpan()[72..]));

        var Failedˉconstruction = Consoleˉapplicationˉconstruction.Evaluateˉrequest([]);
        Equal(Consoleˉapplicationˉconstruction.HEADER_BYTES, Failedˉconstruction.Length);
        Equal(
            (uint)Consoleˉapplicationˉplanˉstatus.Invalidˉsize,
            BinaryPrimitives.ReadUInt32LittleEndian(Failedˉconstruction.AsSpan()[12..]));
        Equal(
            0u,
            BinaryPrimitives.ReadUInt32LittleEndian(Failedˉconstruction.AsSpan()[16..]));

        Expectˉconstructionˉfailure(
            default,
            Nativeˉimage,
            Windows,
            Windowsˉrecovery,
            "uninitialized");
        Expectˉconstructionˉfailure(
            Windowsˉconstruction.AsSpan(0, Windowsˉconstruction.Length - 1)
                .ToArray()
                .ToImmutableArray(),
            Nativeˉimage,
            Windows,
            Windowsˉrecovery,
            "truncated");
        Expectˉconstructionˉfailure(
            Windowsˉconstruction.Add(0),
            Nativeˉimage,
            Windows,
            Windowsˉrecovery,
            "extended");
        for (var Offset = 0; Offset < 100; Offset += 4)
        {
            var Original = BinaryPrimitives.ReadUInt32LittleEndian(
                Windowsˉconstruction.AsSpan()[Offset..]);
            Expectˉconstructionˉfailure(
                Replaceˉu32(
                    Windowsˉconstruction,
                    Offset,
                    Original == uint.MaxValue ? 0 : Original + 1),
                Nativeˉimage,
                Windows,
                Windowsˉrecovery,
                $"changed field at offset {Offset}");
        }
        var Changedˉliteral = Windowsˉconstruction.ToArray();
        Changedˉliteral[100] ^= 1;
        Expectˉconstructionˉfailure(
            Changedˉliteral.ToImmutableArray(),
            Nativeˉimage,
            Windows,
            Windowsˉrecovery,
            "changed literal");
    }

    private static void Nativeˉconsoleˉapplicationˉpublicationˉisˉatomic()
    {
        static (int Exitˉcode, string Standardˉoutput, string Standardˉerror) Executeˉtool(
            params string[] arguments)
        {
            var Originalˉoutput = Console.Out;
            var Originalˉerror = Console.Error;
            using var Output = new StringWriter(
                System.Globalization.CultureInfo.InvariantCulture);
            using var Error = new StringWriter(
                System.Globalization.CultureInfo.InvariantCulture);
            try
            {
                Console.SetOut(Output);
                Console.SetError(Error);
                var Exitˉcode = Windvale.Tool.Program.Main(arguments);
                return (Exitˉcode, Output.ToString(), Error.ToString());
            }
            finally
            {
                Console.SetOut(Originalˉoutput);
                Console.SetError(Originalˉerror);
            }
        }

        Sequenceˉequal(
            [".wvb", ".exe", ".elf", ".exe", ".elf", ".exe", ".elf"],
            new[]
            {
                "wvb",
                Windowsˉconsoleˉapplicationˉcontract.TARGET_NAME,
                Linuxˉconsoleˉapplicationˉcontract.TARGET_NAME,
                Windowsˉconsoleˉapplicationˉcontract.HOSTED_TARGET_NAME,
                Linuxˉconsoleˉapplicationˉcontract.HOSTED_TARGET_NAME,
                Windowsˉconsoleˉapplicationˉcontract.COMPILER_TARGET_NAME,
                Linuxˉconsoleˉapplicationˉcontract.COMPILER_TARGET_NAME,
            }.Select(Windvale.Tool.Program.Targetˉoutputˉextension));

        var Directoryˉpath = System.IO.Path.Combine(
            System.IO.Path.GetTempPath(),
            $"windvale-atomic-publication-{Guid.NewGuid():N}");
        var Outputˉpath = System.IO.Path.Combine(Directoryˉpath, "Application.elf");
        Directory.CreateDirectory(Directoryˉpath);
        try
        {
            var Moduleˉpath = System.IO.Path.Combine(Directoryˉpath, "Sum.wvb");
            var Aotˉpath = System.IO.Path.Combine(Directoryˉpath, "Sum.exe");
            File.WriteAllBytes(Moduleˉpath, Compileˉsuccess(SUM_SOURCE));
            var Aot = Executeˉtool(
                "aot",
                Moduleˉpath,
                "--target",
                Windowsˉconsoleˉapplicationˉcontract.TARGET_NAME,
                "-o",
                Aotˉpath);
            Equal(0, Aot.Exitˉcode);
            Contains(
                Aot.Standardˉoutput,
                $"Target: {Windowsˉconsoleˉapplicationˉcontract.TARGET_NAME}");
            Equal(
                WINDOWS_CONSOLE_SUM_SHA256,
                Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(Aotˉpath)))
                    .ToLowerInvariant());

            var Rejectedˉpath = System.IO.Path.Combine(Directoryˉpath, "Rejected.bin");
            var Rejected = Executeˉtool(
                "aot",
                Moduleˉpath,
                "--target",
                Windowsˉconsoleˉapplicationˉcontract.TARGET_NAME,
                "-o",
                Rejectedˉpath);
            Equal(64, Rejected.Exitˉcode);
            False(
                File.Exists(Rejectedˉpath),
                "Rejected AOT publication created an output file.");
            Contains(Rejected.Standardˉerror, "AOT output must use the .exe extension");

            byte[] Original = [1, 2, 3, 4];
            File.WriteAllBytes(Outputˉpath, Original);
            try
            {
                Windvale.Tool.Atomicˉfileˉpublisher.Publish(
                    Outputˉpath,
                    [5, 6, 7],
                    _ => throw new IOException("Injected prepublication failure."));
                throw new InvalidOperationException("Atomic publication accepted the injected failure.");
            }
            catch (IOException Exception)
            {
                True(
                    Exception.Message.Contains("Injected prepublication failure", StringComparison.Ordinal),
                    "Atomic publication returned the wrong injected failure.");
            }

            Sequenceˉequal(Original, File.ReadAllBytes(Outputˉpath));
            Equal(
                0,
                Directory.GetFiles(Directoryˉpath, ".Application.elf.*.tmp").Length);

            byte[] Replacement = [8, 9, 10];
            Action<string>? Prepareˉtemporary = null;
            if (OperatingSystem.IsLinux())
            {
                Prepareˉtemporary = Prepareˉlinuxˉtestˉexecutable;
            }
            Windvale.Tool.Atomicˉfileˉpublisher.Publish(
                Outputˉpath,
                Replacement,
                Prepareˉtemporary);
            Sequenceˉequal(Replacement, File.ReadAllBytes(Outputˉpath));
            if (OperatingSystem.IsLinux())
            {
                Equal(
                    UnixFileMode.UserRead |
                        UnixFileMode.UserWrite |
                        UnixFileMode.UserExecute |
                        UnixFileMode.GroupRead |
                        UnixFileMode.GroupExecute |
                        UnixFileMode.OtherRead |
                        UnixFileMode.OtherExecute,
                    File.GetUnixFileMode(Outputˉpath));
            }
        }
        finally
        {
            foreach (var Path in Directory.GetFiles(Directoryˉpath))
            {
                File.Delete(Path);
            }
            Directory.Delete(Directoryˉpath);
        }
    }

    private static void Prepareˉlinuxˉtestˉexecutable(string path)
    {
        if (!OperatingSystem.IsLinux())
        {
            throw new PlatformNotSupportedException("Linux executable mode requires Linux.");
        }
        File.SetUnixFileMode(
            path,
            UnixFileMode.UserRead |
                UnixFileMode.UserWrite |
                UnixFileMode.UserExecute |
                UnixFileMode.GroupRead |
                UnixFileMode.GroupExecute |
                UnixFileMode.OtherRead |
                UnixFileMode.OtherExecute);
    }

    private static int Executeˉlinuxˉapplication(
        ImmutableArray<byte> image,
        string expectedˉoutput = "",
        IReadOnlyList<string>? arguments = null,
        int timeoutˉmilliseconds = 10_000,
        ISet<string>? loadedˉmappings = null,
        string expectedˉerror = "")
    {
        if (!OperatingSystem.IsLinux())
        {
            throw new PlatformNotSupportedException("Direct ELF execution requires Linux.");
        }
        var Path = System.IO.Path.Combine(
            System.IO.Path.GetTempPath(),
            $"windvale-linux-console-{Guid.NewGuid():N}.elf");
        try
        {
            File.WriteAllBytes(Path, image.AsSpan());
            File.SetUnixFileMode(
                Path,
                UnixFileMode.UserRead | UnixFileMode.UserWrite | UnixFileMode.UserExecute);
            var Startˉinfo = new ProcessStartInfo
            {
                FileName = Path,
                UseShellExecute = false,
                RedirectStandardOutput = true,
                RedirectStandardError = true,
            };
            foreach (var Argument in arguments ?? [])
            {
                Startˉinfo.ArgumentList.Add(Argument);
            }
            using var Process = System.Diagnostics.Process.Start(Startˉinfo) ??
                throw new InvalidOperationException("Linux did not start the generated application.");
            if (loadedˉmappings is null)
            {
                if (!Process.WaitForExit(timeoutˉmilliseconds))
                {
                    Process.Kill(entireProcessTree: true);
                    throw new InvalidOperationException(
                        "The generated Linux application did not exit.");
                }
            }
            else
            {
                var Timer = Stopwatch.StartNew();
                while (true)
                {
                    if (Process.WaitForExit(0))
                    {
                        break;
                    }
                    try
                    {
                        Captureˉlinuxˉmappings(Process.Id, loadedˉmappings);
                    }
                    catch (FileNotFoundException) when (Process.HasExited)
                    {
                        break;
                    }
                    catch (DirectoryNotFoundException) when (Process.HasExited)
                    {
                        break;
                    }
                    var Remaining = timeoutˉmilliseconds - checked((int)Timer.ElapsedMilliseconds);
                    if (Remaining <= 0)
                    {
                        Process.Kill(entireProcessTree: true);
                        throw new InvalidOperationException(
                            "The generated Linux application did not exit.");
                    }
                    if (Process.WaitForExit(Math.Min(Remaining, 100)))
                    {
                        break;
                    }
                }
            }
            var Standardˉoutput = Process.StandardOutput.ReadToEnd();
            var Standardˉerror = Process.StandardError.ReadToEnd();
            True(
                StringComparer.Ordinal.Equals(expectedˉoutput, Standardˉoutput),
                $"The generated Linux application exited {Process.ExitCode} with " +
                    $"stdout '{Standardˉoutput}' and stderr '{Standardˉerror}'.");
            Equal(expectedˉerror, Standardˉerror);
            return Process.ExitCode;
        }
        finally
        {
            File.Delete(Path);
        }
    }

    private static void Captureˉlinuxˉmappings(
        int processˉid,
        ISet<string> loadedˉmappings)
    {
        foreach (var Line in File.ReadLines($"/proc/{processˉid}/maps"))
        {
            var Pathˉstart = Line.IndexOf('/');
            if (Pathˉstart >= 0)
            {
                loadedˉmappings.Add(Line[Pathˉstart..]);
            }
        }
    }

    private static void Rejectˉlinuxˉapplication(
        ReadOnlySpan<byte> bytes,
        string expectedˉcode)
    {
        var Windvaleˉrejected = false;
        try
        {
            _ = Consoleˉapplicationˉverification.Verify(bytes);
        }
        catch (Consoleˉapplicationˉverificationˉexception)
        {
            Windvaleˉrejected = true;
        }
        True(
            Windvaleˉrejected,
            "The Windvale-owned verifier accepted a malformed Linux console application.");

        try
        {
            _ = Linuxˉconsoleˉapplicationˉverifier.Verify(bytes);
        }
        catch (Linuxˉconsoleˉapplicationˉexception Exception)
        {
            Equal(expectedˉcode, Exception.Code);
            return;
        }
        throw new InvalidOperationException("The malformed Linux console application was accepted.");
    }

    private static byte[] Mutateˉbyte(ImmutableArray<byte> source, int offset)
    {
        var Result = source.ToArray();
        Result[offset] ^= 1;
        return Result;
    }

    private static void Rejectˉwindowsˉapplication(
        ReadOnlySpan<byte> bytes,
