        throw new InvalidOperationException("The malformed Windows console application was accepted.");
    }

    private static void Nativeˉwideˉcallsˉagree()
    {
        var Parameters = string.Join(
            ", ",
            Enumerable.Range(0, Nativeˉcontract.MAXIMUM_CALL_PARAMETERS)
                .Select(Index => $"P{Index:D2}: i32"));
        var Arguments = string.Join(
            ", ",
            Enumerable.Range(1, Nativeˉcontract.MAXIMUM_CALL_PARAMETERS));
        var Wideˉsource = $$"""
            module Nativeˉmaximumˉwideˉcall profile portable;
            fn Select({{Parameters}}) -> i32 { return P00 + P31 + P63; }
            export fn Main() -> i32 { return Select({{Arguments}}); }
            """;
        var Wideˉverified = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess(Wideˉsource));
        var Wideˉreference = new Referenceˉruntime(
            Wideˉverified,
            new Referenceˉcapabilityˉhost(TextWriter.Null),
            Runtimeˉoptions.Portableˉdefaults).Runˉmain();
        Equal(97, Wideˉreference.Exitˉcode);
        var Wideˉfirst = X64ˉnativeˉbackend.Compile(Wideˉverified);
        var Wideˉsecond = X64ˉnativeˉbackend.Compile(Wideˉverified);
        Sequenceˉequal(Wideˉfirst.Fragment.Code, Wideˉsecond.Fragment.Code);
        True(
            Wideˉfirst.Module.Functions
                .SelectMany(Function => Function.Blocks)
                .SelectMany(Block => Block.Operations)
                .Any(Operation => Operation is Nativeˉcall
                { Arguments.Length: Nativeˉcontract.MAXIMUM_CALL_PARAMETERS }),
            "Native machine IR omitted the bounded maximum-width call.");
        Equal(
            Wideˉreference.Exitˉcode,
            X64ˉnativeˉexecutor.Executeˉi32(
                Wideˉfirst.Fragment,
                maximumˉinstructions: Wideˉreference.Executedˉinstructions));
        var Wideˉobject = Nativeˉobjectˉsink.Writeˉwvo(Wideˉfirst.Fragment);
        var Wideˉlinked = Linkˉsuccess(
            [Wideˉobject.ToArray()],
            new(Linkˉcontract.DEFAULT_BASE_ADDRESS, "Main"));
        Equal(
            Wideˉreference.Exitˉcode,
            X64ˉnativeˉexecutor.Executeˉi32(
                Wideˉfirst.Fragment with { Code = Wideˉlinked.Imageˉbytes },
                maximumˉinstructions: Wideˉreference.Executedˉinstructions));

        var Mainˉsymbol = Wideˉfirst.Fragment.Symbols.Single(
            Symbol => Symbol.Binding == Nativeˉsymbolˉbinding.Export);
        var Mainˉoffset = checked((int)Mainˉsymbol.Offset);
        var Mainˉcode = Wideˉfirst.Fragment.Code.AsSpan(
            Mainˉoffset,
            checked((int)Mainˉsymbol.Size));
        var Stackˉreserve = Mainˉcode.IndexOf(new byte[]
        {
            0x48, 0x81, 0xEC, 0xC0, 0x03, 0x00, 0x00,
        });
        True(Stackˉreserve >= 0, "Native maximum-width call omitted its bounded stack reservation.");
        var Stackˉrelease = Mainˉcode.IndexOf(new byte[]
        {
            0x48, 0x81, 0xC4, 0xC0, 0x03, 0x00, 0x00,
        });
        True(Stackˉrelease >= 0, "Native maximum-width call omitted its bounded stack release.");

        var Corruptedˉreserve = Wideˉfirst.Fragment.Code.ToArray();
        Corruptedˉreserve[Mainˉoffset + Stackˉreserve + 3] ^= 0x10;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                Wideˉfirst.Fragment with { Code = Corruptedˉreserve.ToImmutableArray() }));

        var Corruptedˉoutgoingˉslot = Wideˉfirst.Fragment.Code.ToArray();
        Corruptedˉoutgoingˉslot[Mainˉoffset + Stackˉreserve + 17] ^= 0x01;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                Wideˉfirst.Fragment with { Code = Corruptedˉoutgoingˉslot.ToImmutableArray() }));

        var Corruptedˉrelease = Wideˉfirst.Fragment.Code.ToArray();
        Corruptedˉrelease[Mainˉoffset + Stackˉrelease + 3] ^= 0x10;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                Wideˉfirst.Fragment with { Code = Corruptedˉrelease.ToImmutableArray() }));

        var Descriptorˉverified = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess("""
            module Nativeˉwideˉdescriptor profile portable;
            data Expected: bytes = [0, 42, 255];
            fn Fifth(A: i32, B: i32, C: i32, D: i32, Value: bytes) -> bytes {
                return Value;
            }
            export fn Main() -> bytes { return Fifth(1, 2, 3, 4, Expected); }
            """));
        var Descriptorˉnative = X64ˉnativeˉbackend.Compile(Descriptorˉverified);
        Sequenceˉequal(
            new byte[] { 0, 42, 255 },
            X64ˉnativeˉexecutor.Executeˉbytes(Descriptorˉnative.Fragment));
        var Descriptorˉobject = Nativeˉobjectˉsink.Writeˉwvo(Descriptorˉnative.Fragment);
        var Descriptorˉlinked = Linkˉsuccess(
            [Descriptorˉobject.ToArray()],
            new(Linkˉcontract.DEFAULT_BASE_ADDRESS, "Main"));
        Sequenceˉequal(
            new byte[] { 0, 42, 255 },
            X64ˉnativeˉexecutor.Executeˉbytes(
                Descriptorˉnative.Fragment with { Code = Descriptorˉlinked.Imageˉbytes }));

        var Descriptorˉmain = Descriptorˉnative.Fragment.Symbols.Single(
            Symbol => Symbol.Binding == Nativeˉsymbolˉbinding.Export);
        var Descriptorˉmainˉoffset = checked((int)Descriptorˉmain.Offset);
        var Descriptorˉreserve = Descriptorˉnative.Fragment.Code.AsSpan(
                Descriptorˉmainˉoffset,
                checked((int)Descriptorˉmain.Size))
            .IndexOf(new byte[] { 0x48, 0x81, 0xEC, 0x10, 0x00, 0x00, 0x00 });
        True(Descriptorˉreserve >= 0, "Native descriptor call omitted its stack cell.");
        var Corruptedˉdescriptorˉcell = Descriptorˉnative.Fragment.Code.ToArray();
        Corruptedˉdescriptorˉcell[Descriptorˉmainˉoffset + Descriptorˉreserve + 35] ^= 0x01;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                Descriptorˉnative.Fragment with
                {
                    Code = Corruptedˉdescriptorˉcell.ToImmutableArray(),
                }));

        var Voidˉverified = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess("""
            module Nativeˉwideˉvoid profile portable;
            fn Ignore(A: i32, B: i32, C: i32, D: i32, E: i32) -> void { return; }
            export fn Main() -> i32 { Ignore(1, 2, 3, 4, 5); return 42; }
            """));
        Equal(
            42,
            X64ˉnativeˉexecutor.Executeˉi32(
                X64ˉnativeˉbackend.Compile(Voidˉverified).Fragment));
    }

    private static void Nativeˉnominalˉvaluesˉagree()
    {
        var Verified = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess(NATIVE_NOMINAL_SOURCE));
        var Interpreted = new Referenceˉruntime(
            Verified,
            new Referenceˉcapabilityˉhost(TextWriter.Null),
            Runtimeˉoptions.Portableˉdefaults).Runˉmain();
        Equal(42, Interpreted.Exitˉcode);

        var First = X64ˉnativeˉbackend.Compile(Verified);
        var Second = X64ˉnativeˉbackend.Compile(Verified);
        Sequenceˉequal(First.Fragment.Code, Second.Fragment.Code);
        Nativeˉshapesˉmatchˉverifiedˉwvb(Verified, First);
        var Recordˉstorage = Nativeˉrecordˉstorageˉplanner.Measure(First.Module);
        Nativeˉrecordˉstorageˉisˉvalid(First.Module, Recordˉstorage);
        var Repeatedˉrecordˉstorage = Nativeˉrecordˉstorageˉplanner.Measure(Second.Module);
        Equal(
            Nativeˉrecordˉstorageˉdigest(Recordˉstorage),
            Nativeˉrecordˉstorageˉdigest(Repeatedˉrecordˉstorage));
        for (var Function = 0; Function < Recordˉstorage.Length; Function++)
        {
            Sequenceˉequal(
                Recordˉstorage[Function].Localˉrecordˉfieldˉoffsets,
                Repeatedˉrecordˉstorage[Function].Localˉrecordˉfieldˉoffsets);
            Sequenceˉequal(
                Recordˉstorage[Function].Valueˉrecordˉfieldˉoffsets,
                Repeatedˉrecordˉstorage[Function].Valueˉrecordˉfieldˉoffsets);
        }
        Equal(
            "0:Advance:1:3:9:25:3:3:28:3:31:32;" +
            "1:Main:0:4:12:16:3:6:19:6:-1:25;" +
            "2:Make:0:1:3:13:3:3:16:3:19:20;" +
            "3:Read:1:4:12:24:3:3:27:3:-1:30",
            string.Join(
                ";",
                Recordˉstorage.Select(Function =>
                    $"{Function.Functionˉindex}:{Function.Functionˉname}:" +
                    $"{Function.Recordˉparameterˉbindings}:" +
                    $"{Function.Recordˉlocalˉbindings}:" +
                    $"{Function.Declaredˉrecordˉlocalˉfieldˉcells}:" +
                    $"{Function.Persistentˉrecordˉbaseˉcell}:" +
                    $"{Function.Persistentˉrecordˉfieldˉcells}:" +
                    $"{Function.Peakˉliveˉrecordˉfieldˉcells}:" +
                    $"{Function.Scratchˉrecordˉbaseˉcell}:" +
                    $"{Function.Scratchˉrecordˉfieldˉcells}:" +
                    $"{Function.Recordˉreturnˉpointerˉcell}:" +
                    $"{Function.Projectedˉframeˉcells}")));
        Equal(2, First.Module.Types.Length);
        True(
            First.Module.Functions.SelectMany(Function => Function.Blocks)
                .SelectMany(Block => Block.Operations)
                .Any(Operation => Operation is Nativeˉenumˉconstant),
            "Native machine IR omitted enum constants.");
        True(
            First.Module.Functions.SelectMany(Function => Function.Blocks)
                .SelectMany(Block => Block.Operations)
                .Any(Operation => Operation is Nativeˉenumˉcomparison),
            "Native machine IR omitted enum comparisons.");
        True(
            First.Module.Functions.SelectMany(Function => Function.Blocks)
                .SelectMany(Block => Block.Operations)
                .Any(Operation => Operation is Nativeˉrecordˉcreate),
            "Native machine IR omitted record construction.");
        True(
            First.Module.Functions.SelectMany(Function => Function.Blocks)
                .SelectMany(Block => Block.Operations)
                .Any(Operation => Operation is Nativeˉrecordˉfield),
            "Native machine IR omitted record field access.");
        _ = Nativeˉfragmentˉverifier.Verify(First.Fragment);
        Equal(Interpreted.Exitˉcode, X64ˉnativeˉexecutor.Executeˉi32(First.Fragment));

        var Object = Nativeˉobjectˉsink.Writeˉwvo(First.Fragment);
        var Linked = Linkˉsuccess(
            [Object.ToArray()],
            new(Linkˉcontract.DEFAULT_BASE_ADDRESS, "Main"));
        Sequenceˉequal(First.Fragment.Code, Linked.Imageˉbytes);
        Equal(
            Interpreted.Exitˉcode,
            X64ˉnativeˉexecutor.Executeˉi32(First.Fragment with { Code = Linked.Imageˉbytes }));

        var Corruptedˉrecord = First.Fragment.Code.ToArray();
        var Recordˉcreate = Corruptedˉrecord.AsSpan().IndexOf(new byte[]
        {
            0x41, 0xB8, 0x00, 0x00, 0x00, 0x00,
            0x48, 0x8B, 0x84, 0x24,
        });
        True(Recordˉcreate >= 0, "Native nominal fragment omitted its typed frame-record construction.");
        BinaryPrimitives.WriteInt32LittleEndian(
            Corruptedˉrecord.AsSpan(Recordˉcreate + 18, sizeof(int)),
            0);
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉrecord.ToImmutableArray() }));

        var Nonzeroˉdefault = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess("""
            module Nativeˉnonzeroˉenum profile portable;
            enum Nativeˉstate { Ready = 1; }
            export fn Main() -> i32 { return 0; }
            """));
        Throwsˉnative("WVN2001", () => _ = X64ˉnativeˉbackend.Compile(Nonzeroˉdefault));

        var Repeatedˉconstruction = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess("""
            module Nativeˉrecordˉframe profile portable;
            record Nativeˉcell { Value: i32; }
            export fn Main() -> i32 {
                var Index: i32 = 0;
                var Cell: Nativeˉcell = Nativeˉcell(0);
                while Index < 131072 {
                    Cell = Nativeˉcell(Index);
                    Index = Index + 1;
                }
                return Cell.Value;
            }
            """));
        var Repeatedˉnative = X64ˉnativeˉbackend.Compile(Repeatedˉconstruction);
        var Repeatedˉmeasurement = X64ˉnativeˉexecutor.Measureˉi32(
            Repeatedˉnative.Fragment,
            maximumˉinstructions: 4_000_000);
        Equal(131_071, Repeatedˉmeasurement.Scalar);
        Equal(0u, Repeatedˉmeasurement.Recordˉarenaˉused);
    }

    private static void Nativeˉdescriptorˉownershipˉisˉplanned()
    {
        const string Source = """
            module Nativeˉdescriptorˉownership profile portable;
            record Nativeˉbyteˉpair { Whole: bytes; Part: bytes; }
            data Prefix: bytes = [7];

            fn Build() -> Nativeˉbyteˉpair {
                let Whole: bytes = Bytesˉconcat(
                    Prefix,
                    Bytesˉfromˉu16ˉlittle(2u32)
                );
                let Part: bytes = Bytesˉslice(Whole, 0u32, 1u32);
                return Nativeˉbyteˉpair(Whole, Part);
            }

            fn Select(Value: Nativeˉbyteˉpair) -> bytes {
                return Value.Part;
            }

            export fn Main() -> i32 {
                var Replaced: bytes = Bytesˉfromˉu32ˉlittle(7u32);
                let Built: Nativeˉbyteˉpair = Build();
                Replaced = Select(Built);
                Bytesˉconcat(Built.Whole, Replaced);
                return 0;
            }
            """;
        var Verified = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess(Source));
        var First = X64ˉnativeˉbackend.Compile(Verified);
        var Second = X64ˉnativeˉbackend.Compile(Verified);
        var Plan = First.Module.Descriptorˉownership ??
            throw new InvalidOperationException("Native lowering omitted descriptor ownership.");
        var Repeated = Second.Module.Descriptorˉownership ??
            throw new InvalidOperationException("Repeated native lowering omitted descriptor ownership.");
        var Emission = First.Module.Descriptorˉallocatorˉemission ??
            throw new InvalidOperationException("Native lowering omitted descriptor allocator emission.");
        var Repeatedˉemission = Second.Module.Descriptorˉallocatorˉemission ??
            throw new InvalidOperationException("Repeated native lowering omitted descriptor allocator emission.");

        Equal(Nativeˉdescriptorˉownershipˉplanner.FORMAT_VERSION, Plan.Formatˉversion);
        True(Plan.Terminalˉfailureˉdiscardsˉarena,
            "The ownership plan omitted terminal arena teardown.");
        Equal(
            Plan.Totalˉactions,
            Plan.Functions.Sum(Function => Function.Actions.Length));
        Sequenceˉequal(
            Plan.Functions.SelectMany(Function => Function.Actions),
            Repeated.Functions.SelectMany(Function => Function.Actions));
        Nativeˉdescriptorˉownershipˉverifier.Verify(First.Module, Plan);
        var Projection = Nativeˉdescriptorˉallocatorˉprojector.Project(Plan);
        Equal(Plan.Totalˉactions, Projection.Ownershipˉactions);
        Equal(
            Projection.Ownershipˉactions,
            checked(Projection.Allocatorˉleafˉcalls + Projection.Ownershipˉmovementˉactions));
        Nativeˉdescriptorˉallocatorˉemissionˉverifier.Verify(First.Module, Emission);
        Equal(
            Nativeˉdescriptorˉallocatorˉemissionˉcontract.FORMAT_VERSION,
            Emission.Formatˉversion);
        Equal(8u, Emission.Candidateˉcontextˉformatˉversion);
        Equal(128u, Emission.Candidateˉcontextˉsize);
        Equal(112, Emission.Allocatorˉstateˉpointerˉoffset);
        Equal(120, Emission.Allocatorˉleafˉpointerˉoffset);
        Equal(3, Emission.Requestˉframeˉcells);
        Equal(Projection.Allocatorˉleafˉcalls, Emission.Allocatorˉleafˉinvocations);
        Equal(Projection.Ownershipˉmovementˉactions, Emission.Ownershipˉmovementˉactions);
        Sequenceˉequal(
            Emission.Functions.SelectMany(Function => Function.Emissions),
            Repeatedˉemission.Functions.SelectMany(Function => Function.Emissions));
        var Emissions = Emission.Functions.SelectMany(Function => Function.Emissions).ToArray();
        True(
            Emissions.Any(Value => Value.Phase ==
                Nativeˉdescriptorˉallocatorˉemissionˉphase.Operationˉbefore),
            "The allocator emission plan omitted replacement-before-copy operations.");
        True(
            Emissions.Any(Value => Value.Phase ==
                Nativeˉdescriptorˉallocatorˉemissionˉphase.Operationˉallocation),
            "The allocator emission plan omitted acquisition operations.");
        True(
            Emissions.Any(Value => Value.Phase ==
                Nativeˉdescriptorˉallocatorˉemissionˉphase.Operationˉafter),
            "The allocator emission plan omitted post-definition or last-use operations.");
        True(
            Emissions.Any(Value => Value.Phase ==
                Nativeˉdescriptorˉallocatorˉemissionˉphase.Terminatorˉcleanup),
            "The allocator emission plan omitted return cleanup.");
        True(
            Emissions.Any(Value =>
                Value.Source.Addressing ==
                    Nativeˉdescriptorˉownerˉaddressing.Indirectˉrecord),
            "The allocator emission plan omitted borrowed record-field addressing.");
        True(
            Emission.Functions.Any(Function =>
                Function.Generatedˉcodeˉinvocations > 0 &&
                Function.Requestˉbaseˉcell == Function.Existingˉframeˉcells &&
                Function.Projectedˉframeˉcells ==
                    Function.Existingˉframeˉcells +
                        Nativeˉdescriptorˉallocatorˉemissionˉcontract.REQUEST_FRAME_CELLS &&
                Function.Preservesˉinstructionˉbudget &&
                Function.Preservesˉcallˉdepth),
            "The allocator emission plan omitted bounded request scratch or budget preservation.");
        True(Plan.Functions.Sum(Function => Function.Acquireˉactions) > 0,
            "The ownership plan omitted allocated descriptor results.");
        True(Plan.Functions.Sum(Function => Function.Borrowˉactions) > 0,
            "The ownership plan omitted static borrowed descriptors.");
        True(Plan.Functions.Sum(Function => Function.Retainˉactions) > 0,
            "The ownership plan omitted aliases, locals, or record fields.");
        True(Plan.Functions.Sum(Function => Function.Releaseˉactions) > 0,
            "The ownership plan omitted last-use or frame cleanup.");
        True(Plan.Functions.Sum(Function => Function.Callˉborrowˉactions) > 0,
            "The ownership plan omitted borrowed call arguments.");
        True(Plan.Functions.Sum(Function => Function.Acceptedˉreturnˉactions) > 0,
            "The ownership plan omitted caller-owned result acceptance.");
        True(Plan.Functions.Sum(Function => Function.Transferredˉreturnˉactions) > 0,
            "The ownership plan omitted callee-to-caller return transfer.");
        True(Plan.Functions.Sum(Function => Function.Recordˉvalueˉdescriptorˉfields) > 0,
            "The ownership plan omitted descriptor-bearing direct records.");
        Equal(0, X64ˉnativeˉexecutor.Executeˉi32(First.Fragment));

        var Corruptedˉfunctionˉindex = Enumerable.Range(0, Plan.Functions.Length)
            .FirstOrDefault(
                Index => !Plan.Functions[Index].Actions.IsEmpty,
                -1);
        True(Corruptedˉfunctionˉindex >= 0, "The ownership plan unexpectedly has no actions.");
        var Originalˉfunction = Plan.Functions[Corruptedˉfunctionˉindex];
        var Originalˉaction = Originalˉfunction.Actions[0];
        var Corruptedˉactions = Originalˉfunction.Actions.SetItem(
            0,
            Originalˉaction with
            {
                Kind = Originalˉaction.Kind ==
                    Nativeˉdescriptorˉownershipˉactionˉkind.Release
                        ? Nativeˉdescriptorˉownershipˉactionˉkind.Retain
                        : Nativeˉdescriptorˉownershipˉactionˉkind.Release,
            });
        var Corruptedˉfunctions = Plan.Functions.SetItem(
            Corruptedˉfunctionˉindex,
            Originalˉfunction with { Actions = Corruptedˉactions });
        Throwsˉnative(
            "WVN2903",
            () => Nativeˉdescriptorˉownershipˉverifier.Verify(
                First.Module,
                Plan with { Functions = Corruptedˉfunctions }));
        Throwsˉnative(
            "WVN2903",
            () => Nativeˉdescriptorˉownershipˉverifier.Verify(
                First.Module,
                Plan with { Totalˉactions = checked(Plan.Totalˉactions + 1) }));

        var Emissionˉfunctionˉindex = Enumerable.Range(0, Emission.Functions.Length)
            .FirstOrDefault(Index => !Emission.Functions[Index].Emissions.IsEmpty, -1);
        True(Emissionˉfunctionˉindex >= 0, "The allocator emission plan unexpectedly has no calls.");
        var Emissionˉfunction = Emission.Functions[Emissionˉfunctionˉindex];
        var Corruptˉemissions = Emissionˉfunction.Emissions.SetItem(
            0,
            Emissionˉfunction.Emissions[0] with
            {
                Phase = (Nativeˉdescriptorˉallocatorˉemissionˉphase)0,
            });
        Throwsˉnative(
            "WVN2905",
            () => Nativeˉdescriptorˉallocatorˉemissionˉverifier.Verify(
                First.Module,
                Emission with
                {
                    Functions = Emission.Functions.SetItem(
                        Emissionˉfunctionˉindex,
                        Emissionˉfunction with { Emissions = Corruptˉemissions }),
                }));
        Throwsˉnative(
            "WVN2905",
            () => Nativeˉdescriptorˉallocatorˉemissionˉverifier.Verify(
                First.Module,
                Emission with
                {
                    Allocatorˉleafˉinvocations = checked(
                        Emission.Allocatorˉleafˉinvocations + 1),
                }));
        Throwsˉnative(
            "WVN2905",
            () => Nativeˉdescriptorˉallocatorˉemissionˉverifier.Verify(
                First.Module,
                Emission with
                {
                    Functions = Emission.Functions.SetItem(
                        Emissionˉfunctionˉindex,
                        null!),
                }));
    }

    private static void Nativeˉdescriptorˉallocatorˉreclaims()
    {
        var Source = Readˉembeddedˉsource("Windvale.Seed.Tests.Descriptor-Allocator.wva");
        var Objectˉbytes = Assembleˉsuccess(Source);
        Equal(
            X64ˉnativeˉdescriptorˉallocator.CANONICAL_OBJECT_SHA256,
            Objectˉdigest.Calculateˉsha256(Objectˉbytes));
        var Object = Objectˉcodec.Readˉandˉverify(Objectˉbytes);
        Sequenceˉequal(
            X64ˉnativeˉdescriptorˉallocator.Code,
            X64ˉnativeˉdescriptorˉallocator.Read(Object));
        Equal(
            X64ˉnativeˉdescriptorˉallocator.CANONICAL_CODE_SHA256,
            Objectˉdigest.Calculateˉsha256(X64ˉnativeˉdescriptorˉallocator.Code.AsSpan()));

        var Corruptedˉobject = Objectˉbytes.ToArray();
        var Codeˉoffset = Corruptedˉobject.AsSpan().IndexOf(
            X64ˉnativeˉdescriptorˉallocator.Code.AsSpan());
        True(Codeˉoffset >= 0, "The canonical WVO omitted its allocator code extent.");
        Corruptedˉobject[
            checked(Codeˉoffset + (X64ˉnativeˉdescriptorˉallocator.Code.Length / 2))] ^= 0x01;
        Throwsˉinvalidˉoperation(
            "WVA descriptor allocator code",
            () => _ = X64ˉnativeˉdescriptorˉallocator.Read(
                Objectˉcodec.Readˉandˉverify(Corruptedˉobject)));

        const int Arenaˉbytes = 128;
        var State = new byte[Nativeˉdescriptorˉallocatorˉcontract.STATE_BYTES];
        var Arena = new byte[Arenaˉbytes];
        var Nativeˉstateˉallocation = Marshal.AllocHGlobal(
            Nativeˉdescriptorˉallocatorˉcontract.STATE_BYTES + 7);
        var Nativeˉrequestˉallocation = Marshal.AllocHGlobal(
            Nativeˉdescriptorˉallocatorˉcontract.REQUEST_BYTES + 7);
        var Nativeˉarenaˉallocation = Marshal.AllocHGlobal(Arenaˉbytes + 15);
        var Nativeˉstate = Alignˉpointer(Nativeˉstateˉallocation, 8);
        var Nativeˉrequest = Alignˉpointer(Nativeˉrequestˉallocation, 8);
        var Nativeˉarena = Alignˉpointer(Nativeˉarenaˉallocation, 16);
        var Arenaˉaddress = checked((ulong)Nativeˉarena.ToInt64());
        BinaryPrimitives.WriteUInt64LittleEndian(State, Arenaˉaddress);
        BinaryPrimitives.WriteUInt32LittleEndian(State.AsSpan(8), (uint)Arenaˉbytes);
        Marshal.Copy(State, 0, Nativeˉstate, State.Length);
        Marshal.Copy(Arena, 0, Nativeˉarena, Arena.Length);

        using var Executable = Nativeˉexecutableˉimage.Allocateˉwritable(
            X64ˉnativeˉpublicationˉlifetime.Plan(
                X64ˉnativeˉdescriptorˉallocator.Code.Length));
        try
        {
            Executable.Copyˉimage(X64ˉnativeˉdescriptorˉallocator.Code.ToArray());
            Executable.Sealˉexecutable();
            _ = Executable.Invoke(Address =>
            {
                var Leaf = Marshal.GetDelegateForFunctionPointer<
                    Nativeˉdescriptorˉallocatorˉleaf>(Address);

                uint Call(
                    Nativeˉdescriptorˉallocatorˉoperation operation,
                    uint payload,
                    uint owner,
                    Nativeˉdescriptorˉallocatorˉstatus expected)
                {
                    var Request = new byte[Nativeˉdescriptorˉallocatorˉcontract.REQUEST_BYTES];
                    BinaryPrimitives.WriteUInt32LittleEndian(
                        Request,
                        Nativeˉdescriptorˉallocatorˉcontract.FORMAT_VERSION);
                    BinaryPrimitives.WriteUInt32LittleEndian(
                        Request.AsSpan(4),
                        Nativeˉdescriptorˉallocatorˉcontract.REQUEST_BYTES);
                    BinaryPrimitives.WriteUInt32LittleEndian(
                        Request.AsSpan(8),
                        (uint)operation);
                    BinaryPrimitives.WriteUInt32LittleEndian(Request.AsSpan(12), payload);
                    BinaryPrimitives.WriteUInt32LittleEndian(Request.AsSpan(16), owner);
                    var Referenceˉstatus = Nativeˉdescriptorˉallocatorˉreference.Execute(
                        State,
                        Request,
                        Arena,
                        Arenaˉaddress);
                    Equal(expected, Referenceˉstatus);

                    var Nativeˉinput = new byte[Nativeˉdescriptorˉallocatorˉcontract.REQUEST_BYTES];
                    BinaryPrimitives.WriteUInt32LittleEndian(
                        Nativeˉinput,
                        Nativeˉdescriptorˉallocatorˉcontract.FORMAT_VERSION);
                    BinaryPrimitives.WriteUInt32LittleEndian(
                        Nativeˉinput.AsSpan(4),
                        Nativeˉdescriptorˉallocatorˉcontract.REQUEST_BYTES);
                    BinaryPrimitives.WriteUInt32LittleEndian(
                        Nativeˉinput.AsSpan(8),
                        (uint)operation);
                    BinaryPrimitives.WriteUInt32LittleEndian(Nativeˉinput.AsSpan(12), payload);
                    BinaryPrimitives.WriteUInt32LittleEndian(Nativeˉinput.AsSpan(16), owner);
                    Marshal.Copy(Nativeˉinput, 0, Nativeˉrequest, Nativeˉinput.Length);
                    var Nativeˉstatus = Leaf(
                        0,
                        0,
                        checked((ulong)Nativeˉstate.ToInt64()),
                        checked((ulong)Nativeˉrequest.ToInt64()),
                        checked((ulong)Nativeˉstate.ToInt64()),
                        checked((ulong)Nativeˉrequest.ToInt64()));
                    Equal((uint)expected, Nativeˉstatus);

                    var Nativeˉresult = new byte[Nativeˉinput.Length];
                    var Nativeˉstateˉbytes = new byte[State.Length];
                    var Nativeˉarenaˉbytes = new byte[Arena.Length];
                    Marshal.Copy(Nativeˉrequest, Nativeˉresult, 0, Nativeˉresult.Length);
                    Marshal.Copy(Nativeˉstate, Nativeˉstateˉbytes, 0, Nativeˉstateˉbytes.Length);
                    Marshal.Copy(Nativeˉarena, Nativeˉarenaˉbytes, 0, Nativeˉarenaˉbytes.Length);
                    Sequenceˉequal(Request, Nativeˉresult);
                    Sequenceˉequal(State, Nativeˉstateˉbytes);
                    Sequenceˉequal(Arena, Nativeˉarenaˉbytes);
                    return BinaryPrimitives.ReadUInt32LittleEndian(
                        Request.AsSpan(
                            Nativeˉdescriptorˉallocatorˉcontract.REQUEST_OWNER_TOKEN_OFFSET));
                }

                var First = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Acquire,
                    payload: 1,
                    owner: 0,
                    Nativeˉdescriptorˉallocatorˉstatus.Success);
                Equal(1u, First);
                Equal(
                    checked(Arenaˉaddress +
                        Nativeˉdescriptorˉallocatorˉcontract.BLOCK_HEADER_BYTES),
                    Readˉnativeˉrequestˉu64(
                        Nativeˉrequest,
                        Nativeˉdescriptorˉallocatorˉcontract.REQUEST_DATA_POINTER_OFFSET));
                var Second = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Acquire,
                    payload: 1,
                    owner: 0,
                    Nativeˉdescriptorˉallocatorˉstatus.Success);
                Equal(33u, Second);
                var Third = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Acquire,
                    payload: 1,
                    owner: 0,
                    Nativeˉdescriptorˉallocatorˉstatus.Success);
                Equal(65u, Third);
                var Fourth = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Acquire,
                    payload: 1,
                    owner: 0,
                    Nativeˉdescriptorˉallocatorˉstatus.Success);
                Equal(97u, Fourth);
                _ = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Acquire,
                    payload: 0,
                    owner: 0,
                    Nativeˉdescriptorˉallocatorˉstatus.Exhausted);

                _ = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Retain,
                    payload: 0,
                    First,
                    Nativeˉdescriptorˉallocatorˉstatus.Success);
                _ = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Release,
                    payload: 0,
                    First,
                    Nativeˉdescriptorˉallocatorˉstatus.Success);
                _ = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Release,
                    payload: 0,
                    Second,
                    Nativeˉdescriptorˉallocatorˉstatus.Success);
                _ = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Release,
                    payload: 0,
                    Fourth,
                    Nativeˉdescriptorˉallocatorˉstatus.Success);
                _ = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Release,
                    payload: 0,
                    Third,
                    Nativeˉdescriptorˉallocatorˉstatus.Success);
                _ = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Release,
                    payload: 0,
                    First,
                    Nativeˉdescriptorˉallocatorˉstatus.Success);

                Equal(
                    0u,
                    BinaryPrimitives.ReadUInt32LittleEndian(
                        State.AsSpan(
                            Nativeˉdescriptorˉallocatorˉcontract.STATE_ALLOCATED_BLOCKS_OFFSET)));
                Equal(
                    0u,
                    BinaryPrimitives.ReadUInt32LittleEndian(
                        State.AsSpan(
                            Nativeˉdescriptorˉallocatorˉcontract.STATE_CHARGED_BYTES_OFFSET)));
                Equal(1u, BinaryPrimitives.ReadUInt32LittleEndian(State.AsSpan(16)));
                Equal((uint)Arenaˉbytes, BinaryPrimitives.ReadUInt32LittleEndian(Arena));
                Equal(
                    Nativeˉdescriptorˉallocatorˉcontract.FREE_BLOCK_MAGIC,
                    BinaryPrimitives.ReadUInt32LittleEndian(Arena.AsSpan(12)));

                var Reused = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Acquire,
                    payload: 112,
                    owner: 0,
                    Nativeˉdescriptorˉallocatorˉstatus.Success);
                Equal(1u, Reused);
                _ = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Release,
                    payload: 0,
                    Reused,
                    Nativeˉdescriptorˉallocatorˉstatus.Success);
                _ = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Release,
                    payload: 0,
                    Reused,
                    Nativeˉdescriptorˉallocatorˉstatus.Invalidˉowner);
                _ = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Retain,
                    payload: 0,
                    owner: 0,
                    Nativeˉdescriptorˉallocatorˉstatus.Success);
                _ = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Release,
                    payload: 0,
                    owner: 0,
                    Nativeˉdescriptorˉallocatorˉstatus.Success);
                _ = Call(
                    (Nativeˉdescriptorˉallocatorˉoperation)0,
                    payload: 0,
                    owner: 0,
                    Nativeˉdescriptorˉallocatorˉstatus.Invalidˉrequest);
                _ = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Acquire,
                    payload: 1,
                    owner: 1,
                    Nativeˉdescriptorˉallocatorˉstatus.Invalidˉrequest);
                _ = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Retain,
                    payload: 1,
                    owner: 0,
                    Nativeˉdescriptorˉallocatorˉstatus.Invalidˉrequest);
                _ = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Acquire,
                    payload: checked((uint)Bytecodeˉlimits.MAX_BYTE_DATA_BYTES + 1),
                    owner: 0,
                    Nativeˉdescriptorˉallocatorˉstatus.Invalidˉrequest);
                _ = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Acquire,
                    payload: checked((uint)Bytecodeˉlimits.MAX_BYTE_DATA_BYTES),
                    owner: 0,
                    Nativeˉdescriptorˉallocatorˉstatus.Exhausted);

                var Overflowˉowner = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Acquire,
                    payload: 1,
                    owner: 0,
                    Nativeˉdescriptorˉallocatorˉstatus.Success);
                BinaryPrimitives.WriteUInt32LittleEndian(Arena.AsSpan(4), uint.MaxValue);
                Marshal.Copy(Arena, 0, Nativeˉarena, Arena.Length);
                _ = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Retain,
                    payload: 0,
                    Overflowˉowner,
                    Nativeˉdescriptorˉallocatorˉstatus.Referenceˉoverflow);
                BinaryPrimitives.WriteUInt32LittleEndian(Arena.AsSpan(4), 1);
                Marshal.Copy(Arena, 0, Nativeˉarena, Arena.Length);
                _ = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Release,
                    payload: 0,
                    Overflowˉowner,
                    Nativeˉdescriptorˉallocatorˉstatus.Success);

                BinaryPrimitives.WriteUInt32LittleEndian(Arena.AsSpan(8), 1);
                Marshal.Copy(Arena, 0, Nativeˉarena, Arena.Length);
                _ = Call(
                    Nativeˉdescriptorˉallocatorˉoperation.Acquire,
                    payload: 1,
                    owner: 0,
                    Nativeˉdescriptorˉallocatorˉstatus.Corruptˉstate);

                return 0;
            });
        }
        finally
        {
            Marshal.FreeHGlobal(Nativeˉarenaˉallocation);
            Marshal.FreeHGlobal(Nativeˉrequestˉallocation);
            Marshal.FreeHGlobal(Nativeˉstateˉallocation);
        }

        static IntPtr Alignˉpointer(IntPtr value, int alignment)
        {
            var Address = checked((ulong)value.ToInt64());
            return new(checked((long)((Address + checked((uint)alignment - 1)) &
                ~checked((ulong)alignment - 1))));
        }

        static ulong Readˉnativeˉrequestˉu64(IntPtr request, int offset) =>
            unchecked((ulong)Marshal.ReadInt64(request, offset));
    }

    private static void Nativeˉdynamicˉtextˉagrees()
    {
        const string Source = """
            module Nativeˉdynamicˉtext profile hosted;
            capability console.write_line;
            capability diagnostic.write_line;
            record Nativeˉtag { Value: i32; }
            enum Nativeˉstate { Ready = 0; Running = 1; }
            enum Nativeˉedge { Zero = 0; Second = 2; Maximum = 2147483647; }
            data Euro: bytes = [226, 130, 172];
            data Quoteˉedges: bytes = [34, 92, 8, 12, 10, 13, 9, 0, 31, 32, 126, 127, 195, 169, 226, 130, 172, 240, 159, 152, 128, 244, 143, 191, 191];

            fn Compose(State: Nativeˉstate, Delta: i32, Byte: u8, Count: u32) -> text {
                return Textˉconcat(
                    Enumˉname(State),
                    Textˉconcat(
                        ":",
                        Textˉconcat(
                            I32ˉformat(Delta),
                            Textˉconcat(
                                ":",
                                Textˉconcat(U8ˉformat(Byte), Textˉconcat(":", U32ˉformat(Count))))
                        )
                    )
                );
            }

            fn Emit(Value: text) -> void {
                console.write_line(Value);
                diagnostic.write_line(Textˉquote(Textˉconcat(Value, Textˉfromˉutf8(Euro))));
                return;
            }

            export fn Main() -> i32 {
                Emit(Compose(Nativeˉstate.Running, -3, 7u8, 42u32));
                console.write_line(Textˉconcat(
                    I32ˉformat(-2147483647 - 1),
                    Textˉconcat(":", U32ˉformat(4294967295u32))));
                console.write_line(Textˉconcat(I32ˉformat(0), Textˉconcat(":", U32ˉformat(0u32))));
                diagnostic.write_line(Textˉquote(Textˉfromˉutf8(Quoteˉedges)));
                diagnostic.write_line(Textˉconcat(
                    Enumˉname(Nativeˉedge.Second),
                    Textˉconcat(":", Enumˉname(Nativeˉedge.Maximum))));
                return 42;
            }
            """;
        var Verified = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess(Source));
        var Authorized = ImmutableHashSet.Create(
            StringComparer.Ordinal,
            Capabilityˉcatalog.CONSOLE_WRITE_LINE,
            Capabilityˉcatalog.DIAGNOSTIC_WRITE_LINE);

        var Referenceˉoutput = new StringWriter();
        var Referenceˉdiagnostic = new StringWriter();
        var Referenceˉresources = new Hostedˉresourceˉcontext(
            [],
            Referenceˉoutput,
            Referenceˉdiagnostic);
        var Reference = new Referenceˉruntime(
            Verified,
            new Referenceˉcapabilityˉhost(Referenceˉresources),
            new(Authorized)).Runˉmain();
        Equal(42, Reference.Exitˉcode);
        Equal("Running:-3:7:42\n-2147483648:4294967295\n0:0\n", Referenceˉoutput.ToString());
        Equal(
            "\"Running:-3:7:42\\u20AC\"\n" +
            "\"\\\"\\\\\\b\\f\\n\\r\\t\\u0000\\u001F ~\\u007F\\u00E9\\u20AC\\uD83D\\uDE00\\uDBFF\\uDFFF\"\n" +
            "Second:Maximum\n",
            Referenceˉdiagnostic.ToString());

        var First = X64ˉnativeˉbackend.Compile(Verified);
        var Second = X64ˉnativeˉbackend.Compile(Verified);
        Sequenceˉequal(First.Fragment.Code, Second.Fragment.Code);
        Sequenceˉequal(First.Fragment.Types, Second.Fragment.Types);
        var Operations = First.Module.Functions
            .SelectMany(Function => Function.Blocks)
            .SelectMany(Block => Block.Operations)
            .ToImmutableArray();
        True(Operations.Any(Operation => Operation is Nativeˉenumˉname), "Native IR omitted enum.name.");
        True(Operations.Count(Operation => Operation is Nativeˉintegerˉformat) == 7,
            "Native IR omitted integer formatting.");
        True(Operations.Any(Operation => Operation is Nativeˉtextˉconcat), "Native IR omitted text.concat.");
        True(Operations.Any(Operation => Operation is Nativeˉtextˉfromˉutf8), "Native IR omitted text.from_utf8.");
        True(Operations.Any(Operation => Operation is Nativeˉtextˉquote), "Native IR omitted text.quote.");
        True(Operations.Any(Operation => Operation is Nativeˉvoidˉcall), "Native IR omitted void calls.");
        True(First.Module.Functions.Any(Function => Function.Returnˉtype == Nativeˉvalueˉtype.Borrowedˉtext),
            "Native IR omitted a descriptor-returning function.");
        True(First.Module.Functions.Any(Function => Function.Returnˉtype == Nativeˉvalueˉtype.Void),
            "Native IR omitted a void function.");
        foreach (var Service in new[]
        {
            Nativeˉservice.Enumˉname,
            Nativeˉservice.Textˉconcat,
            Nativeˉservice.Textˉquote,
            Nativeˉservice.I32ˉformat,
            Nativeˉservice.U32ˉformat,
        })
        {
            var Firstˉservice = X64ˉnativeˉtextˉservices.Build(Service, First.Fragment.Types);
            var Secondˉservice = X64ˉnativeˉtextˉservices.Build(Service, First.Fragment.Types);
            Sequenceˉequal(Firstˉservice, Secondˉservice);
            X64ˉnativeˉtextˉservices.Verify(Service, Firstˉservice.AsSpan(), First.Fragment.Types);
            var Corruptedˉservice = Firstˉservice.ToArray();
            Corruptedˉservice[0] ^= 0x01;
            Throwsˉinvalidˉoperation(
                $"Native {Service} service identity",
                () => X64ˉnativeˉtextˉservices.Verify(
                    Service,
                    Corruptedˉservice,
                    First.Fragment.Types));
        }
        Equal(
            323,
            X64ˉnativeˉtextˉservices.ENUM_NAME_CANONICAL_SIZE);
        Equal(
            X64ˉnativeˉtextˉservices.TEXT_CONCAT_CANONICAL_SIZE,
            X64ˉnativeˉtextˉservices.Build(Nativeˉservice.Textˉconcat).Length);
        Equal(
            X64ˉnativeˉtextˉservices.I32_FORMAT_CANONICAL_SIZE,
            X64ˉnativeˉtextˉservices.Build(Nativeˉservice.I32ˉformat).Length);
        Equal(
            X64ˉnativeˉtextˉservices.U32_FORMAT_CANONICAL_SIZE,
            X64ˉnativeˉtextˉservices.Build(Nativeˉservice.U32ˉformat).Length);
        Equal(
            X64ˉnativeˉtextˉservices.TEXT_QUOTE_CANONICAL_SIZE,
            X64ˉnativeˉtextˉservices.Build(Nativeˉservice.Textˉquote).Length);
        var Enumˉbundle = X64ˉnativeˉtextˉservices.Build(
            Nativeˉservice.Enumˉname,
            First.Fragment.Types);
        True(
            Enumˉbundle.Length > X64ˉnativeˉtextˉservices.ENUM_NAME_CANONICAL_SIZE,
            "Native enum-name service omitted its immutable metadata.");
        var Enumˉmetadata = Enumˉbundle.AsSpan()[X64ˉnativeˉtextˉservices.ENUM_NAME_CANONICAL_SIZE..];
        Equal(0x4E455657u, BinaryPrimitives.ReadUInt32LittleEndian(Enumˉmetadata));
        Equal(1u, BinaryPrimitives.ReadUInt32LittleEndian(Enumˉmetadata[4..]));
        Equal((uint)Enumˉmetadata.Length, BinaryPrimitives.ReadUInt32LittleEndian(Enumˉmetadata[8..]));
        Equal((uint)First.Fragment.Types.Length, BinaryPrimitives.ReadUInt32LittleEndian(Enumˉmetadata[12..]));
        Equal(
            (uint)First.Fragment.Types.OfType<Enumˉtypeˉdeclaration>().Sum(Enum => Enum.Members.Length),
            BinaryPrimitives.ReadUInt32LittleEndian(Enumˉmetadata[16..]));
        var Corruptedˉmetadata = Enumˉbundle.ToArray();
        Corruptedˉmetadata[^1] ^= 0x01;
        Throwsˉinvalidˉoperation(
            "Native Enumˉname service identity",
            () => X64ˉnativeˉtextˉservices.Verify(
                Nativeˉservice.Enumˉname,
                Corruptedˉmetadata,
                First.Fragment.Types));
        var Corruptedˉmetadataˉheader = Enumˉbundle.ToArray();
        BinaryPrimitives.WriteUInt32LittleEndian(
            Corruptedˉmetadataˉheader.AsSpan(X64ˉnativeˉtextˉservices.ENUM_NAME_CANONICAL_SIZE + 8),
            uint.MaxValue);
        Throwsˉinvalidˉoperation(
            "Native Enumˉname service identity",
            () => X64ˉnativeˉtextˉservices.Verify(
                Nativeˉservice.Enumˉname,
                Corruptedˉmetadataˉheader,
                First.Fragment.Types));

        void Runˉnative(ImmutableArray<byte> code)
        {
            using var Output = new Nativeˉoutputˉcapture();
            using var Diagnostic = new Nativeˉoutputˉcapture();
            var Resources = new Hostedˉresourceˉcontext([], TextWriter.Null, TextWriter.Null);
            Equal(
                Reference.Exitˉcode,
                X64ˉnativeˉexecutor.Executeˉi32(
                    First.Fragment with { Code = code },
                    maximumˉinstructions: Reference.Executedˉinstructions,
                    hostˉservices: new(Output.Channel, Authorized, Resources, Diagnostic.Channel)));
            Equal(Referenceˉoutput.ToString(), Output.Readˉtext());
            Equal(Referenceˉdiagnostic.ToString(), Diagnostic.Readˉtext());
        }

        Runˉnative(First.Fragment.Code);
        var Object = Nativeˉobjectˉsink.Writeˉwvo(First.Fragment);
        var Linked = Linkˉsuccess([Object.ToArray()], new(Linkˉcontract.DEFAULT_BASE_ADDRESS, "Main"));
        Runˉnative(Linked.Imageˉbytes);

        var Invalidˉutf8 = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess("""
            module Nativeˉinvalidˉutf8 profile portable;
            data Invalid: bytes = [192, 175];
            export fn Main() -> i32 {
                let Value: text = Textˉfromˉutf8(Invalid);
                return 0;
            }
            """));
        Throwsˉruntime(
            "WVR3014",
            () => _ = new Referenceˉruntime(
                Invalidˉutf8,
                new Referenceˉcapabilityˉhost(TextWriter.Null),
                Runtimeˉoptions.Portableˉdefaults).Runˉmain());
        Throwsˉnativeˉtrap(
            "WVR3014",
            () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                X64ˉnativeˉbackend.Compile(Invalidˉutf8).Fragment));

        var Valueˉlimit = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess("""
            module Nativeˉtextˉvalueˉlimit profile portable;
            export fn Main() -> i32 {
                var Value: text = "a";
                var Power: i32 = 0;
                while Power < 20 {
                    Value = Textˉconcat(Value, Value);
                    Power = Power + 1;
                }
                Value = Textˉconcat(Value, "a");
                return 0;
            }
            """));
        Throwsˉruntime(
            "WVR3012",
            () => _ = new Referenceˉruntime(
                Valueˉlimit,
                new Referenceˉcapabilityˉhost(TextWriter.Null),
                Runtimeˉoptions.Portableˉdefaults).Runˉmain());
        Throwsˉnativeˉtrap(
            "WVR3012",
            () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                X64ˉnativeˉbackend.Compile(Valueˉlimit).Fragment,
                maximumˉinstructions: 10_000));

        var Arenaˉexhaustion = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess("""
            module Nativeˉtextˉarena profile portable;
            export fn Main() -> i32 {
                var Value: text = "a";
                var Power: i32 = 0;
                while Power < 19 {
                    Value = Textˉconcat(Value, Value);
                    Power = Power + 1;
                }
                var Copy: text = Value;
                var Count: i32 = 0;
                while Count < 276 {
                    Copy = Textˉconcat(Value, "b");
                    Count = Count + 1;
                }
                return 0;
            }
            """));
        Throwsˉnativeˉtrap(
            "WVR3018",
            () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                X64ˉnativeˉbackend.Compile(Arenaˉexhaustion).Fragment,
                maximumˉinstructions: 10_000));

        var Quoteˉvalueˉlimit = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess("""
            module Nativeˉquoteˉvalueˉlimit profile portable;
            data Euro: bytes = [226, 130, 172];
            export fn Main() -> i32 {
                var Value: text = Textˉfromˉutf8(Euro);
                var Power: i32 = 0;
                while Power < 18 {
                    Value = Textˉconcat(Value, Value);
                    Power = Power + 1;
                }
                Value = Textˉquote(Value);
                return 0;
            }
            """));
        Throwsˉruntime(
            "WVR3012",
            () => _ = new Referenceˉruntime(
                Quoteˉvalueˉlimit,
                new Referenceˉcapabilityˉhost(TextWriter.Null),
                Runtimeˉoptions.Portableˉdefaults).Runˉmain());
        Throwsˉnativeˉtrap(
            "WVR3012",
            () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                X64ˉnativeˉbackend.Compile(Quoteˉvalueˉlimit).Fragment,
                maximumˉinstructions: 10_000));

        var Quoteˉarenaˉexhaustion = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess("""
            module Nativeˉquoteˉarena profile portable;
            export fn Main() -> i32 {
                var Value: text = "a";
                var Power: i32 = 0;
                while Power < 18 {
                    Value = Textˉconcat(Value, Value);
                    Power = Power + 1;
                }
                var Quoted: text = "";
                var Count: i32 = 0;
                while Count < 511 {
                    Quoted = Textˉquote(Value);
                    Count = Count + 1;
                }
                return 0;
            }
            """));
        Throwsˉnativeˉtrap(
            "WVR3018",
            () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                X64ˉnativeˉbackend.Compile(Quoteˉarenaˉexhaustion).Fragment,
                maximumˉinstructions: 20_000));

        var Longˉmember = $"N{new string('a', 127)}";
        var Enumˉarenaˉexhaustion = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess($$"""
            module Nativeˉenumˉarena profile portable;
            enum Nativeˉlong { {{Longˉmember}} = 0; }
            export fn Main() -> i32 {
                var Name: text = "";
                var Count: i32 = 0;
                while Count < 1048578 {
                    Name = Enumˉname(Nativeˉlong.{{Longˉmember}});
                    Count = Count + 1;
                }
                return 0;
            }
            """));
        Throwsˉnativeˉtrap(
            "WVR3018",
            () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                X64ˉnativeˉbackend.Compile(Enumˉarenaˉexhaustion).Fragment,
                maximumˉinstructions: 100_000_000));

        var Descriptorˉfunction = First.Module.Functions
            .Select((Function, Index) => (Function, Index))
            .First(Item => Item.Function.Returnˉtype == Nativeˉvalueˉtype.Borrowedˉtext);
        var Descriptorˉsymbol = First.Fragment.Symbols.Single(Symbol =>
            StringComparer.Ordinal.Equals(Symbol.Name, $"$function_{Descriptorˉfunction.Index:D4}"));
        var Corruptedˉhiddenˉresult = First.Fragment.Code.ToArray();
        var Descriptorˉstart = checked((int)Descriptorˉsymbol.Offset);
        var Frameˉallocation = Corruptedˉhiddenˉresult.AsSpan(
                Descriptorˉstart,
                checked((int)Descriptorˉsymbol.Size))
            .IndexOf(new byte[] { 0x48, 0x81, 0xEC });
        True(Frameˉallocation >= 0, "Descriptor-returning native function omitted its frame allocation.");
        Corruptedˉhiddenˉresult[Descriptorˉstart + Frameˉallocation + 8] ^= 0x01;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉhiddenˉresult.ToImmutableArray() }));

        var Invalidˉtypes = First.Fragment.Types.SetItem(
            0,
            new Enumˉtypeˉdeclaration(
                "",
                [new("Ready", 0), new("Running", 1)]));
        Throwsˉnative(
            "WVN3009",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Types = Invalidˉtypes }));
    }

    private static void Nativeˉwvdumpˉstructuralˉparserˉruns()
    {
        const string Reportˉmarker = "fn Stringˉvalue(Input: bytes, Cursor: u32) -> text";
        var Reportˉoffset = WVDUMP_CORE_SOURCE.IndexOf(Reportˉmarker, StringComparison.Ordinal);
        True(Reportˉoffset > 0, "The Windvale wvdump structural/report boundary is missing.");
        var Structuralˉsource = WVDUMP_CORE_SOURCE[..Reportˉoffset]
            .Replace("profile hosted", "profile portable", StringComparison.Ordinal);
        foreach (var Capability in new[]
        {
            "console.write_line",
            "diagnostic.write_line",
            "file.read_bytes",
            "process.argument",
            "process.argument_count",
        })
        {
            Structuralˉsource = Structuralˉsource
                .Replace($"capability {Capability};\r\n", "", StringComparison.Ordinal)
                .Replace($"capability {Capability};\n", "", StringComparison.Ordinal);
        }
        Structuralˉsource +=
            """
            export fn Main() -> i32 {
                let Envelope: Wvbˉinspection = Inspectˉwvbˉenvelope(Validˉmodule);
                if Envelope.Status != Wvbˉstatus.Valid { return 1; }
                if Envelope.Sectionsˉseen != 7u32 { return 2; }
                if Envelope.Failureˉoffset != 95u32 { return 3; }

                let Payload: Wvbˉpayloadˉinspection = Inspectˉwvbˉpayloads(Validˉmodule);
                if Payload.Status != Wvbˉstatus.Valid { return 4; }
                if Payload.Declarationsˉseen != 1u32 { return 5; }
                if Payload.Instructionsˉseen != 0u32 { return 6; }
                return 42;
            }
            """;

        var Verified = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess(Structuralˉsource));
        var Interpreted = new Referenceˉruntime(
            Verified,
            new Referenceˉcapabilityˉhost(TextWriter.Null),
            Runtimeˉoptions.Portableˉdefaults).Runˉmain();
        Equal(42, Interpreted.Exitˉcode);

        var Native = X64ˉnativeˉbackend.Compile(Verified);
        True(Native.Module.Types.Length == 5, "Native wvdump omitted structural nominal metadata.");
        True(
            Native.Module.Functions.SelectMany(Function => Function.Blocks)
                .SelectMany(Block => Block.Operations)
                .Count(Operation => Operation is Nativeˉrecordˉcreate) >= 4,
            "Native wvdump omitted structural record construction.");
        Equal(
            Interpreted.Exitˉcode,
            X64ˉnativeˉexecutor.Executeˉi32(
                Native.Fragment,
                maximumˉinstructions: Interpreted.Executedˉinstructions));

        var Object = Nativeˉobjectˉsink.Writeˉwvo(Native.Fragment);
        var Linked = Linkˉsuccess(
            [Object.ToArray()],
            new(Linkˉcontract.DEFAULT_BASE_ADDRESS, "Main"));
        Equal(
            Interpreted.Exitˉcode,
            X64ˉnativeˉexecutor.Executeˉi32(
                Native.Fragment with { Code = Linked.Imageˉbytes },
                maximumˉinstructions: Interpreted.Executedˉinstructions));
    }

    private static void Nativeˉwvdumpˉcompleteˉruns()
    {
        var Input = Compileˉsuccess(NATIVE_CONSTANT_SOURCE).ToImmutableArray();
        var Verified = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess(WVDUMP_CORE_SOURCE));
        var Authorized = ImmutableHashSet.Create(
            StringComparer.Ordinal,
            Capabilityˉcatalog.CONSOLE_WRITE_LINE,
            Capabilityˉcatalog.DIAGNOSTIC_WRITE_LINE,
            Capabilityˉcatalog.FILE_READ_BYTES,
            Capabilityˉcatalog.PROCESS_ARGUMENT,
            Capabilityˉcatalog.PROCESS_ARGUMENT_COUNT);

        Testˉfileˉreader Makeˉreader() => new((Name, Maximum) =>
        {
            Equal("input.wvb", Name);
            True(Input.Length <= Maximum, "The complete wvdump fixture exceeded the hosted reader bound.");
            return Input;
        });

        Hostedˉresourceˉcontext Makeˉresources(
            TextWriter output,
            TextWriter diagnostic,
            Testˉfileˉreader reader,
            string resourceˉname = "input.wvb") =>
            new([resourceˉname], output, diagnostic, reader);

        var Referenceˉoutput = new StringWriter();
        var Referenceˉdiagnostic = new StringWriter();
        var Referenceˉreader = Makeˉreader();
        var Reference = new Referenceˉruntime(
            Verified,
            new Referenceˉcapabilityˉhost(Makeˉresources(
                Referenceˉoutput,
                Referenceˉdiagnostic,
                Referenceˉreader)),
            new(Authorized)).Runˉmain();
        Equal(0, Reference.Exitˉcode);
        Equal(string.Empty, Referenceˉdiagnostic.ToString());
        True(Referenceˉoutput.ToString().StartsWith("wvdump 1\nmodule version=1.11", StringComparison.Ordinal),
            "The complete Windvale wvdump report omitted its module header.");
        True(Referenceˉoutput.ToString().Contains("name=\"Main\"", StringComparison.Ordinal),
            "The complete Windvale wvdump report omitted its function declaration.");
        Equal(1, Referenceˉreader.Readˉcount);

        var First = X64ˉnativeˉbackend.Compile(Verified);
        var Second = X64ˉnativeˉbackend.Compile(Verified);
        Sequenceˉequal(First.Fragment.Code, Second.Fragment.Code);
        Sequenceˉequal(First.Fragment.Types, Second.Fragment.Types);
        Sequenceˉequal(
            Enum.GetValues<Nativeˉservice>()
                .Where(Service => Service != Nativeˉservice.Fileˉwriteˉbytes),
            First.Fragment.Requiredˉservices);
        var Operations = First.Module.Functions
            .SelectMany(Function => Function.Blocks)
            .SelectMany(Block => Block.Operations)
            .ToImmutableArray();
        True(Operations.Count(Operation => Operation is Nativeˉtextˉconcat) >= 100,
            "Complete native wvdump omitted its report composition.");
        True(Operations.Any(Operation => Operation is Nativeˉdiagnosticˉwriteˉline),
            "Complete native wvdump omitted diagnostics.");
        True(Operations.Any(Operation => Operation is Nativeˉvoidˉcall),
            "Complete native wvdump omitted void calls.");
        True(First.Module.Functions.Any(Function => Function.Returnˉtype == Nativeˉvalueˉtype.Borrowedˉtext),
            "Complete native wvdump omitted descriptor-returning helpers.");

        var Nativeˉpath = Path.Combine(
            Path.GetTempPath(),
            $"windvale-native-wvdump-{Guid.NewGuid():N}.wvb");
        void Runˉnative(ImmutableArray<byte> code)
        {
            using var Output = new Nativeˉoutputˉcapture();
            using var Diagnostic = new Nativeˉoutputˉcapture();
            var Reader = new Testˉfileˉreader((_, _) =>
                throw new InvalidOperationException("Native execution called the Stage 0 file reader."));
            Equal(
                Reference.Exitˉcode,
                X64ˉnativeˉexecutor.Executeˉi32(
                    First.Fragment with { Code = code },
                    maximumˉinstructions: Reference.Executedˉinstructions,
                    hostˉservices: new(
                        Output.Channel,
                        Authorized,
                        Makeˉresources(
                            TextWriter.Null,
                            TextWriter.Null,
                            Reader,
                            Nativeˉpath),
                        Diagnostic.Channel,
                        Nativeˉfileˉinput.Hostˉfileˉsystem())));
            Equal(Referenceˉoutput.ToString(), Output.Readˉtext());
            Equal(Referenceˉdiagnostic.ToString(), Diagnostic.Readˉtext());
            Equal(0, Reader.Readˉcount);
        }

        try
        {
            File.WriteAllBytes(Nativeˉpath, Input.AsSpan());
            Runˉnative(First.Fragment.Code);
            var Object = Nativeˉobjectˉsink.Writeˉwvo(First.Fragment);
            var Linked = Linkˉsuccess(
                [Object.ToArray()],
                new(Linkˉcontract.DEFAULT_BASE_ADDRESS, "Main"));
            Runˉnative(Linked.Imageˉbytes);
        }
        finally
        {
            File.Delete(Nativeˉpath);
        }
    }

    private static void Nativeˉborrowedˉbytesˉagree()
    {
        var Verified = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess(NATIVE_BYTES_SOURCE));
        var Interpreted = new Referenceˉruntime(
            Verified,
            new Referenceˉcapabilityˉhost(TextWriter.Null),
            Runtimeˉoptions.Portableˉdefaults).Runˉmain();
        Equal(42, Interpreted.Exitˉcode);

        var First = X64ˉnativeˉbackend.Compile(Verified);
        var Second = X64ˉnativeˉbackend.Compile(Verified);
        Sequenceˉequal(First.Fragment.Code, Second.Fragment.Code);
        Sequenceˉequal(First.Fragment.Symbols, Second.Fragment.Symbols);
        Sequenceˉequal(First.Fragment.Patches, Second.Fragment.Patches);
        True(
            First.Module.Data.Single() is Nativeˉbytesˉdata,
            "Native machine IR did not retain immutable byte data.");
        Sequenceˉequal(
            new byte[] { 42, 1, 0, 0, 0, 255, 255, 255, 255 },
            ((Nativeˉbytesˉdata)First.Module.Data.Single()).Bytes);
        var Operations = First.Module.Functions
            .SelectMany(Function => Function.Blocks)
            .SelectMany(Block => Block.Operations)
            .ToImmutableArray();
        True(Operations.Any(Operation => Operation is Nativeˉstaticˉbytesˉconstant),
            "Native machine IR omitted the static borrowed-bytes value.");
        True(Operations.Any(Operation => Operation is Nativeˉbytesˉslice),
            "Native machine IR omitted the bounded byte slice.");
        Sequenceˉequal(
            Enum.GetValues<Nativeˉbytesˉreadˉkind>(),
            Operations
                .OfType<Nativeˉbytesˉread>()
                .Select(Operation => Operation.Kind)
                .Distinct()
                .Order());
        True(Operations.Any(Operation => Operation is Nativeˉbytesˉlength),
            "Native machine IR omitted the byte length.");
        Equal(2, Operations.OfType<Nativeˉbytesˉfromˉu8>().Count());
        Equal(2, Operations.OfType<Nativeˉbytesˉfromˉu16ˉlittle>().Count());
        True(Operations.Any(Operation => Operation is Nativeˉbytesˉfromˉu32ˉlittle),
            "Native machine IR omitted little-endian byte construction.");
        True(Operations.Any(Operation => Operation is Nativeˉu32ˉfromˉu8),
            "Native machine IR omitted the lossless u8-to-u32 conversion.");
        True(Operations.Any(Operation => Operation is Nativeˉu32ˉbinary),
            "Native machine IR omitted checked u32 arithmetic.");
        True(Operations.Any(Operation => Operation is Nativeˉu32ˉcomparison),
            "Native machine IR omitted u32 comparisons.");
        True(Operations.Any(Operation => Operation is Nativeˉu8ˉcomparison),
            "Native machine IR omitted u8 comparisons.");

        _ = Nativeˉfragmentˉverifier.Verify(First.Fragment);

        var Encodedˉownedˉthreshold = First.Fragment.Code.AsSpan().IndexOf(new byte[]
        {
            0x44, 0x89, 0xC1,
            0x81, 0xF9, 0x40, 0x00, 0x00, 0x00,
            0x0F, 0x83,
        });
        True(Encodedˉownedˉthreshold >= 0, "Native bytes.concat omitted its owned-buffer threshold.");
        var Corruptedˉownedˉthreshold = First.Fragment.Code.ToArray();
        Corruptedˉownedˉthreshold[Encodedˉownedˉthreshold + 5] = 0x3F;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉownedˉthreshold.ToImmutableArray() }));

        var Encodedˉu8ˉstart = First.Fragment.Code.AsSpan().IndexOf(new byte[]
        {
            0x41, 0x8B, 0x47, Nativeˉexecutionˉcontextˉcontract.TEXT_ARENA_USED_OFFSET,
            0x41, 0x89, 0xC1,
            0x89, 0xC1,
            0x83, 0xC1, 0x01,
            0x0F, 0x82,
        });
        True(Encodedˉu8ˉstart >= 0, "Native bytes.from_u8 omitted its checked arena allocation.");

        var Corruptedˉu8ˉallocation = First.Fragment.Code.ToArray();
        Corruptedˉu8ˉallocation[Encodedˉu8ˉstart + 11] = 0x02;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉu8ˉallocation.ToImmutableArray() }));

        var Corruptedˉu8ˉstore = First.Fragment.Code.ToArray();
        Corruptedˉu8ˉstore[Encodedˉu8ˉstart + 69] = 0x89;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉu8ˉstore.ToImmutableArray() }));

        var Corruptedˉu8ˉalias = First.Fragment.Code.ToArray();
        Corruptedˉu8ˉalias.AsSpan(Encodedˉu8ˉstart + 46, sizeof(int)).CopyTo(
            Corruptedˉu8ˉalias.AsSpan(Encodedˉu8ˉstart + 65, sizeof(int)));
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉu8ˉalias.ToImmutableArray() }));

        var Encodedˉu32ˉstart = First.Fragment.Code.AsSpan().IndexOf(new byte[]
        {
            0x41, 0x8B, 0x47, Nativeˉexecutionˉcontextˉcontract.TEXT_ARENA_USED_OFFSET,
            0x41, 0x89, 0xC1,
            0x89, 0xC1,
            0x83, 0xC1, 0x04,
            0x0F, 0x82,
        });
        True(Encodedˉu32ˉstart >= 0, "Native bytes.from_u32_little omitted its checked arena allocation.");
        var Corruptedˉu32ˉalias = First.Fragment.Code.ToArray();
        Corruptedˉu32ˉalias.AsSpan(Encodedˉu32ˉstart + 46, sizeof(int)).CopyTo(
            Corruptedˉu32ˉalias.AsSpan(Encodedˉu32ˉstart + 65, sizeof(int)));
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉu32ˉalias.ToImmutableArray() }));

        var Encodedˉu16ˉcomparison = First.Fragment.Code.AsSpan().IndexOf(new byte[]
        {
            0x3D, 0xFF, 0xFF, 0x00, 0x00,
            0x0F, 0x87,
        });
        var Encodedˉu16ˉstart = Encodedˉu16ˉcomparison - 7;
        True(Encodedˉu16ˉstart >= 0, "Native bytes.from_u16_little omitted its checked range guard.");

        var Corruptedˉu16ˉmaximum = First.Fragment.Code.ToArray();
        Corruptedˉu16ˉmaximum[Encodedˉu16ˉstart + 8] = 0xFE;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉu16ˉmaximum.ToImmutableArray() }));

        var Corruptedˉu16ˉbranch = First.Fragment.Code.ToArray();
        Corruptedˉu16ˉbranch[Encodedˉu16ˉstart + 13] = 0x86;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉu16ˉbranch.ToImmutableArray() }));

        var Corruptedˉu16ˉallocation = First.Fragment.Code.ToArray();
        Corruptedˉu16ˉallocation[Encodedˉu16ˉstart + 29] = 0x03;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉu16ˉallocation.ToImmutableArray() }));

        var Corruptedˉu16ˉstore = First.Fragment.Code.ToArray();
        Corruptedˉu16ˉstore[Encodedˉu16ˉstart + 87] = 0x90;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉu16ˉstore.ToImmutableArray() }));

        var Corruptedˉu16ˉalias = First.Fragment.Code.ToArray();
        Corruptedˉu16ˉalias.AsSpan(Encodedˉu16ˉstart + 64, sizeof(int)).CopyTo(
            Corruptedˉu16ˉalias.AsSpan(Encodedˉu16ˉstart + 83, sizeof(int)));
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉu16ˉalias.ToImmutableArray() }));

        var Corruptedˉu16ˉfailure = First.Fragment.Code.ToArray();
        Corruptedˉu16ˉfailure[Encodedˉu16ˉstart + 99] = 0x00;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉu16ˉfailure.ToImmutableArray() }));

        Equal(
            42,
            X64ˉnativeˉexecutor.Executeˉi32(
                First.Fragment,
                maximumˉinstructions: Interpreted.Executedˉinstructions,
                maximumˉcallˉdepth: 2));
        var Objectˉbytes = Nativeˉobjectˉsink.Writeˉwvo(First.Fragment);
        Sequenceˉequal(Objectˉbytes, Nativeˉobjectˉsink.Writeˉwvo(Second.Fragment));
        var Linked = Linkˉsuccess(
            [Objectˉbytes.ToArray()],
            new(Linkˉcontract.DEFAULT_BASE_ADDRESS, "Main"));
        Equal(
            42,
            X64ˉnativeˉexecutor.Executeˉi32(
                First.Fragment with { Code = Linked.Imageˉbytes },
                maximumˉinstructions: Interpreted.Executedˉinstructions,
                maximumˉcallˉdepth: 2));

        var U16ˉoverflow = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess("""
            module Nativeˉu16ˉoverflow profile portable;

            export fn Main() -> i32 {
                Bytesˉfromˉu16ˉlittle(65536u32);
                return 0;
            }
            """));
        Throwsˉruntime(
            "WVR3016",
            () => _ = new Referenceˉruntime(
                U16ˉoverflow,
                new Referenceˉcapabilityˉhost(TextWriter.Null),
                Runtimeˉoptions.Portableˉdefaults).Runˉmain());
        var Nativeˉu16ˉoverflow = X64ˉnativeˉbackend.Compile(U16ˉoverflow);
        _ = Nativeˉfragmentˉverifier.Verify(Nativeˉu16ˉoverflow.Fragment);
        Throwsˉnativeˉtrap(
            "WVR3016",
            () => _ = X64ˉnativeˉexecutor.Executeˉi32(Nativeˉu16ˉoverflow.Fragment));
        var Nativeˉu16ˉoverflowˉobject = Nativeˉobjectˉsink.Writeˉwvo(Nativeˉu16ˉoverflow.Fragment);
        var Nativeˉu16ˉoverflowˉlinked = Linkˉsuccess(
            [Nativeˉu16ˉoverflowˉobject.ToArray()],
            new(Linkˉcontract.DEFAULT_BASE_ADDRESS, "Main"));
        Throwsˉnativeˉtrap(
            "WVR3016",
            () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                Nativeˉu16ˉoverflow.Fragment with
                {
                    Code = Nativeˉu16ˉoverflowˉlinked.Imageˉbytes,
