        var Utf8ˉverified = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess("""
            module Nativeˉutf8ˉvalidation profile portable;
            data Empty: bytes = [];
            data Ascii: bytes = [0, 65, 127];
            data Twoˉminimum: bytes = [194, 128];
            data Twoˉmaximum: bytes = [223, 191];
            data Threeˉe0: bytes = [224, 160, 128];
            data Threeˉstandard: bytes = [225, 128, 191, 236, 191, 191, 238, 128, 128, 239, 191, 191];
            data Threeˉed: bytes = [237, 159, 191];
            data Fourˉf0: bytes = [240, 144, 128, 128];
            data Fourˉstandard: bytes = [241, 128, 128, 128, 243, 191, 191, 191];
            data Fourˉf4: bytes = [244, 143, 191, 191];
            data Strayˉcontinuation: bytes = [128];
            data Overlongˉtwo: bytes = [192, 175];
            data Truncatedˉtwo: bytes = [194];
            data Badˉtwoˉcontinuation: bytes = [194, 32];
            data Overlongˉthree: bytes = [224, 159, 191];
            data Surrogate: bytes = [237, 160, 128];
            data Truncatedˉthree: bytes = [225, 128];
            data Badˉthreeˉcontinuation: bytes = [225, 128, 32];
            data Overlongˉfour: bytes = [240, 143, 191, 191];
            data Aboveˉunicode: bytes = [244, 144, 128, 128];
            data Highˉlead: bytes = [245, 128, 128, 128];
            data Truncatedˉfour: bytes = [241, 128, 128];
            data Badˉfourˉcontinuation: bytes = [241, 128, 32, 128];
            export fn Main() -> i32 {
                if !Textˉutf8ˉisˉvalid(Empty) { return 1; }
                if !Textˉutf8ˉisˉvalid(Ascii) { return 1; }
                if !Textˉutf8ˉisˉvalid(Twoˉminimum) { return 1; }
                if !Textˉutf8ˉisˉvalid(Twoˉmaximum) { return 1; }
                if !Textˉutf8ˉisˉvalid(Threeˉe0) { return 1; }
                if !Textˉutf8ˉisˉvalid(Threeˉstandard) { return 1; }
                if !Textˉutf8ˉisˉvalid(Threeˉed) { return 1; }
                if !Textˉutf8ˉisˉvalid(Fourˉf0) { return 1; }
                if !Textˉutf8ˉisˉvalid(Fourˉstandard) { return 1; }
                if !Textˉutf8ˉisˉvalid(Fourˉf4) { return 1; }
                if Textˉutf8ˉisˉvalid(Strayˉcontinuation) { return 2; }
                if Textˉutf8ˉisˉvalid(Overlongˉtwo) { return 2; }
                if Textˉutf8ˉisˉvalid(Truncatedˉtwo) { return 2; }
                if Textˉutf8ˉisˉvalid(Badˉtwoˉcontinuation) { return 2; }
                if Textˉutf8ˉisˉvalid(Overlongˉthree) { return 2; }
                if Textˉutf8ˉisˉvalid(Surrogate) { return 2; }
                if Textˉutf8ˉisˉvalid(Truncatedˉthree) { return 2; }
                if Textˉutf8ˉisˉvalid(Badˉthreeˉcontinuation) { return 2; }
                if Textˉutf8ˉisˉvalid(Overlongˉfour) { return 2; }
                if Textˉutf8ˉisˉvalid(Aboveˉunicode) { return 2; }
                if Textˉutf8ˉisˉvalid(Highˉlead) { return 2; }
                if Textˉutf8ˉisˉvalid(Truncatedˉfour) { return 2; }
                if Textˉutf8ˉisˉvalid(Badˉfourˉcontinuation) { return 2; }
                return 42;
            }
            """));
        var Utf8ˉreference = new Referenceˉruntime(
            Utf8ˉverified,
            new Referenceˉcapabilityˉhost(TextWriter.Null),
            Runtimeˉoptions.Portableˉdefaults).Runˉmain();
        Equal(42, Utf8ˉreference.Exitˉcode);
        var Utf8ˉnative = X64ˉnativeˉbackend.Compile(Utf8ˉverified);
        Sequenceˉequal([Nativeˉservice.Textˉutf8ˉisˉvalid], Utf8ˉnative.Fragment.Requiredˉservices);
        True(
            Utf8ˉnative.Module.Functions.SelectMany(Function => Function.Blocks)
                .SelectMany(Block => Block.Operations)
                .Count(Operation => Operation is Nativeˉtextˉutf8ˉisˉvalid) == 23,
            "Native machine IR omitted UTF-8 validation.");
        var Utf8ˉservice = X64ˉnativeˉutf8ˉservice.Build();
        Equal(X64ˉnativeˉutf8ˉservice.CANONICAL_SIZE, Utf8ˉservice.Length);
        Equal(
            X64ˉnativeˉutf8ˉservice.CANONICAL_SHA256,
            Convert.ToHexString(SHA256.HashData(Utf8ˉservice.AsSpan())).ToLowerInvariant());
        Sequenceˉequal(Utf8ˉservice, X64ˉnativeˉutf8ˉservice.Build());
        X64ˉnativeˉutf8ˉservice.Verify(Utf8ˉservice.AsSpan());
        var Corruptedˉutf8ˉservice = Utf8ˉservice.ToArray();
        Corruptedˉutf8ˉservice[0] ^= 0x01;
        Throwsˉinvalidˉoperation(
            "Native UTF-8 service identity",
            () => X64ˉnativeˉutf8ˉservice.Verify(Corruptedˉutf8ˉservice));
        Equal(
            Utf8ˉreference.Exitˉcode,
            X64ˉnativeˉexecutor.Executeˉi32(
                Utf8ˉnative.Fragment,
                maximumˉinstructions: Utf8ˉreference.Executedˉinstructions));

        var Dataˉpatch = First.Fragment.Patches[0];
        var Corruptedˉdescriptor = First.Fragment.Code.ToArray();
        Corruptedˉdescriptor[checked((int)Dataˉpatch.Offset - 3)] = 0x90;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉdescriptor.ToImmutableArray() }));

        var Corruptedˉlength = First.Fragment.Code.ToArray();
        Corruptedˉlength[checked((int)Dataˉpatch.Offset + 13)] ^= 0x01;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉlength.ToImmutableArray() }));

        var Corruptedˉdescriptorˉtype = First.Fragment.Code.ToArray();
        var Descriptorˉslotˉoffset = BinaryPrimitives.ReadInt32LittleEndian(
            Corruptedˉdescriptorˉtype.AsSpan(checked((int)Dataˉpatch.Offset + 8), sizeof(int)));
        var Scalarˉconstant = -1;
        for (var Offset = checked((int)Dataˉpatch.Offset + 20);
            Offset <= Corruptedˉdescriptorˉtype.Length - 12;
            Offset++)
        {
            if (Corruptedˉdescriptorˉtype[Offset] == 0xB8 &&
                Corruptedˉdescriptorˉtype.AsSpan(Offset + 5, 3).SequenceEqual(
                    new byte[] { 0x89, 0x84, 0x24 }))
            {
                Scalarˉconstant = Offset;
                break;
            }
        }
        True(Scalarˉconstant >= 0, "Native borrowed bytes did not emit a later scalar constant.");
        BinaryPrimitives.WriteInt32LittleEndian(
            Corruptedˉdescriptorˉtype.AsSpan(Scalarˉconstant + 8, sizeof(int)),
            Descriptorˉslotˉoffset);
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉdescriptorˉtype.ToImmutableArray() }));

        var Corruptedˉbyteˉargument = First.Fragment.Code.ToArray();
        var Byteˉargument = Corruptedˉbyteˉargument.AsSpan().IndexOf(
            new byte[] { 0x4C, 0x8D, 0x84, 0x24 });
        True(Byteˉargument >= 0, "Native borrowed bytes did not use the typed first-argument form.");
        Corruptedˉbyteˉargument[Byteˉargument + 1] = 0x8B;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉbyteˉargument.ToImmutableArray() }));

        var Corruptedˉbyteˉbounds = First.Fragment.Code.ToArray();
        var Byteˉboundsˉbranch = Corruptedˉbyteˉbounds.AsSpan().IndexOf(
            new byte[] { 0x0F, 0x87 });
        True(Byteˉboundsˉbranch >= 0, "Native borrowed bytes did not emit an unsigned bounds branch.");
        BinaryPrimitives.WriteInt32LittleEndian(
            Corruptedˉbyteˉbounds.AsSpan(Byteˉboundsˉbranch + 2, sizeof(int)),
            0);
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉbyteˉbounds.ToImmutableArray() }));

        var Boundsˉverified = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess("""
            module Nativeˉbyteˉbounds profile portable;
            data Input: bytes = [1, 2, 3, 4];
            export fn Main() -> i32 {
                let Value: u32 = Bytesˉreadˉu32ˉlittle(Input, 1u32);
                if Value == 0u32 { return 0; }
                return 1;
            }
            """));
        Throwsˉruntime(
            "WVR3008",
            () => _ = new Referenceˉruntime(
                Boundsˉverified,
                new Referenceˉcapabilityˉhost(TextWriter.Null),
                Runtimeˉoptions.Portableˉdefaults).Runˉmain());
        Throwsˉnativeˉtrap(
            "WVR3008",
            () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                X64ˉnativeˉbackend.Compile(Boundsˉverified).Fragment));

        var Overflowˉverified = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess("""
            module Nativeˉu32ˉoverflow profile portable;
            export fn Main() -> i32 {
                let Value: u32 = 4294967295u32 + 1u32;
                if Value == 0u32 { return 0; }
                return 1;
            }
            """));
        Throwsˉruntime(
            "WVR3007",
            () => _ = new Referenceˉruntime(
                Overflowˉverified,
                new Referenceˉcapabilityˉhost(TextWriter.Null),
                Runtimeˉoptions.Portableˉdefaults).Runˉmain());
        Throwsˉnativeˉtrap(
            "WVR3007",
            () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                X64ˉnativeˉbackend.Compile(Overflowˉverified).Fragment));
    }

    private static void Nativeˉruntimeˉserviceˉisˉauthorized()
    {
        var Verified = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess(HELLO_SOURCE));
        var Authorizedˉcapabilities = ImmutableHashSet.Create(
            StringComparer.Ordinal,
            Capabilityˉcatalog.CONSOLE_WRITE_LINE);
        var Interpreterˉoutput = new StringWriter();
        var Interpreted = new Referenceˉruntime(
            Verified,
            new Referenceˉcapabilityˉhost(Interpreterˉoutput),
            new(Authorizedˉcapabilities)).Runˉmain();
        Equal(0, Interpreted.Exitˉcode);
        Equal("Hello from Windvale\n", Interpreterˉoutput.ToString());
        True(Interpreted.Executedˉinstructions > 1, "The hosted reference runtime did not charge instructions.");
        Throwsˉruntime(
            "WVR3029",
            () => _ = new Referenceˉruntime(
                Verified,
                new Referenceˉcapabilityˉhost(new Failingˉtextˉwriter()),
                new(Authorizedˉcapabilities)).Runˉmain());

        var First = X64ˉnativeˉbackend.Compile(Verified);
        var Second = X64ˉnativeˉbackend.Compile(Verified);
        Sequenceˉequal(First.Fragment.Code, Second.Fragment.Code);
        Sequenceˉequal(First.Fragment.Symbols, Second.Fragment.Symbols);
        Sequenceˉequal(First.Fragment.Patches, Second.Fragment.Patches);
        Sequenceˉequal(
            [Nativeˉservice.Consoleˉwriteˉline],
            First.Fragment.Requiredˉservices);
        True(
            First.Module.Data.Single() is Nativeˉutf8ˉdata,
            "Native machine IR did not retain immutable UTF-8 text data.");
        Sequenceˉequal(
            System.Text.Encoding.UTF8.GetBytes("Hello from Windvale"),
            ((Nativeˉutf8ˉdata)First.Module.Data.Single()).Bytes);
        True(
            First.Module.Functions
                .SelectMany(Function => Function.Blocks)
                .SelectMany(Block => Block.Operations)
                .Any(Operation => Operation is Nativeˉconsoleˉwriteˉline),
            "Native machine IR did not retain the authorized console service call.");

        foreach (var Platform in Enum.GetValues<Nativeˉoutputˉplatform>())
        {
            foreach (var Service in new[]
            {
                Nativeˉservice.Consoleˉwriteˉline,
                Nativeˉservice.Diagnosticˉwriteˉline,
            })
            {
                var Firstˉleaf = X64ˉnativeˉoutputˉservices.Build(Service, Platform);
                var Secondˉleaf = X64ˉnativeˉoutputˉservices.Build(Service, Platform);
                Sequenceˉequal(Firstˉleaf, Secondˉleaf);
                Equal(
                    X64ˉnativeˉoutputˉservices.Canonicalˉsize(Platform),
                    Firstˉleaf.Length);
                Equal(
                    X64ˉnativeˉoutputˉservices.Canonicalˉsha256(Service, Platform),
                    Convert.ToHexString(SHA256.HashData(Firstˉleaf.AsSpan())).ToLowerInvariant());
                X64ˉnativeˉoutputˉservices.Verify(Service, Platform, Firstˉleaf.AsSpan());
                var Corruptedˉleaf = Firstˉleaf.ToArray();
                Corruptedˉleaf[0] ^= 0x01;
                Throwsˉinvalidˉoperation(
                    $"Native {Platform} {Service} service identity",
                    () => X64ˉnativeˉoutputˉservices.Verify(
                        Service,
                        Platform,
                        Corruptedˉleaf));
            }
        }

        using var Nativeˉoutput = new Nativeˉoutputˉcapture();
        var Host = new Nativeˉhostˉservices(Nativeˉoutput.Channel, Authorizedˉcapabilities);
        Equal(
            0,
            X64ˉnativeˉexecutor.Executeˉi32(
                First.Fragment,
                maximumˉinstructions: Interpreted.Executedˉinstructions,
                hostˉservices: Host));
        Equal("Hello from Windvale\n", Nativeˉoutput.Readˉtext());
        Throwsˉnativeˉtrap(
            "WVR3011",
            () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                First.Fragment,
                maximumˉinstructions: Interpreted.Executedˉinstructions - 1,
                hostˉservices: new(Nativeˉoutput.Channel, Authorizedˉcapabilities)));
        Throwsˉnativeˉtrap(
            "WVR3010",
            () => _ = X64ˉnativeˉexecutor.Executeˉi32(First.Fragment));
        Throwsˉnativeˉtrap(
            "WVR3010",
            () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                First.Fragment,
                hostˉservices: new(Nativeˉoutput.Channel)));
        Throwsˉnativeˉtrap(
            "WVR3001",
            () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                First.Fragment,
                hostˉservices: new(null, Authorizedˉcapabilities)));

        var Failureˉpath = Path.Combine(
            Path.GetTempPath(),
            $"windvale-native-output-failure-{Guid.NewGuid():N}.tmp");
        File.WriteAllBytes(Failureˉpath, []);
        try
        {
            using var Readˉonly = new FileStream(
                Failureˉpath,
                FileMode.Open,
                FileAccess.Read,
                FileShare.ReadWrite | FileShare.Delete);
            Throwsˉnativeˉtrap(
                "WVR3029",
                () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                    First.Fragment,
                    hostˉservices: new(
                        Nativeˉoutputˉchannel.Fromˉfileˉhandle(Readˉonly.SafeFileHandle),
                        Authorizedˉcapabilities)));
        }
        finally
        {
            File.Delete(Failureˉpath);
        }

        var Dualˉoutputˉverified = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess("""
            module Nativeˉoutputˉchannels profile hosted;

            capability console.write_line;
            capability diagnostic.write_line;

            export fn Main() -> i32 {
                console.write_line("console-€-😀");
                diagnostic.write_line("diagnostic-€-😀");
                console.write_line("");
                return 0;
            }
            """));
        var Dualˉoutputˉfragment = X64ˉnativeˉbackend.Compile(Dualˉoutputˉverified).Fragment;
        var Dualˉoutputˉcapabilities = ImmutableHashSet.Create(
            StringComparer.Ordinal,
            Capabilityˉcatalog.CONSOLE_WRITE_LINE,
            Capabilityˉcatalog.DIAGNOSTIC_WRITE_LINE);
        using (var Consoleˉcapture = new Nativeˉoutputˉcapture())
        using (var Diagnosticˉcapture = new Nativeˉoutputˉcapture())
        {
            Equal(
                0,
                X64ˉnativeˉexecutor.Executeˉi32(
                    Dualˉoutputˉfragment,
                    hostˉservices: new(
                        Consoleˉcapture.Channel,
                        Dualˉoutputˉcapabilities,
                        diagnosticˉoutput: Diagnosticˉcapture.Channel)));
            Equal("console-€-😀\n\n", Consoleˉcapture.Readˉtext());
            Equal("diagnostic-€-😀\n", Diagnosticˉcapture.Readˉtext());
        }

        var Objectˉbytes = Nativeˉobjectˉsink.Writeˉwvo(First.Fragment);
        Sequenceˉequal(Objectˉbytes, Nativeˉobjectˉsink.Writeˉwvo(Second.Fragment));
        var Object = Objectˉcodec.Readˉandˉverify(Objectˉbytes.AsSpan()).Value;
        Equal(2, Object.Sections.Length);
        Equal(".rodata", Object.Sections[1].Name);
        Equal(Objectˉsectionˉkind.Readˉonlyˉdata, Object.Sections[1].Kind);
        Sequenceˉequal(
            System.Text.Encoding.UTF8.GetBytes("Hello from Windvale"),
            Object.Sections[1].Data);
        var Linked = Linkˉsuccess(
            [Objectˉbytes.ToArray()],
            new(Linkˉcontract.DEFAULT_BASE_ADDRESS, "Main"));
        Sequenceˉequal(First.Fragment.Code, Linked.Imageˉbytes);
        using var Linkedˉoutput = new Nativeˉoutputˉcapture();
        Equal(
            0,
            X64ˉnativeˉexecutor.Executeˉi32(
                First.Fragment with { Code = Linked.Imageˉbytes },
                maximumˉinstructions: Interpreted.Executedˉinstructions,
                hostˉservices: new(Linkedˉoutput.Channel, Authorizedˉcapabilities)));
        Equal("Hello from Windvale\n", Linkedˉoutput.Readˉtext());

        var Textˉpatch = First.Fragment.Patches.Single();
        var Corruptedˉservice = First.Fragment.Code.ToArray();
        Corruptedˉservice[checked((int)Textˉpatch.Offset - 3)] = 0x90;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉservice.ToImmutableArray() }));

        var Corruptedˉpatch = First.Fragment.Code.ToArray();
        Corruptedˉpatch[checked((int)Textˉpatch.Offset)] ^= 0x01;
        Throwsˉnative(
            "WVN3024",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉpatch.ToImmutableArray() }));

        var Textˉsymbol = First.Fragment.Symbols.Single(Symbol =>
            Symbol.Kind == Nativeˉsymbolˉkind.Data);
        var Invalidˉutf8 = First.Fragment.Code.ToArray();
        Invalidˉutf8[checked((int)Textˉsymbol.Offset)] = 0xFF;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Invalidˉutf8.ToImmutableArray() }));
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Requiredˉservices = [] }));
    }

    private static void Windvaleˉnativeˉstencilsˉreproduceˉargumentˉservices()
    {
        const string INVALID_STENCIL =
            "The WVA native stencil does not match the bounded native-service contract.";
        var Assemblerˉmodule = Moduleˉcodec.Readˉandˉverify(Compileˉwithˉtoolˉfoundationˉsuccess(
            WVA_ASSEMBLER_CORE_SOURCE,
            "Wva-Assembler-Core.wv"));
        var Authorized = Assemblerˉmodule.Module.Capabilities
            .Select(Capability => Capability.Name)
            .ToImmutableHashSet(StringComparer.Ordinal);

        ImmutableArray<byte> Assembleˉtwice(
            string source,
            string sourceˉname,
            string outputˉname)
        {
            var Sourceˉbytes = Encoding.UTF8.GetBytes(source).ToImmutableArray();

            Capturingˉfileˉwriter Runˉwindvaleˉassembler()
            {
                var Output = new StringWriter();
                var Diagnostics = new StringWriter();
                var Writer = new Capturingˉfileˉwriter();
                var Result = new Referenceˉruntime(
                    Assemblerˉmodule,
                    new Referenceˉcapabilityˉhost(new Hostedˉresourceˉcontext(
                        [sourceˉname, outputˉname],
                        Output,
                        Diagnostics,
                        new Testˉfileˉreader((Name, Maximumˉbytes) =>
                        {
                            Equal(sourceˉname, Name);
                            True(
                                Sourceˉbytes.Length <= Maximumˉbytes,
                                "The native-stencil source exceeded the Windvale assembler input bound.");
                            return Sourceˉbytes;
                        }),
                        Writer)),
                    new(Authorized, Maximumˉinstructions: 10_000_000)).Runˉmain();
                Equal(0, Result.Exitˉcode);
                Equal(string.Empty, Diagnostics.ToString());
                Contains(Output.ToString(), "assembly status=valid");
                Equal(1, Writer.Writeˉcount);
                Equal(outputˉname, Writer.Resourceˉname);
                return Writer;
            }

            var First = Runˉwindvaleˉassembler();
            var Second = Runˉwindvaleˉassembler();
            Sequenceˉequal(First.Bytes, Second.Bytes);
            Sequenceˉequal(Assembleˉsuccess(source), First.Bytes);
            return First.Bytes;
        }

        static Verifiedˉobject Corruptˉdata(
            Verifiedˉobject verified,
            int offset,
            byte value)
        {
            var Object = verified.Value;
            var Section = Object.Sections.Single();
            var Data = Section.Data.ToArray();
            Data[offset] = value;
            return Objectˉverifier.Verify(Object with
            {
                Sections = [Section with { Data = Data.ToImmutableArray() }],
            });
        }

        static void Verifyˉembeddedˉobject(
            ImmutableArray<byte> expected,
            string resource,
            int size,
            string sha256)
        {
            using var Embeddedˉstream = typeof(X64ˉnativeˉstencil).Assembly
                .GetManifestResourceStream(resource) ??
                throw new InvalidOperationException($"The native-stencil resource {resource} was not embedded.");
            var Embeddedˉbytes = new byte[checked((int)Embeddedˉstream.Length)];
            Embeddedˉstream.ReadExactly(Embeddedˉbytes);
            Sequenceˉequal(expected, Embeddedˉbytes);
            Equal(size, Embeddedˉbytes.Length);
            Equal(
                sha256,
                Convert.ToHexString(SHA256.HashData(Embeddedˉbytes)).ToLowerInvariant());
        }

        var Countˉbytes = Assembleˉtwice(
            PROCESS_ARGUMENT_COUNT_STENCIL_SOURCE,
            "Process-Argument-Count.wva",
            "Process-Argument-Count.wvo");
        Verifyˉembeddedˉobject(
            Countˉbytes,
            "Windvale.NativeCompiler.Process-Argument-Count.wvo",
            166,
            "e2057943b9c79e10a432ea20a77da5ed0a261e3effdd36511cbb34e77e55c10b");
        var Countˉverified = Objectˉcodec.Readˉandˉverify(Countˉbytes.AsSpan());
        var Countˉstencil = X64ˉnativeˉstencil.Readˉprocessˉargumentˉcount(Countˉverified);
        var Countˉinstantiated = X64ˉnativeˉstencil.Instantiateˉu8(
            Countˉstencil,
            Nativeˉstencilˉpatchˉkind.Executionˉcontextˉu8ˉoffset,
            checked((byte)Nativeˉexecutionˉcontextˉcontract.ARGUMENT_COUNT_OFFSET));
        Sequenceˉequal(
            X64ˉnativeˉargumentˉservices.Build(Nativeˉservice.Processˉargumentˉcount),
            Countˉinstantiated);
        Equal(
            X64ˉnativeˉargumentˉservices.ARGUMENT_COUNT_CANONICAL_SIZE,
            Countˉinstantiated.Length);
        Equal(
            X64ˉnativeˉargumentˉservices.ARGUMENT_COUNT_CANONICAL_SHA256,
            Convert.ToHexString(SHA256.HashData(Countˉinstantiated.AsSpan())).ToLowerInvariant());
        X64ˉnativeˉargumentˉservices.Verify(
            Nativeˉservice.Processˉargumentˉcount,
            Countˉinstantiated.AsSpan());

        Throwsˉinvalidˉoperation(
            INVALID_STENCIL,
            () => _ = X64ˉnativeˉstencil.Readˉprocessˉargumentˉcount(
                Corruptˉdata(Countˉverified, 8, 4)));
        Throwsˉinvalidˉoperation(
            INVALID_STENCIL,
            () => _ = X64ˉnativeˉstencil.Readˉprocessˉargumentˉcount(
                Corruptˉdata(Countˉverified, 12, 2)));
        Throwsˉinvalidˉoperation(
            INVALID_STENCIL,
            () => _ = X64ˉnativeˉstencil.Readˉprocessˉargumentˉcount(
                Corruptˉdata(Countˉverified, 16, 2)));
        Throwsˉinvalidˉoperation(
            INVALID_STENCIL,
            () => _ = X64ˉnativeˉstencil.Readˉprocessˉargumentˉcount(
                Corruptˉdata(Countˉverified, 20, 0x40)));
        Throwsˉinvalidˉoperation(
            INVALID_STENCIL,
            () => _ = X64ˉnativeˉstencil.Instantiateˉu8(
                Countˉstencil,
                Nativeˉstencilˉpatchˉkind.Executionˉcontextˉserviceˉfailureˉdetailˉu8ˉoffset,
                checked((byte)Nativeˉexecutionˉcontextˉcontract.ARGUMENT_COUNT_OFFSET)));
        Throwsˉinvalidˉoperation(
            INVALID_STENCIL,
            () => _ = X64ˉnativeˉstencil.Instantiateˉu8(
                Countˉstencil with { Template = Countˉinstantiated },
                Nativeˉstencilˉpatchˉkind.Executionˉcontextˉu8ˉoffset,
                checked((byte)Nativeˉexecutionˉcontextˉcontract.ARGUMENT_COUNT_OFFSET)));

        var Argumentˉbytes = Assembleˉtwice(
            PROCESS_ARGUMENT_STENCIL_SOURCE,
            "Process-Argument.wva",
            "Process-Argument.wvo");
        Verifyˉembeddedˉobject(
            Argumentˉbytes,
            "Windvale.NativeCompiler.Process-Argument.wvo",
            321,
            "307e61dcb2a156eb0d4b77f7d93676d7b1ac24f9bb6fe1f31217837213352bad");
        var Argumentˉverified = Objectˉcodec.Readˉandˉverify(Argumentˉbytes.AsSpan());
        var Argumentˉstencil = X64ˉnativeˉstencil.Readˉprocessˉargument(Argumentˉverified);
        Equal(2u, Argumentˉstencil.Formatˉversion);
        Equal(8, Argumentˉstencil.Patches.Length);
        Equal(
            2,
            Argumentˉstencil.Patches.Count(Patch =>
                Patch.Kind ==
                    Nativeˉstencilˉpatchˉkind.Executionˉcontextˉserviceˉfailureˉdetailˉu8ˉoffset));
        Equal(
            2,
            Argumentˉstencil.Patches.Count(Patch =>
                Patch.Kind == Nativeˉstencilˉpatchˉkind.Borrowedˉtextˉlengthˉu8ˉoffset));
        var Argumentˉinstantiated = X64ˉnativeˉstencil.Instantiateˉprocessˉargument(
            Argumentˉstencil);
        Sequenceˉequal(
            X64ˉnativeˉargumentˉservices.Build(Nativeˉservice.Processˉargument),
            Argumentˉinstantiated);
        Equal(
            X64ˉnativeˉargumentˉservices.ARGUMENT_CANONICAL_SIZE,
            Argumentˉinstantiated.Length);
        Equal(
            X64ˉnativeˉargumentˉservices.ARGUMENT_CANONICAL_SHA256,
            Convert.ToHexString(SHA256.HashData(Argumentˉinstantiated.AsSpan())).ToLowerInvariant());
        X64ˉnativeˉargumentˉservices.Verify(
            Nativeˉservice.Processˉargument,
            Argumentˉinstantiated.AsSpan());

        Throwsˉinvalidˉoperation(
            INVALID_STENCIL,
            () => _ = X64ˉnativeˉstencil.Readˉprocessˉargument(
                Corruptˉdata(Argumentˉverified, 8, 7)));
        Throwsˉinvalidˉoperation(
            INVALID_STENCIL,
            () => _ = X64ˉnativeˉstencil.Readˉprocessˉargument(
                Corruptˉdata(Argumentˉverified, 12, 69)));
        Throwsˉinvalidˉoperation(
            INVALID_STENCIL,
            () => _ = X64ˉnativeˉstencil.Readˉprocessˉargument(
                Corruptˉdata(Argumentˉverified, 16, 4)));
        Throwsˉinvalidˉoperation(
            INVALID_STENCIL,
            () => _ = X64ˉnativeˉstencil.Readˉprocessˉargument(
                Corruptˉdata(Argumentˉverified, 20, 2)));
        Throwsˉinvalidˉoperation(
            INVALID_STENCIL,
            () => _ = X64ˉnativeˉstencil.Readˉprocessˉargument(
                Corruptˉdata(Argumentˉverified, 24, 3)));
        Throwsˉinvalidˉoperation(
            INVALID_STENCIL,
            () => _ = X64ˉnativeˉstencil.Readˉprocessˉargument(
                Corruptˉdata(Argumentˉverified, 112, 0x40)));
        Throwsˉinvalidˉoperation(
            INVALID_STENCIL,
            () => _ = X64ˉnativeˉstencil.Readˉprocessˉargument(
                Corruptˉdata(Argumentˉverified, 115, 1)));
        Throwsˉinvalidˉoperation(
            INVALID_STENCIL,
            () => _ = X64ˉnativeˉstencil.Instantiateˉu8(
                Argumentˉstencil,
                Nativeˉstencilˉpatchˉkind.Executionˉcontextˉserviceˉfailureˉdetailˉu8ˉoffset,
                checked((byte)Nativeˉexecutionˉcontextˉcontract.SERVICE_FAILURE_DETAIL_OFFSET)));
        var Duplicateˉpatches = Argumentˉstencil.Patches.ToArray();
        Duplicateˉpatches[1] = Duplicateˉpatches[1] with { Offset = Duplicateˉpatches[0].Offset };
        Throwsˉinvalidˉoperation(
            INVALID_STENCIL,
            () => _ = X64ˉnativeˉstencil.Instantiateˉprocessˉargument(
                Argumentˉstencil with { Patches = Duplicateˉpatches.ToImmutableArray() }));
        Throwsˉinvalidˉoperation(
            INVALID_STENCIL,
            () => _ = X64ˉnativeˉstencil.Instantiateˉprocessˉargument(
                Argumentˉstencil with { Template = Argumentˉinstantiated }));
    }

    private static void Windvaleˉnativeˉstencilˉconsumerˉruns()
    {
        var Coreˉresult = Seedˉcompiler.Compileˉmodules(
            new("Compiler/Windvale/Native-Stencil-Core.wv", NATIVE_STENCIL_CORE_SOURCE),
            []);
        True(
            Coreˉresult.Success,
            "The Windvale native-stencil core did not compile: " +
                string.Join(" | ", Coreˉresult.Diagnostics));
        Equal(
            NATIVE_STENCIL_CORE_SHA256,
            Moduleˉdigest.Calculateˉsha256(Coreˉresult.Moduleˉbytes.AsSpan()));

        var Demoˉresult = Seedˉcompiler.Compileˉmodules(
            new("Examples/Compiler/Native-Stencil-Demo.wv", NATIVE_STENCIL_DEMO_SOURCE),
            [
                new("Compiler/Windvale/Native-Stencil-Core.wv", NATIVE_STENCIL_CORE_SOURCE),
            ]);
        True(
            Demoˉresult.Success,
            "The Windvale native-stencil demo did not compile: " +
                string.Join(" | ", Demoˉresult.Diagnostics));
        Equal(
            NATIVE_STENCIL_DEMO_SHA256,
            Moduleˉdigest.Calculateˉsha256(Demoˉresult.Moduleˉbytes.AsSpan()));
        var Demo = Moduleˉcodec.Readˉandˉverify(Demoˉresult.Moduleˉbytes.AsSpan());

        static ImmutableArray<byte> Readˉnativeˉstencilˉresource(string name)
        {
            using var Stream = typeof(X64ˉnativeˉstencil).Assembly
                .GetManifestResourceStream(name) ??
                throw new InvalidOperationException($"The native-stencil resource {name} was not embedded.");
            var Bytes = new byte[checked((int)Stream.Length)];
            Stream.ReadExactly(Bytes);
            return Bytes.ToImmutableArray();
        }

        var Countˉdata = (Bytesˉdataˉdeclaration)Demo.Module.Data.Single(
            Data => Data.Name == "Argumentˉcountˉobject");
        var Argumentˉdata = (Bytesˉdataˉdeclaration)Demo.Module.Data.Single(
            Data => Data.Name == "Argumentˉobject");
        Sequenceˉequal(
            Readˉnativeˉstencilˉresource(
                "Windvale.NativeCompiler.Process-Argument-Count.wvo"),
            Countˉdata.Values);
        Sequenceˉequal(
            Readˉnativeˉstencilˉresource("Windvale.NativeCompiler.Process-Argument.wvo"),
            Argumentˉdata.Values);

        var Interpreted = new Referenceˉruntime(
            Demo,
            new Referenceˉcapabilityˉhost(TextWriter.Null),
            Runtimeˉoptions.Portableˉdefaults with { Maximumˉinstructions = 20_000_000 })
            .Runˉmain();
        Equal(0, Interpreted.Exitˉcode);

        var First = X64ˉnativeˉbackend.Compile(Demo);
        var Second = X64ˉnativeˉbackend.Compile(Demo);
        Sequenceˉequal(First.Fragment.Code, Second.Fragment.Code);
        Sequenceˉequal(First.Fragment.Symbols, Second.Fragment.Symbols);
        Sequenceˉequal(First.Fragment.Patches, Second.Fragment.Patches);
        Sequenceˉequal(First.Fragment.Types, Second.Fragment.Types);
        var Operations = First.Module.Functions
            .SelectMany(Function => Function.Blocks)
            .SelectMany(Block => Block.Operations)
            .ToImmutableArray();
        True(Operations.Any(Operation => Operation is Nativeˉbytesˉslice),
            "The Windvale native-stencil consumer omitted immutable byte slicing.");
        True(Operations.Any(Operation => Operation is Nativeˉbytesˉconcat),
            "The Windvale native-stencil consumer omitted immutable byte replacement.");
        True(Operations.Any(Operation => Operation is Nativeˉbytesˉfromˉu32ˉlittle),
            "The Windvale native-stencil consumer omitted typed patch-byte construction.");
        True(Operations.Any(Operation => Operation is Nativeˉrecordˉcreate),
            "The Windvale native-stencil consumer omitted typed result construction.");
        True(Operations.Any(Operation => Operation is Nativeˉenumˉcomparison),
            "The Windvale native-stencil consumer omitted typed status checks.");
        _ = Nativeˉfragmentˉverifier.Verify(First.Fragment);
        Equal(
            Interpreted.Exitˉcode,
            X64ˉnativeˉexecutor.Executeˉi32(
                First.Fragment,
                maximumˉinstructions: Interpreted.Executedˉinstructions));

        var Firstˉobject = Nativeˉobjectˉsink.Writeˉwvo(First.Fragment);
        var Secondˉobject = Nativeˉobjectˉsink.Writeˉwvo(Second.Fragment);
        Sequenceˉequal(Firstˉobject, Secondˉobject);
        var Linked = Linkˉsuccess(
            [Firstˉobject.ToArray()],
            new(Linkˉcontract.DEFAULT_BASE_ADDRESS, "Main"));
        Sequenceˉequal(First.Fragment.Code, Linked.Imageˉbytes);
        Equal(
            Interpreted.Exitˉcode,
            X64ˉnativeˉexecutor.Executeˉi32(
                First.Fragment with { Code = Linked.Imageˉbytes },
                maximumˉinstructions: Interpreted.Executedˉinstructions));
    }

    private static void Windvaleˉnativeˉstencilˉbridgeˉruns()
    {
        var Bridgeˉresult = Seedˉcompiler.Compileˉmodules(
            new("Compiler/Windvale/Native-Stencil-Bridge.wv", NATIVE_STENCIL_BRIDGE_SOURCE),
            [
                new("Compiler/Windvale/Native-Stencil-Core.wv", NATIVE_STENCIL_CORE_SOURCE),
            ]);
        True(
            Bridgeˉresult.Success,
            "The Windvale native-stencil bridge did not compile: " +
                string.Join(" | ", Bridgeˉresult.Diagnostics));
        Equal(
            NATIVE_STENCIL_BRIDGE_SHA256,
            Moduleˉdigest.Calculateˉsha256(Bridgeˉresult.Moduleˉbytes.AsSpan()));
        Equal(X64ˉnativeˉargumentˉservices.CONSUMER_CANONICAL_SIZE, Bridgeˉresult.Moduleˉbytes.Length);
        Equal(X64ˉnativeˉargumentˉservices.CONSUMER_CANONICAL_SHA256, NATIVE_STENCIL_BRIDGE_SHA256);

        using (var Stream = typeof(X64ˉnativeˉargumentˉservices).Assembly
            .GetManifestResourceStream("Windvale.Native.Native-Stencil-Bridge.wvb") ??
            throw new InvalidOperationException("The retained native-stencil bridge was not embedded."))
        {
            var Retained = new byte[checked((int)Stream.Length)];
            Stream.ReadExactly(Retained);
            Sequenceˉequal(Bridgeˉresult.Moduleˉbytes, Retained);
        }

        var Bridge = Moduleˉcodec.Readˉandˉverify(Bridgeˉresult.Moduleˉbytes.AsSpan());
        var Countˉdata = (Bytesˉdataˉdeclaration)Bridge.Module.Data.Single(
            Data => Data.Name == "Argumentˉcountˉobject");
        var Argumentˉdata = (Bytesˉdataˉdeclaration)Bridge.Module.Data.Single(
            Data => Data.Name == "Argumentˉobject");
        static ImmutableArray<byte> Readˉobjectˉresource(string name)
        {
            using var Stream = typeof(X64ˉnativeˉstencil).Assembly
                .GetManifestResourceStream(name) ??
                throw new InvalidOperationException($"The native-stencil object {name} was not embedded.");
            var Bytes = new byte[checked((int)Stream.Length)];
            Stream.ReadExactly(Bytes);
            return Bytes.ToImmutableArray();
        }
        Sequenceˉequal(
            Readˉobjectˉresource("Windvale.NativeCompiler.Process-Argument-Count.wvo"),
            Countˉdata.Values);
        Sequenceˉequal(
            Readˉobjectˉresource("Windvale.NativeCompiler.Process-Argument.wvo"),
            Argumentˉdata.Values);

        var Expectedˉbuilder = ImmutableArray.CreateBuilder<byte>(
            X64ˉnativeˉargumentˉservices.ARGUMENT_COUNT_CANONICAL_SIZE +
            X64ˉnativeˉargumentˉservices.ARGUMENT_CANONICAL_SIZE);
        Expectedˉbuilder.AddRange(X64ˉnativeˉstencil.Buildˉprocessˉargumentˉcount());
        Expectedˉbuilder.AddRange(X64ˉnativeˉstencil.Buildˉprocessˉargument());
        var Expected = Expectedˉbuilder.MoveToImmutable();

        var Reference = new Referenceˉruntime(
            Bridge,
            new Referenceˉcapabilityˉhost(TextWriter.Null),
            Runtimeˉoptions.Portableˉdefaults);
        var Interpreted = Reference.Runˉmainˉbytes();
        Sequenceˉequal(Expected, Interpreted.Bytes);
        Throwsˉruntime("WVR3003", () => _ = Reference.Runˉmain());

        var First = X64ˉnativeˉbackend.Compile(Bridge);
        var Second = X64ˉnativeˉbackend.Compile(Bridge);
        Sequenceˉequal(First.Fragment.Code, Second.Fragment.Code);
        Sequenceˉequal(First.Fragment.Symbols, Second.Fragment.Symbols);
        Sequenceˉequal(First.Fragment.Patches, Second.Fragment.Patches);
        Equal(
            Nativeˉentryˉresultˉkind.Descriptor,
            Nativeˉfragmentˉverifier.Verifyˉentryˉresultˉkind(First.Fragment));
        Sequenceˉequal(
            new byte[] { 0x48, 0x89, 0xC8 },
            First.Fragment.Code.AsSpan(30, 3).ToArray());
        Sequenceˉequal(
            Expected,
            X64ˉnativeˉexecutor.Executeˉbytes(
                First.Fragment,
                maximumˉinstructions: Interpreted.Executedˉinstructions));
        Throwsˉnative("WVN4011", () => _ = X64ˉnativeˉexecutor.Executeˉi32(First.Fragment));

        var Corruptedˉcode = First.Fragment.Code.ToArray();
        Corruptedˉcode[32] ^= 0x01;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉcode.ToImmutableArray() }));

        var Firstˉobject = Nativeˉobjectˉsink.Writeˉwvo(First.Fragment);
        var Secondˉobject = Nativeˉobjectˉsink.Writeˉwvo(Second.Fragment);
        Sequenceˉequal(Firstˉobject, Secondˉobject);
        var Linked = Linkˉsuccess(
            [Firstˉobject.ToArray()],
            new(Linkˉcontract.DEFAULT_BASE_ADDRESS, "Main"));
        Sequenceˉequal(First.Fragment.Code, Linked.Imageˉbytes);
        Sequenceˉequal(
            Expected,
            X64ˉnativeˉexecutor.Executeˉbytes(
                First.Fragment with { Code = Linked.Imageˉbytes },
                maximumˉinstructions: Interpreted.Executedˉinstructions));

        Sequenceˉequal(
            Expected.AsSpan(0, X64ˉnativeˉargumentˉservices.ARGUMENT_COUNT_CANONICAL_SIZE)
                .ToArray(),
            X64ˉnativeˉargumentˉservices.Build(Nativeˉservice.Processˉargumentˉcount));
        Sequenceˉequal(
            Expected.AsSpan()[X64ˉnativeˉargumentˉservices.ARGUMENT_COUNT_CANONICAL_SIZE..]
                .ToArray(),
            X64ˉnativeˉargumentˉservices.Build(Nativeˉservice.Processˉargument));

        var Scalar = X64ˉnativeˉbackend.Compile(
            Moduleˉcodec.Readˉandˉverify(Compileˉsuccess(NATIVE_CONSTANT_SOURCE)));
        Throwsˉnative("WVN4011", () => _ = X64ˉnativeˉexecutor.Executeˉbytes(Scalar.Fragment));
        Throwsˉruntime(
            "WVR3003",
            () => _ = new Referenceˉruntime(
                Moduleˉcodec.Readˉandˉverify(Compileˉsuccess(NATIVE_CONSTANT_SOURCE)),
                new Referenceˉcapabilityˉhost(TextWriter.Null),
                Runtimeˉoptions.Portableˉdefaults).Runˉmainˉbytes());
        var Staticˉbytes = X64ˉnativeˉbackend.Compile(
            Moduleˉcodec.Readˉandˉverify(Compileˉsuccess("""
                module Nativeˉstaticˉbytes profile portable;
                data Value: bytes = [1, 2, 3, 4];
                export fn Main() -> bytes { return Value; }
                """)));
        Sequenceˉequal(
            new byte[] { 1, 2, 3, 4 },
            X64ˉnativeˉexecutor.Executeˉbytes(Staticˉbytes.Fragment));
        var Hostedˉbytes = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess("""
            module Nativeˉhostedˉbytes profile hosted;
            capability file.read_bytes;
            data Name: text = "input.bin";
            export fn Main() -> bytes { return file.read_bytes(Name); }
            """));
        Throwsˉnative("WVN2002", () => _ = X64ˉnativeˉbackend.Compile(Hostedˉbytes));
    }

    private static void Windvaleˉnativeˉpublicationˉlayoutˉruns()
    {
        var Coreˉresult = Seedˉcompiler.Compileˉmodules(
            new("Compiler/Windvale/Native-Publication-Core.wv", NATIVE_PUBLICATION_CORE_SOURCE),
            []);
        True(
            Coreˉresult.Success,
            "The Windvale native-publication core did not compile: " +
                string.Join(" | ", Coreˉresult.Diagnostics));
        Equal(7_190, Coreˉresult.Moduleˉbytes.Length);
        Equal(
            NATIVE_PUBLICATION_CORE_SHA256,
            Moduleˉdigest.Calculateˉsha256(Coreˉresult.Moduleˉbytes.AsSpan()));

        var Bridgeˉresult = Seedˉcompiler.Compileˉmodules(
            new("Compiler/Windvale/Native-Publication-Bridge.wv", NATIVE_PUBLICATION_BRIDGE_SOURCE),
            [
                new("Compiler/Windvale/Native-Publication-Core.wv", NATIVE_PUBLICATION_CORE_SOURCE),
            ]);
        True(
            Bridgeˉresult.Success,
            "The Windvale native-publication bridge did not compile: " +
                string.Join(" | ", Bridgeˉresult.Diagnostics));
        Equal(X64ˉnativeˉpublicationˉlayout.PLANNER_CANONICAL_SIZE, Bridgeˉresult.Moduleˉbytes.Length);
        Equal(
            NATIVE_PUBLICATION_BRIDGE_SHA256,
            Moduleˉdigest.Calculateˉsha256(Bridgeˉresult.Moduleˉbytes.AsSpan()));
        Equal(
            X64ˉnativeˉpublicationˉlayout.PLANNER_CANONICAL_SHA256,
            NATIVE_PUBLICATION_BRIDGE_SHA256);

        using (var Stream = typeof(X64ˉnativeˉpublicationˉlayout).Assembly
            .GetManifestResourceStream("Windvale.Native.Native-Publication-Bridge.wvb") ??
            throw new InvalidOperationException("The retained native-publication bridge was not embedded."))
        {
            var Retained = new byte[checked((int)Stream.Length)];
            Stream.ReadExactly(Retained);
            Sequenceˉequal(Bridgeˉresult.Moduleˉbytes, Retained);
        }

        var Bridge = Moduleˉcodec.Readˉandˉverify(Bridgeˉresult.Moduleˉbytes.AsSpan());
        Equal(Moduleˉprofile.Hosted, Bridge.Module.Profile);
        Equal(Capabilityˉcatalog.FILE_READ_BYTES, Bridge.Module.Capabilities.Single().Name);
        var Main = Bridge.Module.Exports.Single(Export => Export.Name == "Main");
        Equal(Valueˉtype.Bytes, Bridge.Module.Functions[Main.Targetˉindex].Returnˉtype.Kind);

        var Noˉservices = ImmutableArray<Nativeˉpublicationˉservice>.Empty;
        var Emptyˉplan = X64ˉnativeˉpublicationˉlayout.Plan(5, Noˉservices);
        Equal(5, Emptyˉplan.Fragmentˉbytes);
        Equal(16, Emptyˉplan.Imageˉbytes);
        True(Emptyˉplan.Placements.IsEmpty, "A service-free image received a service placement.");

        var Services = ImmutableArray.Create(
            new Nativeˉpublicationˉservice(Nativeˉservice.Processˉargumentˉcount, 5),
            new Nativeˉpublicationˉservice(Nativeˉservice.Processˉargument, 70));
        var First = X64ˉnativeˉpublicationˉlayout.Plan(5, Services);
        var Second = X64ˉnativeˉpublicationˉlayout.Plan(5, Services);
        Equal(102, First.Imageˉbytes);
        Sequenceˉequal(
            new[]
            {
                new Nativeˉpublicationˉplacement(
                    Nativeˉservice.Processˉargumentˉcount,
                    16,
                    5),
                new Nativeˉpublicationˉplacement(
                    Nativeˉservice.Processˉargument,
                    32,
                    70),
            },
            First.Placements);
        Sequenceˉequal(First.Placements, Second.Placements);

        var Maximumˉfragment = X64ˉnativeˉpublicationˉlayout.Plan(
            Nativeˉcontract.MAXIMUM_CODE_BYTES,
            Noˉservices);
        Equal(Nativeˉcontract.MAXIMUM_CODE_BYTES, Maximumˉfragment.Imageˉbytes);
        var Maximumˉimage = X64ˉnativeˉpublicationˉlayout.Plan(
            1,
            [
                new(
                    Nativeˉservice.Consoleˉwriteˉline,
                    X64ˉnativeˉpublicationˉlayout.MAXIMUM_IMAGE_BYTES - 16),
            ]);
        Equal(X64ˉnativeˉpublicationˉlayout.MAXIMUM_IMAGE_BYTES, Maximumˉimage.Imageˉbytes);
        var Allˉservices = Enumerable.Range(1, X64ˉnativeˉpublicationˉlayout.MAXIMUM_SERVICES)
            .Select(Value => new Nativeˉpublicationˉservice((Nativeˉservice)Value, 1))
            .ToImmutableArray();
        var Allˉplan = X64ˉnativeˉpublicationˉlayout.Plan(1, Allˉservices);
        Equal(193, Allˉplan.Imageˉbytes);
        Equal(16, Allˉplan.Placements[0].Offset);
        Equal(192, Allˉplan.Placements[^1].Offset);

        Throwsˉnative(
            "WVN4013",
            () => _ = X64ˉnativeˉpublicationˉlayout.Buildˉrequest(0, Noˉservices));
        Throwsˉnative(
            "WVN4013",
            () => _ = X64ˉnativeˉpublicationˉlayout.Buildˉrequest(
                Nativeˉcontract.MAXIMUM_CODE_BYTES + 1,
                Noˉservices));
        Throwsˉnative(
            "WVN4013",
            () => _ = X64ˉnativeˉpublicationˉlayout.Buildˉrequest(
                1,
                [new((Nativeˉservice)13, 1)]));
        Throwsˉnative(
            "WVN4013",
            () => _ = X64ˉnativeˉpublicationˉlayout.Buildˉrequest(
                1,
                [new(Nativeˉservice.Consoleˉwriteˉline, 0)]));
        Throwsˉnative(
            "WVN4013",
            () => _ = X64ˉnativeˉpublicationˉlayout.Buildˉrequest(
                1,
                [
                    new(Nativeˉservice.Processˉargument, 1),
                    new(Nativeˉservice.Processˉargumentˉcount, 1),
                ]));
        Throwsˉnative(
            "WVN4013",
            () => _ = X64ˉnativeˉpublicationˉlayout.Plan(
                1,
                [
                    new(
                        Nativeˉservice.Consoleˉwriteˉline,
                        X64ˉnativeˉpublicationˉlayout.MAXIMUM_IMAGE_BYTES),
                ]));

        var Request = X64ˉnativeˉpublicationˉlayout.Buildˉrequest(5, Services);
        var Response = X64ˉnativeˉpublicationˉlayout.Evaluateˉrequest(Request);
        var Repeatedˉresponse = X64ˉnativeˉpublicationˉlayout.Evaluateˉrequest(Request);
        Sequenceˉequal(Response, Repeatedˉresponse);
        Sequenceˉequal(
            First.Placements,
            X64ˉnativeˉpublicationˉlayout.Verifyˉresponse(5, Services, Response).Placements);

        static ImmutableArray<byte> Replaceˉu32(
            ImmutableArray<byte> input,
            int offset,
            uint value)
        {
            var Result = input.ToArray();
            BinaryPrimitives.WriteUInt32LittleEndian(Result.AsSpan(offset), value);
            return Result.ToImmutableArray();
        }

        static void Expectˉrequestˉfailure(
            ImmutableArray<byte> request,
            Nativeˉpublicationˉstatus status,
            uint failureˉoffset)
        {
            var Result = X64ˉnativeˉpublicationˉlayout.Evaluateˉrequest(request);
            Equal(X64ˉnativeˉpublicationˉlayout.RESPONSE_HEADER_BYTES, Result.Length);
            Equal(
                X64ˉnativeˉpublicationˉlayout.RESPONSE_MAGIC,
                BinaryPrimitives.ReadUInt32LittleEndian(Result.AsSpan()));
            Equal(
                (uint)status,
                BinaryPrimitives.ReadUInt32LittleEndian(Result.AsSpan()[12..]));
            Equal(
                failureˉoffset,
                BinaryPrimitives.ReadUInt32LittleEndian(Result.AsSpan()[16..]));
        }

        Expectˉrequestˉfailure([], Nativeˉpublicationˉstatus.Invalidˉsize, 0);
        Expectˉrequestˉfailure(
            Request.AsSpan(0, 23).ToArray().ToImmutableArray(),
            Nativeˉpublicationˉstatus.Invalidˉsize,
            23);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 0, 0),
            Nativeˉpublicationˉstatus.Invalidˉmagic,
            0);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 4, 2),
            Nativeˉpublicationˉstatus.Invalidˉversion,
            4);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 8, (uint)Request.Length + 1),
            Nativeˉpublicationˉstatus.Invalidˉsize,
            8);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 12, 0),
            Nativeˉpublicationˉstatus.Invalidˉfragment,
            12);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 12, Nativeˉcontract.MAXIMUM_CODE_BYTES + 1u),
            Nativeˉpublicationˉstatus.Invalidˉfragment,
            12);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 16, 13),
            Nativeˉpublicationˉstatus.Invalidˉservice,
            16);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 20, 1),
            Nativeˉpublicationˉstatus.Invalidˉreserved,
            20);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 24, 0),
            Nativeˉpublicationˉstatus.Invalidˉservice,
            24);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 28, 0),
            Nativeˉpublicationˉstatus.Invalidˉrange,
            28);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 32, 1),
            Nativeˉpublicationˉstatus.Invalidˉreserved,
            32);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 36, (uint)Nativeˉservice.Processˉargumentˉcount),
            Nativeˉpublicationˉstatus.Invalidˉorder,
            36);
        Expectˉrequestˉfailure(
            Replaceˉu32(
                Request,
                28,
                X64ˉnativeˉpublicationˉlayout.MAXIMUM_IMAGE_BYTES),
            Nativeˉpublicationˉstatus.Imageˉlimit,
            28);
        Expectˉrequestˉfailure(
            Request.Add(0),
            Nativeˉpublicationˉstatus.Invalidˉsize,
            8);

        Throwsˉnative(
            "WVN4014",
            () => _ = X64ˉnativeˉpublicationˉlayout.Verifyˉresponse(
                5,
                Services,
                Response.AsSpan(0, 31).ToArray().ToImmutableArray()));
        foreach (var (Offset, Value) in new (int Offset, uint Value)[]
        {
            (0, 0),
            (4, 2),
            (8, (uint)Response.Length + 1),
            (12, 99),
            (16, 0),
            (20, 6),
            (24, 103),
            (28, 1),
            (32, (uint)Nativeˉservice.Consoleˉwriteˉline),
            (36, 17),
            (40, 6),
            (36, uint.MaxValue),
            (40, uint.MaxValue),
        })
        {
            Throwsˉnative(
                "WVN4014",
                () => _ = X64ˉnativeˉpublicationˉlayout.Verifyˉresponse(
                    5,
                    Services,
                    Replaceˉu32(Response, Offset, Value)));
        }
        Throwsˉnative(
            "WVN4013",
            () => _ = X64ˉnativeˉpublicationˉlayout.Verifyˉresponse(
                5,
                Services,
                Replaceˉu32(Response, 12, (uint)Nativeˉpublicationˉstatus.Imageˉlimit)));

        var Dataˉfragment = X64ˉnativeˉbackend.Compile(
            Moduleˉcodec.Readˉandˉverify(Compileˉsuccess(
                "module Nativeˉpublicationˉdata profile portable; data Values: [i32] = [3, 5, 8, 13]; export fn Main() -> i32 { return Values[3]; }")))
            .Fragment;
        True(!Dataˉfragment.Patches.IsEmpty, "The publication fixture omitted its relative data patch.");
        foreach (var Patch in Dataˉfragment.Patches)
        {
            var Symbol = Dataˉfragment.Symbols.Single(Item => Item.Name == Patch.Symbol);
            Equal(
                checked((int)Symbol.Offset + Patch.Addend - (int)Patch.Offset),
                BinaryPrimitives.ReadInt32LittleEndian(
                    Dataˉfragment.Code.AsSpan(checked((int)Patch.Offset), sizeof(int))));
        }
        Equal(13, X64ˉnativeˉexecutor.Executeˉi32(Dataˉfragment));
    }

    private static void Windvaleˉnativeˉpublicationˉlifetimeˉruns()
    {
        var Coreˉresult = Seedˉcompiler.Compileˉmodules(
            new(
                "Compiler/Windvale/Native-Publication-Lifetime-Core.wv",
                NATIVE_PUBLICATION_LIFETIME_CORE_SOURCE),
            []);
        True(
            Coreˉresult.Success,
            "The Windvale native publication-lifetime core did not compile: " +
                string.Join(" | ", Coreˉresult.Diagnostics));
        Equal(4_955, Coreˉresult.Moduleˉbytes.Length);
        Equal(
            NATIVE_PUBLICATION_LIFETIME_CORE_SHA256,
            Moduleˉdigest.Calculateˉsha256(Coreˉresult.Moduleˉbytes.AsSpan()));

        var Bridgeˉresult = Seedˉcompiler.Compileˉmodules(
            new(
                "Compiler/Windvale/Native-Publication-Lifetime-Bridge.wv",
                NATIVE_PUBLICATION_LIFETIME_BRIDGE_SOURCE),
            [
                new(
                    "Compiler/Windvale/Native-Publication-Lifetime-Core.wv",
                    NATIVE_PUBLICATION_LIFETIME_CORE_SOURCE),
            ]);
        True(
            Bridgeˉresult.Success,
            "The Windvale native publication-lifetime bridge did not compile: " +
                string.Join(" | ", Bridgeˉresult.Diagnostics));
        Equal(
            X64ˉnativeˉpublicationˉlifetime.PLANNER_CANONICAL_SIZE,
            Bridgeˉresult.Moduleˉbytes.Length);
        Equal(
            NATIVE_PUBLICATION_LIFETIME_BRIDGE_SHA256,
            Moduleˉdigest.Calculateˉsha256(Bridgeˉresult.Moduleˉbytes.AsSpan()));
        Equal(
            X64ˉnativeˉpublicationˉlifetime.PLANNER_CANONICAL_SHA256,
            NATIVE_PUBLICATION_LIFETIME_BRIDGE_SHA256);

        using (var Stream = typeof(X64ˉnativeˉpublicationˉlifetime).Assembly
            .GetManifestResourceStream("Windvale.Native.Native-Publication-Lifetime-Bridge.wvb") ??
            throw new InvalidOperationException(
                "The retained native publication-lifetime bridge was not embedded."))
        {
            var Retained = new byte[checked((int)Stream.Length)];
            Stream.ReadExactly(Retained);
            Sequenceˉequal(Bridgeˉresult.Moduleˉbytes, Retained);
        }

        var Bridge = Moduleˉcodec.Readˉandˉverify(Bridgeˉresult.Moduleˉbytes.AsSpan());
        Equal(Moduleˉprofile.Hosted, Bridge.Module.Profile);
        Equal(Capabilityˉcatalog.FILE_READ_BYTES, Bridge.Module.Capabilities.Single().Name);
        var Main = Bridge.Module.Exports.Single(Export => Export.Name == "Main");
        Equal(Valueˉtype.Bytes, Bridge.Module.Functions[Main.Targetˉindex].Returnˉtype.Kind);

        var Expected = ImmutableArray.Create(
            new Nativeˉpublicationˉtransition(
                Nativeˉpublicationˉstate.Unallocated,
                Nativeˉpublicationˉaction.Allocateˉwritable,
                Nativeˉpublicationˉstate.Writable),
            new Nativeˉpublicationˉtransition(
                Nativeˉpublicationˉstate.Writable,
                Nativeˉpublicationˉaction.Copyˉimage,
                Nativeˉpublicationˉstate.Copied),
            new Nativeˉpublicationˉtransition(
                Nativeˉpublicationˉstate.Writable,
                Nativeˉpublicationˉaction.Release,
                Nativeˉpublicationˉstate.Released),
            new Nativeˉpublicationˉtransition(
                Nativeˉpublicationˉstate.Copied,
                Nativeˉpublicationˉaction.Sealˉexecutable,
                Nativeˉpublicationˉstate.Executable),
            new Nativeˉpublicationˉtransition(
                Nativeˉpublicationˉstate.Copied,
                Nativeˉpublicationˉaction.Release,
                Nativeˉpublicationˉstate.Released),
            new Nativeˉpublicationˉtransition(
                Nativeˉpublicationˉstate.Executable,
                Nativeˉpublicationˉaction.Invoke,
                Nativeˉpublicationˉstate.Invoked),
            new Nativeˉpublicationˉtransition(
                Nativeˉpublicationˉstate.Executable,
                Nativeˉpublicationˉaction.Release,
                Nativeˉpublicationˉstate.Released),
            new Nativeˉpublicationˉtransition(
                Nativeˉpublicationˉstate.Invoked,
                Nativeˉpublicationˉaction.Release,
                Nativeˉpublicationˉstate.Released),
            new Nativeˉpublicationˉtransition(
                Nativeˉpublicationˉstate.Released,
                Nativeˉpublicationˉaction.Complete,
                Nativeˉpublicationˉstate.Released));
        var Plan = X64ˉnativeˉpublicationˉlifetime.Plan(102);
        Equal(102, Plan.Imageˉbytes);
        Sequenceˉequal(Expected, Plan.Transitions);
        Sequenceˉequal(
            Expected,
            X64ˉnativeˉpublicationˉlifetime.Plan(102).Transitions);
        Equal(1, X64ˉnativeˉpublicationˉlifetime.Plan(1).Imageˉbytes);
        Equal(
            X64ˉnativeˉpublicationˉlayout.MAXIMUM_IMAGE_BYTES,
            X64ˉnativeˉpublicationˉlifetime.Plan(
                X64ˉnativeˉpublicationˉlayout.MAXIMUM_IMAGE_BYTES).Imageˉbytes);

        Throwsˉnative(
            "WVN4015",
            () => _ = X64ˉnativeˉpublicationˉlifetime.Buildˉrequest(0));
        Throwsˉnative(
            "WVN4015",
            () => _ = X64ˉnativeˉpublicationˉlifetime.Buildˉrequest(
                X64ˉnativeˉpublicationˉlayout.MAXIMUM_IMAGE_BYTES + 1));

        var Request = X64ˉnativeˉpublicationˉlifetime.Buildˉrequest(102);
        var Response = X64ˉnativeˉpublicationˉlifetime.Evaluateˉrequest(Request);
        Sequenceˉequal(
            Response,
            X64ˉnativeˉpublicationˉlifetime.Evaluateˉrequest(Request));
        Sequenceˉequal(
            Expected,
            X64ˉnativeˉpublicationˉlifetime.Verifyˉresponse(102, Response).Transitions);

        static ImmutableArray<byte> Replaceˉu32(
            ImmutableArray<byte> input,
            int offset,
            uint value)
        {
            var Result = input.ToArray();
            BinaryPrimitives.WriteUInt32LittleEndian(Result.AsSpan(offset), value);
            return Result.ToImmutableArray();
        }

        static void Expectˉrequestˉfailure(
            ImmutableArray<byte> request,
            Nativeˉpublicationˉlifetimeˉstatus status,
            uint failureˉoffset)
        {
            var Result = X64ˉnativeˉpublicationˉlifetime.Evaluateˉrequest(request);
            Equal(X64ˉnativeˉpublicationˉlifetime.RESPONSE_HEADER_BYTES, Result.Length);
            Equal(
                X64ˉnativeˉpublicationˉlifetime.RESPONSE_MAGIC,
                BinaryPrimitives.ReadUInt32LittleEndian(Result.AsSpan()));
            Equal(
                (uint)status,
                BinaryPrimitives.ReadUInt32LittleEndian(Result.AsSpan()[12..]));
            Equal(
                failureˉoffset,
                BinaryPrimitives.ReadUInt32LittleEndian(Result.AsSpan()[16..]));
        }

        Expectˉrequestˉfailure([], Nativeˉpublicationˉlifetimeˉstatus.Invalidˉsize, 0);
        Expectˉrequestˉfailure(
            Request.AsSpan(0, 19).ToArray().ToImmutableArray(),
            Nativeˉpublicationˉlifetimeˉstatus.Invalidˉsize,
            19);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 0, 0),
            Nativeˉpublicationˉlifetimeˉstatus.Invalidˉmagic,
            0);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 4, 2),
            Nativeˉpublicationˉlifetimeˉstatus.Invalidˉversion,
            4);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 8, 19),
            Nativeˉpublicationˉlifetimeˉstatus.Invalidˉsize,
            8);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 12, 0),
            Nativeˉpublicationˉlifetimeˉstatus.Invalidˉimage,
            12);
        Expectˉrequestˉfailure(
            Replaceˉu32(
                Request,
                12,
                X64ˉnativeˉpublicationˉlayout.MAXIMUM_IMAGE_BYTES + 1u),
            Nativeˉpublicationˉlifetimeˉstatus.Invalidˉimage,
            12);
        Expectˉrequestˉfailure(
            Replaceˉu32(Request, 16, 1),
            Nativeˉpublicationˉlifetimeˉstatus.Invalidˉreserved,
            16);
        Expectˉrequestˉfailure(
            Request.Add(0),
            Nativeˉpublicationˉlifetimeˉstatus.Invalidˉsize,
            8);

        Throwsˉnative(
            "WVN4016",
            () => _ = X64ˉnativeˉpublicationˉlifetime.Verifyˉresponse(
                102,
                Response.AsSpan(0, 31).ToArray().ToImmutableArray()));
        foreach (var (Offset, Value) in new (int Offset, uint Value)[]
        {
            (0, 0),
            (4, 2),
            (8, (uint)Response.Length + 1),
            (12, 99),
            (16, 0),
            (20, 103),
            (24, 8),
            (28, 1),
            (32, 1),
            (36, 2),
            (40, 2),
            (44, uint.MaxValue),
            (48, uint.MaxValue),
            (52, uint.MaxValue),
        })
        {
            Throwsˉnative(
                "WVN4016",
                () => _ = X64ˉnativeˉpublicationˉlifetime.Verifyˉresponse(
                    102,
                    Replaceˉu32(Response, Offset, Value)));
        }
        Throwsˉnative(
            "WVN4015",
            () => _ = X64ˉnativeˉpublicationˉlifetime.Verifyˉresponse(
                102,
                Replaceˉu32(
                    Response,
                    12,
                    (uint)Nativeˉpublicationˉlifetimeˉstatus.Invalidˉimage)));
        Throwsˉnative(
            "WVN4016",
            () => _ = Nativeˉexecutableˉimage.Allocateˉwritable(
                Plan with { Transitions = Plan.Transitions.RemoveAt(0) }));
        Throwsˉnative(
            "WVN4016",
            () => _ = Nativeˉexecutableˉimage.Allocateˉwritable(
                Plan with
                {
                    Transitions = Plan.Transitions.SetItem(
                        0,
                        Plan.Transitions[0] with
                        {
                            Nextˉstate = Nativeˉpublicationˉstate.Executable,
                        }),
                }));

        var Writable = Nativeˉexecutableˉimage.Allocateˉwritable(
            X64ˉnativeˉpublicationˉlifetime.Plan(1));
        Equal(Nativeˉpublicationˉstate.Writable, Writable.State);
        Throwsˉnative("WVN4017", () => _ = Writable.Executableˉaddress);
        Throwsˉnative("WVN4017", () => Writable.Sealˉexecutable());
        Throwsˉnative("WVN4017", () => Writable.Copyˉimage([0x90, 0xC3]));
        Writable.Dispose();
        Equal(Nativeˉpublicationˉstate.Released, Writable.State);

        var Copied = Nativeˉexecutableˉimage.Allocateˉwritable(
            X64ˉnativeˉpublicationˉlifetime.Plan(1));
        Copied.Copyˉimage([0xC3]);
        Equal(Nativeˉpublicationˉstate.Copied, Copied.State);
        Copied.Dispose();
        Equal(Nativeˉpublicationˉstate.Released, Copied.State);

        var Sealed = Nativeˉexecutableˉimage.Allocateˉwritable(
            X64ˉnativeˉpublicationˉlifetime.Plan(1));
        Sealed.Copyˉimage([0xC3]);
        Sealed.Sealˉexecutable();
        Equal(Nativeˉpublicationˉstate.Executable, Sealed.State);
        Sealed.Dispose();
        Equal(Nativeˉpublicationˉstate.Released, Sealed.State);

        var Executable = Nativeˉexecutableˉimage.Allocateˉwritable(
            X64ˉnativeˉpublicationˉlifetime.Plan(1));
        try
        {
            Executable.Copyˉimage([0xC3]);
            Executable.Sealˉexecutable();
            Equal(Nativeˉpublicationˉstate.Executable, Executable.State);
            Throwsˉnative("WVN4017", () => Executable.Copyˉimage([0xC3]));
            Equal(29, Executable.Invoke(Address =>
            {
                True(Address != IntPtr.Zero, "The executable image exposed a null address.");
                return 29;
            }));
            Equal(Nativeˉpublicationˉstate.Invoked, Executable.State);
            Throwsˉnative("WVN4017", () => _ = Executable.Invoke(_ => 0));
        }
        finally
        {
            Executable.Dispose();
        }
        Equal(Nativeˉpublicationˉstate.Released, Executable.State);
        Executable.Dispose();
    }

    private static void Nativeˉhostedˉinputˉinspectsˉwvb()
    {
        var Source = WVB_HEADER_INSPECTOR_SOURCE;
        var Input = Compileˉsuccess(NATIVE_CONSTANT_SOURCE).ToImmutableArray();
        var Verified = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess(Source));
        var Authorized = ImmutableHashSet.Create(
            StringComparer.Ordinal,
            Capabilityˉcatalog.CONSOLE_WRITE_LINE,
            Capabilityˉcatalog.FILE_READ_BYTES,
            Capabilityˉcatalog.PROCESS_ARGUMENT,
            Capabilityˉcatalog.PROCESS_ARGUMENT_COUNT);

        Hostedˉresourceˉcontext Makeˉresources(
            TextWriter output,
            Testˉfileˉreader reader,
            string resourceˉname = "input.wvb") =>
            new([resourceˉname], output, TextWriter.Null, reader);
        Testˉfileˉreader Makeˉreader() => new((Name, Maximum) =>
        {
            Equal("input.wvb", Name);
            True(Input.Length <= Maximum, "The WVB fixture exceeded the hosted reader bound.");
            return Input;
        });

        var Referenceˉoutput = new StringWriter();
        var Referenceˉreader = Makeˉreader();
        var Referenceˉresources = Makeˉresources(Referenceˉoutput, Referenceˉreader);
        var Reference = new Referenceˉruntime(
            Verified,
            new Referenceˉcapabilityˉhost(Referenceˉresources),
            new(Authorized)).Runˉmain();
        Equal(0, Reference.Exitˉcode);
        Equal("input.wvb\nwvb-header=pass\n", Referenceˉoutput.ToString());
        Equal(1, Referenceˉreader.Readˉcount);

        var First = X64ˉnativeˉbackend.Compile(Verified);
        var Second = X64ˉnativeˉbackend.Compile(Verified);
        Sequenceˉequal(First.Fragment.Code, Second.Fragment.Code);
        Sequenceˉequal(
            [
                Nativeˉservice.Consoleˉwriteˉline,
                Nativeˉservice.Processˉargumentˉcount,
                Nativeˉservice.Processˉargument,
                Nativeˉservice.Fileˉreadˉbytes,
            ],
            First.Fragment.Requiredˉservices);
        var Operations = First.Module.Functions
            .SelectMany(Function => Function.Blocks)
            .SelectMany(Block => Block.Operations)
            .ToImmutableArray();
        True(Operations.Any(Operation => Operation is Nativeˉprocessˉargumentˉcount),
            "Native machine IR omitted process.argument_count.");
        True(Operations.Any(Operation => Operation is Nativeˉprocessˉargument),
            "Native machine IR omitted process.argument.");
        True(Operations.Count(Operation => Operation is Nativeˉfileˉreadˉbytes) == 2,
            "Native machine IR did not retain both file.read_bytes calls.");
        foreach (var Service in new[]
        {
            Nativeˉservice.Processˉargumentˉcount,
            Nativeˉservice.Processˉargument,
        })
        {
            var Firstˉservice = X64ˉnativeˉargumentˉservices.Build(Service);
            var Secondˉservice = X64ˉnativeˉargumentˉservices.Build(Service);
            Sequenceˉequal(Firstˉservice, Secondˉservice);
            X64ˉnativeˉargumentˉservices.Verify(Service, Firstˉservice.AsSpan());
            var Corruptedˉservice = Firstˉservice.ToArray();
            Corruptedˉservice[0] ^= 0x01;
            Throwsˉinvalidˉoperation(
                $"Native {Service} service identity",
                () => X64ˉnativeˉargumentˉservices.Verify(Service, Corruptedˉservice));
        }
        Equal(
            X64ˉnativeˉargumentˉservices.ARGUMENT_COUNT_CANONICAL_SIZE,
            X64ˉnativeˉargumentˉservices.Build(
                Nativeˉservice.Processˉargumentˉcount).Length);
        Equal(
            X64ˉnativeˉargumentˉservices.ARGUMENT_CANONICAL_SIZE,
            X64ˉnativeˉargumentˉservices.Build(Nativeˉservice.Processˉargument).Length);

        foreach (var Platform in new[]
        {
            Nativeˉfileˉinputˉplatform.Windows,
            Nativeˉfileˉinputˉplatform.Linux,
        })
        {
            var Firstˉservice = X64ˉnativeˉfileˉinputˉservice.Build(Platform);
            var Secondˉservice = X64ˉnativeˉfileˉinputˉservice.Build(Platform);
            Sequenceˉequal(Firstˉservice, Secondˉservice);
            Equal(X64ˉnativeˉfileˉinputˉservice.Canonicalˉsize(Platform), Firstˉservice.Length);
            Equal(
                X64ˉnativeˉfileˉinputˉservice.Canonicalˉsha256(Platform),
                Convert.ToHexString(SHA256.HashData(Firstˉservice.AsSpan())).ToLowerInvariant());
            X64ˉnativeˉfileˉinputˉservice.Verify(Platform, Firstˉservice.AsSpan());
            var Corruptedˉservice = Firstˉservice.ToArray();
            Corruptedˉservice[0] ^= 0x01;
            Throwsˉinvalidˉoperation(
                $"Native {Platform} file-input service identity",
                () => X64ˉnativeˉfileˉinputˉservice.Verify(Platform, Corruptedˉservice));
        }

        using var Nativeˉoutput = new Nativeˉoutputˉcapture();
        var Nativeˉpath = Path.Combine(
            Path.GetTempPath(),
            $"windvale-native-file-input-{Guid.NewGuid():N}.wvb");
        var Nativeˉreader = new Testˉfileˉreader((_, _) =>
            throw new InvalidOperationException("Native execution called the Stage 0 file reader."));
        try
        {
            File.WriteAllBytes(Nativeˉpath, Input.AsSpan());
            var Nativeˉresources = Makeˉresources(
                TextWriter.Null,
                Nativeˉreader,
                Nativeˉpath);
            Equal(
                0,
                X64ˉnativeˉexecutor.Executeˉi32(
                    First.Fragment,
                    hostˉservices: new(
                        Nativeˉoutput.Channel,
                        Authorized,
                        Nativeˉresources,
                        fileˉinput: Nativeˉfileˉinput.Hostˉfileˉsystem())));
            Equal($"{Nativeˉpath}\nwvb-header=pass\n", Nativeˉoutput.Readˉtext());
            Equal(0, Nativeˉreader.Readˉcount);

            var Objectˉbytes = Nativeˉobjectˉsink.Writeˉwvo(First.Fragment);
            var Linked = Linkˉsuccess(
                [Objectˉbytes.ToArray()],
                new(Linkˉcontract.DEFAULT_BASE_ADDRESS, "Main"));
            Sequenceˉequal(First.Fragment.Code, Linked.Imageˉbytes);
            using var Linkedˉoutput = new Nativeˉoutputˉcapture();
            Equal(
                0,
                X64ˉnativeˉexecutor.Executeˉi32(
                    First.Fragment with { Code = Linked.Imageˉbytes },
                    hostˉservices: new(
                        Linkedˉoutput.Channel,
                        Authorized,
                        Nativeˉresources,
                        fileˉinput: Nativeˉfileˉinput.Hostˉfileˉsystem())));
            Equal($"{Nativeˉpath}\nwvb-header=pass\n", Linkedˉoutput.Readˉtext());
            Equal(0, Nativeˉreader.Readˉcount);
        }
        finally
        {
            File.Delete(Nativeˉpath);
        }

        const string Argumentˉtableˉsource = """
            module Nativeˉargumentˉtable profile hosted;

            capability console.write_line;
            capability process.argument;
            capability process.argument_count;

            export fn Main() -> i32 {
                let Count: u32 = process.argument_count();
                if Count != 67u32 { return 1; }
                var Index: u32 = 0u32;
                while Index < Count {
                    console.write_line(process.argument(Index));
                    Index = Index + 1u32;
                }
                return 0;
            }
            """;
        var Argumentˉtableˉverified = Moduleˉcodec.Readˉandˉverify(
            Compileˉsuccess(Argumentˉtableˉsource));
        var Argumentˉtableˉfragment = X64ˉnativeˉbackend.Compile(
            Argumentˉtableˉverified).Fragment;
        var Maximumˉarguments = Enumerable.Range(0, Hostedˉresourceˉlimits.MAX_ARGUMENTS)
            .Select(Index => Index switch
            {
                0 => "",
                1 => "ascii",
                2 => "euro-€",
                3 => "supplementary-😀",
                _ => $"argument-{Index}",
            })
            .ToImmutableArray();
        var Expectedˉarguments = string.Concat(Maximumˉarguments.Select(Argument => $"{Argument}\n"));
        var Argumentˉtableˉreferenceˉoutput = new StringWriter();
        var Argumentˉtableˉreferenceˉresources = new Hostedˉresourceˉcontext(
            Maximumˉarguments,
            Argumentˉtableˉreferenceˉoutput,
            TextWriter.Null);
        var Argumentˉtableˉreference = new Referenceˉruntime(
            Argumentˉtableˉverified,
            new Referenceˉcapabilityˉhost(Argumentˉtableˉreferenceˉresources),
            new(Authorized)).Runˉmain();
        Equal(0, Argumentˉtableˉreference.Exitˉcode);
        Equal(Expectedˉarguments, Argumentˉtableˉreferenceˉoutput.ToString());
        using var Argumentˉtableˉnativeˉoutput = new Nativeˉoutputˉcapture();
        var Argumentˉtableˉnativeˉresources = new Hostedˉresourceˉcontext(
            Maximumˉarguments,
            TextWriter.Null,
            TextWriter.Null);
        Equal(
            0,
            X64ˉnativeˉexecutor.Executeˉi32(
                Argumentˉtableˉfragment,
                maximumˉinstructions: Argumentˉtableˉreference.Executedˉinstructions,
                hostˉservices: new(
                    Argumentˉtableˉnativeˉoutput.Channel,
                    Authorized,
                    Argumentˉtableˉnativeˉresources)));
        Equal(Expectedˉarguments, Argumentˉtableˉnativeˉoutput.Readˉtext());

        var Emptyˉargumentˉresources = new Hostedˉresourceˉcontext(
            [],
            TextWriter.Null,
            TextWriter.Null);
        Equal(
            1,
            X64ˉnativeˉexecutor.Executeˉi32(
                Argumentˉtableˉfragment,
                hostˉservices: new(
                    Argumentˉtableˉnativeˉoutput.Channel,
                    Authorized,
                    Emptyˉargumentˉresources)));

        foreach (var Pointerˉoffset in new[]
        {
            Nativeˉserviceˉtableˉcontract.CONSOLE_WRITE_LINE_POINTER_OFFSET,
            Nativeˉserviceˉtableˉcontract.PROCESS_ARGUMENT_COUNT_POINTER_OFFSET,
            Nativeˉserviceˉtableˉcontract.PROCESS_ARGUMENT_POINTER_OFFSET,
            Nativeˉserviceˉtableˉcontract.FILE_READ_BYTES_POINTER_OFFSET,
        })
        {
            var Corrupted = First.Fragment.Code.ToArray();
            var Serviceˉload = Corrupted.AsSpan().IndexOf(new byte[]
            {
                0x49, 0x8B, 0x47,
                Nativeˉexecutionˉcontextˉcontract.SERVICE_TABLE_POINTER_OFFSET,
                0x48, 0x8B, 0x40,
                checked((byte)Pointerˉoffset),
            });
            True(Serviceˉload >= 0, $"Native code omitted service-table offset {Pointerˉoffset}.");
            Corrupted[Serviceˉload + 7] ^= 0x01;
            Throwsˉnative(
                "WVN3030",
                () => _ = Nativeˉfragmentˉverifier.Verify(
                    First.Fragment with { Code = Corrupted.ToImmutableArray() }));
        }
        Throwsˉnative(
            "WVN3009",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with
                {
                    Requiredˉservices =
                    [
                        Nativeˉservice.Processˉargument,
                        Nativeˉservice.Processˉargumentˉcount,
                    ],
                }));

        var Invalidˉargumentˉverified = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess(
            Source.Replace("process.argument(0u32)", "process.argument(1u32)", StringComparison.Ordinal)));
        var Invalidˉargumentˉfragment = X64ˉnativeˉbackend.Compile(Invalidˉargumentˉverified).Fragment;
        var Missingˉargumentˉresources = Makeˉresources(TextWriter.Null, Makeˉreader());
        Throwsˉnativeˉtrap(
            "WVR3020",
            () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                Invalidˉargumentˉfragment,
                hostˉservices: new(
                    Argumentˉtableˉnativeˉoutput.Channel,
                    Authorized,
                    Missingˉargumentˉresources,
                    fileˉinput: Nativeˉfileˉinput.Hostˉfileˉsystem())));

        var Missingˉfileˉreader = new Testˉfileˉreader((_, _) =>
            throw new InvalidOperationException("Native execution called the Stage 0 file reader."));
        var Missingˉpath = Path.Combine(
            Path.GetTempPath(),
            $"windvale-native-missing-{Guid.NewGuid():N}.wvb");
        var Missingˉfileˉresources = Makeˉresources(
            TextWriter.Null,
            Missingˉfileˉreader,
            Missingˉpath);
        Throwsˉnativeˉtrap(
            "WVR3022",
            () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                First.Fragment,
                hostˉservices: new(
                    Argumentˉtableˉnativeˉoutput.Channel,
                    Authorized,
                    Missingˉfileˉresources,
                    fileˉinput: Nativeˉfileˉinput.Hostˉfileˉsystem())));
        Equal(0, Missingˉfileˉreader.Readˉcount);

        var Invalidˉnameˉresources = Makeˉresources(
            TextWriter.Null,
            Missingˉfileˉreader,
            "");
        Throwsˉnativeˉtrap(
            "WVR3021",
            () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                First.Fragment,
                hostˉservices: new(
                    Argumentˉtableˉnativeˉoutput.Channel,
                    Authorized,
                    Invalidˉnameˉresources,
                    fileˉinput: Nativeˉfileˉinput.Hostˉfileˉsystem())));

        var Oversizedˉpath = Path.Combine(
            Path.GetTempPath(),
            $"windvale-native-oversized-{Guid.NewGuid():N}.bin");
        try
        {
            File.WriteAllBytes(
                Oversizedˉpath,
                new byte[Bytecodeˉlimits.MAX_BYTE_DATA_BYTES + 1]);
            var Oversizedˉresources = Makeˉresources(
                TextWriter.Null,
                Missingˉfileˉreader,
                Oversizedˉpath);
            Throwsˉnativeˉtrap(
                "WVR3025",
                () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                    First.Fragment,
                    hostˉservices: new(
                        Argumentˉtableˉnativeˉoutput.Channel,
                        Authorized,
                        Oversizedˉresources,
                        fileˉinput: Nativeˉfileˉinput.Hostˉfileˉsystem())));
        }
        finally
        {
            File.Delete(Oversizedˉpath);
        }

        var Snapshotˉdirectory = Path.Combine(
            Path.GetTempPath(),
            $"windvale-native-snapshots-{Guid.NewGuid():N}");
        Directory.CreateDirectory(Snapshotˉdirectory);
        try
        {
            var Snapshotˉpaths = Enumerable
                .Range(0, Hostedˉresourceˉlimits.MAX_FILE_SNAPSHOTS + 1)
                .Select(Index => Path.Combine(Snapshotˉdirectory, $"input-{Index}.bin"))
                .ToImmutableArray();
            foreach (var Pathˉname in Snapshotˉpaths)
            {
                File.WriteAllBytes(Pathˉname, []);
            }
            var Snapshotˉcalls = string.Join(
                Environment.NewLine,
                Enumerable.Range(0, Snapshotˉpaths.Length).Select(Index =>
                    $"    file.read_bytes(process.argument({Index}u32));"));
            var Snapshotˉsource = $$"""
                module Nativeˉfileˉsnapshotˉlimit profile hosted;
                capability file.read_bytes;
                capability process.argument;
                export fn Main() -> i32 {
                {{Snapshotˉcalls}}
                    return 0;
                }
                """;
            var Snapshotˉfragment = X64ˉnativeˉbackend.Compile(
                Moduleˉcodec.Readˉandˉverify(
                    Compileˉsuccess(Snapshotˉsource))).Fragment;
            var Snapshotˉresources = new Hostedˉresourceˉcontext(
                Snapshotˉpaths,
                TextWriter.Null,
                TextWriter.Null,
                Missingˉfileˉreader);
            Throwsˉnativeˉtrap(
                "WVR3028",
                () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                    Snapshotˉfragment,
                    hostˉservices: new(
                        null,
                        Authorized,
                        Snapshotˉresources,
                        fileˉinput: Nativeˉfileˉinput.Hostˉfileˉsystem())));
        }
        finally
        {
            Directory.Delete(Snapshotˉdirectory, recursive: true);
        }
        Equal(0, Missingˉfileˉreader.Readˉcount);
    }

    private static void Nativeˉfileˉoutputˉpublishes()
    {
        const string Source = """
            module Nativeˉfileˉoutput profile hosted;

            capability file.write_bytes;
            capability process.argument;

            data Payload: bytes = [0, 65, 226, 130, 172, 240, 159, 152, 128, 255];
            data Empty: bytes = [];

            export fn Main() -> i32 {
                file.write_bytes(process.argument(0u32), Payload);
                file.write_bytes(process.argument(1u32), Empty);
                return 0;
            }
            """;
        var First = X64ˉnativeˉbackend.Compile(
            Moduleˉcodec.Readˉandˉverify(Compileˉsuccess(Source)));
        var Second = X64ˉnativeˉbackend.Compile(
            Moduleˉcodec.Readˉandˉverify(Compileˉsuccess(Source)));
        Sequenceˉequal(First.Fragment.Code, Second.Fragment.Code);
        Sequenceˉequal(
            [Nativeˉservice.Processˉargument, Nativeˉservice.Fileˉwriteˉbytes],
            First.Fragment.Requiredˉservices);
        Equal(2, First.Module.Functions[0].Blocks
            .SelectMany(Block => Block.Operations)
            .OfType<Nativeˉfileˉwriteˉbytes>()
            .Count());
        _ = Nativeˉfragmentˉverifier.Verify(First.Fragment);
        var Corruptedˉcall = First.Fragment.Code.ToArray();
        var Fileˉwriteˉload = Corruptedˉcall.AsSpan().IndexOf(new byte[]
        {
            0x49, 0x8B, 0x47,
            Nativeˉexecutionˉcontextˉcontract.SERVICE_TABLE_POINTER_OFFSET,
            0x48, 0x8B, 0x40,
            Nativeˉserviceˉtableˉcontract.FILE_WRITE_BYTES_POINTER_OFFSET,
        });
        True(Fileˉwriteˉload >= 0, "Native code omitted the file.write_bytes service-table load.");
        Corruptedˉcall[Fileˉwriteˉload + 7] ^= 0x01;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉcall.ToImmutableArray() }));

        foreach (var Platform in Enum.GetValues<Nativeˉfileˉinputˉplatform>())
        {
            var Leaf = X64ˉnativeˉfileˉoutputˉservice.Build(Platform);
            Equal(X64ˉnativeˉfileˉoutputˉservice.Canonicalˉsize(Platform), Leaf.Length);
            Equal(
                X64ˉnativeˉfileˉoutputˉservice.Canonicalˉsha256(Platform),
                Convert.ToHexString(SHA256.HashData(Leaf.AsSpan())).ToLowerInvariant());
            X64ˉnativeˉfileˉoutputˉservice.Verify(Platform, Leaf.AsSpan());
            var Corrupted = Leaf.ToArray();
            Corrupted[^1] ^= 0x01;
            Throwsˉinvalidˉoperation(
                $"Native {Platform} file-output service identity",
                () => X64ˉnativeˉfileˉoutputˉservice.Verify(Platform, Corrupted));
        }

        var Authorized = ImmutableHashSet.Create(
            StringComparer.Ordinal,
            Capabilityˉcatalog.FILE_WRITE_BYTES,
            Capabilityˉcatalog.PROCESS_ARGUMENT);
        var Directoryˉpath = Path.Combine(
            Path.GetTempPath(),
            $"windvale-native-file-output-{Guid.NewGuid():N}");
        Directory.CreateDirectory(Directoryˉpath);
        var Payloadˉpath = Path.Combine(Directoryˉpath, "published-ǣ-😀.bin");
        var Emptyˉpath = Path.Combine(Directoryˉpath, "empty.bin");
        var Expected = new byte[] { 0, 65, 226, 130, 172, 240, 159, 152, 128, 255 };
        try
        {
            File.WriteAllBytes(Payloadˉpath, Enumerable.Repeat((byte)0xCC, 128).ToArray());
            var Resources = new Hostedˉresourceˉcontext(
                [Payloadˉpath, Emptyˉpath],
                TextWriter.Null,
                TextWriter.Null);
            var Host = new Nativeˉhostˉservices(
                null,
                Authorized,
                Resources,
                fileˉoutput: Nativeˉfileˉoutput.Hostˉfileˉsystem());

            using (var Corruptedˉtable = new Nativeˉfileˉoutputˉcontext(Host, required: true))
            {
                Marshal.WriteByte(
                    Corruptedˉtable.Address,
                    Nativeˉfileˉoutputˉtableˉcontract.RESERVED_OFFSET,
                    1);
                Throwsˉinvalidˉoperation(
                    "The native file-output table violated its independently verified static layout.",
                    Corruptedˉtable.Verifyˉcompleted);
            }

            Throwsˉnativeˉtrap(
                "WVR3010",
                () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                    First.Fragment,
                    hostˉservices: new(
                        null,
                        [Capabilityˉcatalog.PROCESS_ARGUMENT],
                        Resources,
                        fileˉoutput: Nativeˉfileˉoutput.Hostˉfileˉsystem())));
            Throwsˉnativeˉtrap(
                "WVR3001",
                () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                    First.Fragment,
                    hostˉservices: new(null, Authorized, Resources)));

            Equal(0, X64ˉnativeˉexecutor.Executeˉi32(First.Fragment, hostˉservices: Host));
            Sequenceˉequal(Expected, File.ReadAllBytes(Payloadˉpath));
            Equal(0L, new FileInfo(Emptyˉpath).Length);

            var Object = Nativeˉobjectˉsink.Writeˉwvo(First.Fragment);
            var Linked = Linkˉsuccess(
                [Object.ToArray()],
                new(Linkˉcontract.DEFAULT_BASE_ADDRESS, "Main"));
            File.WriteAllBytes(Payloadˉpath, Enumerable.Repeat((byte)0xDD, 64).ToArray());
            Equal(
                0,
                X64ˉnativeˉexecutor.Executeˉi32(
                    First.Fragment with { Code = Linked.Imageˉbytes },
                    hostˉservices: Host));
            Sequenceˉequal(Expected, File.ReadAllBytes(Payloadˉpath));

            const string Copyˉsource = """
                module Nativeˉfileˉcopy profile hosted;
                capability file.read_bytes;
                capability file.write_bytes;
                capability process.argument;
                export fn Main() -> i32 {
                    file.write_bytes(
                        process.argument(1u32),
                        file.read_bytes(process.argument(0u32))
                    );
                    return 0;
                }
                """;
            var Copyˉfragment = X64ˉnativeˉbackend.Compile(
                Moduleˉcodec.Readˉandˉverify(Compileˉsuccess(Copyˉsource))).Fragment;
            var Maximumˉinputˉpath = Path.Combine(Directoryˉpath, "maximum-input.bin");
            var Maximumˉoutputˉpath = Path.Combine(Directoryˉpath, "maximum-output.bin");
            var Maximumˉbytes = new byte[Bytecodeˉlimits.MAX_BYTE_DATA_BYTES];
            for (var Index = 0; Index < Maximumˉbytes.Length; Index++)
            {
                Maximumˉbytes[Index] = unchecked((byte)(Index * 131));
            }
            File.WriteAllBytes(Maximumˉinputˉpath, Maximumˉbytes);
            var Copyˉresources = new Hostedˉresourceˉcontext(
                [Maximumˉinputˉpath, Maximumˉoutputˉpath],
                TextWriter.Null,
                TextWriter.Null);
            Equal(
                0,
                X64ˉnativeˉexecutor.Executeˉi32(
                    Copyˉfragment,
                    hostˉservices: new(
                        null,
                        [
                            Capabilityˉcatalog.FILE_READ_BYTES,
                            Capabilityˉcatalog.FILE_WRITE_BYTES,
                            Capabilityˉcatalog.PROCESS_ARGUMENT,
                        ],
                        Copyˉresources,
                        fileˉinput: Nativeˉfileˉinput.Hostˉfileˉsystem(),
                        fileˉoutput: Nativeˉfileˉoutput.Hostˉfileˉsystem())));
            Sequenceˉequal(Maximumˉbytes, File.ReadAllBytes(Maximumˉoutputˉpath));

            var Missingˉparent = Path.Combine(Directoryˉpath, "missing", "output.bin");
            var Missingˉresources = new Hostedˉresourceˉcontext(
                [Missingˉparent, Emptyˉpath],
                TextWriter.Null,
                TextWriter.Null);
            Throwsˉnativeˉtrap(
                "WVR3022",
                () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                    First.Fragment,
                    hostˉservices: new(
                        null,
                        Authorized,
                        Missingˉresources,
                        fileˉoutput: Nativeˉfileˉoutput.Hostˉfileˉsystem())));

            var Deniedˉresources = new Hostedˉresourceˉcontext(
                [Directoryˉpath, Emptyˉpath],
                TextWriter.Null,
                TextWriter.Null);
            Throwsˉnativeˉtrap(
                "WVR3023",
                () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                    First.Fragment,
                    hostˉservices: new(
                        null,
                        Authorized,
                        Deniedˉresources,
                        fileˉoutput: Nativeˉfileˉoutput.Hostˉfileˉsystem())));

            var Invalidˉresources = new Hostedˉresourceˉcontext(
                ["", Emptyˉpath],
                TextWriter.Null,
                TextWriter.Null);
            Throwsˉnativeˉtrap(
                "WVR3021",
                () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                    First.Fragment,
                    hostˉservices: new(
                        null,
                        Authorized,
                        Invalidˉresources,
                        fileˉoutput: Nativeˉfileˉoutput.Hostˉfileˉsystem())));
        }
        finally
        {
            Directory.Delete(Directoryˉpath, recursive: true);
        }

        var Compilerˉfixture = EXACT_COMPILER_WVB.Value;
        var Compilerˉtoolˉbytes = Compilerˉfixture.Bytes;
        Equal(
            SOURCE_WVB_TOOL_SHA256,
            Moduleˉdigest.Calculateˉsha256(Compilerˉtoolˉbytes.AsSpan()));
        var Compilerˉtool = Compilerˉfixture.Module;
        var Compilerˉnative = EXACT_COMPILER_NATIVE.Value;
        Nativeˉshapesˉmatchˉverifiedˉwvb(Compilerˉtool, Compilerˉnative);
        var Compilerˉrecordˉstorage = Nativeˉrecordˉstorageˉplanner.Measure(
            Compilerˉnative.Module);
        Nativeˉrecordˉstorageˉisˉvalid(
            Compilerˉnative.Module,
            Compilerˉrecordˉstorage);
        var Largestˉrecordˉframe = Compilerˉrecordˉstorage.MaxBy(
            Function => Function.Projectedˉframeˉcells)!;
        True(
            Compilerˉrecordˉstorage.All(Function =>
                Function.Persistentˉrecordˉfieldˉcells <=
                    Function.Declaredˉrecordˉlocalˉfieldˉcells &&
                Function.Peakˉliveˉrecordˉfieldˉcells ==
                    Function.Scratchˉrecordˉfieldˉcells &&
                Function.Scratchˉrecordˉfieldˉcells <=
                    Function.Blockˉrecordˉfieldˉcells &&
                Function.Projectedˉframeˉcells <= Nativeˉcontract.MAXIMUM_FRAME_SLOTS &&
                Function.Projectedˉframeˉcells == checked(
                    Function.Existingˉframeˉcells +
                    Function.Persistentˉrecordˉfieldˉcells +
                    Function.Scratchˉrecordˉfieldˉcells +
                    (Function.Returnsˉrecord ? 1 : 0))),
            "Native record-storage accounting violated its bounded frame model.");
        Equal(
            "NATIVE_RECORD_STORAGE functions=419 record-functions=324 " +
            "parameters=416 assigned-parameters=0 locals=13221 declared=228141 persistent=12754 " +
            "block=121642 peak-live=9941 scratch=9941 values=24380 slots=6032 " +
            "return-functions=263 return-fields=3974 max-frame=1916 " +
            "largest-declared=17538 largest-persistent=229 largest-peak=147 " +
            "largest-scratch=147 max-existing=1539 max-width=34 largest-index=318 " +
            "largest-name=__WvM8F50 nested=0 " +
            "offset-map=809e169723c0360053ce51d3c776aa3e34ed53fbaad849b329337912dbc27a53",
            $"NATIVE_RECORD_STORAGE functions={Compilerˉrecordˉstorage.Length} " +
            $"record-functions={Compilerˉrecordˉstorage.Count(Function => Function.Recordˉvalueˉidentifiers > 0 || Function.Recordˉparameterˉbindings > 0 || Function.Recordˉlocalˉbindings > 0 || Function.Returnsˉrecord)} " +
            $"parameters={Compilerˉrecordˉstorage.Sum(Function => Function.Recordˉparameterˉbindings)} " +
            $"assigned-parameters={Compilerˉrecordˉstorage.Sum(Function => Function.Assignedˉrecordˉparameterˉbindings)} " +
            $"locals={Compilerˉrecordˉstorage.Sum(Function => Function.Recordˉlocalˉbindings)} " +
            $"declared={Compilerˉrecordˉstorage.Sum(Function => Function.Declaredˉrecordˉlocalˉfieldˉcells)} " +
            $"persistent={Compilerˉrecordˉstorage.Sum(Function => Function.Persistentˉrecordˉfieldˉcells)} " +
            $"block={Compilerˉrecordˉstorage.Sum(Function => Function.Blockˉrecordˉfieldˉcells)} " +
            $"peak-live={Compilerˉrecordˉstorage.Sum(Function => Function.Peakˉliveˉrecordˉfieldˉcells)} " +
            $"scratch={Compilerˉrecordˉstorage.Sum(Function => Function.Scratchˉrecordˉfieldˉcells)} " +
            $"values={Compilerˉrecordˉstorage.Sum(Function => Function.Recordˉvalueˉidentifiers)} " +
            $"slots={Compilerˉrecordˉstorage.Sum(Function => Function.Recordˉvalueˉslots)} " +
            $"return-functions={Compilerˉrecordˉstorage.Count(Function => Function.Returnsˉrecord)} " +
            $"return-fields={Compilerˉrecordˉstorage.Sum(Function => Function.Recordˉreturnˉfieldˉcells)} " +
            $"max-frame={Largestˉrecordˉframe.Projectedˉframeˉcells} " +
            $"largest-declared={Largestˉrecordˉframe.Declaredˉrecordˉlocalˉfieldˉcells} " +
            $"largest-persistent={Largestˉrecordˉframe.Persistentˉrecordˉfieldˉcells} " +
            $"largest-peak={Largestˉrecordˉframe.Peakˉliveˉrecordˉfieldˉcells} " +
            $"largest-scratch={Largestˉrecordˉframe.Scratchˉrecordˉfieldˉcells} " +
            $"max-existing={Compilerˉrecordˉstorage.Max(Function => Function.Existingˉframeˉcells)} " +
            $"max-width={Compilerˉrecordˉstorage.Max(Function => Function.Maximumˉrecordˉfieldˉcells)} " +
            $"largest-index={Largestˉrecordˉframe.Functionˉindex} " +
            $"largest-name={Largestˉrecordˉframe.Functionˉname} " +
            $"nested={Compilerˉrecordˉstorage.Count(Function => Function.Containsˉnestedˉrecordˉfields)} " +
            $"offset-map={Nativeˉrecordˉstorageˉdigest(Compilerˉrecordˉstorage)}");
        Equal(27_516_146, Compilerˉnative.Fragment.Code.Length);
        Equal(
            SOURCE_WVB_TOOL_NATIVE_CODE_SHA256,
            Objectˉdigest.Calculateˉsha256(Compilerˉnative.Fragment.Code.AsSpan()));
        _ = Nativeˉfragmentˉverifier.Verify(Compilerˉnative.Fragment);

        var Encodedˉcheckpoint = Compilerˉnative.Fragment.Code.AsSpan().IndexOf(new byte[]
        {
            0x41, 0x8B, 0x47, Nativeˉexecutionˉcontextˉcontract.TEXT_ARENA_USED_OFFSET,
            0x89, 0x84, 0x24,
        });
        True(Encodedˉcheckpoint >= 0, "Native compiler functions omitted their text-arena checkpoint.");
        var Corruptedˉcheckpoint = Compilerˉnative.Fragment.Code.ToArray();
        Corruptedˉcheckpoint[Encodedˉcheckpoint + 3]++;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                Compilerˉnative.Fragment with
                {
                    Code = Corruptedˉcheckpoint.ToImmutableArray(),
                }));

        var Compilerˉdirectory = Path.Combine(
            Path.GetTempPath(),
            $"windvale-native-compiler-{Guid.NewGuid():N}");
        Directory.CreateDirectory(Compilerˉdirectory);
        try
        {
            var Sourceˉpath = Path.Combine(Compilerˉdirectory, "function-only.wv");
            var Outputˉpath = Path.Combine(Compilerˉdirectory, "function-only.wvb");
            File.WriteAllText(Sourceˉpath, SOURCE_WVB_FUNCTION_ONLY_SOURCE, new UTF8Encoding(false));
            using var Compilerˉoutput = new Nativeˉoutputˉcapture();
            using var Compilerˉdiagnostic = new Nativeˉoutputˉcapture();
            var Compilerˉresources = new Hostedˉresourceˉcontext(
                [Sourceˉpath, Outputˉpath],
                TextWriter.Null,
                TextWriter.Null);
            var Compilerˉauthorized = Compilerˉtool.Module.Capabilities
                .Select(Capability => Capability.Name)
                .ToImmutableHashSet(StringComparer.Ordinal);
            var Compilerˉmeasurement = X64ˉnativeˉexecutor.Measureˉi32(
                Compilerˉnative.Fragment,
                maximumˉinstructions: 4_000_000_000,
                hostˉservices: new(
                    Compilerˉoutput.Channel,
                    Compilerˉauthorized,
                    Compilerˉresources,
                    Compilerˉdiagnostic.Channel,
                    Nativeˉfileˉinput.Hostˉfileˉsystem(),
                    Nativeˉfileˉoutput.Hostˉfileˉsystem()));
            Equal(0, Compilerˉmeasurement.Scalar);
            Equal(0u, Compilerˉmeasurement.Recordˉarenaˉused);
            Equal(68_099u, Compilerˉmeasurement.Textˉarenaˉused);
            Equal(
                "source wvb status=Valid functions=4 code-bytes=532 module-bytes=816\n",
                Compilerˉoutput.Readˉtext());
            Equal(string.Empty, Compilerˉdiagnostic.Readˉtext());
            Sequenceˉequal(
                Compileˉsuccess(SOURCE_WVB_FUNCTION_ONLY_SOURCE),
                File.ReadAllBytes(Outputˉpath));
        }
        finally
        {
            Directory.Delete(Compilerˉdirectory, recursive: true);
        }
    }

    private static void Nativeˉcompilerˉaotˉtransportˉisˉmeasured()
    {
        var Compilerˉfixture = EXACT_COMPILER_WVB.Value;
        var Compilerˉbytes = Compilerˉfixture.Bytes;
        var Compilerˉtool = Compilerˉfixture.Module;
        var Compilerˉnative = EXACT_COMPILER_NATIVE.Value;
        var Measurement = Nativeˉobjectˉsink.Measureˉwvo(Compilerˉnative.Fragment);
        Equal(Measurement, Nativeˉobjectˉsink.Measureˉwvo(Compilerˉnative.Fragment));
        Equal(27_516_146, Compilerˉnative.Fragment.Code.Length);
        Equal(27_538_298, Measurement.Encodedˉobjectˉbytes);
        Equal(Compilerˉnative.Fragment.Code.Length, Measurement.Materializedˉsectionˉbytes);
        Equal(Compilerˉnative.Fragment.Code.Length, Measurement.Linkedˉimageˉbytes);
        Equal(27_515_056, Measurement.Textˉbytes);
        Equal(1_090, Measurement.Readˉonlyˉdataˉbytes);
        Equal(2, Measurement.Sections);
        Equal(529, Measurement.Symbols);
        Equal(227, Measurement.Relocations);
        True(
            Measurement.Encodedˉobjectˉbytes > Objectˉlimits.MAX_OBJECT_BYTES,
            "The exact compiler unexpectedly fits the retained encoded-WVO limit.");
        True(
            Measurement.Materializedˉsectionˉbytes > Objectˉlimits.MAX_MEMORY_BYTES,
            "The exact compiler unexpectedly fits the retained WVO memory limit.");
        True(
            Measurement.Linkedˉimageˉbytes > Linkˉlimits.MAX_IMAGE_BYTES,
            "The exact compiler unexpectedly fits the retained flat-link image limit.");
        Throwsˉobject(
            "WVO2017",
            () => _ = Nativeˉobjectˉsink.Writeˉwvo(Compilerˉnative.Fragment));

        var Firstˉobject = Nativeˉobjectˉsink.Writeˉwvo(
            Compilerˉnative.Fragment,
            Objectˉadmissionˉprofile.Largeˉnative);
        var Secondˉobject = Nativeˉobjectˉsink.Writeˉwvo(
            Compilerˉnative.Fragment,
            Objectˉadmissionˉprofile.Largeˉnative);
        Equal(Measurement.Encodedˉobjectˉbytes, Firstˉobject.Length);
        Sequenceˉequal(Firstˉobject, Secondˉobject);
        Equal(
            SOURCE_WVB_TOOL_NATIVE_WVO_SHA256,
            Objectˉdigest.Calculateˉsha256(Firstˉobject.AsSpan()));
        _ = Objectˉcodec.Readˉandˉverify(
            Firstˉobject.AsSpan(),
            Objectˉadmissionˉprofile.Largeˉnative);
        Throwsˉobject(
            "WVO1001",
            () => _ = Objectˉcodec.Readˉandˉverify(Firstˉobject.AsSpan()));

        Hasˉlinkˉdiagnostic(
            [Firstˉobject.ToArray()],
            new(0, "Main"),
            "WVL1002");
        var Firstˉlink = Linkˉsuccess(
            [Firstˉobject.ToArray()],
            new(0, "Main", Linkˉadmissionˉprofile.Largeˉnative));
        var Secondˉlink = Linkˉsuccess(
            [Firstˉobject.ToArray()],
            new(0, "Main", Linkˉadmissionˉprofile.Largeˉnative));
        Equal(Measurement.Linkedˉimageˉbytes, Firstˉlink.Imageˉbytes.Length);
        var Nativeˉentry = Compilerˉnative.Fragment.Symbols
            .Single(Symbol => Symbol.Name == "Main").Offset;
        Equal(Nativeˉentry, Firstˉlink.Entryˉaddress);
        Sequenceˉequal(Firstˉlink.Imageˉbytes, Secondˉlink.Imageˉbytes);
        Sequenceˉequal(Firstˉlink.Mapˉbytes, Secondˉlink.Mapˉbytes);
        Equal(
            SOURCE_WVB_TOOL_NATIVE_CODE_SHA256,
            Objectˉdigest.Calculateˉsha256(Firstˉlink.Imageˉbytes.AsSpan()));
        Equal(
            SOURCE_WVB_TOOL_NATIVE_LINK_MAP_SHA256,
            Objectˉdigest.Calculateˉsha256(Firstˉlink.Mapˉbytes.AsSpan()));
        Contains(
            System.Text.Encoding.UTF8.GetString(Firstˉlink.Mapˉbytes.AsSpan()),
            $"target name={Linkˉcontract.LARGE_NATIVE_TARGET_NAME} architecture=x86-64");

        Sequenceˉequal(
            [
                Capabilityˉcatalog.CONSOLE_WRITE_LINE,
                Capabilityˉcatalog.DIAGNOSTIC_WRITE_LINE,
                Capabilityˉcatalog.FILE_READ_BYTES,
                Capabilityˉcatalog.FILE_WRITE_BYTES,
                Capabilityˉcatalog.PROCESS_ARGUMENT,
                Capabilityˉcatalog.PROCESS_ARGUMENT_COUNT,
            ],
            Compilerˉtool.Module.Capabilities.Select(Capability => Capability.Name));
        Sequenceˉequal(
            [
                Nativeˉservice.Consoleˉwriteˉline,
                Nativeˉservice.Processˉargumentˉcount,
                Nativeˉservice.Processˉargument,
                Nativeˉservice.Fileˉreadˉbytes,
                Nativeˉservice.Textˉutf8ˉisˉvalid,
                Nativeˉservice.Diagnosticˉwriteˉline,
                Nativeˉservice.Enumˉname,
                Nativeˉservice.Textˉconcat,
                Nativeˉservice.U32ˉformat,
                Nativeˉservice.Fileˉwriteˉbytes,
            ],
            Compilerˉnative.Fragment.Requiredˉservices);
        var Windowsˉbundle = X64ˉnativeˉserviceˉbundle.Build(
            Compilerˉnative.Fragment,
            Nativeˉserviceˉplatform.Windows);
        var Linuxˉbundle = X64ˉnativeˉserviceˉbundle.Build(
            Compilerˉnative.Fragment,
            Nativeˉserviceˉplatform.Linux);
        Equal(27_533_731, Windowsˉbundle.Imageˉbytes.Length);
        Equal(
            SOURCE_WVB_TOOL_WINDOWS_SERVICE_BUNDLE_SHA256,
            Objectˉdigest.Calculateˉsha256(Windowsˉbundle.Imageˉbytes.AsSpan()));
        Equal(27_533_447, Linuxˉbundle.Imageˉbytes.Length);
        Equal(
            SOURCE_WVB_TOOL_LINUX_SERVICE_BUNDLE_SHA256,
            Objectˉdigest.Calculateˉsha256(Linuxˉbundle.Imageˉbytes.AsSpan()));
        foreach (var Bundle in new[] { Windowsˉbundle, Linuxˉbundle })
        {
            Equal(Compilerˉnative.Fragment.Code.Length, Bundle.Nativeˉimageˉbytes);
            Sequenceˉequal(
                Compilerˉnative.Fragment.Code,
                Bundle.Imageˉbytes.Take(Bundle.Nativeˉimageˉbytes));
            Sequenceˉequal(
                Compilerˉnative.Fragment.Requiredˉservices,
                Bundle.Placements.Select(Placement => Placement.Service));
            Equal(10, Bundle.Placements.Length);
        }
        Sequenceˉequal(
            Windowsˉbundle.Placements
                .Where(Placement => Placement.Service is not (
                    Nativeˉservice.Consoleˉwriteˉline or
                    Nativeˉservice.Diagnosticˉwriteˉline or
                    Nativeˉservice.Fileˉreadˉbytes or
                    Nativeˉservice.Fileˉwriteˉbytes))
                .Select(Placement => (Placement.Service, Placement.Adapter, Placement.Sha256)),
            Linuxˉbundle.Placements
                .Where(Placement => Placement.Service is not (
                    Nativeˉservice.Consoleˉwriteˉline or
                    Nativeˉservice.Diagnosticˉwriteˉline or
                    Nativeˉservice.Fileˉreadˉbytes or
                    Nativeˉservice.Fileˉwriteˉbytes))
                .Select(Placement => (Placement.Service, Placement.Adapter, Placement.Sha256)));

        var Windowsˉmetadata = Hostedˉcompilerˉapplicationˉmetadata.Build(
            Consoleˉapplicationˉtarget.Windowsˉx64,
            Compilerˉtool.Module.Capabilities,
            Windowsˉbundle,
            4096,
            Nativeˉentry);
        var Linuxˉmetadata = Hostedˉcompilerˉapplicationˉmetadata.Build(
            Consoleˉapplicationˉtarget.Linuxˉx64,
            Compilerˉtool.Module.Capabilities,
            Linuxˉbundle,
            4096,
            Nativeˉentry);
        Equal(
            SOURCE_WVB_TOOL_WINDOWS_METADATA_SHA256,
            Objectˉdigest.Calculateˉsha256(Windowsˉmetadata.AsSpan()));
        Equal(
            SOURCE_WVB_TOOL_LINUX_METADATA_SHA256,
            Objectˉdigest.Calculateˉsha256(Linuxˉmetadata.AsSpan()));
        foreach (var Case in new[]
        {
            (Target: Consoleˉapplicationˉtarget.Windowsˉx64,
                Bundle: Windowsˉbundle, Metadata: Windowsˉmetadata),
            (Target: Consoleˉapplicationˉtarget.Linuxˉx64,
                Bundle: Linuxˉbundle, Metadata: Linuxˉmetadata),
        })
        {
            var Verified = Hostedˉcompilerˉapplicationˉmetadata.Verify(
                Case.Metadata.AsSpan(),
                Case.Target,
                Case.Bundle,
                Case.Bundle.Imageˉbytes.AsSpan());
            Equal(Hostedˉcompilerˉapplicationˉmetadata.SIZE, Case.Metadata.Length);
            Equal(Nativeˉentry, Verified.Nativeˉentryˉoffset);
            Equal(48_000_000_000UL, Verified.Maximumˉinstructions);
            Sequenceˉequal(
                Compilerˉtool.Module.Capabilities.Select(Capability => (
                    Capability.Name,
                    Parameters: string.Join(',', Capability.Parameterˉtypes),
                    Capability.Returnˉtype)),
                Verified.Capabilities.Select(Capability => (
                    Capability.Name,
                    Parameters: string.Join(',', Capability.Parameterˉtypes),
                    Capability.Returnˉtype)));
            Sequenceˉequal(Case.Bundle.Placements, Verified.Services);
            foreach (var Offset in new[]
            {
                32,
                Hostedˉcompilerˉapplicationˉmetadata.CAPABILITY_OFFSET,
                Hostedˉcompilerˉapplicationˉmetadata.SERVICE_OFFSET + 12,
                Hostedˉcompilerˉapplicationˉmetadata.SERVICE_OFFSET + 32,
            })
            {
                var Corrupted = Case.Metadata.ToArray();
                Corrupted[Offset] ^= 0x01;
                Throwsˉinvalidˉdata(() =>
                    _ = Hostedˉcompilerˉapplicationˉmetadata.Verify(
                        Corrupted,
                        Case.Target,
                        Case.Bundle,
                        Case.Bundle.Imageˉbytes.AsSpan()));
            }
            var Corruptedˉbundle = Case.Bundle.Imageˉbytes.ToArray();
            Corruptedˉbundle[Case.Bundle.Placements[0].Imageˉoffset] ^= 0x01;
            Throwsˉinvalidˉdata(() =>
                _ = Hostedˉcompilerˉapplicationˉmetadata.Verify(
                    Case.Metadata.AsSpan(),
                    Case.Target,
                    Case.Bundle,
                    Corruptedˉbundle));
        }
        Throwsˉinvalidˉdata(() =>
            _ = Hostedˉcompilerˉapplicationˉmetadata.Verify(
                Windowsˉmetadata.AsSpan(),
                Consoleˉapplicationˉtarget.Linuxˉx64,
                Windowsˉbundle,
                Windowsˉbundle.Imageˉbytes.AsSpan()));

        var Windowsˉruntime = Hostedˉcompilerˉruntimeˉdata.Build(
            Consoleˉapplicationˉtarget.Windowsˉx64,
            Compilerˉtool.Module.Capabilities,
            Windowsˉbundle,
            Nativeˉentry);
        var Linuxˉruntime = Hostedˉcompilerˉruntimeˉdata.Build(
            Consoleˉapplicationˉtarget.Linuxˉx64,
            Compilerˉtool.Module.Capabilities,
            Linuxˉbundle,
            Nativeˉentry);
        Equal(
            SOURCE_WVB_TOOL_WINDOWS_RUNTIME_HEADER_SHA256,
            Objectˉdigest.Calculateˉsha256(Windowsˉruntime.AsSpan()));
        Equal(
            SOURCE_WVB_TOOL_LINUX_RUNTIME_HEADER_SHA256,
            Objectˉdigest.Calculateˉsha256(Linuxˉruntime.AsSpan()));
        foreach (var Case in new[]
        {
            (Target: Consoleˉapplicationˉtarget.Windowsˉx64,
                Bundle: Windowsˉbundle, Runtime: Windowsˉruntime,
                Virtualˉbytes: 476_135_424u, Inputˉscratch: 2_097_154u,
                Outputˉscratchˉoffset: 474_034_176u),
            (Target: Consoleˉapplicationˉtarget.Linuxˉx64,
                Bundle: Linuxˉbundle, Runtime: Linuxˉruntime,
                Virtualˉbytes: 474_038_272u, Inputˉscratch: 1_048_577u,
                Outputˉscratchˉoffset: 472_985_600u),
        })
        {
            var Verified = Hostedˉcompilerˉruntimeˉdata.Verify(
                Case.Runtime.AsSpan(),
                Case.Target,
                Case.Bundle,
                Case.Bundle.Imageˉbytes.AsSpan());
            Equal(4_096, Case.Runtime.Length);
            Equal(67u, Verified.Layout.Maximumˉarguments);
            Equal(4_096u, Verified.Layout.Maximumˉargumentˉbytes);
            Equal(4_096u, Verified.Layout.Argumentˉtableˉoffset);
            Equal(1_072u, Verified.Layout.Argumentˉtableˉbytes);
            Equal(5_168u, Verified.Layout.Argumentˉbytesˉoffset);
            Equal(65_536u, Verified.Layout.Argumentˉbytes);
            Equal(70_704u, Verified.Layout.Snapshotˉtableˉoffset);
            Equal(2_048u, Verified.Layout.Snapshotˉtableˉbytes);
            Equal(73_728u, Verified.Layout.Recordˉarenaˉoffset);
            Equal(2_170_880u, Verified.Layout.Textˉarenaˉoffset);
            Equal(136_388_608u, Verified.Layout.Nameˉarenaˉoffset);
            Equal(203_497_472u, Verified.Layout.Dataˉarenaˉoffset);
            Equal(471_932_928u, Verified.Layout.Fileˉinputˉscratchˉoffset);
            Equal(Case.Inputˉscratch, Verified.Layout.Fileˉinputˉscratchˉbytes);
            Equal(Case.Outputˉscratchˉoffset, Verified.Layout.Fileˉoutputˉscratchˉoffset);
            Equal(Case.Inputˉscratch, Verified.Layout.Fileˉoutputˉscratchˉbytes);
            Equal(Case.Virtualˉbytes, Verified.Layout.Virtualˉbytes);
            Equal(48_000_000_000UL, Verified.Metadata.Maximumˉinstructions);
            foreach (var Offset in new[]
            {
                Nativeˉexecutionˉcontextˉcontract.INSTRUCTION_BUDGET_OFFSET,
                checked((int)Hostedˉcompilerˉruntimeˉdata.OUTPUT_TABLE_OFFSET +
                    Nativeˉoutputˉtableˉcontract.FLAGS_OFFSET),
                checked((int)Hostedˉcompilerˉruntimeˉdata.FILE_INPUT_TABLE_OFFSET +
                    Nativeˉfileˉinputˉtableˉcontract.SNAPSHOT_CAPACITY_OFFSET),
                checked((int)Hostedˉcompilerˉruntimeˉdata.METADATA_OFFSET +
                    Hostedˉcompilerˉapplicationˉmetadata.SERVICE_OFFSET + 12),
            })
            {
                var Corrupted = Case.Runtime.ToArray();
                Corrupted[Offset] ^= 0x01;
                Throwsˉinvalidˉdata(() =>
                    _ = Hostedˉcompilerˉruntimeˉdata.Verify(
                        Corrupted,
                        Case.Target,
                        Case.Bundle,
                        Case.Bundle.Imageˉbytes.AsSpan()));
            }
        }
        Throwsˉinvalidˉdata(() =>
            _ = Hostedˉcompilerˉruntimeˉdata.Verify(
                Windowsˉruntime.AsSpan(),
                Consoleˉapplicationˉtarget.Linuxˉx64,
                Windowsˉbundle,
                Windowsˉbundle.Imageˉbytes.AsSpan()));

        var Publicˉwindowsˉapplication =
            Windowsˉconsoleˉapplicationˉwriter.Writeˉhostedˉcompiler(
                Compilerˉnative.Fragment,
                Compilerˉtool.Module.Capabilities);
        True(
            Publicˉwindowsˉapplication.Success,
            Publicˉwindowsˉapplication.Diagnostics.IsEmpty
                ? "The public Windows compiler application writer failed without a diagnostic."
                : Publicˉwindowsˉapplication.Diagnostics[0].Message);
        var Firstˉwindowsˉapplication = Publicˉwindowsˉapplication.Imageˉbytes;
        var Secondˉwindowsˉapplication = Windowsˉhostedˉcompilerˉapplicationˉbuilder.Build(
            Compilerˉtool.Module.Capabilities,
            Windowsˉbundle,
            Nativeˉentry);
        Sequenceˉequal(Firstˉwindowsˉapplication, Secondˉwindowsˉapplication);
        Equal(
            SOURCE_WVB_TOOL_WINDOWS_APPLICATION_SHA256,
            Objectˉdigest.Calculateˉsha256(Firstˉwindowsˉapplication.AsSpan()));
        var Verifiedˉwindowsˉapplication =
            Windowsˉhostedˉcompilerˉapplicationˉverifier.Verify(
                Firstˉwindowsˉapplication.AsSpan(),
                Windowsˉbundle);
        Equal(Nativeˉentry, Verifiedˉwindowsˉapplication.Nativeˉentryˉoffset);
        Equal(27_547_136, Verifiedˉwindowsˉapplication.Layout.Applicationˉbytes);
        Equal(27_537_827u, Verifiedˉwindowsˉapplication.Layout.Textˉvirtualˉbytes);
        Equal(27_537_920u, Verifiedˉwindowsˉapplication.Layout.Textˉfileˉbytes);
        Equal(27_538_432u, Verifiedˉwindowsˉapplication.Layout.Dataˉfileˉoffset);
        Equal(27_545_600u, Verifiedˉwindowsˉapplication.Layout.Dataˉsectionˉaddress);
        Equal(27_549_696u, Verifiedˉwindowsˉapplication.Layout.Runtimeˉaddress);
        Equal(476_139_520u, Verifiedˉwindowsˉapplication.Layout.Dataˉvirtualˉbytes);
        Equal(503_689_216u, Verifiedˉwindowsˉapplication.Layout.Imageˉvirtualˉbytes);
        Sequenceˉequal(Windowsˉbundle.Imageˉbytes,
            Verifiedˉwindowsˉapplication.Bundleˉimage);

        var Windowsˉapplicationˉlayout = Verifiedˉwindowsˉapplication.Layout;
        uint Windowsˉserviceˉaddress(Nativeˉservice service) => checked(
            Windowsˉhostedˉcompilerˉapplicationˉcontract.TEXT_ADDRESS +
            Windowsˉhostedˉcompilerˉapplicationˉcontract.BUNDLE_TEXT_OFFSET +
            (uint)Windowsˉbundle.Placements.Single(
                Placement => Placement.Service == service).Imageˉoffset);
        var Windowsˉstartupˉtargets = new Dictionary<string, uint>(StringComparer.Ordinal)
        {
            ["Argument_bytes"] = checked(Windowsˉapplicationˉlayout.Runtimeˉaddress +
                Verifiedˉwindowsˉapplication.Runtime.Layout.Argumentˉbytesˉoffset),
            ["Argument_table"] = checked(Windowsˉapplicationˉlayout.Runtimeˉaddress +
                Verifiedˉwindowsˉapplication.Runtime.Layout.Argumentˉtableˉoffset),
            ["Data_arena"] = checked(Windowsˉapplicationˉlayout.Runtimeˉaddress +
                Verifiedˉwindowsˉapplication.Runtime.Layout.Dataˉarenaˉoffset),
            ["Execution_context"] = Windowsˉapplicationˉlayout.Runtimeˉaddress,
            ["File_input_scratch"] = checked(Windowsˉapplicationˉlayout.Runtimeˉaddress +
                Verifiedˉwindowsˉapplication.Runtime.Layout.Fileˉinputˉscratchˉoffset),
            ["File_input_table"] = checked(Windowsˉapplicationˉlayout.Runtimeˉaddress +
                Hostedˉcompilerˉruntimeˉdata.FILE_INPUT_TABLE_OFFSET),
            ["File_output_scratch"] = checked(Windowsˉapplicationˉlayout.Runtimeˉaddress +
                Verifiedˉwindowsˉapplication.Runtime.Layout.Fileˉoutputˉscratchˉoffset),
            ["File_output_table"] = checked(Windowsˉapplicationˉlayout.Runtimeˉaddress +
                Hostedˉcompilerˉruntimeˉdata.FILE_OUTPUT_TABLE_OFFSET),
            ["Name_arena"] = checked(Windowsˉapplicationˉlayout.Runtimeˉaddress +
                Verifiedˉwindowsˉapplication.Runtime.Layout.Nameˉarenaˉoffset),
            ["Native_main"] = checked(
                Windowsˉhostedˉcompilerˉapplicationˉcontract.TEXT_ADDRESS +
                Windowsˉhostedˉcompilerˉapplicationˉcontract.BUNDLE_TEXT_OFFSET +
                Nativeˉentry),
            ["Output_table"] = checked(Windowsˉapplicationˉlayout.Runtimeˉaddress +
                Hostedˉcompilerˉruntimeˉdata.OUTPUT_TABLE_OFFSET),
            ["Record_arena"] = checked(Windowsˉapplicationˉlayout.Runtimeˉaddress +
                Verifiedˉwindowsˉapplication.Runtime.Layout.Recordˉarenaˉoffset),
            ["Service_console_write"] = Windowsˉserviceˉaddress(
                Nativeˉservice.Consoleˉwriteˉline),
            ["Service_diagnostic_write"] = Windowsˉserviceˉaddress(
                Nativeˉservice.Diagnosticˉwriteˉline),
            ["Service_enum_name"] = Windowsˉserviceˉaddress(Nativeˉservice.Enumˉname),
            ["Service_file_read"] = Windowsˉserviceˉaddress(Nativeˉservice.Fileˉreadˉbytes),
            ["Service_file_write"] = Windowsˉserviceˉaddress(Nativeˉservice.Fileˉwriteˉbytes),
            ["Service_process_argument"] = Windowsˉserviceˉaddress(
                Nativeˉservice.Processˉargument),
            ["Service_process_argument_count"] = Windowsˉserviceˉaddress(
                Nativeˉservice.Processˉargumentˉcount),
            ["Service_table"] = checked(Windowsˉapplicationˉlayout.Runtimeˉaddress +
                Hostedˉcompilerˉruntimeˉdata.SERVICE_TABLE_OFFSET),
            ["Service_text_concat"] = Windowsˉserviceˉaddress(Nativeˉservice.Textˉconcat),
            ["Service_u32_format"] = Windowsˉserviceˉaddress(Nativeˉservice.U32ˉformat),
            ["Service_utf8"] = Windowsˉserviceˉaddress(Nativeˉservice.Textˉutf8ˉisˉvalid),
            ["Snapshot_table"] = checked(Windowsˉapplicationˉlayout.Runtimeˉaddress +
                Verifiedˉwindowsˉapplication.Runtime.Layout.Snapshotˉtableˉoffset),
            ["Text_arena"] = checked(Windowsˉapplicationˉlayout.Runtimeˉaddress +
                Verifiedˉwindowsˉapplication.Runtime.Layout.Textˉarenaˉoffset),
            ["Windows_close_handle_iat"] = checked(
                Windowsˉapplicationˉlayout.Importˉaddress +
                Windowsˉhostedˉcompilerˉimports.CLOSE_HANDLE_IAT_OFFSET),
            ["Windows_command_line_to_argv_iat"] = checked(
                Windowsˉapplicationˉlayout.Importˉaddress +
                Windowsˉhostedˉcompilerˉimports.COMMAND_LINE_TO_ARGV_IAT_OFFSET),
            ["Windows_create_file_iat"] = checked(
                Windowsˉapplicationˉlayout.Importˉaddress +
                Windowsˉhostedˉcompilerˉimports.CREATE_FILE_IAT_OFFSET),
            ["Windows_flush_file_buffers_iat"] = checked(
                Windowsˉapplicationˉlayout.Importˉaddress +
                Windowsˉhostedˉcompilerˉimports.FLUSH_FILE_BUFFERS_IAT_OFFSET),
            ["Windows_get_command_line_iat"] = checked(
                Windowsˉapplicationˉlayout.Importˉaddress +
                Windowsˉhostedˉcompilerˉimports.GET_COMMAND_LINE_IAT_OFFSET),
            ["Windows_get_file_size_iat"] = checked(
                Windowsˉapplicationˉlayout.Importˉaddress +
                Windowsˉhostedˉcompilerˉimports.GET_FILE_SIZE_IAT_OFFSET),
            ["Windows_get_last_error_iat"] = checked(
                Windowsˉapplicationˉlayout.Importˉaddress +
                Windowsˉhostedˉcompilerˉimports.GET_LAST_ERROR_IAT_OFFSET),
            ["Windows_get_std_handle_iat"] = checked(
                Windowsˉapplicationˉlayout.Importˉaddress +
                Windowsˉhostedˉcompilerˉimports.GET_STD_HANDLE_IAT_OFFSET),
            ["Windows_local_free_iat"] = checked(
                Windowsˉapplicationˉlayout.Importˉaddress +
                Windowsˉhostedˉcompilerˉimports.LOCAL_FREE_IAT_OFFSET),
            ["Windows_multi_byte_to_wide_char_iat"] = checked(
                Windowsˉapplicationˉlayout.Importˉaddress +
                Windowsˉhostedˉcompilerˉimports.MULTI_BYTE_TO_WIDE_CHAR_IAT_OFFSET),
            ["Windows_read_file_iat"] = checked(
                Windowsˉapplicationˉlayout.Importˉaddress +
                Windowsˉhostedˉcompilerˉimports.READ_FILE_IAT_OFFSET),
            ["Windows_wide_char_to_multi_byte_iat"] = checked(
                Windowsˉapplicationˉlayout.Importˉaddress +
                Windowsˉhostedˉcompilerˉimports.WIDE_CHAR_TO_MULTI_BYTE_IAT_OFFSET),
            ["Windows_write_file_iat"] = checked(
                Windowsˉapplicationˉlayout.Importˉaddress +
                Windowsˉhostedˉcompilerˉimports.WRITE_FILE_IAT_OFFSET),
        };
        Requireˉhostedˉstartupˉmatchesˉwva(
            WINDOWS_HOSTED_COMPILER_STARTUP_SOURCE,
            "Windows_hosted_compiler_startup",
            Firstˉwindowsˉapplication.AsSpan(
                Windowsˉapplicationˉlayout.Textˉfileˉoffset,
                Windowsˉapplicationˉlayout.Startupˉbytes),
            Windowsˉapplicationˉlayout.Textˉaddress,
            Windowsˉstartupˉtargets,
            Windowsˉhostedˉcompilerˉstartup.WVO_SHA256);

        foreach (var Offset in new[]
        {
            0,
            0x98 + 2,
            Windowsˉapplicationˉlayout.Textˉfileˉoffset,
            Windowsˉapplicationˉlayout.Textˉfileˉoffset +
                Windowsˉapplicationˉlayout.Startupˉbytes,
            Windowsˉapplicationˉlayout.Textˉfileˉoffset +
                Windowsˉapplicationˉlayout.Bundleˉoffset,
            checked((int)Windowsˉapplicationˉlayout.Importˉfileˉoffset),
            checked((int)Windowsˉapplicationˉlayout.Runtimeˉfileˉoffset),
            checked((int)Windowsˉapplicationˉlayout.Relocationˉfileˉoffset),
        })
        {
            var Corrupted = Firstˉwindowsˉapplication.ToArray();
            Corrupted[Offset] ^= 0x01;
            Throwsˉinvalidˉdata(() =>
                _ = Windowsˉhostedˉcompilerˉapplicationˉverifier.Verify(
                    Corrupted,
                    Windowsˉbundle));
        }
        Throwsˉinvalidˉdata(() =>
            _ = Windowsˉhostedˉcompilerˉapplicationˉverifier.Verify(
                Firstˉwindowsˉapplication.AsSpan(0,
                    Firstˉwindowsˉapplication.Length - 1),
                Windowsˉbundle));
        Throwsˉinvalidˉdata(() =>
            _ = Windowsˉhostedˉcompilerˉapplicationˉverifier.Verify(
                [.. Firstˉwindowsˉapplication, 0],
                Windowsˉbundle));

        if (OperatingSystem.IsWindows())
        {
            var Packagedˉcompilerˉdirectory = Path.Combine(
                Path.GetTempPath(),
                $"windvale-packaged-compiler-{Guid.NewGuid():N}");
            Directory.CreateDirectory(Packagedˉcompilerˉdirectory);
            try
            {
                var (Arguments, Outputˉpath) = Writeˉexactˉcompilerˉstage2ˉinputs(
                    Packagedˉcompilerˉdirectory,
                    "Packaged-Stage2.wvb");
                var Loadedˉmodules = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                Equal(
                    0,
                    Executeˉwindowsˉapplication(
                        Firstˉwindowsˉapplication,
                        "source wvb status=Valid functions=419 code-bytes=760855 " +
                            "module-bytes=921900\n",
                        Arguments,
                        timeoutˉmilliseconds: 600_000,
                        loadedˉmodules: Loadedˉmodules));
                Sequenceˉequal(Compilerˉbytes, File.ReadAllBytes(Outputˉpath));
                True(
                    Loadedˉmodules.Contains("KERNEL32.DLL") &&
                    Loadedˉmodules.Contains("SHELL32.DLL"),
                    "The direct Windows Stage 2 run did not expose its declared host adapters: " +
                        string.Join(", ", Loadedˉmodules.Order(StringComparer.OrdinalIgnoreCase)));
                var Dotnetˉmodules = Loadedˉmodules
                    .Where(Name => Name.Equals("clr.dll", StringComparison.OrdinalIgnoreCase) ||
                        Name.Equals("mscoree.dll", StringComparison.OrdinalIgnoreCase) ||
                        Name.Equals("mscorwks.dll", StringComparison.OrdinalIgnoreCase) ||
                        Name.Contains("coreclr", StringComparison.OrdinalIgnoreCase) ||
                        Name.Contains("hostfxr", StringComparison.OrdinalIgnoreCase) ||
                        Name.Contains("hostpolicy", StringComparison.OrdinalIgnoreCase))
                    .Order(StringComparer.OrdinalIgnoreCase)
                    .ToArray();
                Equal(0, Dotnetˉmodules.Length);
            }
            finally
            {
                Directory.Delete(Packagedˉcompilerˉdirectory, recursive: true);
            }
        }

        var Publicˉlinuxˉapplication =
            Linuxˉconsoleˉapplicationˉwriter.Writeˉhostedˉcompiler(
                Compilerˉnative.Fragment,
                Compilerˉtool.Module.Capabilities);
        True(
            Publicˉlinuxˉapplication.Success,
            Publicˉlinuxˉapplication.Diagnostics.IsEmpty
                ? "The public Linux compiler application writer failed without a diagnostic."
                : Publicˉlinuxˉapplication.Diagnostics[0].Message);
        var Firstˉlinuxˉapplication = Publicˉlinuxˉapplication.Imageˉbytes;
        var Secondˉlinuxˉapplication = Linuxˉhostedˉcompilerˉapplicationˉbuilder.Build(
            Compilerˉtool.Module.Capabilities,
            Linuxˉbundle,
            Nativeˉentry);
        Sequenceˉequal(Firstˉlinuxˉapplication, Secondˉlinuxˉapplication);
        Equal(
            SOURCE_WVB_TOOL_LINUX_APPLICATION_SHA256,
            Objectˉdigest.Calculateˉsha256(Firstˉlinuxˉapplication.AsSpan()));
        var Verifiedˉlinuxˉapplication =
            Linuxˉhostedˉcompilerˉapplicationˉverifier.Verify(
                Firstˉlinuxˉapplication.AsSpan(),
                Linuxˉbundle);
        Equal(Nativeˉentry, Verifiedˉlinuxˉapplication.Nativeˉentryˉoffset);
        Equal(27_549_696, Verifiedˉlinuxˉapplication.Layout.Applicationˉbytes);
        Equal(27_537_543u, Verifiedˉlinuxˉapplication.Layout.Textˉbytes);
        Equal(27_545_600u, Verifiedˉlinuxˉapplication.Layout.Dataˉfileˉoffset);
        Equal(474_038_272u, Verifiedˉlinuxˉapplication.Layout.Dataˉvirtualˉbytes);
        Equal(501_583_872u, Verifiedˉlinuxˉapplication.Layout.Imageˉvirtualˉbytes);
        Sequenceˉequal(Linuxˉbundle.Imageˉbytes, Verifiedˉlinuxˉapplication.Bundleˉimage);

        var Linuxˉapplicationˉlayout = Verifiedˉlinuxˉapplication.Layout;
        uint Linuxˉserviceˉaddress(Nativeˉservice service) => checked(
            Linuxˉhostedˉcompilerˉapplicationˉcontract.TEXT_ADDRESS +
            Linuxˉhostedˉcompilerˉapplicationˉcontract.BUNDLE_TEXT_OFFSET +
            (uint)Linuxˉbundle.Placements.Single(
                Placement => Placement.Service == service).Imageˉoffset);
        var Linuxˉstartupˉtargets = new Dictionary<string, uint>(StringComparer.Ordinal)
        {
            ["Argument_bytes"] = checked(Linuxˉapplicationˉlayout.Dataˉaddress +
                Verifiedˉlinuxˉapplication.Runtime.Layout.Argumentˉbytesˉoffset),
            ["Argument_table"] = checked(Linuxˉapplicationˉlayout.Dataˉaddress +
                Verifiedˉlinuxˉapplication.Runtime.Layout.Argumentˉtableˉoffset),
            ["Data_arena"] = checked(Linuxˉapplicationˉlayout.Dataˉaddress +
                Verifiedˉlinuxˉapplication.Runtime.Layout.Dataˉarenaˉoffset),
            ["Execution_context"] = Linuxˉapplicationˉlayout.Dataˉaddress,
            ["File_input_scratch"] = checked(Linuxˉapplicationˉlayout.Dataˉaddress +
                Verifiedˉlinuxˉapplication.Runtime.Layout.Fileˉinputˉscratchˉoffset),
            ["File_input_table"] = checked(Linuxˉapplicationˉlayout.Dataˉaddress +
                Hostedˉcompilerˉruntimeˉdata.FILE_INPUT_TABLE_OFFSET),
            ["File_output_scratch"] = checked(Linuxˉapplicationˉlayout.Dataˉaddress +
                Verifiedˉlinuxˉapplication.Runtime.Layout.Fileˉoutputˉscratchˉoffset),
            ["File_output_table"] = checked(Linuxˉapplicationˉlayout.Dataˉaddress +
                Hostedˉcompilerˉruntimeˉdata.FILE_OUTPUT_TABLE_OFFSET),
            ["Name_arena"] = checked(Linuxˉapplicationˉlayout.Dataˉaddress +
                Verifiedˉlinuxˉapplication.Runtime.Layout.Nameˉarenaˉoffset),
            ["Native_main"] = checked(
                Linuxˉhostedˉcompilerˉapplicationˉcontract.TEXT_ADDRESS +
                Linuxˉhostedˉcompilerˉapplicationˉcontract.BUNDLE_TEXT_OFFSET +
                Nativeˉentry),
            ["Output_table"] = checked(Linuxˉapplicationˉlayout.Dataˉaddress +
                Hostedˉcompilerˉruntimeˉdata.OUTPUT_TABLE_OFFSET),
            ["Record_arena"] = checked(Linuxˉapplicationˉlayout.Dataˉaddress +
                Verifiedˉlinuxˉapplication.Runtime.Layout.Recordˉarenaˉoffset),
            ["Service_console_write"] = Linuxˉserviceˉaddress(
                Nativeˉservice.Consoleˉwriteˉline),
            ["Service_diagnostic_write"] = Linuxˉserviceˉaddress(
                Nativeˉservice.Diagnosticˉwriteˉline),
            ["Service_enum_name"] = Linuxˉserviceˉaddress(Nativeˉservice.Enumˉname),
            ["Service_file_read"] = Linuxˉserviceˉaddress(Nativeˉservice.Fileˉreadˉbytes),
            ["Service_file_write"] = Linuxˉserviceˉaddress(Nativeˉservice.Fileˉwriteˉbytes),
            ["Service_process_argument"] = Linuxˉserviceˉaddress(
                Nativeˉservice.Processˉargument),
            ["Service_process_argument_count"] = Linuxˉserviceˉaddress(
                Nativeˉservice.Processˉargumentˉcount),
            ["Service_table"] = checked(Linuxˉapplicationˉlayout.Dataˉaddress +
                Hostedˉcompilerˉruntimeˉdata.SERVICE_TABLE_OFFSET),
            ["Service_text_concat"] = Linuxˉserviceˉaddress(Nativeˉservice.Textˉconcat),
            ["Service_u32_format"] = Linuxˉserviceˉaddress(Nativeˉservice.U32ˉformat),
            ["Service_utf8"] = Linuxˉserviceˉaddress(Nativeˉservice.Textˉutf8ˉisˉvalid),
            ["Snapshot_table"] = checked(Linuxˉapplicationˉlayout.Dataˉaddress +
                Verifiedˉlinuxˉapplication.Runtime.Layout.Snapshotˉtableˉoffset),
            ["Text_arena"] = checked(Linuxˉapplicationˉlayout.Dataˉaddress +
                Verifiedˉlinuxˉapplication.Runtime.Layout.Textˉarenaˉoffset),
        };
        Requireˉhostedˉstartupˉmatchesˉwva(
            LINUX_HOSTED_COMPILER_STARTUP_SOURCE,
            "Linux_hosted_compiler_startup",
            Firstˉlinuxˉapplication.AsSpan(
                Linuxˉapplicationˉlayout.Textˉfileˉoffset,
                Linuxˉapplicationˉlayout.Startupˉbytes),
            Linuxˉapplicationˉlayout.Textˉaddress,
            Linuxˉstartupˉtargets,
            Linuxˉhostedˉcompilerˉstartup.WVO_SHA256);

        foreach (var Offset in new[]
        {
            0,
            0x180 + 24,
            Linuxˉapplicationˉlayout.Textˉfileˉoffset,
            Linuxˉapplicationˉlayout.Textˉfileˉoffset +
                Linuxˉapplicationˉlayout.Startupˉbytes,
            Linuxˉapplicationˉlayout.Textˉfileˉoffset +
                Linuxˉapplicationˉlayout.Bundleˉoffset,
            checked((int)Linuxˉapplicationˉlayout.Dataˉfileˉoffset),
        })
        {
            var Corrupted = Firstˉlinuxˉapplication.ToArray();
            Corrupted[Offset] ^= 0x01;
            Throwsˉinvalidˉdata(() =>
                _ = Linuxˉhostedˉcompilerˉapplicationˉverifier.Verify(
                    Corrupted,
                    Linuxˉbundle));
        }
        Throwsˉinvalidˉdata(() =>
            _ = Linuxˉhostedˉcompilerˉapplicationˉverifier.Verify(
                Firstˉlinuxˉapplication.AsSpan(0, Firstˉlinuxˉapplication.Length - 1),
                Linuxˉbundle));
        Throwsˉinvalidˉdata(() =>
            _ = Linuxˉhostedˉcompilerˉapplicationˉverifier.Verify(
                [.. Firstˉlinuxˉapplication, 0],
                Linuxˉbundle));

        if (OperatingSystem.IsLinux())
        {
            var Packagedˉcompilerˉdirectory = Path.Combine(
                Path.GetTempPath(),
                $"windvale-packaged-compiler-{Guid.NewGuid():N}");
            Directory.CreateDirectory(Packagedˉcompilerˉdirectory);
            try
            {
                var (Arguments, Outputˉpath) = Writeˉexactˉcompilerˉstage2ˉinputs(
                    Packagedˉcompilerˉdirectory,
                    "Packaged-Stage2.wvb");
                var Loadedˉmappings = new HashSet<string>(StringComparer.Ordinal);
                Equal(
                    0,
                    Executeˉlinuxˉapplication(
                        Firstˉlinuxˉapplication,
                        "source wvb status=Valid functions=419 code-bytes=760855 " +
                            "module-bytes=921900\n",
                        Arguments,
                        timeoutˉmilliseconds: 600_000,
                        loadedˉmappings: Loadedˉmappings));
                Sequenceˉequal(Compilerˉbytes, File.ReadAllBytes(Outputˉpath));
                True(
                    Loadedˉmappings.Any(Name =>
                        Name.Contains("windvale-linux-console-", StringComparison.Ordinal)),
                    "The direct Linux Stage 2 run did not expose its executable mapping: " +
                        string.Join(", ", Loadedˉmappings.Order(StringComparer.Ordinal)));
                var Dotnetˉmappings = Loadedˉmappings
                    .Where(Name => Name.Contains("dotnet", StringComparison.OrdinalIgnoreCase) ||
                        Name.Contains("coreclr", StringComparison.OrdinalIgnoreCase) ||
                        Name.Contains("hostfxr", StringComparison.OrdinalIgnoreCase) ||
                        Name.Contains("hostpolicy", StringComparison.OrdinalIgnoreCase))
                    .Order(StringComparer.Ordinal)
                    .ToArray();
                Equal(0, Dotnetˉmappings.Length);
            }
            finally
            {
                Directory.Delete(Packagedˉcompilerˉdirectory, recursive: true);
            }
        }

        Compilerˉwvbˉverifierˉpackages(Compilerˉbytes.ToArray(), Compilerˉnative.Fragment);

        var Aggregateˉoverflowˉdata = new byte[
            Linkˉlimits.LARGE_NATIVE_MAX_TOTAL_INPUT_BYTES - Firstˉobject.Length + 1];
        var Aggregateˉoverflowˉobject = Objectˉcodec.Write(new Objectˉfile(
            Objectˉarchitecture.X86ˉ64,
            [new(".padding", Objectˉsectionˉkind.Code, 1, (uint)Aggregateˉoverflowˉdata.Length,
                Aggregateˉoverflowˉdata.ToImmutableArray())],
            [],
            []), Objectˉadmissionˉprofile.Largeˉnative);
        Hasˉlinkˉdiagnostic(
            [Firstˉobject.ToArray(), Aggregateˉoverflowˉobject],
            new(0, "Main", Linkˉadmissionˉprofile.Largeˉnative),
            "WVL1003");

        var Maximumˉimageˉobject = Objectˉcodec.Write(new Objectˉfile(
            Objectˉarchitecture.X86ˉ64,
            [
                new(".text", Objectˉsectionˉkind.Code, 1, 1, [0xC3]),
                new(".bss", Objectˉsectionˉkind.Zeroˉfill, 1,
                    Linkˉlimits.LARGE_NATIVE_MAX_IMAGE_BYTES - 1, []),
            ],
            [new("Main", Objectˉsymbolˉbinding.Export, Objectˉsymbolˉkind.Function, 0, 0, 1)],
            []), Objectˉadmissionˉprofile.Largeˉnative);
        Equal(
            Linkˉlimits.LARGE_NATIVE_MAX_IMAGE_BYTES,
            Linkˉsuccess(
                [Maximumˉimageˉobject],
                new(0, "Main", Linkˉadmissionˉprofile.Largeˉnative)).Imageˉbytes.Length);
        Throwsˉobject(
            "WVO2017",
            () => _ = Objectˉcodec.Write(new Objectˉfile(
                Objectˉarchitecture.X86ˉ64,
                [
                    new(".text", Objectˉsectionˉkind.Code, 1, 1, [0xC3]),
                    new(".bss", Objectˉsectionˉkind.Zeroˉfill, 1,
                        Linkˉlimits.LARGE_NATIVE_MAX_IMAGE_BYTES, []),
                ],
                [new("Main", Objectˉsymbolˉbinding.Export, Objectˉsymbolˉkind.Function, 0, 0, 1)],
                []), Objectˉadmissionˉprofile.Largeˉnative));
        Throwsˉobject(
            "WVO1001",
            () => _ = Objectˉcodec.Read(
                new byte[Objectˉlimits.LARGE_NATIVE_MAX_OBJECT_BYTES + 1],
                Objectˉadmissionˉprofile.Largeˉnative));
        Hasˉlinkˉdiagnostic(
            [Firstˉobject.ToArray()],
            new(0, "Main", (Linkˉadmissionˉprofile)0),
            "WVL1001");
    }

    private static void Compilerˉwvbˉverifierˉpackages(
        byte[] compilerˉbytes,
        Nativeˉfragment compilerˉfragment)
    {
        static (int Exitˉcode, string Standardˉoutput, string Standardˉerror) Executeˉtool(
            params string[] arguments)
        {
            var Originalˉoutput = Console.Out;
            var Originalˉerror = Console.Error;
            using var Output = new StringWriter(
                System.Globalization.CultureInfo.InvariantCulture);
            using var Error = new StringWriter(
                System.Globalization.CultureInfo.InvariantCulture);
            try
            {
                Console.SetOut(Output);
                Console.SetError(Error);
                var Exitˉcode = Windvale.Tool.Program.Main(arguments);
                return (Exitˉcode, Output.ToString(), Error.ToString());
            }
            finally
            {
                Console.SetOut(Originalˉoutput);
                Console.SetError(Originalˉerror);
            }
        }

        var Compilation = Seedˉcompiler.Compileˉmodules(
            new(
                "Compiler-Wvb-Verifier-Tool.wv",
                COMPILER_WVB_VERIFIER_TOOL_SOURCE),
            [
                new(
                    "Compiler-Wvb-Verifier-Semantic-Core.wv",
                    COMPILER_WVB_VERIFIER_SEMANTIC_SOURCE),
                new(
                    "Compiler-Wvb-Verifier-Executable-Core.wv",
                    COMPILER_WVB_VERIFIER_EXECUTABLE_SOURCE),
            ]);
        if (!Compilation.Success)
        {
            throw new InvalidOperationException(
                "Compiler-aligned verifier compilation failed: " +
                string.Join(" | ", Compilation.Diagnostics));
        }

        var Verifierˉbytes = Compilation.Moduleˉbytes.ToArray();
        Equal(125_721, Verifierˉbytes.Length);
        Equal(
            COMPILER_WVB_VERIFIER_SHA256,
            Objectˉdigest.Calculateˉsha256(Verifierˉbytes));
        var Verifierˉmodule = Moduleˉcodec.Readˉandˉverify(Verifierˉbytes);
        Sequenceˉequal(
            [
                Capabilityˉcatalog.CONSOLE_WRITE_LINE,
                Capabilityˉcatalog.DIAGNOSTIC_WRITE_LINE,
                Capabilityˉcatalog.FILE_READ_BYTES,
                Capabilityˉcatalog.PROCESS_ARGUMENT,
                Capabilityˉcatalog.PROCESS_ARGUMENT_COUNT,
            ],
            Verifierˉmodule.Module.Capabilities.Select(Capability => Capability.Name));
        var Verifierˉnative = X64ˉnativeˉbackend.Compile(Verifierˉmodule);
        Nativeˉfragmentˉverifier.Verify(Verifierˉnative.Fragment);
        Sequenceˉequal(
            [
                Nativeˉservice.Consoleˉwriteˉline,
                Nativeˉservice.Processˉargumentˉcount,
                Nativeˉservice.Processˉargument,
                Nativeˉservice.Fileˉreadˉbytes,
                Nativeˉservice.Diagnosticˉwriteˉline,
            ],
            Verifierˉnative.Fragment.Requiredˉservices);
        var Nativeˉentry = Verifierˉnative.Fragment.Symbols.Single(Symbol =>
            Symbol.Binding == Nativeˉsymbolˉbinding.Export &&
            Symbol.Kind == Nativeˉsymbolˉkind.Function &&
            Symbol.Name == "Main").Offset;

        var Windowsˉbundle = X64ˉnativeˉserviceˉbundle.Buildˉhostedˉverifier(
            Verifierˉnative.Fragment,
            Nativeˉserviceˉplatform.Windows);
        var Linuxˉbundle = X64ˉnativeˉserviceˉbundle.Buildˉhostedˉverifier(
            Verifierˉnative.Fragment,
            Nativeˉserviceˉplatform.Linux);
        Throwsˉnative(
            "WVN4018",
            () => _ = X64ˉnativeˉserviceˉbundle.Buildˉhostedˉverifier(
                compilerˉfragment,
                Nativeˉserviceˉplatform.Windows));
        ReadOnlySpan<Nativeˉservice> Boundˉservices =
        [
            Nativeˉservice.Consoleˉwriteˉline,
            Nativeˉservice.Processˉargumentˉcount,
            Nativeˉservice.Processˉargument,
            Nativeˉservice.Fileˉreadˉbytes,
            Nativeˉservice.Textˉutf8ˉisˉvalid,
            Nativeˉservice.Diagnosticˉwriteˉline,
        ];
        foreach (var Bundle in new[] { Windowsˉbundle, Linuxˉbundle })
        {
            Equal(6, Bundle.Placements.Length);
            True(
                Bundle.Placements.Select(Item => Item.Service).ToArray().AsSpan()
                    .SequenceEqual(Boundˉservices),
                "The hosted verifier bound a noncanonical service sequence.");
        }

        var Firstˉwindows = Windowsˉconsoleˉapplicationˉwriter.Writeˉhostedˉverifier(
            Verifierˉnative.Fragment,
            Verifierˉmodule.Module.Capabilities);
        True(
            Firstˉwindows.Success,
            Firstˉwindows.Diagnostics.IsEmpty
                ? "The Windows verifier writer failed without a diagnostic."
                : Firstˉwindows.Diagnostics[0].Message);
        var Secondˉwindows = Windowsˉhostedˉverifierˉapplicationˉbuilder.Build(
            Verifierˉmodule.Module.Capabilities,
            Windowsˉbundle,
            Nativeˉentry);
        Sequenceˉequal(Firstˉwindows.Imageˉbytes, Secondˉwindows);
        Equal(1_004_032, Firstˉwindows.Imageˉbytes.Length);
        Equal(
            COMPILER_WVB_VERIFIER_WINDOWS_APPLICATION_SHA256,
            Objectˉdigest.Calculateˉsha256(Firstˉwindows.Imageˉbytes.AsSpan()));
        var Verifiedˉwindows = Windowsˉhostedˉverifierˉapplicationˉverifier.Verify(
            Firstˉwindows.Imageˉbytes.AsSpan(),
            Windowsˉbundle);

        var Firstˉlinux = Linuxˉconsoleˉapplicationˉwriter.Writeˉhostedˉverifier(
            Verifierˉnative.Fragment,
            Verifierˉmodule.Module.Capabilities);
        True(
            Firstˉlinux.Success,
            Firstˉlinux.Diagnostics.IsEmpty
                ? "The Linux verifier writer failed without a diagnostic."
                : Firstˉlinux.Diagnostics[0].Message);
        var Secondˉlinux = Linuxˉhostedˉverifierˉapplicationˉbuilder.Build(
            Verifierˉmodule.Module.Capabilities,
            Linuxˉbundle,
            Nativeˉentry);
        Sequenceˉequal(Firstˉlinux.Imageˉbytes, Secondˉlinux);
        Equal(1_003_520, Firstˉlinux.Imageˉbytes.Length);
        Equal(
            COMPILER_WVB_VERIFIER_LINUX_APPLICATION_SHA256,
            Objectˉdigest.Calculateˉsha256(Firstˉlinux.Imageˉbytes.AsSpan()));
        var Verifiedˉlinux = Linuxˉhostedˉverifierˉapplicationˉverifier.Verify(
            Firstˉlinux.Imageˉbytes.AsSpan(),
            Linuxˉbundle);

        foreach (var Runtime in new[] { Verifiedˉwindows.Runtime, Verifiedˉlinux.Runtime })
        {
            Equal(1u, Runtime.Layout.Snapshotˉcapacity);
            Equal(32u, Runtime.Layout.Snapshotˉtableˉbytes);
            Equal(0u, Runtime.Layout.Fileˉoutputˉscratchˉbytes);
            True(
                Runtime.Layout.Virtualˉbytes < 144u * 1024u * 1024u,
                "The verifier runtime exceeded its one-snapshot layout with the 128 MiB dynamic arena.");
            Equal(16_000_000_000UL, Runtime.Metadata.Maximumˉinstructions);
            Equal(5, Runtime.Metadata.Capabilities.Length);
            Equal(6, Runtime.Metadata.Services.Length);
        }

        Dictionary<string, uint> Startupˉtargets(
            uint runtimeˉaddress,
            Hostedˉverifierˉruntimeˉlayout layout,
            Nativeˉserviceˉbundle bundle,
            uint textˉaddress) => new(StringComparer.Ordinal)
        {
            ["Argument_bytes"] = checked(runtimeˉaddress + layout.Argumentˉbytesˉoffset),
            ["Argument_table"] = checked(runtimeˉaddress + layout.Argumentˉtableˉoffset),
            ["Data_arena"] = checked(runtimeˉaddress + layout.Dataˉarenaˉoffset),
            ["Execution_context"] = runtimeˉaddress,
            ["File_input_scratch"] = checked(
                runtimeˉaddress + layout.Fileˉinputˉscratchˉoffset),
            ["File_input_table"] = checked(
                runtimeˉaddress + Hostedˉverifierˉruntimeˉdata.FILE_INPUT_TABLE_OFFSET),
            ["Name_arena"] = checked(runtimeˉaddress + layout.Nameˉarenaˉoffset),
            ["Native_main"] = checked(
                textˉaddress +
                (uint)Windowsˉhostedˉverifierˉapplicationˉcontract.BUNDLE_TEXT_OFFSET +
                Nativeˉentry),
            ["Output_table"] = checked(
                runtimeˉaddress + Hostedˉverifierˉruntimeˉdata.OUTPUT_TABLE_OFFSET),
            ["Record_arena"] = checked(runtimeˉaddress + layout.Recordˉarenaˉoffset),
            ["Service_console_write"] = Serviceˉaddress(
                textˉaddress, bundle, Nativeˉservice.Consoleˉwriteˉline),
            ["Service_diagnostic_write"] = Serviceˉaddress(
                textˉaddress, bundle, Nativeˉservice.Diagnosticˉwriteˉline),
            ["Service_file_read"] = Serviceˉaddress(
                textˉaddress, bundle, Nativeˉservice.Fileˉreadˉbytes),
            ["Service_process_argument"] = Serviceˉaddress(
                textˉaddress, bundle, Nativeˉservice.Processˉargument),
            ["Service_process_argument_count"] = Serviceˉaddress(
                textˉaddress, bundle, Nativeˉservice.Processˉargumentˉcount),
            ["Service_table"] = checked(
                runtimeˉaddress + Hostedˉverifierˉruntimeˉdata.SERVICE_TABLE_OFFSET),
            ["Service_utf8"] = Serviceˉaddress(
                textˉaddress, bundle, Nativeˉservice.Textˉutf8ˉisˉvalid),
            ["Snapshot_table"] = checked(runtimeˉaddress + layout.Snapshotˉtableˉoffset),
            ["Text_arena"] = checked(runtimeˉaddress + layout.Textˉarenaˉoffset),
        };
        uint Serviceˉaddress(
            uint textˉaddress,
            Nativeˉserviceˉbundle bundle,
            Nativeˉservice service) => checked(
                textˉaddress +
                (uint)Windowsˉhostedˉverifierˉapplicationˉcontract.BUNDLE_TEXT_OFFSET +
                (uint)bundle.Placements.Single(Item => Item.Service == service).Imageˉoffset);

        var Windowsˉtargets = Startupˉtargets(
            Verifiedˉwindows.Layout.Runtimeˉaddress,
            Verifiedˉwindows.Runtime.Layout,
            Windowsˉbundle,
            Verifiedˉwindows.Layout.Textˉaddress);
        Windowsˉtargets.Add("Windows_close_handle_iat", checked(
            Verifiedˉwindows.Layout.Importˉaddress +
            Windowsˉhostedˉverifierˉimports.CLOSE_HANDLE_IAT_OFFSET));
        Windowsˉtargets.Add("Windows_command_line_to_argv_iat", checked(
            Verifiedˉwindows.Layout.Importˉaddress +
            Windowsˉhostedˉverifierˉimports.COMMAND_LINE_TO_ARGV_IAT_OFFSET));
        Windowsˉtargets.Add("Windows_create_file_iat", checked(
            Verifiedˉwindows.Layout.Importˉaddress +
            Windowsˉhostedˉverifierˉimports.CREATE_FILE_IAT_OFFSET));
        Windowsˉtargets.Add("Windows_get_command_line_iat", checked(
            Verifiedˉwindows.Layout.Importˉaddress +
            Windowsˉhostedˉverifierˉimports.GET_COMMAND_LINE_IAT_OFFSET));
        Windowsˉtargets.Add("Windows_get_file_size_iat", checked(
            Verifiedˉwindows.Layout.Importˉaddress +
            Windowsˉhostedˉverifierˉimports.GET_FILE_SIZE_IAT_OFFSET));
        Windowsˉtargets.Add("Windows_get_last_error_iat", checked(
            Verifiedˉwindows.Layout.Importˉaddress +
            Windowsˉhostedˉverifierˉimports.GET_LAST_ERROR_IAT_OFFSET));
        Windowsˉtargets.Add("Windows_get_std_handle_iat", checked(
            Verifiedˉwindows.Layout.Importˉaddress +
            Windowsˉhostedˉverifierˉimports.GET_STD_HANDLE_IAT_OFFSET));
        Windowsˉtargets.Add("Windows_local_free_iat", checked(
            Verifiedˉwindows.Layout.Importˉaddress +
            Windowsˉhostedˉverifierˉimports.LOCAL_FREE_IAT_OFFSET));
        Windowsˉtargets.Add("Windows_multi_byte_to_wide_char_iat", checked(
            Verifiedˉwindows.Layout.Importˉaddress +
            Windowsˉhostedˉverifierˉimports.MULTI_BYTE_TO_WIDE_CHAR_IAT_OFFSET));
        Windowsˉtargets.Add("Windows_read_file_iat", checked(
            Verifiedˉwindows.Layout.Importˉaddress +
            Windowsˉhostedˉverifierˉimports.READ_FILE_IAT_OFFSET));
        Windowsˉtargets.Add("Windows_wide_char_to_multi_byte_iat", checked(
            Verifiedˉwindows.Layout.Importˉaddress +
            Windowsˉhostedˉverifierˉimports.WIDE_CHAR_TO_MULTI_BYTE_IAT_OFFSET));
        Windowsˉtargets.Add("Windows_write_file_iat", checked(
            Verifiedˉwindows.Layout.Importˉaddress +
            Windowsˉhostedˉverifierˉimports.WRITE_FILE_IAT_OFFSET));
        Requireˉhostedˉstartupˉmatchesˉwva(
            WINDOWS_HOSTED_VERIFIER_STARTUP_SOURCE,
            "Windows_hosted_verifier_startup",
            Firstˉwindows.Imageˉbytes.AsSpan(
                Verifiedˉwindows.Layout.Textˉfileˉoffset,
                Verifiedˉwindows.Layout.Startupˉbytes),
            Verifiedˉwindows.Layout.Textˉaddress,
            Windowsˉtargets,
            Windowsˉhostedˉverifierˉstartup.WVO_SHA256);

        var Linuxˉtargets = Startupˉtargets(
            Verifiedˉlinux.Layout.Dataˉaddress,
            Verifiedˉlinux.Runtime.Layout,
            Linuxˉbundle,
            Verifiedˉlinux.Layout.Textˉaddress);
        Requireˉhostedˉstartupˉmatchesˉwva(
            LINUX_HOSTED_VERIFIER_STARTUP_SOURCE,
            "Linux_hosted_verifier_startup",
            Firstˉlinux.Imageˉbytes.AsSpan(
                Verifiedˉlinux.Layout.Textˉfileˉoffset,
                Verifiedˉlinux.Layout.Startupˉbytes),
            Verifiedˉlinux.Layout.Textˉaddress,
            Linuxˉtargets,
            Linuxˉhostedˉverifierˉstartup.WVO_SHA256);

        foreach (var Offset in new[]
        {
            0,
            0x98 + 2,
            Verifiedˉwindows.Layout.Textˉfileˉoffset,
            Verifiedˉwindows.Layout.Textˉfileˉoffset +
                Verifiedˉwindows.Layout.Bundleˉoffset,
            checked((int)Verifiedˉwindows.Layout.Importˉfileˉoffset),
            checked((int)Verifiedˉwindows.Layout.Runtimeˉfileˉoffset),
        })
        {
            var Corrupted = Firstˉwindows.Imageˉbytes.ToArray();
            Corrupted[Offset] ^= 1;
            Throwsˉinvalidˉdata(() =>
                _ = Windowsˉhostedˉverifierˉapplicationˉverifier.Verify(
                    Corrupted,
                    Windowsˉbundle));
        }
        Throwsˉinvalidˉdata(() =>
            _ = Windowsˉhostedˉverifierˉapplicationˉverifier.Verify(
                Firstˉwindows.Imageˉbytes.AsSpan(0, Firstˉwindows.Imageˉbytes.Length - 1),
                Windowsˉbundle));
        Throwsˉinvalidˉdata(() =>
            _ = Windowsˉhostedˉverifierˉapplicationˉverifier.Verify(
                [.. Firstˉwindows.Imageˉbytes, 0],
                Windowsˉbundle));
        foreach (var Offset in new[]
        {
            0,
            0x180 + 24,
            Verifiedˉlinux.Layout.Textˉfileˉoffset,
            Verifiedˉlinux.Layout.Textˉfileˉoffset + Verifiedˉlinux.Layout.Bundleˉoffset,
            checked((int)Verifiedˉlinux.Layout.Dataˉfileˉoffset),
        })
        {
            var Corrupted = Firstˉlinux.Imageˉbytes.ToArray();
            Corrupted[Offset] ^= 1;
            Throwsˉinvalidˉdata(() =>
                _ = Linuxˉhostedˉverifierˉapplicationˉverifier.Verify(
                    Corrupted,
                    Linuxˉbundle));
        }
        Throwsˉinvalidˉdata(() =>
            _ = Linuxˉhostedˉverifierˉapplicationˉverifier.Verify(
                Firstˉlinux.Imageˉbytes.AsSpan(0, Firstˉlinux.Imageˉbytes.Length - 1),
                Linuxˉbundle));
        Throwsˉinvalidˉdata(() =>
            _ = Linuxˉhostedˉverifierˉapplicationˉverifier.Verify(
                [.. Firstˉlinux.Imageˉbytes, 0],
                Linuxˉbundle));

        var Directoryˉpath = Path.Combine(
            Path.GetTempPath(),
            $"windvale-compiler-wvb-verifier-{Guid.NewGuid():N}");
        Directory.CreateDirectory(Directoryˉpath);
        try
        {
            var Validˉpath = Path.Combine(Directoryˉpath, "Compiler.wvb");
            var Invalidˉpath = Path.Combine(Directoryˉpath, "Invalid.wvb");
            var Verifierˉpath = Path.Combine(Directoryˉpath, "Wvverify.wvb");
            File.WriteAllBytes(Validˉpath, compilerˉbytes);
            File.WriteAllBytes(Verifierˉpath, Verifierˉbytes);
            var Invalidˉbytes = compilerˉbytes.ToArray();
            Invalidˉbytes[0] = 0;
            File.WriteAllBytes(Invalidˉpath, Invalidˉbytes);

            var Cliˉtarget = OperatingSystem.IsWindows()
                ? Windowsˉconsoleˉapplicationˉcontract.VERIFIER_TARGET_NAME
                : Linuxˉconsoleˉapplicationˉcontract.VERIFIER_TARGET_NAME;
            var Cliˉapplication = Executeˉtool(
                "aot",
                Verifierˉpath,
                "--target",
                Cliˉtarget);
            Equal(0, Cliˉapplication.Exitˉcode);
            Equal(string.Empty, Cliˉapplication.Standardˉerror);
            Contains(Cliˉapplication.Standardˉoutput, $"Target: {Cliˉtarget}");
            Sequenceˉequal(
                OperatingSystem.IsWindows()
                    ? Firstˉwindows.Imageˉbytes
                    : Firstˉlinux.Imageˉbytes,
                File.ReadAllBytes(Path.ChangeExtension(
                    Verifierˉpath,
                    Windvale.Tool.Program.Targetˉoutputˉextension(Cliˉtarget))));

            if (OperatingSystem.IsWindows())
            {
                var Loadedˉmodules = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                Equal(
                    0,
                    Executeˉwindowsˉapplication(
                        Firstˉwindows.Imageˉbytes,
                        "wvb status=Valid profile=compiler-aligned\n",
                        [Validˉpath],
                        timeoutˉmilliseconds: 600_000,
                        loadedˉmodules: Loadedˉmodules));
                Equal(
                    1,
                    Executeˉwindowsˉapplication(
                        Firstˉwindows.Imageˉbytes,
                        arguments: [Invalidˉpath],
                        timeoutˉmilliseconds: 600_000,
                        expectedˉerror: "wvb status=Invalid phase=semantic\n"));
                True(
                    Loadedˉmodules.Contains("KERNEL32.DLL") &&
                    Loadedˉmodules.Contains("SHELL32.DLL"),
                    "The Windows verifier did not expose its declared host adapters.");
                Equal(
                    0,
                    Loadedˉmodules.Count(Name =>
                        Name.Contains("clr", StringComparison.OrdinalIgnoreCase) ||
                        Name.Contains("hostfxr", StringComparison.OrdinalIgnoreCase) ||
                        Name.Contains("hostpolicy", StringComparison.OrdinalIgnoreCase)));
            }
            if (OperatingSystem.IsLinux())
            {
                var Loadedˉmappings = new HashSet<string>(StringComparer.Ordinal);
                Equal(
                    0,
                    Executeˉlinuxˉapplication(
                        Firstˉlinux.Imageˉbytes,
                        "wvb status=Valid profile=compiler-aligned\n",
                        [Validˉpath],
                        timeoutˉmilliseconds: 600_000,
                        loadedˉmappings: Loadedˉmappings));
                Equal(
                    1,
                    Executeˉlinuxˉapplication(
                        Firstˉlinux.Imageˉbytes,
                        arguments: [Invalidˉpath],
                        timeoutˉmilliseconds: 600_000,
                        expectedˉerror: "wvb status=Invalid phase=semantic\n"));
                Equal(
                    0,
                    Loadedˉmappings.Count(Name =>
                        Name.Contains("dotnet", StringComparison.OrdinalIgnoreCase) ||
                        Name.Contains("coreclr", StringComparison.OrdinalIgnoreCase) ||
                        Name.Contains("hostfxr", StringComparison.OrdinalIgnoreCase) ||
                        Name.Contains("hostpolicy", StringComparison.OrdinalIgnoreCase)));
            }
        }
        finally
        {
            Directory.Delete(Directoryˉpath, recursive: true);
        }

        Compilerˉbuildˉdriverˉpackages(compilerˉfragment);
    }

    private static void Compilerˉbuildˉdriverˉpackages(
        Nativeˉfragment compilerˉfragment)
    {
        static (int Exitˉcode, string Standardˉoutput, string Standardˉerror) Executeˉtool(
            params string[] arguments)
        {
            var Originalˉoutput = Console.Out;
            var Originalˉerror = Console.Error;
            using var Output = new StringWriter(
                System.Globalization.CultureInfo.InvariantCulture);
            using var Error = new StringWriter(
                System.Globalization.CultureInfo.InvariantCulture);
            try
            {
                Console.SetOut(Output);
                Console.SetError(Error);
                var Exitˉcode = Windvale.Tool.Program.Main(arguments);
                return (Exitˉcode, Output.ToString(), Error.ToString());
            }
            finally
            {
                Console.SetOut(Originalˉoutput);
                Console.SetError(Originalˉerror);
            }
        }

        var Driverˉbytes = Compileˉwithˉsourceˉwvbˉsuccess(
            COMPILER_BUILD_DRIVER_SOURCE,
            "Compiler-Build-Driver.wv",
            additionalˉdependencies:
            [
                new(
                    "Project-Manifest-Core.wv",
                    PROJECT_MANIFEST_CORE_SOURCE),
                new(
                    "Compiler-Wvb-Verifier-Semantic-Core.wv",
                    COMPILER_WVB_VERIFIER_SEMANTIC_SOURCE),
                new(
                    "Compiler-Wvb-Verifier-Executable-Core.wv",
                    COMPILER_WVB_VERIFIER_EXECUTABLE_SOURCE),
            ]);
        Equal(1_078_247, Driverˉbytes.Length);
        Equal(
            COMPILER_BUILD_DRIVER_SHA256,
            Objectˉdigest.Calculateˉsha256(Driverˉbytes));
        var Driverˉmodule = Moduleˉcodec.Readˉandˉverify(Driverˉbytes);
        Equal("Windvaleˉcompilerˉbuildˉdriver", Driverˉmodule.Module.Name);
        Sequenceˉequal(
            [
                Capabilityˉcatalog.CONSOLE_WRITE_LINE,
                Capabilityˉcatalog.DIAGNOSTIC_WRITE_LINE,
                Capabilityˉcatalog.FILE_READ_BYTES,
                Capabilityˉcatalog.FILE_WRITE_BYTES,
                Capabilityˉcatalog.PROCESS_ARGUMENT,
                Capabilityˉcatalog.PROCESS_ARGUMENT_COUNT,
            ],
            Driverˉmodule.Module.Capabilities.Select(Capability => Capability.Name));

        var Driverˉnative = X64ˉnativeˉbackend.Compile(Driverˉmodule);
        Nativeˉfragmentˉverifier.Verify(Driverˉnative.Fragment);
        Sequenceˉequal(compilerˉfragment.Requiredˉservices, Driverˉnative.Fragment.Requiredˉservices);
        var Nativeˉentry = Driverˉnative.Fragment.Symbols.Single(Symbol =>
            Symbol.Binding == Nativeˉsymbolˉbinding.Export &&
            Symbol.Kind == Nativeˉsymbolˉkind.Function &&
            Symbol.Name == "Main").Offset;
        var Windowsˉbundle = X64ˉnativeˉserviceˉbundle.Build(
            Driverˉnative.Fragment,
            Nativeˉserviceˉplatform.Windows);
        var Linuxˉbundle = X64ˉnativeˉserviceˉbundle.Build(
            Driverˉnative.Fragment,
            Nativeˉserviceˉplatform.Linux);
        Equal(10, Windowsˉbundle.Placements.Length);
        Equal(10, Linuxˉbundle.Placements.Length);

        var Rejectedˉwindows = Windowsˉconsoleˉapplicationˉwriter
            .Writeˉhostedˉbuildˉdriver(
                compilerˉfragment,
                Driverˉmodule.Module.Capabilities,
                "Compilerˉsourceˉwvbˉtool");
        True(!Rejectedˉwindows.Success, "The Windows build-driver writer accepted the compiler module identity.");
        Equal("WVW1401", Rejectedˉwindows.Diagnostics.Single().Code);
        var Rejectedˉlinux = Linuxˉconsoleˉapplicationˉwriter
            .Writeˉhostedˉbuildˉdriver(
                compilerˉfragment,
                Driverˉmodule.Module.Capabilities,
                "Compilerˉsourceˉwvbˉtool");
        True(!Rejectedˉlinux.Success, "The Linux build-driver writer accepted the compiler module identity.");
        Equal("WVL1401", Rejectedˉlinux.Diagnostics.Single().Code);

        var Firstˉwindows = Windowsˉconsoleˉapplicationˉwriter
            .Writeˉhostedˉbuildˉdriver(
                Driverˉnative.Fragment,
                Driverˉmodule.Module.Capabilities,
                Driverˉmodule.Module.Name);
        True(
            Firstˉwindows.Success,
            Firstˉwindows.Diagnostics.IsEmpty
                ? "The Windows build-driver writer failed without a diagnostic."
                : Firstˉwindows.Diagnostics[0].Message);
        var Secondˉwindows = Windowsˉhostedˉcompilerˉapplicationˉbuilder.Build(
            Driverˉmodule.Module.Capabilities,
            Windowsˉbundle,
            Nativeˉentry,
            Hostedˉcompilerˉapplicationˉprofile.Buildˉdriver);
        Sequenceˉequal(Firstˉwindows.Imageˉbytes, Secondˉwindows);
        Equal(28_917_248, Firstˉwindows.Imageˉbytes.Length);
        Equal(
            COMPILER_BUILD_DRIVER_WINDOWS_APPLICATION_SHA256,
            Objectˉdigest.Calculateˉsha256(Firstˉwindows.Imageˉbytes.AsSpan()));
        var Verifiedˉwindows = Windowsˉhostedˉcompilerˉapplicationˉverifier.Verify(
            Firstˉwindows.Imageˉbytes.AsSpan(),
            Windowsˉbundle,
            Hostedˉcompilerˉapplicationˉprofile.Buildˉdriver);
        Equal(
            Hostedˉcompilerˉapplicationˉprofile.Buildˉdriver,
            Verifiedˉwindows.Runtime.Metadata.Profile);
        Equal(Nativeˉentry, Verifiedˉwindows.Nativeˉentryˉoffset);
        Throwsˉinvalidˉdata(() =>
            _ = Windowsˉhostedˉcompilerˉapplicationˉverifier.Verify(
                Firstˉwindows.Imageˉbytes.AsSpan(),
                Windowsˉbundle));

        var Firstˉlinux = Linuxˉconsoleˉapplicationˉwriter.Writeˉhostedˉbuildˉdriver(
            Driverˉnative.Fragment,
            Driverˉmodule.Module.Capabilities,
            Driverˉmodule.Module.Name);
        True(
            Firstˉlinux.Success,
            Firstˉlinux.Diagnostics.IsEmpty
                ? "The Linux build-driver writer failed without a diagnostic."
                : Firstˉlinux.Diagnostics[0].Message);
        var Secondˉlinux = Linuxˉhostedˉcompilerˉapplicationˉbuilder.Build(
            Driverˉmodule.Module.Capabilities,
            Linuxˉbundle,
            Nativeˉentry,
            Hostedˉcompilerˉapplicationˉprofile.Buildˉdriver);
        Sequenceˉequal(Firstˉlinux.Imageˉbytes, Secondˉlinux);
        Equal(28_917_760, Firstˉlinux.Imageˉbytes.Length);
        Equal(
            COMPILER_BUILD_DRIVER_LINUX_APPLICATION_SHA256,
            Objectˉdigest.Calculateˉsha256(Firstˉlinux.Imageˉbytes.AsSpan()));
        var Verifiedˉlinux = Linuxˉhostedˉcompilerˉapplicationˉverifier.Verify(
            Firstˉlinux.Imageˉbytes.AsSpan(),
            Linuxˉbundle,
            Hostedˉcompilerˉapplicationˉprofile.Buildˉdriver);
        Equal(
            Hostedˉcompilerˉapplicationˉprofile.Buildˉdriver,
            Verifiedˉlinux.Runtime.Metadata.Profile);
        Equal(Nativeˉentry, Verifiedˉlinux.Nativeˉentryˉoffset);
        Throwsˉinvalidˉdata(() =>
            _ = Linuxˉhostedˉcompilerˉapplicationˉverifier.Verify(
                Firstˉlinux.Imageˉbytes.AsSpan(),
                Linuxˉbundle));

        foreach (var Offset in new[]
        {
            0x98 + 2,
            Verifiedˉwindows.Layout.Textˉfileˉoffset + Verifiedˉwindows.Layout.Bundleˉoffset,
            checked((int)Verifiedˉwindows.Layout.Runtimeˉfileˉoffset +
                Hostedˉcompilerˉruntimeˉdata.METADATA_OFFSET),
        })
        {
            var Corrupted = Firstˉwindows.Imageˉbytes.ToArray();
            Corrupted[Offset] ^= 1;
            Throwsˉinvalidˉdata(() =>
                _ = Windowsˉhostedˉcompilerˉapplicationˉverifier.Verify(
                    Corrupted,
                    Windowsˉbundle,
                    Hostedˉcompilerˉapplicationˉprofile.Buildˉdriver));
        }
        Throwsˉinvalidˉdata(() =>
            _ = Windowsˉhostedˉcompilerˉapplicationˉverifier.Verify(
                Firstˉwindows.Imageˉbytes.AsSpan(0, Firstˉwindows.Imageˉbytes.Length - 1),
                Windowsˉbundle,
                Hostedˉcompilerˉapplicationˉprofile.Buildˉdriver));
        Throwsˉinvalidˉdata(() =>
            _ = Windowsˉhostedˉcompilerˉapplicationˉverifier.Verify(
                [.. Firstˉwindows.Imageˉbytes, 0],
                Windowsˉbundle,
                Hostedˉcompilerˉapplicationˉprofile.Buildˉdriver));

        foreach (var Offset in new[]
        {
            0x180 + 24,
            Verifiedˉlinux.Layout.Textˉfileˉoffset + Verifiedˉlinux.Layout.Bundleˉoffset,
            checked((int)Verifiedˉlinux.Layout.Dataˉfileˉoffset +
                Hostedˉcompilerˉruntimeˉdata.METADATA_OFFSET),
        })
        {
            var Corrupted = Firstˉlinux.Imageˉbytes.ToArray();
            Corrupted[Offset] ^= 1;
            Throwsˉinvalidˉdata(() =>
                _ = Linuxˉhostedˉcompilerˉapplicationˉverifier.Verify(
                    Corrupted,
                    Linuxˉbundle,
                    Hostedˉcompilerˉapplicationˉprofile.Buildˉdriver));
        }
        Throwsˉinvalidˉdata(() =>
            _ = Linuxˉhostedˉcompilerˉapplicationˉverifier.Verify(
                Firstˉlinux.Imageˉbytes.AsSpan(0, Firstˉlinux.Imageˉbytes.Length - 1),
                Linuxˉbundle,
                Hostedˉcompilerˉapplicationˉprofile.Buildˉdriver));
        Throwsˉinvalidˉdata(() =>
            _ = Linuxˉhostedˉcompilerˉapplicationˉverifier.Verify(
                [.. Firstˉlinux.Imageˉbytes, 0],
                Linuxˉbundle,
                Hostedˉcompilerˉapplicationˉprofile.Buildˉdriver));

        var Directoryˉpath = Path.Combine(
            Path.GetTempPath(),
            $"windvale-compiler-build-driver-{Guid.NewGuid():N}");
        Directory.CreateDirectory(Directoryˉpath);
        try
        {
            var Driverˉpath = Path.Combine(Directoryˉpath, "Wvbuild.wvb");
            var Sourceˉpath = Path.Combine(Directoryˉpath, "Function-Only.wv");
            var Invalidˉpath = Path.Combine(Directoryˉpath, "Invalid.wv");
            var Outputˉpath = Path.Combine(Directoryˉpath, "Output.wvb");
            var Projectˉsourceˉdirectory = Path.Combine(Directoryˉpath, "Source");
            var Projectˉpath = Path.Combine(Directoryˉpath, "Composition.wvproj");
            var Invalidˉprojectˉpath = Path.Combine(
                Directoryˉpath, "Invalid.wvproj");
            var Duplicateˉprojectˉpath = Path.Combine(
                Directoryˉpath, "Duplicate.wvproj");
            var Projectˉoutputˉpath = Path.Combine(
                Directoryˉpath, "Composition.wvb");
            Directory.CreateDirectory(Projectˉsourceˉdirectory);
            File.WriteAllBytes(Driverˉpath, Driverˉbytes);
            File.WriteAllText(
                Sourceˉpath,
                SOURCE_WVB_FUNCTION_ONLY_SOURCE,
                new UTF8Encoding(false));
            File.WriteAllText(
                Invalidˉpath,
                "this is not Windvale",
                new UTF8Encoding(false));
            File.WriteAllText(
                Path.Combine(Projectˉsourceˉdirectory, "Root.wv"),
                COMPOSITION_ROOT_SOURCE,
                new UTF8Encoding(false));
            File.WriteAllText(
                Path.Combine(Projectˉsourceˉdirectory, "Leaf.wv"),
                COMPOSITION_LEAF_SOURCE,
                new UTF8Encoding(false));
            File.WriteAllText(
                Path.Combine(Projectˉsourceˉdirectory, "Middle.wv"),
                COMPOSITION_MIDDLE_SOURCE,
                new UTF8Encoding(false));
            File.WriteAllText(
                Projectˉpath,
                "windvale-project 1\n" +
                "root \"Source/Root.wv\"\n" +
                "source \"Source/Leaf.wv\"\n" +
                "source \"Source/Middle.wv\"\n" +
                "emit wvb\n",
                new UTF8Encoding(false));
            File.WriteAllText(
                Invalidˉprojectˉpath,
                "windvale-project 2\nroot \"Source/Root.wv\"\nemit wvb\n",
                new UTF8Encoding(false));
            File.WriteAllText(
                Duplicateˉprojectˉpath,
                "windvale-project 1\n" +
                "root \"Source/Root.wv\"\n" +
                "source \"Source/root.wv\"\n" +
                "emit wvb\n",
                new UTF8Encoding(false));

            var Nativeˉprojectˉpath = Projectˉpath.Replace('\\', '/');
            var Nativeˉinvalidˉprojectˉpath = Invalidˉprojectˉpath.Replace('\\', '/');
            var Nativeˉduplicateˉprojectˉpath = Duplicateˉprojectˉpath.Replace('\\', '/');
            var Nativeˉprojectˉoutputˉpath = Projectˉoutputˉpath.Replace('\\', '/');

            var Cliˉtarget = OperatingSystem.IsWindows()
                ? Windowsˉconsoleˉapplicationˉcontract.BUILD_DRIVER_TARGET_NAME
                : Linuxˉconsoleˉapplicationˉcontract.BUILD_DRIVER_TARGET_NAME;
            var Cliˉapplication = Executeˉtool(
                "aot",
                Driverˉpath,
                "--target",
                Cliˉtarget);
            Equal(0, Cliˉapplication.Exitˉcode);
            Equal(string.Empty, Cliˉapplication.Standardˉerror);
            Contains(Cliˉapplication.Standardˉoutput, $"Target: {Cliˉtarget}");
            Sequenceˉequal(
                OperatingSystem.IsWindows()
                    ? Firstˉwindows.Imageˉbytes
                    : Firstˉlinux.Imageˉbytes,
                File.ReadAllBytes(Path.ChangeExtension(
                    Driverˉpath,
                    Windvale.Tool.Program.Targetˉoutputˉextension(Cliˉtarget))));

            var Expectedˉoutput =
                "build status=Published verification=compiler-aligned functions=4 " +
                "code-bytes=532 module-bytes=816\n";
            var Expectedˉerror =
                "build status=Compileˉrejected source-status=Sourceˉwir " +
                "wir-status=Sourceˉbindings function=0 operation=0\n";
            var Sameˉresourceˉerror =
                "build status=Invalidˉinvocation reason=output-is-input\n";
            var Expectedˉprojectˉoutput =
                "build status=Published verification=compiler-aligned functions=6 " +
                "code-bytes=383 module-bytes=857\n";
            var Invalidˉprojectˉerror =
                "build status=Projectˉrejected code=WVP1001 line=1 column=1\n";
            var Duplicateˉprojectˉerror =
                "build status=Projectˉrejected code=WVP1007 line=3 column=9\n";
            var Expectedˉprojectˉbytes = Compileˉcompositionˉsuccess(
                new("leaf.wv", COMPOSITION_LEAF_SOURCE),
                new("middle.wv", COMPOSITION_MIDDLE_SOURCE));
            var Sentinel = "preserve-existing-output"u8.ToArray();
            if (OperatingSystem.IsWindows())
            {
                var Loadedˉmodules = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                Equal(
                    0,
                    Executeˉwindowsˉapplication(
                        Firstˉwindows.Imageˉbytes,
                        Expectedˉoutput,
                        [Sourceˉpath, Outputˉpath],
                        timeoutˉmilliseconds: 600_000,
                        loadedˉmodules: Loadedˉmodules));
                Sequenceˉequal(
                    Compileˉsuccess(SOURCE_WVB_FUNCTION_ONLY_SOURCE),
                    File.ReadAllBytes(Outputˉpath));
                Equal(
                    0,
                    Executeˉwindowsˉapplication(
                        Firstˉwindows.Imageˉbytes,
