    private static void Nativeˉcompilerˉbootstrapˉreproducesˉstage2()
    {
        var Compilerˉfixture = EXACT_COMPILER_WVB.Value;
        var Compilerˉbytes = Compilerˉfixture.Bytes;
        var Compilerˉtool = Compilerˉfixture.Module;
        var Compilerˉrecords = Compilerˉtool.Module.Types
            .OfType<Recordˉtypeˉdeclaration>()
            .ToImmutableArray();
        Equal(59, Compilerˉrecords.Length);
        Equal(23, Compilerˉtool.Module.Types.OfType<Enumˉtypeˉdeclaration>().Count());
        Equal(34, Compilerˉrecords.Max(Record => Record.Fields.Length));
        Equal(
            0,
            Compilerˉrecords.Sum(Record =>
                Record.Fields.Count(Field => Field.Type.Kind == Valueˉtype.Record)));
        var Compilerˉnative = EXACT_COMPILER_NATIVE.Value;
        var Ownership = Compilerˉnative.Module.Descriptorˉownership ??
            throw new InvalidOperationException("The exact native compiler omitted descriptor ownership.");
        Nativeˉdescriptorˉownershipˉverifier.Verify(Compilerˉnative.Module, Ownership);
        var Ownershipˉactions = Ownership.Functions
            .SelectMany(Function => Function.Actions)
            .ToImmutableArray();
        var Allocatorˉprojection = Nativeˉdescriptorˉallocatorˉprojector.Project(Ownership);
        var Allocatorˉemission = Compilerˉnative.Module.Descriptorˉallocatorˉemission ??
            throw new InvalidOperationException(
                "The exact native compiler omitted descriptor allocator emission.");
        Nativeˉdescriptorˉallocatorˉemissionˉverifier.Verify(
            Compilerˉnative.Module,
            Allocatorˉemission);
        True(Ownershipˉactions.Any(Action => Action.Kind ==
                Nativeˉdescriptorˉownershipˉactionˉkind.Borrowˉstatic),
            "The exact compiler ownership plan omitted static descriptor borrowing.");
        True(Ownershipˉactions.Any(Action => Action.Kind ==
                Nativeˉdescriptorˉownershipˉactionˉkind.Borrowˉhost),
            "The exact compiler ownership plan omitted host snapshot borrowing.");
        var Largestˉownershipˉfunction = Ownership.Functions.MaxBy(
            Function => Function.Actions.Length)!;
        Equal(
            "NATIVE_DESCRIPTOR_OWNERSHIP format=1 functions=419 actions=351544 " +
            "allocator-leaf-calls=340671 ownership-movement-actions=10873 " +
            "parameters=386 assigned-parameters=0 locals=4468 " +
            "record-parameter-fields=629 assigned-record-parameter-fields=0 " +
            "record-local-fields=14114 values=8642 record-value-fields=26954 " +
            "acquire=544 borrow=232 retain=51063 release=289064 call-borrow=6021 " +
            "accept-return=3143 transfer-return=1477 largest-actions=80449 " +
            "largest-index=318 largest-name=__WvM8F50 " +
            "action-map=7d89ebff01349c6e4d7ea82591d03cd226ab5f060128295e7ae34f8b96a3bf21",
            $"NATIVE_DESCRIPTOR_OWNERSHIP format={Ownership.Formatˉversion} " +
            $"functions={Ownership.Functions.Length} actions={Ownership.Totalˉactions} " +
            $"allocator-leaf-calls={Allocatorˉprojection.Allocatorˉleafˉcalls} " +
            $"ownership-movement-actions={Allocatorˉprojection.Ownershipˉmovementˉactions} " +
            $"parameters={Ownership.Functions.Sum(Function => Function.Descriptorˉparameterˉbindings)} " +
            $"assigned-parameters={Ownership.Functions.Sum(Function => Function.Assignedˉdescriptorˉparameterˉbindings)} " +
            $"locals={Ownership.Functions.Sum(Function => Function.Descriptorˉlocalˉbindings)} " +
            $"record-parameter-fields={Ownership.Functions.Sum(Function => Function.Recordˉparameterˉdescriptorˉfields)} " +
            $"assigned-record-parameter-fields={Ownership.Functions.Sum(Function => Function.Assignedˉrecordˉparameterˉdescriptorˉfields)} " +
            $"record-local-fields={Ownership.Functions.Sum(Function => Function.Recordˉlocalˉdescriptorˉfields)} " +
            $"values={Ownership.Functions.Sum(Function => Function.Descriptorˉvalueˉidentifiers)} " +
            $"record-value-fields={Ownership.Functions.Sum(Function => Function.Recordˉvalueˉdescriptorˉfields)} " +
            $"acquire={Ownership.Functions.Sum(Function => Function.Acquireˉactions)} " +
            $"borrow={Ownership.Functions.Sum(Function => Function.Borrowˉactions)} " +
            $"retain={Ownership.Functions.Sum(Function => Function.Retainˉactions)} " +
            $"release={Ownership.Functions.Sum(Function => Function.Releaseˉactions)} " +
            $"call-borrow={Ownership.Functions.Sum(Function => Function.Callˉborrowˉactions)} " +
            $"accept-return={Ownership.Functions.Sum(Function => Function.Acceptedˉreturnˉactions)} " +
            $"transfer-return={Ownership.Functions.Sum(Function => Function.Transferredˉreturnˉactions)} " +
            $"largest-actions={Largestˉownershipˉfunction.Actions.Length} " +
            $"largest-index={Largestˉownershipˉfunction.Functionˉindex} " +
            $"largest-name={Largestˉownershipˉfunction.Functionˉname} " +
            $"action-map={Nativeˉdescriptorˉownershipˉdigest(Ownership)}");
        var Allocatorˉemissions = Allocatorˉemission.Functions
            .SelectMany(Function => Function.Emissions)
            .ToImmutableArray();
        var Largestˉallocatorˉfunction = Allocatorˉemission.Functions.MaxBy(
            Function => Function.Allocatorˉleafˉinvocations)!;
        Equal(
            "NATIVE_DESCRIPTOR_ALLOCATOR_EMISSION format=1 context=8/128 " +
            "state-offset=112 leaf-offset=120 request-cells=3 functions=419 " +
            "ownership-actions=351544 leaf-invocations=340671 movement-actions=10873 " +
            "generated=340644 service=27 request-functions=324 entry=0 before=38772 " +
            "allocation=544 after=65796 cleanup=235559 direct-locations=385728 " +
            "indirect-locations=6006 max-frame=1919 largest-invocations=78676 " +
            "largest-index=318 largest-name=__WvM8F50 " +
            "emission-map=93144d1d47ffb0ddfe2937f00a6a427d478b8e548dca4ff08713bbe24b15d368",
            $"NATIVE_DESCRIPTOR_ALLOCATOR_EMISSION format={Allocatorˉemission.Formatˉversion} " +
            $"context={Allocatorˉemission.Candidateˉcontextˉformatˉversion}/" +
            $"{Allocatorˉemission.Candidateˉcontextˉsize} " +
            $"state-offset={Allocatorˉemission.Allocatorˉstateˉpointerˉoffset} " +
            $"leaf-offset={Allocatorˉemission.Allocatorˉleafˉpointerˉoffset} " +
            $"request-cells={Allocatorˉemission.Requestˉframeˉcells} " +
            $"functions={Allocatorˉemission.Functions.Length} " +
            $"ownership-actions={Allocatorˉemission.Ownershipˉactions} " +
            $"leaf-invocations={Allocatorˉemission.Allocatorˉleafˉinvocations} " +
            $"movement-actions={Allocatorˉemission.Ownershipˉmovementˉactions} " +
            $"generated={Allocatorˉemission.Functions.Sum(Function => Function.Generatedˉcodeˉinvocations)} " +
            $"service={Allocatorˉemission.Functions.Sum(Function => Function.Runtimeˉserviceˉinvocations)} " +
            $"request-functions={Allocatorˉemission.Functions.Count(Function => Function.Requestˉbaseˉcell >= 0)} " +
            $"entry={Allocatorˉemissions.Count(Emission => Emission.Phase == Nativeˉdescriptorˉallocatorˉemissionˉphase.Functionˉentry)} " +
            $"before={Allocatorˉemissions.Count(Emission => Emission.Phase == Nativeˉdescriptorˉallocatorˉemissionˉphase.Operationˉbefore)} " +
            $"allocation={Allocatorˉemissions.Count(Emission => Emission.Phase == Nativeˉdescriptorˉallocatorˉemissionˉphase.Operationˉallocation)} " +
            $"after={Allocatorˉemissions.Count(Emission => Emission.Phase == Nativeˉdescriptorˉallocatorˉemissionˉphase.Operationˉafter)} " +
            $"cleanup={Allocatorˉemissions.Count(Emission => Emission.Phase == Nativeˉdescriptorˉallocatorˉemissionˉphase.Terminatorˉcleanup)} " +
            $"direct-locations={Allocatorˉemissions.Sum(Emission => (Emission.Target.Addressing == Nativeˉdescriptorˉownerˉaddressing.Directˉframe ? 1 : 0) + (Emission.Source.Addressing == Nativeˉdescriptorˉownerˉaddressing.Directˉframe ? 1 : 0))} " +
            $"indirect-locations={Allocatorˉemissions.Sum(Emission => (Emission.Target.Addressing == Nativeˉdescriptorˉownerˉaddressing.Indirectˉrecord ? 1 : 0) + (Emission.Source.Addressing == Nativeˉdescriptorˉownerˉaddressing.Indirectˉrecord ? 1 : 0))} " +
            $"max-frame={Allocatorˉemission.Functions.Max(Function => Function.Projectedˉframeˉcells)} " +
            $"largest-invocations={Largestˉallocatorˉfunction.Allocatorˉleafˉinvocations} " +
            $"largest-index={Largestˉallocatorˉfunction.Functionˉindex} " +
            $"largest-name={Largestˉallocatorˉfunction.Functionˉname} " +
            $"emission-map={Nativeˉdescriptorˉallocatorˉemissionˉdigest(Allocatorˉemission)}");
        var Directoryˉpath = Path.Combine(
            Path.GetTempPath(),
            $"windvale-native-bootstrap-{Guid.NewGuid():N}");
        Directory.CreateDirectory(Directoryˉpath);
        try
        {
            var (Arguments, Outputˉpath) = Writeˉexactˉcompilerˉstage2ˉinputs(
                Directoryˉpath,
                "Bootstrap-Stage2.wvb");

            using var Compilerˉoutput = new Nativeˉoutputˉcapture();
            using var Compilerˉdiagnostic = new Nativeˉoutputˉcapture();
            var Compilerˉresources = new Hostedˉresourceˉcontext(
                Arguments.ToImmutableArray(),
                TextWriter.Null,
                TextWriter.Null);
            var Compilerˉauthorized = Compilerˉtool.Module.Capabilities
                .Select(Capability => Capability.Name)
                .ToImmutableHashSet(StringComparer.Ordinal);
            var Measurement = X64ˉnativeˉexecutor.Measureˉi32(
                Compilerˉnative.Fragment,
                maximumˉinstructions: 48_000_000_000,
                hostˉservices: new(
                    Compilerˉoutput.Channel,
                    Compilerˉauthorized,
                    Compilerˉresources,
                    Compilerˉdiagnostic.Channel,
                    Nativeˉfileˉinput.Hostˉfileˉsystem(),
                    Nativeˉfileˉoutput.Hostˉfileˉsystem()));
            Equal(0, Measurement.Scalar);
            Equal(0u, Measurement.Recordˉarenaˉused);
            Equal(128_758_647u, Measurement.Textˉarenaˉused);
            Equal(
                "source wvb status=Valid functions=419 code-bytes=760855 module-bytes=921900\n",
                Compilerˉoutput.Readˉtext());
            Equal(string.Empty, Compilerˉdiagnostic.Readˉtext());
            Sequenceˉequal(Compilerˉbytes, File.ReadAllBytes(Outputˉpath));
        }
        finally
        {
            Directory.Delete(Directoryˉpath, recursive: true);
        }
    }

    private static (List<string> Arguments, string Outputˉpath)
        Writeˉexactˉcompilerˉstage2ˉinputs(string directory, string outputˉname)
    {
        var Inventory = new (string Name, string Source)[]
        {
            ("Source-Wvb-Tool.wv", SOURCE_WVB_TOOL_SOURCE),
            ("Source-Bindings-Core.wv", SOURCE_BINDINGS_SOURCE),
            ("Source-Body-Parser.wv", SOURCE_BODY_PARSER_SOURCE),
            ("Source-Declaration-Parser.wv", SOURCE_DECLARATION_PARSER_SOURCE),
            ("Source-Graph-Core.wv", SOURCE_GRAPH_SOURCE),
            ("Source-Lexer-Core.wv", SOURCE_LEXER_SOURCE),
            ("Source-Set-Core.wv", SOURCE_SET_SOURCE),
            ("Source-Symbols-Core.wv", SOURCE_SYMBOLS_SOURCE),
            ("Source-Wir-Core.wv", SOURCE_WIR_SOURCE),
            ("Source-Wvb-Core.wv", SOURCE_WVB_SOURCE),
            ("Source-Wvb-Temporary-Slots.wv", SOURCE_WVB_TEMPORARY_SLOTS_SOURCE),
            ("Byte-Construction.wv", BYTE_CONSTRUCTION_SOURCE),
            ("Decimal-Parsing.wv", DECIMAL_PARSING_SOURCE),
        };
        var Arguments = new List<string>();
        foreach (var Item in Inventory)
        {
            var Sourceˉpath = Path.Combine(directory, Item.Name);
            File.WriteAllText(Sourceˉpath, Item.Source, new UTF8Encoding(false));
            Arguments.Add(Sourceˉpath);
        }
        var Outputˉpath = Path.Combine(directory, outputˉname);
        Arguments.Add(Outputˉpath);
        return (Arguments, Outputˉpath);
    }

    private static void Sourceˉmodulesˉcompose()
    {
        var First = Compileˉcompositionˉsuccess(
            new("middle.wv", COMPOSITION_MIDDLE_SOURCE),
            new("leaf.wv", COMPOSITION_LEAF_SOURCE));
        var Second = Compileˉcompositionˉsuccess(
            new("leaf.wv", COMPOSITION_LEAF_SOURCE),
            new("middle.wv", COMPOSITION_MIDDLE_SOURCE));
        Sequenceˉequal(First, Second);

        var Module = Moduleˉcodec.Readˉandˉverify(First);
        Equal("Compositionˉdemo", Module.Module.Name);
        Equal(Moduleˉprofile.Portable, Module.Module.Profile);
        Sequenceˉequal(
            ["Helper", "Main", "__WvM1F0", "__WvM1F1", "__WvM2F0", "__WvM2F1"],
            Module.Module.Functions.Select(Function => Function.Name));
        Sequenceˉequal(
            ["__WvM1R0", "__WvM1E0"],
            Module.Module.Types.Select(Type => Type.Name));
        Sequenceˉequal(["__WvM1D0"], Module.Module.Data.Select(Item => Item.Name));
        Sequenceˉequal(["Main"], Module.Module.Exports.Select(Export => Export.Name));
        Equal(
            42,
            new Referenceˉruntime(
                Module,
                new Referenceˉcapabilityˉhost(new StringWriter()),
                Runtimeˉoptions.Portableˉdefaults).Runˉmain().Exitˉcode);

        var Renamedˉaliases = Seedˉcompiler.Compileˉmodules(
            new(
                "root.wv",
                COMPOSITION_ROOT_SOURCE
                    .Replace(" as Middle", " as M", StringComparison.Ordinal)
                    .Replace("Middle.", "M.", StringComparison.Ordinal)),
            [
                new(
                    "middle.wv",
                    COMPOSITION_MIDDLE_SOURCE
                        .Replace(" as Leaf", " as L", StringComparison.Ordinal)
                        .Replace("Leaf.", "L.", StringComparison.Ordinal)),
                new("leaf.wv", COMPOSITION_LEAF_SOURCE),
            ]);
        True(
            Renamedˉaliases.Success,
            "Renamed aliases failed: " + string.Join(" | ", Renamedˉaliases.Diagnostics));
        Sequenceˉequal(First, Renamedˉaliases.Moduleˉbytes);

        const string Qualifiedˉprivateˉroot = """
            module Qualifiedˉprivateˉroot profile portable;
            import Compositionˉleaf as Leaf;
            export fn Main() -> i32 { return Leaf.Helper(1); }
            """;
        Hasˉdiagnostic(
            Seedˉcompiler.Compileˉmodules(
                new("qualified-private-root.wv", Qualifiedˉprivateˉroot),
                [new("leaf.wv", COMPOSITION_LEAF_SOURCE)]),
            "WVC0017");

        const string Qualifiedˉunknownˉroot = """
            module Qualifiedˉunknownˉroot profile portable;
            import Compositionˉleaf as Leaf;
            export fn Main() -> i32 { return Leaf.Missing(); }
            """;
        Hasˉdiagnostic(
            Seedˉcompiler.Compileˉmodules(
                new("qualified-unknown-root.wv", Qualifiedˉunknownˉroot),
                [new("leaf.wv", COMPOSITION_LEAF_SOURCE)]),
            "WVC0018");

        const string Transitiveˉleakˉroot = """
            module Transitiveˉleakˉroot profile portable;
            import Compositionˉmiddle as Middle;
            export fn Main() -> i32 { return Leaf.Compositionˉmake(1); }
            """;
        Hasˉdiagnostic(
            Seedˉcompiler.Compileˉmodules(
                new("transitive-leak-root.wv", Transitiveˉleakˉroot),
                [
                    new("middle.wv", COMPOSITION_MIDDLE_SOURCE),
                    new("leaf.wv", COMPOSITION_LEAF_SOURCE),
                ]),
            "WVC0019");

        const string Duplicateˉaliasˉroot = """
            module Duplicateˉaliasˉroot profile portable;
            import Compositionˉleaf as Dependency;
            import Compositionˉmiddle as Dependency;
            export fn Main() -> i32 { return 0; }
            """;
        Hasˉdiagnostic(
            Seedˉcompiler.Compileˉmodules(
                new("duplicate-alias-root.wv", Duplicateˉaliasˉroot),
                [
                    new("middle.wv", COMPOSITION_MIDDLE_SOURCE),
                    new("leaf.wv", COMPOSITION_LEAF_SOURCE),
                ]),
            "WVC0015");

        const string Missingˉaliasˉroot = """
            module Missingˉaliasˉroot profile portable;
            import Compositionˉleaf as Leaf;
            import Compositionˉmiddle;
            export fn Main() -> i32 { return 0; }
            """;
        Hasˉdiagnostic(
            Seedˉcompiler.Compileˉmodules(
                new("missing-alias-root.wv", Missingˉaliasˉroot),
                [
                    new("middle.wv", COMPOSITION_MIDDLE_SOURCE),
                    new("leaf.wv", COMPOSITION_LEAF_SOURCE),
                ]),
            "WVC1104");

        var Missing = Seedˉcompiler.Compileˉmodules(
            new("root.wv", COMPOSITION_ROOT_SOURCE),
            []);
        Equal("WVC0007", Missing.Diagnostics.Single().Code);
        Equal("root.wv", Missing.Diagnostics.Single().Span.Sourceˉname);

        const string Cycleˉroot = """
            module Cycleˉroot profile portable;
            import Cycleˉdependency as Dependency;
            export fn Main() -> i32 { return Dependency.Cycleˉvalue(); }
            """;
        const string Cycleˉdependency = """
            module Cycleˉdependency profile portable;
            import Cycleˉroot as Root;
            export fn Cycleˉvalue() -> i32 { return 0; }
            """;
        Hasˉdiagnostic(
            Seedˉcompiler.Compileˉmodules(
                new("cycle-root.wv", Cycleˉroot),
                [new("cycle-dependency.wv", Cycleˉdependency)]),
            "WVC0008");

        const string Hostedˉdependency = """
            module Hostedˉdependency profile hosted;
            export fn Hostedˉvalue() -> i32 { return 0; }
            """;
        const string Portableˉroot = """
            module Portableˉroot profile portable;
            import Hostedˉdependency as Dependency;
            export fn Main() -> i32 { return Dependency.Hostedˉvalue(); }
            """;
        Hasˉdiagnostic(
            Seedˉcompiler.Compileˉmodules(
                new("portable-root.wv", Portableˉroot),
                [new("hosted-dependency.wv", Hostedˉdependency)]),
            "WVC0010");

        const string Privateˉdependency = """
            module Privateˉdependency profile portable;
            fn Privateˉvalue() -> i32 { return 0; }
            """;
        const string Privateˉroot = """
            module Privateˉroot profile portable;
