    private static void Capabilityˉbearingˉlibrariesˉcompose()
    {
        const string Rootˉsource = """
            module Resourceˉstoreˉapplication profile hosted;

            import Hostedˉresourceˉstore as Hostedˉresources;
            import Resourceˉstore as Resources;

            capability file.read_bytes;

            export fn Main() -> i32 {
                let Result: Resources.Resourceˉstoreˉresult = Hostedˉresources.Hostedˉresourceˉstoreˉlookup(
                    "fixture.wvrs",
                    "entry"
                );
                if Result.Status != Resources.Resourceˉstoreˉstatus.Valid { return 1; }
                if Result.Identifier != 1u32 { return 2; }
                if Result.Kind != 3u32 { return 3; }
                if Result.Attributes != 7u32 { return 4; }
                if Bytesˉlength(Result.Value) != 4u32 { return 5; }
                if Bytesˉreadˉu8(Result.Value, 0u32) != 3u8 { return 6; }
                if Bytesˉreadˉu8(Result.Value, 1u32) != 5u8 { return 7; }
                if Bytesˉreadˉu8(Result.Value, 2u32) != 8u8 { return 8; }
                if Bytesˉreadˉu8(Result.Value, 3u32) != 13u8 { return 9; }
                return 29;
            }
            """;
        Sourceˉmoduleˉinput Core = new(
            "Libraries/Foundation/Resources/Resource-Store.wv",
            RESOURCE_STORE_SOURCE);
        Sourceˉmoduleˉinput Library = new(
            "Libraries/Platform/Resources/Hosted-Resource-Store.wv",
            HOSTED_RESOURCE_STORE_SOURCE);
        var First = Seedˉcompiler.Compileˉmodules(
            new("resource-store-application.wv", Rootˉsource),
            [Library, Core]);
        var Second = Seedˉcompiler.Compileˉmodules(
            new("resource-store-application.wv", Rootˉsource),
            [Core, Library]);
        True(First.Success, "Capability-bearing library composition failed: " +
            string.Join(" | ", First.Diagnostics));
        True(Second.Success, "Reordered capability-bearing library composition failed: " +
            string.Join(" | ", Second.Diagnostics));
        Sequenceˉequal(First.Moduleˉbytes, Second.Moduleˉbytes);

        var Module = Moduleˉcodec.Readˉandˉverify(First.Moduleˉbytes.AsSpan());
        True(Module.Module.Profile == Moduleˉprofile.Hosted,
            "The composed platform-library application lost its hosted profile.");
        Sequenceˉequal(
            [Capabilityˉcatalog.FILE_READ_BYTES],
            Module.Module.Capabilities.Select(Capability => Capability.Name));
        var Store = Buildˉresourceˉstoreˉfixture();
        var Reader = new Testˉfileˉreader((Name, Maximumˉbytes) =>
        {
            Equal("fixture.wvrs", Name);
            Equal(Bytecodeˉlimits.MAX_BYTE_DATA_BYTES, Maximumˉbytes);
            return Store;
        });
        var Runtime = new Referenceˉruntime(
            Module,
            new Referenceˉcapabilityˉhost(new Hostedˉresourceˉcontext(
                [], TextWriter.Null, TextWriter.Null, Reader)),
            new(ImmutableHashSet.Create(StringComparer.Ordinal, Capabilityˉcatalog.FILE_READ_BYTES)));
        Equal(29, Runtime.Runˉmain().Exitˉcode);
        Equal(1, Reader.Readˉcount);

        const string Unapprovedˉroot = """
            module Unapprovedˉapplication profile hosted;
            import Hostedˉresourceˉstore as Resources;
            export fn Main() -> i32 { return 0; }
            """;
        Hasˉdiagnostic(
            Seedˉcompiler.Compileˉmodules(
                new("unapproved-application.wv", Unapprovedˉroot),
                [Library, Core]),
            "WVC0013");

        const string Unapprovedˉforwarder = """
            module Unapprovedˉforwarder profile hosted;
            import Hostedˉresourceˉstore as Hostedˉresources;
            import Resourceˉstore as Resources;
            export fn Forwardˉlookup(Store: text, Name: text) -> Resources.Resourceˉstoreˉresult {
                return Hostedˉresources.Hostedˉresourceˉstoreˉlookup(Store, Name);
            }
            """;
        const string Forwardingˉroot = """
            module Forwardingˉapplication profile hosted;
            import Unapprovedˉforwarder as Forwarder;
            capability file.read_bytes;
            export fn Main() -> i32 { return 0; }
            """;
        Hasˉdiagnostic(
            Seedˉcompiler.Compileˉmodules(
                new("forwarding-application.wv", Forwardingˉroot),
                [
                    new("unapproved-forwarder.wv", Unapprovedˉforwarder),
                    Library,
                    Core,
                ]),
            "WVC0013");
    }

    private static void Readˉonlyˉdirectoryˉreadsˉareˉtyped()
    {
        const string Rootˉsource = """
            module Directoryˉapplication profile hosted;

            import Readˉonlyˉdirectory as Directory;

            capability filesystem.directory_read_v1;

            export fn Main() -> i32 {
                let First: Directory.Directoryˉreadˉresult = Directory.Directoryˉreadˉbytes(
                    "Kernel.wvb", 1u32, 3u32
                );
                if First.Status != Directory.Directoryˉreadˉstatus.Valid { return 1; }
                if First.Fileˉlength != 5u32 { return 2; }
                if First.Nextˉoffset != 4u32 { return 3; }
                if Bytesˉlength(First.Value) != 3u32 { return 4; }
                if Bytesˉreadˉu8(First.Value, 0u32) != 5u8 { return 5; }
                if Bytesˉreadˉu8(First.Value, 1u32) != 8u8 { return 6; }
                if Bytesˉreadˉu8(First.Value, 2u32) != 13u8 { return 7; }

                let Tail: Directory.Directoryˉreadˉresult = Directory.Directoryˉreadˉbytes(
                    "Kernel.wvb", 4u32, 3u32
                );
                if Tail.Status != Directory.Directoryˉreadˉstatus.Valid { return 8; }
                if Tail.Nextˉoffset != 5u32 { return 9; }
                if Bytesˉlength(Tail.Value) != 1u32 { return 10; }
                if Bytesˉreadˉu8(Tail.Value, 0u32) != 21u8 { return 11; }

                let End: Directory.Directoryˉreadˉresult = Directory.Directoryˉreadˉbytes(
                    "Kernel.wvb", 5u32, 3u32
                );
                if End.Status != Directory.Directoryˉreadˉstatus.Valid { return 12; }
                if End.Nextˉoffset != 5u32 { return 13; }
                if Bytesˉlength(End.Value) != 0u32 { return 14; }

                let Missing: Directory.Directoryˉreadˉresult = Directory.Directoryˉreadˉbytes(
                    "Missing.wvb", 0u32, 3u32
                );
                if Missing.Status != Directory.Directoryˉreadˉstatus.Notˉfound { return 15; }

                let Pastˉend: Directory.Directoryˉreadˉresult = Directory.Directoryˉreadˉbytes(
                    "Kernel.wvb", 6u32, 3u32
                );
                if Pastˉend.Status != Directory.Directoryˉreadˉstatus.Invalidˉoffset { return 16; }
                if Pastˉend.Fileˉlength != 5u32 { return 17; }

                let Invalidˉname: Directory.Directoryˉreadˉresult = Directory.Directoryˉreadˉbytes(
                    "../Kernel.wvb", 0u32, 3u32
                );
                if Invalidˉname.Status != Directory.Directoryˉreadˉstatus.Invalidˉname { return 18; }

                let Invalidˉlimit: Directory.Directoryˉreadˉresult = Directory.Directoryˉreadˉbytes(
                    "Kernel.wvb", 0u32, 3073u32
                );
                if Invalidˉlimit.Status != Directory.Directoryˉreadˉstatus.Invalidˉlimit { return 19; }

                let Invalidˉresponse: Directory.Directoryˉreadˉresult = Directory.Directoryˉreadˉdecode(
                    Textˉtoˉutf8("short"), 0u32, 3u32
                );
                if Invalidˉresponse.Status != Directory.Directoryˉreadˉstatus.Invalidˉresponse { return 20; }

                let Overflowingˉlimit: Directory.Directoryˉreadˉresult = Directory.Directoryˉreadˉbytes(
                    "Kernel.wvb", 4294967295u32, 1u32
                );
                if Overflowingˉlimit.Status != Directory.Directoryˉreadˉstatus.Invalidˉlimit { return 21; }
                return 29;
            }
            """;
        Sourceˉmoduleˉinput Library = new(
            "Libraries/Platform/Filesystem/Read-Only-Directory.wv",
            READ_ONLY_DIRECTORY_SOURCE);
        var First = Seedˉcompiler.Compileˉmodules(
            new("directory-application.wv", Rootˉsource),
            [Library]);
        var Second = Seedˉcompiler.Compileˉmodules(
            new("directory-application.wv", Rootˉsource),
            [Library]);
        True(First.Success, "Read-only directory composition failed: " +
            string.Join(" | ", First.Diagnostics));
        True(Second.Success, "Repeated read-only directory composition failed: " +
            string.Join(" | ", Second.Diagnostics));
        Sequenceˉequal(First.Moduleˉbytes, Second.Moduleˉbytes);

        var Module = Moduleˉcodec.Readˉandˉverify(First.Moduleˉbytes.AsSpan());
        Sequenceˉequal(
            [Capabilityˉcatalog.FILESYSTEM_DIRECTORY_READ_V1],
            Module.Module.Capabilities.Select(Capability => Capability.Name));
        var Directory = new Testˉreadˉonlyˉdirectory();
        var Host = new Referenceˉcapabilityˉhost(new Hostedˉresourceˉcontext(
            [],
            TextWriter.Null,
            TextWriter.Null,
            readˉonlyˉdirectory: Directory));
        var Authorized = new Referenceˉruntime(
            Module,
            Host,
            new(ImmutableHashSet.Create(
                StringComparer.Ordinal,
                Capabilityˉcatalog.FILESYSTEM_DIRECTORY_READ_V1)));
        Equal(29, Authorized.Runˉmain().Exitˉcode);
        Equal(5, Directory.Readˉcount);

        True(
            Readˉonlyˉdirectoryˉcontract.Isˉnameˉvalid(new string('A', 255)),
            "A 255-byte ASCII segment was rejected.");
        True(!Readˉonlyˉdirectoryˉcontract.Isˉnameˉvalid(""), "An empty segment was accepted.");
        True(!Readˉonlyˉdirectoryˉcontract.Isˉnameˉvalid("."), "The current-directory segment was accepted.");
        True(!Readˉonlyˉdirectoryˉcontract.Isˉnameˉvalid(".."), "The parent-directory segment was accepted.");
        True(!Readˉonlyˉdirectoryˉcontract.Isˉnameˉvalid("a/b"), "A slash-bearing segment was accepted.");
        True(!Readˉonlyˉdirectoryˉcontract.Isˉnameˉvalid("a\\b"), "A backslash-bearing segment was accepted.");
        True(!Readˉonlyˉdirectoryˉcontract.Isˉnameˉvalid("a:b"), "A colon-bearing segment was accepted.");
        True(!Readˉonlyˉdirectoryˉcontract.Isˉnameˉvalid("é"), "A non-ASCII segment was accepted.");
        True(
            !Readˉonlyˉdirectoryˉcontract.Isˉnameˉvalid(new string('A', 256)),
            "A 256-byte segment was accepted.");

        var Boundaryˉresponse = Readˉonlyˉdirectoryˉcontract.Read(
            new Boundaryˉreadˉonlyˉdirectory(),
            "Maximum.bin",
            0,
            Readˉonlyˉdirectoryˉcontract.MAX_CHUNK_BYTES);
        Equal(
            Readˉonlyˉdirectoryˉcontract.HEADER_BYTES +
                checked((int)Readˉonlyˉdirectoryˉcontract.MAX_CHUNK_BYTES),
            Boundaryˉresponse.Length);
        Readˉonlyˉdirectoryˉcontract.Verifyˉresponse(
            Boundaryˉresponse.AsSpan(),
            "Maximum.bin",
            0,
            Readˉonlyˉdirectoryˉcontract.MAX_CHUNK_BYTES);
        var Overflowˉresponse = Readˉonlyˉdirectoryˉcontract.Read(
            new Throwingˉreadˉonlyˉdirectory(),
            "Kernel.wvb",
            uint.MaxValue,
            1);
        Readˉonlyˉdirectoryˉcontract.Verifyˉresponse(
            Overflowˉresponse.AsSpan(),
            "Kernel.wvb",
            uint.MaxValue,
            1);

        void Rejectˉresponse(
            ImmutableArray<byte> response,
            string name = "Kernel.wvb",
            uint offset = 0,
            uint maximumˉbytes = 3) =>
            Throwsˉruntime("WVR3030", () =>
                Readˉonlyˉdirectoryˉcontract.Verifyˉresponse(
                    response.AsSpan(), name, offset, maximumˉbytes));

        Rejectˉresponse([0, 1, 2, 3]);
        Rejectˉresponse(new byte[
            Readˉonlyˉdirectoryˉcontract.HEADER_BYTES +
            checked((int)Readˉonlyˉdirectoryˉcontract.MAX_CHUNK_BYTES) + 1]
            .ToImmutableArray());
        Rejectˉresponse(Buildˉdirectoryˉresponse(11, 0, 0, []));
        Rejectˉresponse(Buildˉdirectoryˉresponse(0, 5, 1, [3, 5, 8]));
        Rejectˉresponse(Buildˉdirectoryˉresponse(0, 5, 0, [3]));
        Rejectˉresponse(Buildˉdirectoryˉresponse(1, 0, 0, [3]));
        Rejectˉresponse(Buildˉdirectoryˉresponse(8, 5, 5, []), offset: 5);
        Rejectˉresponse(Buildˉdirectoryˉresponse(9, 0, 0, []));
        Rejectˉresponse(Buildˉdirectoryˉresponse(10, 0, 0, []));
        Rejectˉresponse(
            Buildˉdirectoryˉresponse(0, 5, 0, [3, 5, 8]),
            name: "../Kernel.wvb");
        Throwsˉruntime("WVR3030", () =>
            Readˉonlyˉdirectoryˉcontract.Read(
                new Throwingˉreadˉonlyˉdirectory(),
                "Kernel.wvb",
                0,
                3));

        var Unauthorized = new Referenceˉruntime(
            Module,
            Host,
            Runtimeˉoptions.Portableˉdefaults);
        Throwsˉruntime("WVR3010", () => _ = Unauthorized.Runˉmain());

        var Invalidˉprovider = new Referenceˉruntime(
            Module,
            new Referenceˉcapabilityˉhost(new Hostedˉresourceˉcontext(
                [],
                TextWriter.Null,
                TextWriter.Null,
                readˉonlyˉdirectory: new Invalidˉreadˉonlyˉdirectory())),
            new(ImmutableHashSet.Create(
                StringComparer.Ordinal,
                Capabilityˉcatalog.FILESYSTEM_DIRECTORY_READ_V1)));
        Throwsˉruntime("WVR3030", () => _ = Invalidˉprovider.Runˉmain());

        var Invalidˉhost = new Referenceˉruntime(
            Module,
            new Invalidˉdirectoryˉcapabilityˉhost(),
            new(ImmutableHashSet.Create(
                StringComparer.Ordinal,
                Capabilityˉcatalog.FILESYSTEM_DIRECTORY_READ_V1)));
        Throwsˉruntime("WVR3030", () => _ = Invalidˉhost.Runˉmain());

        const string Directˉinvalidˉsource = """
            module Directˉinvalidˉdirectory profile hosted;
            capability filesystem.directory_read_v1;
            export fn Main() -> i32 {
                let Invalidˉname: bytes = filesystem.directory_read_v1(
                    "../Kernel.wvb", 0u32, 3u32
                );
                if Bytesˉreadˉu32ˉlittle(Invalidˉname, 8u32) != 9u32 { return 1; }
                let Invalidˉlimit: bytes = filesystem.directory_read_v1(
                    "Kernel.wvb", 4294967295u32, 1u32
                );
                if Bytesˉreadˉu32ˉlittle(Invalidˉlimit, 8u32) != 10u32 { return 2; }
                return 29;
            }
            """;
        var Directˉinvalid = Seedˉcompiler.Compile(Directˉinvalidˉsource);
        True(Directˉinvalid.Success, "Direct invalid-request compilation failed: " +
            string.Join(" | ", Directˉinvalid.Diagnostics));
        var Rejectedˉhost = new Rejectingˉdirectoryˉcapabilityˉhost();
        var Directˉruntime = new Referenceˉruntime(
            Moduleˉcodec.Readˉandˉverify(Directˉinvalid.Moduleˉbytes.AsSpan()),
            Rejectedˉhost,
            new(ImmutableHashSet.Create(
                StringComparer.Ordinal,
                Capabilityˉcatalog.FILESYSTEM_DIRECTORY_READ_V1)));
        Equal(29, Directˉruntime.Runˉmain().Exitˉcode);
        Equal(0, Rejectedˉhost.Callˉcount);

        const string Unapprovedˉroot = """
            module Unapprovedˉdirectoryˉapplication profile hosted;
            import Readˉonlyˉdirectory as Directory;
            export fn Main() -> i32 { return 0; }
            """;
        Hasˉdiagnostic(
            Seedˉcompiler.Compileˉmodules(
                new("unapproved-directory-application.wv", Unapprovedˉroot),
                [Library]),
            "WVC0013");

        var Snapshotˉpath = Path.Combine(
            Path.GetTempPath(),
            $"windvale-directory-snapshot-{Guid.NewGuid():N}");
        System.IO.Directory.CreateDirectory(Snapshotˉpath);
        try
        {
            var Kernelˉpath = Path.Combine(Snapshotˉpath, "Kernel.wvb");
            File.WriteAllBytes(Kernelˉpath, [3, 5, 8, 13, 21]);
            System.IO.Directory.CreateDirectory(Path.Combine(Snapshotˉpath, "Nested"));
            File.WriteAllBytes(Path.Combine(Snapshotˉpath, "not queryable.txt"), [1]);

            var Nativeˉsnapshot = new Windvale.Tool.Nativeˉreadˉonlyˉdirectory(Snapshotˉpath);
            File.WriteAllBytes(Kernelˉpath, [99]);

            var Nativeˉread = Nativeˉsnapshot.Readˉbytes("Kernel.wvb", 1, 3);
            Equal(Readˉonlyˉdirectoryˉstatus.Valid, Nativeˉread.Status);
            Equal(5u, Nativeˉread.Fileˉlength);
            Sequenceˉequal<byte>([5, 8, 13], Nativeˉread.Bytes);
            Equal(
                Readˉonlyˉdirectoryˉstatus.Notˉfound,
                Nativeˉsnapshot.Readˉbytes("kernel.wvb", 0, 3).Status);
            Equal(
                Readˉonlyˉdirectoryˉstatus.Notˉfile,
                Nativeˉsnapshot.Readˉbytes("Nested", 0, 3).Status);
            Equal(
                Readˉonlyˉdirectoryˉstatus.Invalidˉoffset,
                Nativeˉsnapshot.Readˉbytes("Kernel.wvb", 6, 3).Status);

            File.WriteAllBytes(Kernelˉpath, [3, 5, 8, 13, 21]);
            var Moduleˉpath = Path.Combine(Snapshotˉpath, "Directory-Application.wvb");
            File.WriteAllBytes(Moduleˉpath, First.Moduleˉbytes.AsSpan());
            var Originalˉoutput = Console.Out;
            var Originalˉerror = Console.Error;
            using var Output = new StringWriter(System.Globalization.CultureInfo.InvariantCulture);
            using var Error = new StringWriter(System.Globalization.CultureInfo.InvariantCulture);
            try
            {
                Console.SetOut(Output);
                Console.SetError(Error);
                Equal(
                    0,
                    Windvale.Tool.Program.Main(
                    [
                        "run",
                        Moduleˉpath,
                        "--allow",
                        Capabilityˉcatalog.FILESYSTEM_DIRECTORY_READ_V1,
                        "--bind-read-only-directory",
                        Snapshotˉpath,
                    ]));
            }
            finally
            {
                Console.SetOut(Originalˉoutput);
                Console.SetError(Originalˉerror);
            }
            Equal("Result: 29\n", Output.ToString().Replace("\r\n", "\n", StringComparison.Ordinal));
            Equal("", Error.ToString());
        }
        finally
        {
            System.IO.Directory.Delete(Snapshotˉpath, recursive: true);
        }
    }

    private static ImmutableArray<byte> Buildˉdirectoryˉresponse(
        uint status,
        uint fileˉlength,
        uint returnedˉoffset,
        ReadOnlySpan<byte> chunk)
    {
        var Response = new byte[Readˉonlyˉdirectoryˉcontract.HEADER_BYTES + chunk.Length];
        BinaryPrimitives.WriteUInt32LittleEndian(
            Response.AsSpan(0),
            Readˉonlyˉdirectoryˉcontract.MAGIC);
        BinaryPrimitives.WriteUInt32LittleEndian(
            Response.AsSpan(4),
            Readˉonlyˉdirectoryˉcontract.VERSION);
        BinaryPrimitives.WriteUInt32LittleEndian(Response.AsSpan(8), status);
        BinaryPrimitives.WriteUInt32LittleEndian(Response.AsSpan(12), fileˉlength);
        BinaryPrimitives.WriteUInt32LittleEndian(Response.AsSpan(16), returnedˉoffset);
        BinaryPrimitives.WriteUInt32LittleEndian(
            Response.AsSpan(20),
            checked((uint)chunk.Length));
        chunk.CopyTo(Response.AsSpan(Readˉonlyˉdirectoryˉcontract.HEADER_BYTES));
        return ImmutableArray.Create(Response);
    }

    private static void Randomˉaccessˉstorageˉisˉtyped()
    {
        const string Rootˉsource = """
            module Randomˉaccessˉstorageˉapplication profile hosted;
            import Randomˉaccessˉstorage as Storage;
            capability storage.random_access_v1;

            export fn Main() -> i32 {
                let Description: Storage.Storageˉresult = Storage.Storageˉdescribe();
                if Description.Status != Storage.Storageˉstatus.Valid { return 1; }
                if Description.Generation == 0u64 { return 2; }
                if Description.Storageˉlength != 5u64 { return 3; }
                let Generation: u64 = Description.Generation;

                let Read: Storage.Storageˉresult = Storage.Storageˉreadˉat(
                    Generation, 1u64, 3u32
                );
                if Read.Status != Storage.Storageˉstatus.Valid { return 4; }
                if Read.Value != Textˉtoˉutf8("bcd") { return 5; }
                if Read.Progress != 3u32 { return 6; }

                let Invalid: Storage.Storageˉresult = Storage.Storageˉreadˉat(
                    Generation, 0u64, 65537u32
                );
                if Invalid.Status != Storage.Storageˉstatus.Invalidˉrequest { return 7; }

                let Stale: Storage.Storageˉresult = Storage.Storageˉreadˉat(
                    Generation + 1u64, 0u64, 1u32
                );
                if Stale.Status != Storage.Storageˉstatus.Stale { return 8; }
                if Stale.Generation != Generation { return 9; }

                let Write: Storage.Storageˉresult = Storage.Storageˉwriteˉat(
                    Generation, 2u64, Textˉtoˉutf8("XY")
                );
                if Write.Status != Storage.Storageˉstatus.Valid { return 10; }
                if Write.Completion != Storage.Storageˉcompletion.Completed { return 11; }
                if Write.Progress != 2u32 || Write.Storageˉlength != 5u64 { return 12; }

                let Full: Storage.Storageˉresult = Storage.Storageˉreadˉat(
                    Generation, 0u64, 5u32
                );
                if Full.Value != Textˉtoˉutf8("abXYe") { return 13; }

                let Resize: Storage.Storageˉresult = Storage.Storageˉresize(
                    Generation, 4u64
                );
                if Resize.Completion != Storage.Storageˉcompletion.Completed { return 14; }
                if Resize.Storageˉlength != 4u64 { return 15; }

                let Flush: Storage.Storageˉresult = Storage.Storageˉflush(
                    Generation, Storage.Storageˉflush.Contentˉandˉlength
                );
                if Flush.Completion != Storage.Storageˉcompletion.Completed { return 16; }
                if Flush.Storageˉlength != 4u64 { return 17; }

                let Past: Storage.Storageˉresult = Storage.Storageˉreadˉat(
                    Generation, 5u64, 1u32
                );
                if Past.Status != Storage.Storageˉstatus.Outsideˉstorage { return 18; }
                if Past.Storageˉlength != 4u64 { return 19; }
                return 29;
            }
            """;
        Sourceˉmoduleˉinput Library = new(
            "Libraries/Platform/Storage/Random-Access-Storage.wv",
            RANDOM_ACCESS_STORAGE_SOURCE);
        var First = Seedˉcompiler.Compileˉmodules(
            new("random-access-storage-application.wv", Rootˉsource),
            [Library]);
        var Second = Seedˉcompiler.Compileˉmodules(
            new("random-access-storage-application.wv", Rootˉsource),
            [Library]);
        True(First.Success, "Random-access storage composition failed: " +
            string.Join(" | ", First.Diagnostics));
        True(Second.Success, "Repeated random-access storage composition failed: " +
            string.Join(" | ", Second.Diagnostics));
        Sequenceˉequal(First.Moduleˉbytes, Second.Moduleˉbytes);

        var Module = Moduleˉcodec.Readˉandˉverify(First.Moduleˉbytes.AsSpan());
        Sequenceˉequal(
            [Capabilityˉcatalog.STORAGE_RANDOM_ACCESS_V1],
            Module.Module.Capabilities.Select(Capability => Capability.Name));
        var Storage = new Testˉrandomˉaccessˉstorage("abcde"u8.ToImmutableArray());
        var Host = new Referenceˉcapabilityˉhost(new Hostedˉresourceˉcontext(
            [],
            TextWriter.Null,
            TextWriter.Null,
            randomˉaccessˉstorage: Storage));
        var Authorized = new Referenceˉruntime(
            Module,
            Host,
            new(ImmutableHashSet.Create(
                StringComparer.Ordinal,
                Capabilityˉcatalog.STORAGE_RANDOM_ACCESS_V1)));
        Equal(29, Authorized.Runˉmain().Exitˉcode);
        Equal(1, Storage.Describeˉcount);
        Equal(4, Storage.Readˉcount);
        Equal(1, Storage.Writeˉcount);
        Equal(1, Storage.Resizeˉcount);
        Equal(1, Storage.Flushˉcount);
        Sequenceˉequal<byte>("abXY"u8.ToArray(), Storage.Bytes);

        var Unauthorized = new Referenceˉruntime(
            Module,
            Host,
            Runtimeˉoptions.Portableˉdefaults);
        Throwsˉruntime("WVR3010", () => _ = Unauthorized.Runˉmain());

        var Unsupported = new Referenceˉruntime(
            Module,
            new Referenceˉcapabilityˉhost(new Hostedˉresourceˉcontext(
                [], TextWriter.Null, TextWriter.Null)),
            new(ImmutableHashSet.Create(
                StringComparer.Ordinal,
                Capabilityˉcatalog.STORAGE_RANDOM_ACCESS_V1)));
        Throwsˉruntime("WVR3001", () => _ = Unsupported.Runˉmain());

        var Rejecting = new Rejectingˉrandomˉaccessˉstorage();
        var Rejection = Randomˉaccessˉstorageˉcontract.Invoke(
            Rejecting,
            uint.MaxValue,
            0,
            0,
            0,
            []);
        Equal(0, Rejecting.Callˉcount);
        Equal(
            (uint)Randomˉaccessˉstorageˉstatus.Invalidˉrequest,
            BinaryPrimitives.ReadUInt32LittleEndian(Rejection.AsSpan()[12..]));
        _ = Randomˉaccessˉstorageˉcontract.Invoke(
            Rejecting,
            (uint)Randomˉaccessˉstorageˉoperation.Write,
            1,
            ulong.MaxValue,
            0,
            [1]);
        _ = Randomˉaccessˉstorageˉcontract.Invoke(
            Rejecting,
            (uint)Randomˉaccessˉstorageˉoperation.Read,
            1,
            0,
            1,
            [1]);
        Equal(0, Rejecting.Callˉcount);

        Throwsˉruntime("WVR3031", () =>
            Randomˉaccessˉstorageˉcontract.Invoke(
                new Invalidˉrandomˉaccessˉstorage(),
                (uint)Randomˉaccessˉstorageˉoperation.Describe,
                0,
                0,
                0,
                []));
        Throwsˉruntime("WVR3031", () =>
            Randomˉaccessˉstorageˉcontract.Invoke(
                new Invalidˉrandomˉaccessˉstorage(),
                (uint)Randomˉaccessˉstorageˉoperation.Read,
                1,
                0,
                1,
                []));
        var Description = Randomˉaccessˉstorageˉcontract.Invoke(
            Storage,
            (uint)Randomˉaccessˉstorageˉoperation.Describe,
            0,
            0,
            0,
            []);
        void Rejectˉresponse(byte[] response) =>
            Throwsˉruntime("WVR3031", () =>
            Randomˉaccessˉstorageˉcontract.Verifyˉresponse(
                response,
                (uint)Randomˉaccessˉstorageˉoperation.Describe,
                0,
                0,
                0,
                0));
        Rejectˉresponse([0, 1, 2, 3]);
        Rejectˉresponse(new byte[
            Randomˉaccessˉstorageˉcontract.HEADER_BYTES +
            checked((int)Randomˉaccessˉstorageˉcontract.MAX_TRANSFER_BYTES) + 1]);
        var Corruptˉresponse = Description.ToArray();
        Corruptˉresponse[0] ^= 0xFF;
        Rejectˉresponse(Corruptˉresponse);
        Corruptˉresponse = Description.ToArray();
        BinaryPrimitives.WriteUInt32LittleEndian(Corruptˉresponse.AsSpan(12), 9);
        Rejectˉresponse(Corruptˉresponse);
        Corruptˉresponse = Description.ToArray();
        BinaryPrimitives.WriteUInt64LittleEndian(Corruptˉresponse.AsSpan(32), ulong.MaxValue);
        Rejectˉresponse(Corruptˉresponse);
        Corruptˉresponse = Description.ToArray();
        BinaryPrimitives.WriteUInt32LittleEndian(Corruptˉresponse.AsSpan(44), 4);
        Rejectˉresponse(Corruptˉresponse);

        var Boundaryˉstorage = new Testˉrandomˉaccessˉstorage(
            new byte[checked((int)Randomˉaccessˉstorageˉcontract.MAX_TRANSFER_BYTES)]
                .ToImmutableArray());
        var Boundaryˉresponse = Randomˉaccessˉstorageˉcontract.Invoke(
            Boundaryˉstorage,
            (uint)Randomˉaccessˉstorageˉoperation.Read,
            Testˉrandomˉaccessˉstorage.GENERATION,
            0,
            Randomˉaccessˉstorageˉcontract.MAX_TRANSFER_BYTES,
            []);
        Equal(
            Randomˉaccessˉstorageˉcontract.HEADER_BYTES +
                checked((int)Randomˉaccessˉstorageˉcontract.MAX_TRANSFER_BYTES),
            Boundaryˉresponse.Length);

        var Partial = Randomˉaccessˉstorageˉcontract.Invoke(
            new Writeˉoutcomeˉrandomˉaccessˉstorage(
                Randomˉaccessˉstorageˉcompletion.Partial,
                2,
                12),
            (uint)Randomˉaccessˉstorageˉoperation.Write,
            Writeˉoutcomeˉrandomˉaccessˉstorage.GENERATION,
            10,
            0,
            [1, 2, 3]);
        Equal(
            (uint)Randomˉaccessˉstorageˉcompletion.Partial,
            BinaryPrimitives.ReadUInt32LittleEndian(Partial.AsSpan()[44..]));
        var Indeterminate = Randomˉaccessˉstorageˉcontract.Invoke(
            new Writeˉoutcomeˉrandomˉaccessˉstorage(
                Randomˉaccessˉstorageˉcompletion.Indeterminate,
                0,
                0),
            (uint)Randomˉaccessˉstorageˉoperation.Write,
            Writeˉoutcomeˉrandomˉaccessˉstorage.GENERATION,
            10,
            0,
            [1, 2, 3]);
        Equal(
            (uint)Randomˉaccessˉstorageˉcompletion.Indeterminate,
            BinaryPrimitives.ReadUInt32LittleEndian(Indeterminate.AsSpan()[44..]));
        Throwsˉruntime("WVR3031", () =>
            Randomˉaccessˉstorageˉcontract.Invoke(
                new Writeˉoutcomeˉrandomˉaccessˉstorage(
                    Randomˉaccessˉstorageˉcompletion.Partial,
                    3,
                    13),
                (uint)Randomˉaccessˉstorageˉoperation.Write,
                Writeˉoutcomeˉrandomˉaccessˉstorage.GENERATION,
                10,
                0,
                [1, 2, 3]));

        Storage.Isˉrevoked = true;
        var Revoked = Randomˉaccessˉstorageˉcontract.Invoke(
            Storage,
            (uint)Randomˉaccessˉstorageˉoperation.Read,
            Testˉrandomˉaccessˉstorage.GENERATION,
            0,
            1,
            []);
        Equal(
            (uint)Randomˉaccessˉstorageˉstatus.Revoked,
            BinaryPrimitives.ReadUInt32LittleEndian(Revoked.AsSpan()[12..]));

        var Nativeˉdirectory = Path.Combine(
            Path.GetTempPath(),
            $"windvale-random-storage-{Guid.NewGuid():N}");
        System.IO.Directory.CreateDirectory(Nativeˉdirectory);
        try
        {
            var Moduleˉpath = Path.Combine(Nativeˉdirectory, "Storage-Application.wvb");
            var Storageˉpath = Path.Combine(Nativeˉdirectory, "Database.wvdb");
            File.WriteAllBytes(Moduleˉpath, First.Moduleˉbytes.AsSpan());
            File.WriteAllBytes(Storageˉpath, "abcde"u8);
            var Originalˉoutput = Console.Out;
            var Originalˉerror = Console.Error;
            using var Output = new StringWriter(System.Globalization.CultureInfo.InvariantCulture);
            using var Error = new StringWriter(System.Globalization.CultureInfo.InvariantCulture);
            try
            {
                Console.SetOut(Output);
                Console.SetError(Error);
                Equal(
                    0,
                    Windvale.Tool.Program.Main(
                    [
                        "run",
                        Moduleˉpath,
                        "--allow",
                        Capabilityˉcatalog.STORAGE_RANDOM_ACCESS_V1,
                        "--bind-random-access-storage",
                        Storageˉpath,
                    ]));
            }
            finally
            {
                Console.SetOut(Originalˉoutput);
                Console.SetError(Originalˉerror);
            }
            Equal("Result: 29\n", Output.ToString().Replace("\r\n", "\n", StringComparison.Ordinal));
            Equal("", Error.ToString());
            Sequenceˉequal<byte>("abXY"u8.ToArray(), File.ReadAllBytes(Storageˉpath));
            File.WriteAllBytes(Storageˉpath, "lease-released"u8);
        }
        finally
        {
            System.IO.Directory.Delete(Nativeˉdirectory, recursive: true);
        }
    }

    private static ImmutableArray<byte> Buildˉresourceˉstoreˉfixture()
    {
        var Name = Encoding.UTF8.GetBytes("entry");
        byte[] Data = [3, 5, 8, 13];
        const int HEADER_BYTES = 32;
        const int ENTRY_BYTES = 96;
        var Dataˉoffset = HEADER_BYTES + ENTRY_BYTES + Name.Length;
        var Store = new byte[Dataˉoffset + Data.Length];
        BinaryPrimitives.WriteUInt32LittleEndian(Store.AsSpan(0), 0x5352_5657);
        BinaryPrimitives.WriteUInt32LittleEndian(Store.AsSpan(4), 1);
        BinaryPrimitives.WriteUInt32LittleEndian(Store.AsSpan(8), checked((uint)Store.Length));
        BinaryPrimitives.WriteUInt32LittleEndian(Store.AsSpan(12), 1);
        BinaryPrimitives.WriteUInt32LittleEndian(Store.AsSpan(16), ENTRY_BYTES);
        BinaryPrimitives.WriteUInt32LittleEndian(Store.AsSpan(20), checked((uint)Name.Length));
        BinaryPrimitives.WriteUInt32LittleEndian(Store.AsSpan(24), checked((uint)Data.Length));
        BinaryPrimitives.WriteUInt32LittleEndian(Store.AsSpan(HEADER_BYTES), 1);
        BinaryPrimitives.WriteUInt32LittleEndian(Store.AsSpan(HEADER_BYTES + 4), 3);
        BinaryPrimitives.WriteUInt32LittleEndian(Store.AsSpan(HEADER_BYTES + 8), 7);
        BinaryPrimitives.WriteUInt32LittleEndian(Store.AsSpan(HEADER_BYTES + 12), HEADER_BYTES + ENTRY_BYTES);
        BinaryPrimitives.WriteUInt32LittleEndian(Store.AsSpan(HEADER_BYTES + 16), checked((uint)Name.Length));
        BinaryPrimitives.WriteUInt32LittleEndian(Store.AsSpan(HEADER_BYTES + 20), checked((uint)Dataˉoffset));
        BinaryPrimitives.WriteUInt32LittleEndian(Store.AsSpan(HEADER_BYTES + 24), checked((uint)Data.Length));
        Encoding.ASCII.GetBytes(Convert.ToHexString(SHA256.HashData(Data)).ToLowerInvariant())
            .CopyTo(Store, HEADER_BYTES + 32);
        Name.CopyTo(Store, HEADER_BYTES + ENTRY_BYTES);
        Data.CopyTo(Store, Dataˉoffset);
        return Store.ToImmutableArray();
    }

    private static void Projectsˉselectˉsourceˉsets()
    {
        const string Valid = """
            windvale-project 1
            root "Source/Main.wv"
            source "Source/Leaf.wv"
            source "Source/Middle.wv"
            emit wvb
            """;
        var Parsed = Projectˉparser.Parse(Valid);
        True(Parsed.Success, "The valid project manifest was rejected.");
        Equal("Source/Main.wv", Parsed.Manifest!.Root.Value);
        Sequenceˉequal(
            ["Source/Leaf.wv", "Source/Middle.wv"],
            Parsed.Manifest.Sources.Select(Source => Source.Value));
        Equal(Projectˉemissionˉkind.Wvb, Parsed.Manifest.Emission);

        Projectˉhasˉdiagnostic(string.Empty, "WVP1001");
        Projectˉhasˉdiagnostic("windvale-project 2\nroot \"Main.wv\"\nemit wvb\n", "WVP1001");
        Projectˉhasˉdiagnostic("\uFEFFwindvale-project 1\nroot \"Main.wv\"\nemit wvb\n", "WVP1001");
        Projectˉhasˉdiagnostic("windvale-project 1\n \nroot \"Main.wv\"\nemit wvb\n", "WVP1003");
        Projectˉhasˉdiagnostic("windvale-project 1\r", "WVP1003");
        Projectˉhasˉdiagnostic("windvale-project 1\n# comment\nroot \"Main.wv\"\nemit wvb\n", "WVP1003");
        Projectˉhasˉdiagnostic("windvale-project 1\nroot Main.wv\nemit wvb\n", "WVP1003");
        Projectˉhasˉdiagnostic(
            "windvale-project 1\nroot \"Main.wv\"\nroot \"Other.wv\"\nemit wvb\n",
            "WVP1004");
        Projectˉhasˉdiagnostic(
            "windvale-project 1\nroot \"Main.wv\"\nemit wvb\nemit wvb\n",
            "WVP1004");
        Projectˉhasˉdiagnostic("windvale-project 1\nemit wvb\n", "WVP1004");
        Projectˉhasˉdiagnostic("windvale-project 1\nroot \"Main.wv\"\n", "WVP1004");

        foreach (var Invalidˉpath in new[]
        {
            string.Empty,
            "/Main.wv",
            "../Main.wv",
            "Source/../Main.wv",
            "Source\\Main.wv",
            "C:/Main.wv",
            "Source//Main.wv",
            "Source/./Main.wv",
            "Source/Main.WV",
            "Source/Main File.wv",
            "Source/Maïn.wv",
            "Source/Main?.wv",
        })
        {
            Projectˉhasˉdiagnostic(
                $"windvale-project 1\nroot \"{Invalidˉpath}\"\nemit wvb\n",
                "WVP1006");
        }
        Projectˉhasˉdiagnostic(
            $"windvale-project 1\nroot \"{new string('a', Projectˉlimits.MAX_PATH_BYTES)}.wv\"\nemit wvb\n",
            "WVP1006");
        Projectˉhasˉdiagnostic(
            "windvale-project 1\nroot \"Main.wv\"\nemit wvb\n" +
            new string('\n', Projectˉlimits.MAX_MANIFEST_BYTES),
            "WVP1002");
        Projectˉhasˉdiagnostic(
            "windvale-project 1\nroot \"Main.wv\"\nemit wvb\n\uD800",
            "WVP1002");

        var Maximum = new StringBuilder("windvale-project 1\nroot \"Root.wv\"\n");
        for (var Index = 0; Index < Projectˉlimits.MAX_SOURCE_MODULES - 1; Index++)
        {
            Maximum.AppendLine($"source \"Source/Module-{Index}.wv\"");
        }
        Maximum.AppendLine("emit wvb");
        True(Projectˉparser.Parse(Maximum.ToString()).Success, "The exact project module bound was rejected.");
        Maximum.Insert(Maximum.ToString().LastIndexOf("emit wvb", StringComparison.Ordinal),
            "source \"Source/Excess.wv\"\n");
        Projectˉhasˉdiagnostic(Maximum.ToString(), "WVP1005");

        var Temporaryˉdirectory = Path.Combine(
            Path.GetTempPath(),
            $"windvale-project-test-{Guid.NewGuid():N}");
        Directory.CreateDirectory(Temporaryˉdirectory);
        try
        {
            var Projectˉpath = Path.Combine(Temporaryˉdirectory, "Example.wvproj");
            File.WriteAllText(
                Projectˉpath,
                "windvale-project 1\nroot \"Source/Main.wv\"\nsource \"Source/Leaf.wv\"\nemit wvb\n",
                new UTF8Encoding(false, true));
            var Read = Projectˉreader.Read(Projectˉpath);
            True(Read.Success, "The valid project file was not resolved.");
            Equal(
                Path.GetFullPath(Path.Combine(Temporaryˉdirectory, "Source", "Main.wv")),
                Read.Plan!.Rootˉpath);
            Sequenceˉequal(
                [Path.GetFullPath(Path.Combine(Temporaryˉdirectory, "Source", "Leaf.wv"))],
                Read.Plan.Sourceˉpaths);

            File.WriteAllText(
                Projectˉpath,
                "windvale-project 1\nroot \"Source/Main.wv\"\nsource \"Source/Main.wv\"\nemit wvb\n",
                new UTF8Encoding(false, true));
            var Duplicate = Projectˉreader.Read(Projectˉpath);
            False(Duplicate.Success, "The project reader accepted a duplicate resolved source path.");
            Equal("WVP1007", Duplicate.Diagnostics.Single().Code);

            File.WriteAllBytes(Projectˉpath, [0xFF]);
            var Invalidˉutf8 = Projectˉreader.Read(Projectˉpath);
            False(Invalidˉutf8.Success, "The project reader accepted malformed UTF-8.");
            Equal("WVP1002", Invalidˉutf8.Diagnostics.Single().Code);
        }
        finally
        {
            Directory.Delete(Temporaryˉdirectory, recursive: true);
        }
    }

    private static void Windvaleˉprojectˉmanifestsˉagree()
    {
        var Coreˉresult = Seedˉcompiler.Compile(
            PROJECT_MANIFEST_CORE_SOURCE,
            "Tools/Windvale.Project/Project-Manifest-Core.wv");
        True(
            Coreˉresult.Success,
            "The Windvale project core did not compile: " +
                string.Join(" | ", Coreˉresult.Diagnostics));
        var Core = Moduleˉcodec.Readˉandˉverify(Coreˉresult.Moduleˉbytes.AsSpan());
        Equal(
            PROJECT_MANIFEST_CORE_SHA256,
            Moduleˉdigest.Calculateˉsha256(Coreˉresult.Moduleˉbytes.AsSpan()));
        Equal("Windvaleˉproject", Core.Module.Name);
        Equal(Moduleˉprofile.Portable, Core.Module.Profile);
        Equal(0, Core.Module.Capabilities.Length);
        True(
            Core.Module.Exports.Any(Export => Export.Name == "Windvaleˉprojectˉscanˉmanifest"),
            "The Windvale project core did not export its manifest scanner.");
        True(
            Core.Module.Exports.Any(Export => Export.Name == "Windvaleˉprojectˉpathˉat"),
            "The Windvale project core did not export its path view.");

        var Toolˉresult = Seedˉcompiler.Compileˉmodules(
            new(
                "Tools/Windvale.Project/Project-Manifest-Tool.wv",
                PROJECT_MANIFEST_TOOL_SOURCE),
            [
                new(
                    "Tools/Windvale.Project/Project-Manifest-Core.wv",
                    PROJECT_MANIFEST_CORE_SOURCE),
            ]);
        True(
            Toolˉresult.Success,
            "The Windvale project tool did not compile: " +
                string.Join(" | ", Toolˉresult.Diagnostics));
        var Tool = Moduleˉcodec.Readˉandˉverify(Toolˉresult.Moduleˉbytes.AsSpan());
        Equal(
            PROJECT_MANIFEST_TOOL_SHA256,
            Moduleˉdigest.Calculateˉsha256(Toolˉresult.Moduleˉbytes.AsSpan()));
        Equal("Windvaleˉprojectˉtool", Tool.Module.Name);
        Equal(Moduleˉprofile.Hosted, Tool.Module.Profile);

        Projectˉparserˉagreesˉwithˉtool(
            Tool,
            "windvale-project 1\n" +
            "root \"Source/Main.wv\"\n" +
            "source \"Source/Leaf.wv\"\n" +
            "source \"Source/Middle.wv\"\n" +
            "emit wvb\n");
        Projectˉparserˉagreesˉwithˉtool(
            Tool,
            "windvale-project 1\r\n" +
            "emit wvb\r\n" +
            "source \"Source/Leaf.wv\"\r\n" +
            "root \"Source/Main.wv\"\r\n");

        foreach (var Invalid in new[]
        {
            string.Empty,
            "windvale-project 2\nroot \"Main.wv\"\nemit wvb\n",
            "\uFEFFwindvale-project 1\nroot \"Main.wv\"\nemit wvb\n",
            "windvale-project 1\n \nroot \"Main.wv\"\nemit wvb\n",
            "windvale-project 1\r",
            "windvale-project 1\nroot Main.wv\nemit wvb\n",
            "windvale-project 1\nroot \"Main.wv\"\nroot \"Other.wv\"\nemit wvb\n",
            "windvale-project 1\nroot \"Main.wv\"\nemit wvb\nemit wvb\n",
            "windvale-project 1\nemit wvb\n",
            "windvale-project 1\nroot \"Main.wv\"\n",
            "windvale-project 1\nroot \"../Main.wv\"\nemit wvb\n",
            "windvale-project 1\nroot \"Source/Main.WV\"\nemit wvb\n",
            "windvale-project 1\nroot \"Source/Maïn.wv\"\nemit wvb\n",
            "windvale-project 1\nroot \"Main.wv\"\nemit wvb\n" +
                new string('\n', Projectˉlimits.MAX_MANIFEST_BYTES),
        })
        {
            Projectˉparserˉagreesˉwithˉtool(Tool, Invalid);
        }

        var Maximum = new StringBuilder("windvale-project 1\nroot \"Root.wv\"\n");
        for (var Index = 0; Index < Projectˉlimits.MAX_SOURCE_MODULES - 1; Index++)
        {
            Maximum.AppendLine($"source \"Source/Module-{Index}.wv\"");
        }
        Maximum.AppendLine("emit wvb");
        Projectˉparserˉagreesˉwithˉtool(Tool, Maximum.ToString());
        Maximum.Insert(
            Maximum.ToString().LastIndexOf("emit wvb", StringComparison.Ordinal),
            "source \"Source/Excess.wv\"\n");
        Projectˉparserˉagreesˉwithˉtool(Tool, Maximum.ToString());

        var Invalidˉutf8 = Runˉprojectˉmanifestˉtool(Tool, [0xFF]);
        Equal(1, Invalidˉutf8.Exitˉcode);
        Equal(string.Empty, Invalidˉutf8.Output);
        Equal("project status=WVP1002 line=1 column=1\n", Invalidˉutf8.Diagnostics);
        Equal(1, Invalidˉutf8.Readˉcount);
    }

    private static void Nativeˉprojectˉmanifestsˉagree()
    {
        var Toolˉresult = Seedˉcompiler.Compileˉmodules(
            new(
                "Tools/Windvale.Project/Project-Manifest-Tool.wv",
                PROJECT_MANIFEST_TOOL_SOURCE),
            [
                new(
                    "Tools/Windvale.Project/Project-Manifest-Core.wv",
                    PROJECT_MANIFEST_CORE_SOURCE),
            ]);
        True(
            Toolˉresult.Success,
            "The Windvale project tool did not compile for native execution: " +
                string.Join(" | ", Toolˉresult.Diagnostics));
        var Tool = Moduleˉcodec.Readˉandˉverify(Toolˉresult.Moduleˉbytes.AsSpan());
        var Authorized = Tool.Module.Capabilities
            .Select(Capability => Capability.Name)
            .ToImmutableHashSet(StringComparer.Ordinal);

        var First = X64ˉnativeˉbackend.Compile(Tool);
        var Second = X64ˉnativeˉbackend.Compile(Tool);
        Sequenceˉequal(First.Fragment.Code, Second.Fragment.Code);
        Sequenceˉequal(First.Fragment.Symbols, Second.Fragment.Symbols);
        Sequenceˉequal(First.Fragment.Patches, Second.Fragment.Patches);
        Sequenceˉequal(First.Fragment.Types, Second.Fragment.Types);
        Sequenceˉequal(
            [
                Nativeˉservice.Consoleˉwriteˉline,
                Nativeˉservice.Processˉargumentˉcount,
                Nativeˉservice.Processˉargument,
                Nativeˉservice.Fileˉreadˉbytes,
                Nativeˉservice.Textˉutf8ˉisˉvalid,
                Nativeˉservice.Diagnosticˉwriteˉline,
                Nativeˉservice.Textˉconcat,
                Nativeˉservice.Textˉquote,
                Nativeˉservice.U32ˉformat,
            ],
            First.Fragment.Requiredˉservices);
        var Operations = First.Module.Functions
            .SelectMany(Function => Function.Blocks)
            .SelectMany(Block => Block.Operations)
            .ToImmutableArray();
        True(Operations.Any(Operation => Operation is Nativeˉbytesˉconcat),
            "The native project tool omitted immutable byte concatenation.");
        True(Operations.Any(Operation => Operation is Nativeˉbytesˉfromˉu32ˉlittle),
            "The native project tool omitted little-endian directory construction.");
        True(Operations.Any(Operation => Operation is Nativeˉtextˉtoˉutf8),
            "The native project tool omitted borrowed text encoding.");
        True(
            Tool.Module.Types
                .OfType<Recordˉtypeˉdeclaration>()
                .Any(Record => Record.Fields.Any(Field => Field.Type.Kind == Valueˉtype.Bytes)),
            "The native project tool omitted its borrowed-byte record boundary.");
        _ = Nativeˉfragmentˉverifier.Verify(First.Fragment);
        Equal(
            PROJECT_MANIFEST_NATIVE_CODE_SHA256,
            Objectˉdigest.Calculateˉsha256(First.Fragment.Code.AsSpan()));

        var Corruptedˉrecordˉtag = First.Fragment.Code.ToArray();
        var Recordˉtag = Enumerable
            .Range(0, Corruptedˉrecordˉtag.Length - 22)
            .Where(Index =>
                Corruptedˉrecordˉtag[Index] == 0x41 &&
                Corruptedˉrecordˉtag[Index + 1] == 0xB8 &&
                Corruptedˉrecordˉtag[Index + 6] == 0x48 &&
                Corruptedˉrecordˉtag[Index + 7] == 0x8B &&
                Corruptedˉrecordˉtag[Index + 8] == 0x84 &&
                Corruptedˉrecordˉtag[Index + 9] == 0x24 &&
                Corruptedˉrecordˉtag[Index + 14] == 0x48 &&
                Corruptedˉrecordˉtag[Index + 15] == 0x89 &&
                Corruptedˉrecordˉtag[Index + 16] == 0x84 &&
                Corruptedˉrecordˉtag[Index + 17] == 0x24)
            .DefaultIfEmpty(-1)
            .First();
        True(Recordˉtag >= 0, "The native project tool omitted typed frame-record movement.");
        BinaryPrimitives.WriteInt32LittleEndian(
            Corruptedˉrecordˉtag.AsSpan(Recordˉtag + 2, sizeof(int)),
            int.MaxValue);
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉrecordˉtag.ToImmutableArray() }));

        var Corruptedˉbyteˉlimit = First.Fragment.Code.ToArray();
        var Byteˉlimit = Corruptedˉbyteˉlimit.AsSpan().IndexOf(new byte[]
        {
            0x3D, 0x00, 0x00, 0x40, 0x00, 0x0F, 0x87,
        });
        True(Byteˉlimit >= 0, "The native project tool omitted the 4 MiB byte-value bound.");
        Corruptedˉbyteˉlimit[Byteˉlimit + 1] ^= 0x01;
        Throwsˉnative(
            "WVN3030",
            () => _ = Nativeˉfragmentˉverifier.Verify(
                First.Fragment with { Code = Corruptedˉbyteˉlimit.ToImmutableArray() }));

        var Firstˉobject = Nativeˉobjectˉsink.Writeˉwvo(First.Fragment);
        var Secondˉobject = Nativeˉobjectˉsink.Writeˉwvo(Second.Fragment);
        Sequenceˉequal(Firstˉobject, Secondˉobject);
        Equal(
            PROJECT_MANIFEST_NATIVE_WVO_SHA256,
            Objectˉdigest.Calculateˉsha256(Firstˉobject.AsSpan()));
        var Firstˉlinked = Linkˉsuccess(
            [Firstˉobject.ToArray()],
            new(Linkˉcontract.DEFAULT_BASE_ADDRESS, "Main"));
        var Secondˉlinked = Linkˉsuccess(
            [Secondˉobject.ToArray()],
            new(Linkˉcontract.DEFAULT_BASE_ADDRESS, "Main"));
        Sequenceˉequal(Firstˉlinked.Imageˉbytes, Secondˉlinked.Imageˉbytes);
        Sequenceˉequal(Firstˉlinked.Mapˉbytes, Secondˉlinked.Mapˉbytes);
        Sequenceˉequal(First.Fragment.Code, Firstˉlinked.Imageˉbytes);

        void Runˉcase(string manifest)
        {
            var Manifestˉbytes = Encoding.UTF8.GetBytes(manifest).ToImmutableArray();
            var Reference = Runˉprojectˉmanifestˉtool(Tool, Manifestˉbytes);
            Equal(1, Reference.Readˉcount);
            var Nativeˉpath = Path.Combine(
                Path.GetTempPath(),
                $"windvale-native-project-{Guid.NewGuid():N}.wvproj");

            void Runˉnative(ImmutableArray<byte> code)
            {
                using var Output = new Nativeˉoutputˉcapture();
                using var Diagnostic = new Nativeˉoutputˉcapture();
                var Reader = new Testˉfileˉreader((_, _) =>
                    throw new InvalidOperationException(
                        "Native project execution called the Stage 0 file reader."));
                var Resources = new Hostedˉresourceˉcontext(
                    [Nativeˉpath],
                    TextWriter.Null,
                    TextWriter.Null,
                    Reader);
                Equal(
                    Reference.Exitˉcode,
                    X64ˉnativeˉexecutor.Executeˉi32(
                        First.Fragment with { Code = code },
                        maximumˉinstructions: Reference.Executedˉinstructions,
                        hostˉservices: new(
                            Output.Channel,
                            Authorized,
                            Resources,
                            Diagnostic.Channel,
                            Nativeˉfileˉinput.Hostˉfileˉsystem())));
                Equal(Reference.Output, Output.Readˉtext());
                Equal(Reference.Diagnostics, Diagnostic.Readˉtext());
                Equal(0, Reader.Readˉcount);
            }

            try
            {
                File.WriteAllBytes(Nativeˉpath, Manifestˉbytes.AsSpan());
                Runˉnative(First.Fragment.Code);
                Runˉnative(Firstˉlinked.Imageˉbytes);
            }
            finally
            {
                File.Delete(Nativeˉpath);
            }
        }

        Runˉcase(
            "windvale-project 1\n" +
            "root \"Source/Main.wv\"\n" +
            "source \"Source/Leaf.wv\"\n" +
            "emit wvb\n");
        Runˉcase(
            "windvale-project 1\n" +
            " \n" +
            "root \"Source/Main.wv\"\n" +
            "emit wvb\n");

        var Limitˉverified = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess("""
            module Nativeˉprojectˉbyteˉlimit profile hosted;
            capability file.read_bytes;
            capability process.argument;
            export fn Main() -> i32 {
                let Input: bytes = file.read_bytes(process.argument(0u32));
                let Combined: bytes = Bytesˉconcat(Input, Input);
                return 0;
            }
            """));
        var Limitˉinput = new byte[Bytecodeˉlimits.MAX_BYTE_DATA_BYTES / 2 + 1]
            .ToImmutableArray();
        var Limitˉreader = new Testˉfileˉreader((Name, Maximum) =>
        {
            Equal("input.bin", Name);
            True(Limitˉinput.Length <= Maximum, "The byte-limit fixture exceeded the hosted bound.");
            return Limitˉinput;
        });
        var Limitˉauthorized = ImmutableHashSet.Create(
            StringComparer.Ordinal,
            Capabilityˉcatalog.FILE_READ_BYTES,
            Capabilityˉcatalog.PROCESS_ARGUMENT);
        Throwsˉruntime(
            "WVR3015",
            () => _ = new Referenceˉruntime(
                Limitˉverified,
                new Referenceˉcapabilityˉhost(new Hostedˉresourceˉcontext(
                    ["input.bin"],
                    TextWriter.Null,
                    TextWriter.Null,
                    Limitˉreader)),
                new(Limitˉauthorized)).Runˉmain());
        Equal(1, Limitˉreader.Readˉcount);

        var Limitˉnative = X64ˉnativeˉbackend.Compile(Limitˉverified);
        var Limitˉpath = Path.Combine(
            Path.GetTempPath(),
            $"windvale-native-project-limit-{Guid.NewGuid():N}.bin");
        try
        {
            File.WriteAllBytes(Limitˉpath, Limitˉinput.AsSpan());
            var Reader = new Testˉfileˉreader((_, _) =>
                throw new InvalidOperationException(
                    "Native byte-limit execution called the Stage 0 file reader."));
            Throwsˉnativeˉtrap(
                "WVR3015",
                () => _ = X64ˉnativeˉexecutor.Executeˉi32(
                    Limitˉnative.Fragment,
                    hostˉservices: new(
                        null,
                        Limitˉauthorized,
                        new Hostedˉresourceˉcontext(
                            [Limitˉpath],
                            TextWriter.Null,
                            TextWriter.Null,
                            Reader),
                        fileˉinput: Nativeˉfileˉinput.Hostˉfileˉsystem())));
            Equal(0, Reader.Readˉcount);
        }
        finally
        {
            File.Delete(Limitˉpath);
        }
    }

