                    Maximumˉinstructions: 4_000_000_000)).Runˉmain().Exitˉcode);

        var Memoryˉadapterˉbytes = Compileˉwithˉsourceˉwvbˉsuccess(
            SOURCE_WVB_MEMORY_ADAPTER_SOURCE,
            "Source-Wvb-Memory-Adapter.wv");
        Equal(919_577, Memoryˉadapterˉbytes.Length);
        Equal(
            SOURCE_WVB_MEMORY_ADAPTER_SHA256,
            Moduleˉdigest.Calculateˉsha256(Memoryˉadapterˉbytes));
        var Memoryˉadapter = Moduleˉcodec.Readˉandˉverify(Memoryˉadapterˉbytes);
        Equal(Moduleˉprofile.Portable, Memoryˉadapter.Module.Profile);
        Equal(0, Memoryˉadapter.Module.Capabilities.Length);
        Equal(417, Memoryˉadapter.Functions.Length);
        var Memoryˉmain = Memoryˉadapter.Functions.Single(
            Function => Function.Declaration.Name == "Main");
        Equal(1, Memoryˉmain.Declaration.Parameterˉtypes.Length);
        Equal(Valueˉtype.Bytes, Memoryˉmain.Declaration.Parameterˉtypes[0]);
        Equal(Valueˉtype.Bytes, Memoryˉmain.Declaration.Returnˉtype);
        Equal(
            759_232,
            Memoryˉadapter.Functions.Sum(Function => Function.Declaration.Codeˉlength));
        Equal(
            157_844,
            Memoryˉadapter.Functions.Sum(Function => Function.Instructions.Length));
        Equal(
            1_408,
            Memoryˉadapter.Functions.Max(Function => Function.Declaration.Localˉtypes.Length));
        Equal(
            34,
            Memoryˉadapter.Functions.Max(
                Function => Function.Declaration.Maximumˉstackˉdepth));
        var Memoryˉruntime = new Referenceˉruntime(
            Memoryˉadapter,
            new Referenceˉcapabilityˉhost(new StringWriter()),
            Runtimeˉoptions.Portableˉdefaults with
            {
                Maximumˉinstructions = 20_000_000,
            });
        var Memoryˉresult = Memoryˉruntime.Runˉmainˉbytes(
            Buildˉsingleˉsourceˉset(SOURCE_WVB_FUNCTION_ONLY_SOURCE));
        Equal(8_504_719L, Memoryˉresult.Executedˉinstructions);
        Equal(832, Memoryˉresult.Bytes.Length);
        Equal(
            0x4F43_5657u,
            BinaryPrimitives.ReadUInt32LittleEndian(Memoryˉresult.Bytes.AsSpan(0, 4)));
        Equal((ushort)1, BinaryPrimitives.ReadUInt16LittleEndian(Memoryˉresult.Bytes.AsSpan(4, 2)));
        Equal((ushort)0, BinaryPrimitives.ReadUInt16LittleEndian(Memoryˉresult.Bytes.AsSpan(6, 2)));
        Equal(0u, BinaryPrimitives.ReadUInt32LittleEndian(Memoryˉresult.Bytes.AsSpan(8, 4)));
        Equal(816u, BinaryPrimitives.ReadUInt32LittleEndian(Memoryˉresult.Bytes.AsSpan(12, 4)));
        Sequenceˉequal(
            Compileˉsuccess(SOURCE_WVB_FUNCTION_ONLY_SOURCE),
            Memoryˉresult.Bytes.AsSpan()[16..].ToArray());
        var Memoryˉfailure = new Referenceˉruntime(
            Memoryˉadapter,
            new Referenceˉcapabilityˉhost(new StringWriter()),
            Runtimeˉoptions.Portableˉdefaults with
            {
                Maximumˉinstructions = 20_000_000,
            }).Runˉmainˉbytes(ImmutableArray<byte>.Empty);
        Equal(1_058L, Memoryˉfailure.Executedˉinstructions);
        Equal(
            0x4F43_5657u,
            BinaryPrimitives.ReadUInt32LittleEndian(Memoryˉfailure.Bytes.AsSpan(0, 4)));
        Equal((ushort)1, BinaryPrimitives.ReadUInt16LittleEndian(Memoryˉfailure.Bytes.AsSpan(4, 2)));
        Equal((ushort)0, BinaryPrimitives.ReadUInt16LittleEndian(Memoryˉfailure.Bytes.AsSpan(6, 2)));
        Equal(1u, BinaryPrimitives.ReadUInt32LittleEndian(Memoryˉfailure.Bytes.AsSpan(8, 4)));
        var Memoryˉdiagnosticˉlength = BinaryPrimitives.ReadUInt32LittleEndian(
            Memoryˉfailure.Bytes.AsSpan(12, 4));
        Equal(checked(16 + (int)Memoryˉdiagnosticˉlength), Memoryˉfailure.Bytes.Length);
        var Memoryˉdiagnostic = System.Text.Encoding.UTF8.GetString(
            Memoryˉfailure.Bytes.AsSpan()[16..]);
        Equal(
            "source-wvb status=Sourceˉwir wir-status=Sourceˉbindings function=0 operation=0",
            Memoryˉdiagnostic);

        var Toolˉfixture = EXACT_COMPILER_WVB.Value;
        var Toolˉbytes = Toolˉfixture.Bytes;
        Equal(
            SOURCE_WVB_TOOL_SHA256,
            Moduleˉdigest.Calculateˉsha256(Toolˉbytes.AsSpan()));
        var Tool = Toolˉfixture.Module;
        var Sourceˉbytes = System.Text.Encoding.UTF8.GetBytes(
            SOURCE_WVB_FUNCTION_ONLY_SOURCE).ToImmutableArray();
        var Output = new StringWriter();
        var Diagnostics = new StringWriter();
        var Writer = new Capturingˉfileˉwriter();
        var Reader = new Testˉfileˉreader((Name, Maximumˉbytes) =>
        {
            Equal("function-only.wv", Name);
            True(Sourceˉbytes.Length <= Maximumˉbytes,
                "The source-to-WVB hosted byte limit was too small.");
            return Sourceˉbytes;
        });
        var Authorized = Tool.Module.Capabilities
            .Select(Capability => Capability.Name)
            .ToImmutableHashSet(StringComparer.Ordinal);
        var Toolˉresult = new Referenceˉruntime(
            Tool,
            new Referenceˉcapabilityˉhost(new Hostedˉresourceˉcontext(
                ["function-only.wv", "function-only.wvb"],
                Output,
                Diagnostics,
                Reader,
                Writer)),
            new(Authorized, Maximumˉinstructions: 4_000_000_000)).Runˉmain();
        Equal(0, Toolˉresult.Exitˉcode);
        Equal(string.Empty, Diagnostics.ToString());
        Equal(
            "source wvb status=Valid functions=4 code-bytes=532 module-bytes=816\n",
            Output.ToString().Replace("\r\n", "\n", StringComparison.Ordinal));
        Equal(1, Reader.Readˉcount);
        Equal(1, Writer.Writeˉcount);
        Equal("function-only.wvb", Writer.Resourceˉname);

        var Stageˉzeroˉbytes = Compileˉsuccess(SOURCE_WVB_FUNCTION_ONLY_SOURCE);
        Sequenceˉequal(Stageˉzeroˉbytes, Writer.Bytes);
        var Generated = Moduleˉcodec.Readˉandˉverify(Writer.Bytes.AsSpan());
        Equal("Sourceˉwvbˉfixture", Generated.Module.Name);
        Equal(
            6,
            new Referenceˉruntime(
                Generated,
                new Referenceˉcapabilityˉhost(new StringWriter()),
                Runtimeˉoptions.Portableˉdefaults).Runˉmain().Exitˉcode);

        const string Controlˉsource = """
            module Sourceˉwvbˉcontrol profile portable;
            data Values: [i32] = [7];
            fn Wouldˉtrap() -> bool { return Values[2] == 0; }
            export fn Main() -> i32 {
                if false && Wouldˉtrap() { return 90; }
                if !(true || Wouldˉtrap()) { return 91; }
                var Result = 0;
                var Index = 0;
                if false || true && true {
                    while Index < 5 {
                        Index += 1;
                        if Index == 2 { continue; }
                        if Index == 4 { break; }
                        Result += Index;
                    }
                    Result *= 2;
                    Result -= 1;
                }
                return Result;
            }
            """;
        var Controlˉsourceˉbytes = System.Text.Encoding.UTF8.GetBytes(
            Controlˉsource).ToImmutableArray();
        var Controlˉoutput = new StringWriter();
        var Controlˉdiagnostics = new StringWriter();
        var Controlˉwriter = new Capturingˉfileˉwriter();
        var Controlˉreader = new Testˉfileˉreader((Name, Maximumˉbytes) =>
        {
            Equal("control.wv", Name);
            True(Controlˉsourceˉbytes.Length <= Maximumˉbytes,
                "The source-to-WVB hosted byte limit was too small for control operators.");
            return Controlˉsourceˉbytes;
        });
        var Controlˉtoolˉresult = new Referenceˉruntime(
            Tool,
            new Referenceˉcapabilityˉhost(new Hostedˉresourceˉcontext(
                ["control.wv", "control.wvb"],
                Controlˉoutput,
                Controlˉdiagnostics,
                Controlˉreader,
                Controlˉwriter)),
            new(Authorized, Maximumˉinstructions: 4_000_000_000)).Runˉmain();
        Equal(0, Controlˉtoolˉresult.Exitˉcode);
        Equal(string.Empty, Controlˉdiagnostics.ToString());
        Contains(Controlˉoutput.ToString(), "source wvb status=Valid");
        Equal(1, Controlˉreader.Readˉcount);
        Equal(1, Controlˉwriter.Writeˉcount);
        Equal("control.wvb", Controlˉwriter.Resourceˉname);
        var Controlˉstageˉzeroˉbytes = Compileˉsuccess(Controlˉsource);
        Sequenceˉequal(Controlˉstageˉzeroˉbytes, Controlˉwriter.Bytes);
        Equal(
            7,
            new Referenceˉruntime(
                Moduleˉcodec.Readˉandˉverify(Controlˉwriter.Bytes.AsSpan()),
                new Referenceˉcapabilityˉhost(new StringWriter()),
                Runtimeˉoptions.Portableˉdefaults).Runˉmain().Exitˉcode);

        var Dataˉsourceˉbytes = System.Text.Encoding.UTF8.GetBytes(
            SOURCE_WVB_DATA_AND_TEXT_SOURCE).ToImmutableArray();
        var Dataˉoutput = new StringWriter();
        var Dataˉdiagnostics = new StringWriter();
        var Dataˉwriter = new Capturingˉfileˉwriter();
        var Dataˉreader = new Testˉfileˉreader((Name, Maximumˉbytes) =>
        {
            Equal("data-and-text.wv", Name);
