    private static void Localˉinferenceˉruns()
    {
        const string Source = """
            module Localˉinference profile portable;

            data Values: bytes = [
                3u8,
                5u8,
            ];

            enum Localˉmode {
                Ready = 1;
                Closed = 2;
            }

            record Localˉsnapshot {
                Count: u32;
                Mode: Localˉmode;
            }

            fn Add(
                Left: i32,
                Right: i32,
            ) -> i32 {
                return Left + Right;
            }

            export fn Main() -> i32 {
                let Signed = -7;
                let Byte = 3u8;
                let Count = Bytesˉlength(Values);
                let Enabled = true;
                let Message = "windvale";
                let Copy = Values;
                let Mode = Localˉmode.Ready;
                let Snapshot = Localˉsnapshot(
                    Count,
                    Mode,
                );
                var Result = Add(
                    Signed,
                    10,
                );
                if Byte == Bytesˉreadˉu8(Copy, 0u32) { Result = Result + 1; }
                if Enabled { Result = Result + 1; }
                if Bytesˉlength(Textˉtoˉutf8(Message)) == 8u32 { Result = Result + 1; }
                if Snapshot.Count == 2u32 { Result = Result + 1; }
                if Snapshot.Mode == Localˉmode.Ready { Result = Result + 1; }
                return Result;
            }
            """;

        Equal(8, Runˉportable(Source));

        const string Voidˉinitializer = """
            module Invalidˉinference profile portable;
            fn Touch() -> void {}
            export fn Main() -> i32 {
                let Value = Touch();
                return 0;
            }
            """;
        Hasˉdiagnostic(Voidˉinitializer, "WVC2044");
    }

    private static void Typedˉconstantsˉrun()
    {
        const string Source = """
            module Typedˉconstants profile portable;

            enum Constantˉmode {
                Ready = 1;
                Closed = 2;
            }

            const BASE: i32 = 40;
            const ANSWER: i32 = BASE + 2;
            const LIMIT: u32 = 3u32 * 4u32;
            const ENABLED: bool = ANSWER > BASE;
            const MODE: Constantˉmode = Constantˉmode.Ready;
            const SIGNED: i64 = -9i64;
            const UNSIGNED: u64 = 18446744073709551615u64;
            export const PUBLIC_LIMIT: u8 = 9u8;

            export fn Main() -> i32 {
                var Score = ANSWER;
                if ENABLED { Score = Score + 1; }
                if MODE == Constantˉmode.Ready { Score = Score + 1; }
                if LIMIT == 12u32 { Score = Score + 1; }
                if SIGNED < 0i64 { Score = Score + 1; }
                if UNSIGNED > 4294967295u64 { Score = Score + 1; }
                if PUBLIC_LIMIT == 9u8 { Score = Score + 1; }
                return Score;
            }
            """;
        var Bytes = Compileˉsuccess(Source);
        Sequenceˉequal(Compileˉsuccess(Source), Bytes);
        var Module = Moduleˉcodec.Readˉandˉverify(Bytes);
        Equal(0, Module.Module.Data.Length);
        Sequenceˉequal(["Main"], Module.Module.Exports.Select(Export => Export.Name));
        Equal(48, Runˉportable(Source));

        Hasˉdiagnostic("""
            module Invalidˉconstant profile portable;
            const FIRST: i32 = SECOND;
            const SECOND: i32 = 2;
            export fn Main() -> i32 { return 0; }
            """, "WVC2103");
        Hasˉdiagnostic("""
            module Invalidˉconstant profile portable;
            const BAD: i32 = true;
            export fn Main() -> i32 { return 0; }
            """, "WVC2102");
        Hasˉdiagnostic("""
            module Invalidˉconstant profile portable;
            fn Value() -> i32 { return 1; }
            const BAD: i32 = Value();
            export fn Main() -> i32 { return 0; }
            """, "WVC2104");
        Hasˉdiagnostic("""
            module Invalidˉconstant profile portable;
            const BAD: i32 = 2147483647 + 1;
            export fn Main() -> i32 { return 0; }
            """, "WVC2106");
        Hasˉdiagnostic("""
            module Invalidˉconstant profile portable;
            const BAD: text = "value";
            export fn Main() -> i32 { return 0; }
            """, "WVC2101");
        Hasˉdiagnostic("""
            module Invalidˉconstant profile portable;
            const Bad: i32 = 1;
            export fn Main() -> i32 { return 0; }
            """, "WVC2100");

        Hasˉdiagnostic(
            Seedˉcompiler.Compileˉmodules(
                new(
                    "constant-root.wv",
                    "module Constantˉroot profile portable; import Constantˉdependency as Dependency; export fn Main() -> i32 { return Dependency.VALUE; }"),
                [
                    new(
                        "constant-dependency.wv",
                        "module Constantˉdependency profile portable; const VALUE: i32 = 7; export fn Value() -> i32 { return VALUE; }")
                ]),
            "WVC0017");
    }

    private static void Advancedˉlanguageˉfeaturesˉrun()
    {
        var Portableˉcases = new (string Source, string Hash, int Exitˉcode)[]
        {
            (SOURCE_WVB_MATCH_SOURCE, SOURCE_WVB_MATCH_SHA256, 2),
            (SOURCE_WVB_MATCH_FALLTHROUGH_SOURCE, SOURCE_WVB_MATCH_FALLTHROUGH_SHA256, 3),
            (SOURCE_WVB_VARIANTS_SOURCE, SOURCE_WVB_VARIANTS_SHA256, 45),
            (SOURCE_WVB_COLLECTIONS_SOURCE, SOURCE_WVB_COLLECTIONS_SHA256, 16),
            (SOURCE_WVB_OPERATORS_WINDVALE_SOURCE, SOURCE_WVB_OPERATORS_WINDVALE_SHA256, 28),
            (SOURCE_WVB_OPERATORS_SOURCE, SOURCE_WVB_OPERATORS_SHA256, 28),
        };
        foreach (var Case in Portableˉcases)
        {
            var Bytes = Compileˉsuccess(Case.Source);
            Equal(Case.Hash, Moduleˉdigest.Calculateˉsha256(Bytes));
            var Module = Moduleˉcodec.Readˉandˉverify(Bytes);
            Equal(Moduleˉcodec.MINOR_VERSION, Module.Module.Formatˉminorˉversion);
            Sequenceˉequal(Bytes, Moduleˉcodec.Write(Module.Module));
            Equal(
                Case.Exitˉcode,
                new Referenceˉruntime(
                    Module,
                    new Referenceˉcapabilityˉhost(new StringWriter()),
                    Runtimeˉoptions.Portableˉdefaults).Runˉmain().Exitˉcode);
        }

        var Metadataˉbytes = Compileˉsuccess(SOURCE_WVB_METADATA_SOURCE);
        Equal(SOURCE_WVB_METADATA_SHA256, Moduleˉdigest.Calculateˉsha256(Metadataˉbytes));
        var Metadataˉmodule = Moduleˉcodec.Readˉandˉverify(Metadataˉbytes);
        Equal(Moduleˉcodec.MINOR_VERSION, Metadataˉmodule.Module.Formatˉminorˉversion);
        Equal(Moduleˉprofile.Hosted, Metadataˉmodule.Module.Profile);
        var Metadata = Metadataˉmodule.Module.Metadata
            ?? throw new InvalidOperationException("The metadata fixture omitted module metadata.");
        Equal(Moduleˉauthority.Application, Metadata.Authority);
        Sequenceˉequal(["linux", "windows", "windvale"], Metadata.Platformˉscopes);
        Sequenceˉequal(
            [new Capabilityˉrequirement(Capabilityˉcatalog.CONSOLE_WRITE_LINE, 1)],
            Metadata.Requiredˉcapabilities);
        Sequenceˉequal(
            [new Capabilityˉrequirement(Capabilityˉcatalog.FILE_READ_BYTES, 1)],
            Metadata.Optionalˉcapabilities);
        Sequenceˉequal(Metadataˉbytes, Moduleˉcodec.Write(Metadataˉmodule.Module));

        var Output = new StringWriter();
        var Authorized = Metadataˉmodule.Module.Capabilities
            .Select(Capability => Capability.Name)
            .ToImmutableHashSet(StringComparer.Ordinal);
        Equal(
            0,
            new Referenceˉruntime(
                Metadataˉmodule,
                new Referenceˉcapabilityˉhost(Output),
                new(Authorized)).Runˉmain().Exitˉcode);
        Equal("metadata\n", Output.ToString().Replace("\r\n", "\n", StringComparison.Ordinal));
    }

    private static void Operatorsˉrun()
    {
        const string Source = """
            module Operators profile portable;
            export fn Main() -> i32 {
                var Score: i32 = 0;
                let Seven: i32 = 10 - 3;
                if Seven == 7 { Score = Score + 1; }
                if Seven != 8 { Score = Score + 1; }
                if Seven <= 7 { Score = Score + 1; }
                if Seven > 6 { Score = Score + 1; }
                if Seven >= 7 { Score = Score + 1; }
                if -Seven < 0 { Score = Score + 1; }
                if true == true { Score = Score + 1; }
                if true != false { Score = Score + 1; }
                return Score;
            }
            """;
        Equal(8, Runˉportable(Source));
    }

    private static void Wideˉscalarsˉrun()
    {
        const string Source = """
            module Wideˉscalars profile hosted;

            capability console.write_line;

            record Wideˉpair {
                Signed: i64;
                Unsigned: u64;
            }

            fn Make() -> Wideˉpair {
                return Wideˉpair(-9i64, 18446744073709551615u64);
            }

            export fn Main() -> i32 {
                let Pair: Wideˉpair = Make();
                var Score: i32 = 0;
                if Pair.Signed + 10i64 == 1i64 { Score = Score + 1; }
                if Pair.Signed < 0i64 { Score = Score + 1; }
                if -Pair.Signed == 9i64 { Score = Score + 1; }
                if Pair.Unsigned - 1u64 == 18446744073709551614u64 { Score = Score + 1; }
                if Pair.Unsigned > 4294967295u64 { Score = Score + 1; }
                if 3i64 * 7i64 >= 21i64 { Score = Score + 1; }
                if 3u64 * 7u64 <= 21u64 { Score = Score + 1; }
                console.write_line(Textˉconcat(
                    I64ˉformat(-9223372036854775807i64 - 1i64),
                    Textˉconcat(" ", U64ˉformat(Pair.Unsigned))
                ));
                return Score;
            }
            """;

        var Bytes = Compileˉsuccess(Source);
        Equal(Moduleˉcodec.MINOR_VERSION, BinaryPrimitives.ReadUInt16LittleEndian(Bytes.AsSpan(6)));
        var Baselineˉbytes = Compileˉsuccess(SUM_SOURCE);
        Equal(
            Moduleˉcodec.MINOR_VERSION,
            BinaryPrimitives.ReadUInt16LittleEndian(Baselineˉbytes.AsSpan(6)));

        var Module = Moduleˉcodec.Readˉandˉverify(Bytes);
        Equal(Moduleˉcodec.MINOR_VERSION, Module.Module.Formatˉminorˉversion);
        var Pair = (Recordˉtypeˉdeclaration)Module.Module.Types.Single();
        Equal(Valueˉtype.I64, Pair.Fields[0].Type);
        Equal(Valueˉtype.U64, Pair.Fields[1].Type);
        Sequenceˉequal(Bytes, Moduleˉcodec.Write(Module.Module));

        var Inspection = Moduleˉinspector.Inspect(Module, Bytes);
        Contains(Inspection, "Windvale bytecode 1.11");
        Contains(Inspection, "i64.const 9");
        Contains(Inspection, "i64.negate");
        Contains(Inspection, "u64.const 18446744073709551615");
        Contains(Inspection, "i64.add");
        Contains(Inspection, "u64.subtract");
        Contains(Inspection, "i64.format");
        Contains(Inspection, "u64.format");

        var Output = new StringWriter();
        var Result = new Referenceˉruntime(
            Module,
            new Referenceˉcapabilityˉhost(Output),
            Runtimeˉoptions.Portableˉdefaults with
            {
                Authorizedˉcapabilities = ImmutableHashSet.Create(
                    StringComparer.Ordinal,
                    Capabilityˉcatalog.CONSOLE_WRITE_LINE),
            }).Runˉmain();
        Equal(7, Result.Exitˉcode);
        Equal("-9223372036854775808 18446744073709551615\n", Output.ToString());
        Throwsˉnative("WVN2003", () => X64ˉnativeˉbackend.Compile(Module));
    }

    private static void U64ˉbinaryˉcodecsˉrun()
    {
        const string Source = """
            module U64ˉbinaryˉcodecs profile portable;

            export fn Main() -> i32 {
                let Maximum: u64 = 18446744073709551615u64;
                let Encoded: bytes = Bytesˉfromˉu64ˉlittle(Maximum);
                if Bytesˉlength(Encoded) != 8u32 { return 1; }
                if Bytesˉreadˉu8(Encoded, 0u32) != 255u8 { return 2; }
                if Bytesˉreadˉu8(Encoded, 7u32) != 255u8 { return 3; }
                if Bytesˉreadˉu64ˉlittle(Encoded, 0u32) != Maximum { return 4; }

                let Offset: bytes = Bytesˉconcat(Bytesˉfromˉu8(7u8), Encoded);
                if Bytesˉreadˉu64ˉlittle(Offset, 1u32) != Maximum { return 5; }
                let Boundary: u64 = 4294967296u64;
                if Bytesˉreadˉu64ˉlittle(
                    Bytesˉfromˉu64ˉlittle(Boundary), 0u32
                ) != Boundary { return 6; }
                let Widened: u64 = U64ˉfromˉu32(4294967295u32);
                if Widened != 4294967295u64 { return 7; }
                return 29;
            }
            """;

        var Bytes = Compileˉsuccess(Source);
        Equal(
            Moduleˉcodec.MINOR_VERSION,
            BinaryPrimitives.ReadUInt16LittleEndian(Bytes.AsSpan(6)));
        var Module = Moduleˉcodec.Readˉandˉverify(Bytes);
        Sequenceˉequal(Bytes, Moduleˉcodec.Write(Module.Module));
        var Inspection = Moduleˉinspector.Inspect(Module, Bytes);
        Contains(Inspection, "Windvale bytecode 1.11");
        Contains(Inspection, "bytes.from_u64_little");
        Contains(Inspection, "bytes.read_u64_little");
        Contains(Inspection, "u64.from_u32");
        Equal(
            29,
            new Referenceˉruntime(
                Module,
                new Referenceˉcapabilityˉhost(TextWriter.Null),
                Runtimeˉoptions.Portableˉdefaults).Runˉmain().Exitˉcode);

        var Relabeled = (byte[])Bytes.Clone();
        BinaryPrimitives.WriteUInt16LittleEndian(
            Relabeled.AsSpan(6),
            10);
        Throwsˉbytecode("WVB1003", () => Moduleˉcodec.Readˉandˉverify(Relabeled));

        const string Truncatedˉsource = """
            module Truncatedˉu64ˉread profile portable;
            export fn Main() -> i32 {
                Bytesˉreadˉu64ˉlittle(Textˉtoˉutf8("1234567"), 0u32);
                return 0;
            }
            """;
        var Truncated = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess(Truncatedˉsource));
        Throwsˉruntime(
            "WVR3008",
            () => new Referenceˉruntime(
                Truncated,
                new Referenceˉcapabilityˉhost(TextWriter.Null),
                Runtimeˉoptions.Portableˉdefaults).Runˉmain());
    }

    private static void Malformedˉmodulesˉareˉrejected()
    {
        var Valid = Compileˉsuccess(SUM_SOURCE);

        var Badˉmagic = (byte[])Valid.Clone();
        Badˉmagic[0] ^= 0xFF;
        Throwsˉbytecode("WVB1002", () => Moduleˉcodec.Readˉandˉverify(Badˉmagic));

        var Badˉversion = (byte[])Valid.Clone();
        Badˉversion[4] = 2;
        Throwsˉbytecode("WVB1003", () => Moduleˉcodec.Readˉandˉverify(Badˉversion));

        const string Wideˉsource = """
            module Wideˉversion profile portable;
            export fn Main() -> i32 { 1i64; return 0; }
            """;
        var Badˉwideˉversion = Compileˉsuccess(Wideˉsource);
        BinaryPrimitives.WriteUInt16LittleEndian(
            Badˉwideˉversion.AsSpan(6),
            10);
        Throwsˉbytecode("WVB1003", () => Moduleˉcodec.Readˉandˉverify(Badˉwideˉversion));

        var Badˉsectionˉcount = (byte[])Valid.Clone();
        BinaryPrimitives.WriteUInt32LittleEndian(Badˉsectionˉcount.AsSpan(8), 5);
        Throwsˉbytecode("WVB1004", () => Moduleˉcodec.Readˉandˉverify(Badˉsectionˉcount));

        var Badˉflags = (byte[])Valid.Clone();
        Badˉflags[13] = 1;
        Throwsˉbytecode("WVB1009", () => Moduleˉcodec.Readˉandˉverify(Badˉflags));

        var Badˉutf8 = (byte[])Valid.Clone();
        var Moduleˉpayload = Findˉsectionˉpayload(Badˉutf8, Sectionˉkind.Module);
        Badˉutf8[Moduleˉpayload + 5] = 0xFF;
        Throwsˉbytecode("WVB1016", () => Moduleˉcodec.Readˉandˉverify(Badˉutf8));

        var Truncated = Valid[..^1];
        Throwsˉbytecode("WVB1018", () => Moduleˉcodec.Readˉandˉverify(Truncated));

        var Trailing = new byte[Valid.Length + 1];
        Valid.CopyTo(Trailing, 0);
        Throwsˉbytecode("WVB1017", () => Moduleˉcodec.Readˉandˉverify(Trailing));

        var Oversized = new byte[Bytecodeˉlimits.MAX_MODULE_BYTES + 1];
        Throwsˉbytecode("WVB1001", () => Moduleˉcodec.Readˉandˉverify(Oversized));

        var Badˉcount = Compileˉsuccess(HELLO_SOURCE);
        var Capabilityˉpayload = Findˉsectionˉpayload(Badˉcount, Sectionˉkind.Capabilities);
        BinaryPrimitives.WriteUInt32LittleEndian(Badˉcount.AsSpan(Capabilityˉpayload), uint.MaxValue);
        Throwsˉbytecode("WVB1011", () => Moduleˉcodec.Readˉandˉverify(Badˉcount));

        var Badˉtypeˉcount = Compileˉsuccess(SUM_SOURCE);
        var Typesˉpayload = Findˉsectionˉpayload(Badˉtypeˉcount, Sectionˉkind.Types);
        BinaryPrimitives.WriteUInt32LittleEndian(
            Badˉtypeˉcount.AsSpan(Typesˉpayload),
            Bytecodeˉlimits.MAX_NOMINAL_TYPES + 1u);
        Throwsˉbytecode("WVB1012", () => Moduleˉcodec.Readˉandˉverify(Badˉtypeˉcount));

        const string Enumˉsource = """
            module Enumˉbinary profile portable;
            enum State { Ready = 0; }
            export fn Main() -> i32 { return 0; }
            """;
        var Badˉtypeˉkind = Compileˉsuccess(Enumˉsource);
        var Badˉtypeˉpayload = Findˉsectionˉpayload(Badˉtypeˉkind, Sectionˉkind.Types);
        Badˉtypeˉkind[Badˉtypeˉpayload + sizeof(uint)] = byte.MaxValue;
        Throwsˉbytecode("WVB1020", () => Moduleˉcodec.Readˉandˉverify(Badˉtypeˉkind));
    }

