    private static WebAssemblyˉexecutionˉresult Runˉreferenceˉwebassemblyˉi32(
        IEnumerable<byte> input,
        long maximumˉinstructions = 1_000_000)
    {
        var Verified = Moduleˉcodec.Readˉandˉverify(input.ToArray());
        var Runtime = new Referenceˉruntime(
            Verified,
            new Referenceˉcapabilityˉhost(new StringWriter()),
            Runtimeˉoptions.Portableˉdefaults with
            {
                Maximumˉinstructions = maximumˉinstructions,
                Collectˉfunctionˉsteps = true,
            });
        try
        {
            var Result = Runtime.Runˉmain();
            Equal(
                Result.Executedˉinstructions,
                Runtime.Readˉfunctionˉsteps().Sum(Item => Item.Executedˉinstructions));
            return new(0, Result.Exitˉcode, Result.Executedˉinstructions);
        }
        catch (Runtimeˉexception Exception) when (Exception.Code == "WVR3007")
        {
            var Steps = Runtime.Readˉfunctionˉsteps()
                .Sum(Item => Item.Executedˉinstructions);
            return new(3007, 0, Steps);
        }
        catch (Runtimeˉexception Exception) when (Exception.Code == "WVR3011")
        {
            var Steps = Runtime.Readˉfunctionˉsteps()
                .Sum(Item => Item.Executedˉinstructions);
            return new(3011, 0, Steps);
        }
    }

    private static WebAssemblyˉexecutionˉresult Executeˉstraightˉi32ˉwebassembly(
        ReadOnlySpan<byte> module,
        Verifiedˉmodule source)
    {
        Equal(1, source.Functions.Length);
        var Function = source.Functions[0];
        Equal("Main", Function.Declaration.Name);
        Equal(Valueˉtype.I32, Function.Declaration.Returnˉtype.Kind);
        True(
            Function.Declaration.Localˉtypes.All(Type => Type.Kind == Valueˉtype.I32),
            "The straight-i32 fixture contains a non-i32 local.");

        var Reader = new WebAssemblyˉtestˉreader(module);
        Reader.Readˉheader();

        var Typeˉend = Reader.Readˉsection(1);
        Reader.Require(Reader.Readˉuleb32() == 1, "The straight-i32 type count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x60, "The straight-i32 function type is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 0, "The straight-i32 parameter count is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 1, "The straight-i32 result count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The straight-i32 result type is invalid.");
        Reader.Require(Reader.Position == Typeˉend, "The straight-i32 type section has trailing bytes.");

        var Functionˉend = Reader.Readˉsection(3);
        Reader.Require(Reader.Readˉuleb32() == 1, "The straight-i32 function count is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 0, "The straight-i32 type index is invalid.");
        Reader.Require(Reader.Position == Functionˉend, "The straight-i32 function section has trailing bytes.");

        var Globalˉend = Reader.Readˉsection(6);
        Reader.Require(Reader.Readˉuleb32() == 3, "The straight-i32 global count is invalid.");
        Reader.Readˉglobal(0, 1);
        Reader.Readˉglobal(1, 0);
        Reader.Readˉglobal(1, 0);
        Reader.Require(Reader.Position == Globalˉend, "The straight-i32 global section has trailing bytes.");

        var Exportˉend = Reader.Readˉsection(7);
        Reader.Require(Reader.Readˉuleb32() == 4, "The straight-i32 export count is invalid.");
        Reader.Readˉexport("Windvale.run", 0, 0);
        Reader.Readˉexport("Windvale.abi", 3, 0);
        Reader.Readˉexport("Windvale.result", 3, 1);
        Reader.Readˉexport("Windvale.instructions", 3, 2);
        Reader.Require(Reader.Position == Exportˉend, "The straight-i32 export section has trailing bytes.");

        var Codeˉend = Reader.Readˉsection(10);
        Reader.Require(Reader.Readˉuleb32() == 1, "The straight-i32 body count is invalid.");
        var Bodyˉlength = Reader.Readˉuleb32();
        Reader.Require(Bodyˉlength <= int.MaxValue, "The straight-i32 body is oversized.");
        Reader.Require(
            Reader.Position <= Codeˉend - (int)Bodyˉlength,
            "The straight-i32 body is truncated.");
        var Bodyˉend = Reader.Position + (int)Bodyˉlength;

        var Localˉcount = Function.Declaration.Localˉtypes.Length;
        var Scratchˉleft = (uint)Localˉcount;
        var Scratchˉright = Scratchˉleft + 1;
        var Scratchˉresult = Scratchˉleft + 2;
        var Scratchˉwide = Scratchˉleft + 3;
        Reader.Require(Reader.Readˉuleb32() == 2, "The straight-i32 local group count is invalid.");
        Reader.Require(
            Reader.Readˉuleb32() == (uint)Localˉcount + 3,
            "The straight-i32 i32 local count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The straight-i32 local group type is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 1, "The straight-i32 i64 local count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7E, "The straight-i32 wide local type is invalid.");
        Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The straight-i32 result reset is invalid.");
        Reader.Readˉindexed(0x24, 1);
        Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The straight-i32 instruction reset is invalid.");
        Reader.Readˉindexed(0x24, 2);

        void Readˉoverflowˉreturn()
        {
            Reader.Require(Reader.Readˉbyte() == 0x04, "The overflow if opcode is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x40, "The overflow block type is invalid.");
            Reader.Require(Reader.Readˉi32ˉconstant() == 3007, "The overflow status is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x0F, "The overflow return opcode is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x0B, "The overflow branch is unterminated.");
        }

        void Readˉcheckedˉadd()
        {
            Reader.Readˉindexed(0x21, Scratchˉright);
            Reader.Readˉindexed(0x21, Scratchˉleft);
            Reader.Readˉindexed(0x20, Scratchˉleft);
            Reader.Readˉindexed(0x20, Scratchˉright);
            Reader.Require(Reader.Readˉbyte() == 0x6A, "The checked add opcode is invalid.");
            Reader.Readˉindexed(0x22, Scratchˉresult);
            Reader.Readˉindexed(0x20, Scratchˉleft);
            Reader.Require(Reader.Readˉbyte() == 0x73, "The checked add left xor is invalid.");
            Reader.Readˉindexed(0x20, Scratchˉresult);
            Reader.Readˉindexed(0x20, Scratchˉright);
            Reader.Require(Reader.Readˉbyte() == 0x73, "The checked add right xor is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x71, "The checked add mask is invalid.");
            Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The checked add sign constant is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x48, "The checked add sign comparison is invalid.");
            Readˉoverflowˉreturn();
            Reader.Readˉindexed(0x20, Scratchˉresult);
        }

        void Readˉcheckedˉsubtract()
        {
            Reader.Readˉindexed(0x21, Scratchˉright);
            Reader.Readˉindexed(0x21, Scratchˉleft);
            Reader.Readˉindexed(0x20, Scratchˉleft);
            Reader.Readˉindexed(0x20, Scratchˉright);
            Reader.Require(Reader.Readˉbyte() == 0x6B, "The checked subtract opcode is invalid.");
            Reader.Readˉindexed(0x22, Scratchˉresult);
            Reader.Readˉindexed(0x20, Scratchˉleft);
            Reader.Require(Reader.Readˉbyte() == 0x73, "The checked subtract result xor is invalid.");
            Reader.Readˉindexed(0x20, Scratchˉleft);
            Reader.Readˉindexed(0x20, Scratchˉright);
            Reader.Require(Reader.Readˉbyte() == 0x73, "The checked subtract operand xor is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x71, "The checked subtract mask is invalid.");
            Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The checked subtract sign constant is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x48, "The checked subtract sign comparison is invalid.");
            Readˉoverflowˉreturn();
            Reader.Readˉindexed(0x20, Scratchˉresult);
        }

        void Readˉcheckedˉmultiply()
        {
            Reader.Readˉindexed(0x21, Scratchˉright);
            Reader.Readˉindexed(0x21, Scratchˉleft);
            Reader.Readˉindexed(0x20, Scratchˉleft);
            Reader.Require(Reader.Readˉbyte() == 0xAC, "The checked multiply left extension is invalid.");
            Reader.Readˉindexed(0x20, Scratchˉright);
            Reader.Require(Reader.Readˉbyte() == 0xAC, "The checked multiply right extension is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x7E, "The checked multiply opcode is invalid.");
            Reader.Readˉindexed(0x22, Scratchˉwide);
            Reader.Require(Reader.Readˉbyte() == 0xA7, "The checked multiply wrap is invalid.");
            Reader.Readˉindexed(0x22, Scratchˉresult);
            Reader.Require(Reader.Readˉbyte() == 0xAC, "The checked multiply result extension is invalid.");
            Reader.Readˉindexed(0x20, Scratchˉwide);
            Reader.Require(Reader.Readˉbyte() == 0x52, "The checked multiply comparison is invalid.");
            Readˉoverflowˉreturn();
            Reader.Readˉindexed(0x20, Scratchˉresult);
        }

        void Readˉcheckedˉnegate()
        {
            Reader.Readˉindexed(0x21, Scratchˉleft);
            Reader.Readˉindexed(0x20, Scratchˉleft);
            Reader.Require(
                Reader.Readˉi32ˉconstant() == int.MinValue,
                "The checked negate minimum is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x46, "The checked negate comparison is invalid.");
            Readˉoverflowˉreturn();
            Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The checked negate zero is invalid.");
            Reader.Readˉindexed(0x20, Scratchˉleft);
            Reader.Require(Reader.Readˉbyte() == 0x6B, "The checked negate subtraction is invalid.");
        }

        var Locals = new int[Localˉcount];
        var Stack = new Stack<int>();
        var Trapped = false;
        var Trapˉstep = 0;
        var Result = 0;
        foreach (var (Instruction, Index) in Function.Instructions.Select((Item, Index) => (Item, Index)))
        {
            var Step = Index + 1;
            Reader.Require(
                Reader.Readˉi32ˉconstant() == Step,
                "The emitted WVB instruction charge is invalid.");
            Reader.Readˉindexed(0x24, 2);
            switch (Instruction.Opcode)
            {
                case Opcode.I32ˉconst:
                    Reader.Require(
                        Reader.Readˉi32ˉconstant() == Instruction.Signedˉoperand,
                        "The emitted i32 constant changed value.");
                    if (!Trapped) Stack.Push(Instruction.Signedˉoperand);
                    break;
                case Opcode.Localˉload:
                    Reader.Readˉindexed(0x20, Instruction.Unsignedˉoperand);
                    if (!Trapped) Stack.Push(Locals[(int)Instruction.Unsignedˉoperand]);
                    break;
                case Opcode.Localˉstore:
                    Reader.Readˉindexed(0x21, Instruction.Unsignedˉoperand);
                    if (!Trapped) Locals[(int)Instruction.Unsignedˉoperand] = Stack.Pop();
                    break;
                case Opcode.Pop:
                    Reader.Require(Reader.Readˉbyte() == 0x1A, "The emitted drop opcode is invalid.");
                    if (!Trapped) _ = Stack.Pop();
                    break;
                case Opcode.I32ˉadd:
                    Readˉcheckedˉadd();
                    if (!Trapped)
                    {
                        var Right = Stack.Pop();
                        var Left = Stack.Pop();
                        try { Stack.Push(checked(Left + Right)); }
                        catch (OverflowException) { Trapped = true; Trapˉstep = Step; }
                    }
                    break;
                case Opcode.I32ˉsubtract:
                    Readˉcheckedˉsubtract();
                    if (!Trapped)
                    {
                        var Right = Stack.Pop();
                        var Left = Stack.Pop();
                        try { Stack.Push(checked(Left - Right)); }
                        catch (OverflowException) { Trapped = true; Trapˉstep = Step; }
                    }
                    break;
                case Opcode.I32ˉmultiply:
                    Readˉcheckedˉmultiply();
                    if (!Trapped)
                    {
                        var Right = Stack.Pop();
                        var Left = Stack.Pop();
                        try { Stack.Push(checked(Left * Right)); }
                        catch (OverflowException) { Trapped = true; Trapˉstep = Step; }
                    }
                    break;
                case Opcode.I32ˉnegate:
                    Readˉcheckedˉnegate();
                    if (!Trapped)
                    {
                        var Value = Stack.Pop();
                        try { Stack.Push(checked(-Value)); }
                        catch (OverflowException) { Trapped = true; Trapˉstep = Step; }
                    }
                    break;
                case Opcode.Return:
                    Reader.Readˉindexed(0x24, 1);
                    Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The success status is invalid.");
                    Reader.Require(Reader.Readˉbyte() == 0x0F, "The success return opcode is invalid.");
                    if (!Trapped) Result = Stack.Pop();
                    break;
                default:
                    throw new InvalidDataException(
                        $"Unsupported straight-i32 source opcode {Instruction.Opcode}.");
            }
        }

        Reader.Require(Reader.Readˉbyte() == 0x0B, "The straight-i32 body is unterminated.");
        Reader.Require(Reader.Position == Bodyˉend, "The straight-i32 body has trailing bytes.");
        Reader.Require(Reader.Position == Codeˉend, "The straight-i32 code section has trailing bytes.");
        Reader.Require(Reader.Position == Reader.Length, "The straight-i32 module has trailing bytes.");
        return Trapped
            ? new(3007, 0, Trapˉstep)
            : new(0, Result, Function.Instructions.Length);
    }

    private static void Validateˉmemoryˉwebassembly(
        ReadOnlySpan<byte> module,
        Verifiedˉmodule source,
        int outputˉkind)
    {
        Equal(1, source.Functions.Length);
        var Function = source.Functions[0];
        Equal("Main", Function.Declaration.Name);
        Equal(1, Function.Declaration.Parameterˉtypes.Length);
        Equal(4, Function.Instructions.Length);
        var Valueˉkind = outputˉkind == 1 ? Valueˉtype.Bytes : Valueˉtype.Text;
        Equal(Valueˉkind, Function.Declaration.Parameterˉtypes[0].Kind);
        Equal(Valueˉkind, Function.Declaration.Returnˉtype.Kind);
        Equal(1, Function.Declaration.Localˉtypes.Length);
        Equal(Valueˉkind, Function.Declaration.Localˉtypes[0].Kind);
        Equal(Opcode.Localˉload, Function.Instructions[0].Opcode);
        Equal(Opcode.Localˉstore, Function.Instructions[1].Opcode);
        Equal(Opcode.Localˉload, Function.Instructions[2].Opcode);
        Equal(Opcode.Return, Function.Instructions[3].Opcode);

        var Reader = new WebAssemblyˉtestˉreader(module);
        Reader.Readˉheader();

        var Typeˉend = Reader.Readˉsection(1);
        Reader.Require(Reader.Readˉuleb32() == 1, "The memory ABI type count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x60, "The memory ABI function type is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 2, "The memory ABI parameter count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The memory ABI budget type is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The memory ABI length type is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 1, "The memory ABI result count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The memory ABI status type is invalid.");
        Reader.Require(Reader.Position == Typeˉend, "The memory ABI type section has trailing bytes.");

        var Expectedˉfunctions = outputˉkind == 2 ? 2u : 1u;
        var Functionˉend = Reader.Readˉsection(3);
        Reader.Require(
            Reader.Readˉuleb32() == Expectedˉfunctions,
            "The memory ABI function count is invalid.");
        for (var Index = 0u; Index < Expectedˉfunctions; Index++)
        {
            Reader.Require(Reader.Readˉuleb32() == 0, "A memory ABI type index is invalid.");
        }
        Reader.Require(
            Reader.Position == Functionˉend,
            "The memory ABI function section has trailing bytes.");

        var Memoryˉend = Reader.Readˉsection(5);
        Reader.Require(Reader.Readˉuleb32() == 1, "The memory ABI memory count is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 1, "The memory ABI limits are not fixed.");
        Reader.Require(Reader.Readˉuleb32() == 129, "The memory ABI minimum is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 129, "The memory ABI maximum is invalid.");
        Reader.Require(
            Reader.Position == Memoryˉend,
            "The memory ABI memory section has trailing bytes.");

        var Globalˉend = Reader.Readˉsection(6);
        Reader.Require(Reader.Readˉuleb32() == 8, "The memory ABI global count is invalid.");
        Reader.Readˉglobal(0, 3);
        Reader.Readˉglobal(0, 65_536);
        Reader.Readˉglobal(0, 4_194_304);
        Reader.Readˉglobal(0, 4_259_840);
        Reader.Readˉglobal(0, 4_194_304);
        Reader.Readˉglobal(1, 0);
        Reader.Readˉglobal(0, outputˉkind);
        Reader.Readˉglobal(1, 0);
        Reader.Require(
            Reader.Position == Globalˉend,
            "The memory ABI global section has trailing bytes.");

        var Exportˉend = Reader.Readˉsection(7);
        Reader.Require(Reader.Readˉuleb32() == 10, "The memory ABI export count is invalid.");
        Reader.Readˉexport("Windvale.run", 0, 0);
        Reader.Readˉexport("Windvale.abi", 3, 0);
        Reader.Readˉexport("Windvale.memory", 2, 0);
        Reader.Readˉexport("Windvale.input_offset", 3, 1);
        Reader.Readˉexport("Windvale.input_capacity", 3, 2);
        Reader.Readˉexport("Windvale.output_offset", 3, 3);
        Reader.Readˉexport("Windvale.output_capacity", 3, 4);
        Reader.Readˉexport("Windvale.output_length", 3, 5);
        Reader.Readˉexport("Windvale.output_kind", 3, 6);
        Reader.Readˉexport("Windvale.instructions", 3, 7);
        Reader.Require(
            Reader.Position == Exportˉend,
            "The memory ABI export section has trailing bytes.");

        var Codeˉend = Reader.Readˉsection(10);
        Reader.Require(
            Reader.Readˉuleb32() == Expectedˉfunctions,
            "The memory ABI body count is invalid.");
        var Wrapperˉlength = Reader.Readˉuleb32();
        Reader.Require(
            Wrapperˉlength == (outputˉkind == 2 ? 138u : 122u),
            "The memory ABI wrapper length is invalid.");
        var Wrapperˉend = Reader.Position + checked((int)Wrapperˉlength);
        Reader.Require(Reader.Readˉuleb32() == 0, "The memory ABI wrapper has locals.");
        Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The output length reset is invalid.");
        Reader.Readˉindexed(0x24, 5);
        Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The instruction reset is invalid.");
        Reader.Readˉindexed(0x24, 7);
        Reader.Readˉindexed(0x20, 1);
        Reader.Require(Reader.Readˉi32ˉconstant() == 4_194_304, "The input limit is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x4B, "The input range comparison is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x04, "The input range branch is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x40, "The input range block type is invalid.");
        Reader.Require(Reader.Readˉi32ˉconstant() == 3008, "The input range status is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x0F, "The input range return is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x0B, "The input range branch is unterminated.");
        if (outputˉkind == 2)
        {
            Reader.Require(Reader.Readˉi32ˉconstant() == 65_536, "The UTF-8 input offset is invalid.");
            Reader.Readˉindexed(0x20, 1);
            Reader.Readˉindexed(0x10, 1);
            Reader.Require(Reader.Readˉbyte() == 0x45, "The UTF-8 result check is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x04, "The UTF-8 failure branch is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x40, "The UTF-8 failure block type is invalid.");
            Reader.Require(Reader.Readˉi32ˉconstant() == 3014, "The UTF-8 status is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x0F, "The UTF-8 failure return is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x0B, "The UTF-8 failure branch is unterminated.");
        }
        for (var Instruction = 0; Instruction < 4; Instruction++)
        {
            Reader.Readˉindexed(0x23, 7);
            Reader.Readˉindexed(0x20, 0);
            Reader.Require(Reader.Readˉbyte() == 0x4F, "A memory ABI meter comparison is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x04, "A memory ABI meter branch is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x40, "A memory ABI meter block type is invalid.");
            Reader.Require(Reader.Readˉi32ˉconstant() == 3011, "The memory ABI budget status is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x0F, "The memory ABI budget return is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x0B, "A memory ABI meter branch is unterminated.");
            Reader.Readˉindexed(0x23, 7);
            Reader.Require(Reader.Readˉi32ˉconstant() == 1, "A memory ABI charge is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x6A, "A memory ABI charge addition is invalid.");
            Reader.Readˉindexed(0x24, 7);
        }
        Reader.Require(Reader.Readˉi32ˉconstant() == 4_259_840, "The output copy offset is invalid.");
        Reader.Require(Reader.Readˉi32ˉconstant() == 65_536, "The input copy offset is invalid.");
        Reader.Readˉindexed(0x20, 1);
        Reader.Require(Reader.Readˉbyte() == 0xFC, "The memory copy prefix is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 10, "The memory copy opcode is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 0, "The memory copy target index is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 0, "The memory copy source index is invalid.");
        Reader.Readˉindexed(0x20, 1);
        Reader.Readˉindexed(0x24, 5);
        Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The memory ABI success status is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x0B, "The memory ABI wrapper is unterminated.");
        Reader.Require(Reader.Position == Wrapperˉend, "The memory ABI wrapper has trailing bytes.");

        if (outputˉkind == 2)
        {
            var Validatorˉlength = Reader.Readˉuleb32();
            Reader.Require(Validatorˉlength == 335, "The UTF-8 validator length is invalid.");
            var Validatorˉend = Reader.Position + checked((int)Validatorˉlength);
            Reader.Require(Reader.Readˉuleb32() == 1, "The UTF-8 validator local groups are invalid.");
            Reader.Require(Reader.Readˉuleb32() == 5, "The UTF-8 validator local count is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x7F, "The UTF-8 validator local type is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x02, "The UTF-8 validator outer block is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x40, "The UTF-8 validator block type is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x03, "The UTF-8 validator loop is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x40, "The UTF-8 validator loop type is invalid.");
            Reader.Skip(Validatorˉend - Reader.Position);
        }
        Reader.Require(Reader.Position == Codeˉend, "The memory ABI code section has trailing bytes.");
        Reader.Require(Reader.Position == Reader.Length, "The memory ABI module has trailing bytes.");
    }

    private static void Validateˉruntimeˉcallˉwebassembly(
        ReadOnlySpan<byte> module,
        Verifiedˉmodule source)
    {
        True(
            source.Functions.Length is >= 2 and <= 16,
            "The runtime-call function count is outside the profile.");
        True(
            source.Functions.Sum(Function => Function.Declaration.Codeˉlength) <=
                131_072,
            "The runtime-call aggregate code is outside the profile.");
        True(
            source.Functions.Sum(Function => Function.Instructions.Length) <=
                400_000,
            "The runtime-call aggregate instruction count is outside the profile.");
        var Rootˉfirstˉleaf = source.Functions.Length == 2 &&
            source.Functions[0].Declaration.Name == "Main";
        if (!Rootˉfirstˉleaf)
        {
            Equal("Main", source.Functions[^1].Declaration.Name);
        }
        for (var Functionˉindex = 0; Functionˉindex < source.Functions.Length;
            Functionˉindex++)
        {
            var Function = source.Functions[Functionˉindex];
            Equal(1, Function.Declaration.Parameterˉtypes.Length);
            Equal(Valueˉtype.Bytes, Function.Declaration.Parameterˉtypes[0].Kind);
            Equal(Valueˉtype.Bytes, Function.Declaration.Returnˉtype.Kind);
            True(
                Function.Declaration.Codeˉlength <=
                    (Rootˉfirstˉleaf ? 131_072 : 65_536),
                "A runtime-call function exceeds its profile code bound.");
            foreach (var Call in Function.Instructions.Where(Instruction =>
                Instruction.Opcode == Opcode.Call))
            {
                if (Rootˉfirstˉleaf && Functionˉindex == 0)
                {
                    Equal(1u, Call.Unsignedˉoperand);
                }
                else
                {
                    True(
                        Call.Unsignedˉoperand < (uint)Functionˉindex,
                        "A runtime call does not target a lower function ordinal.");
                }
            }
            if (Rootˉfirstˉleaf && Functionˉindex == 1)
            {
                True(
                    Function.Instructions.All(Instruction =>
                        Instruction.Opcode != Opcode.Call),
                    "The root-first runtime leaf contains a call.");
            }
        }

        var Reader = new WebAssemblyˉtestˉreader(module);
        Reader.Readˉheader();
        var Typeˉend = Reader.Readˉsection(1);
        Reader.Require(Reader.Readˉuleb32() == 2, "The runtime-call type count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x60, "The runtime-call wrapper type is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 2, "The runtime-call wrapper parameter count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The runtime-call budget type is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The runtime-call input-length type is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 1, "The runtime-call wrapper result count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The runtime-call status type is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x60, "The runtime-call private type is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 1, "The runtime-call private parameter count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7E, "The runtime-call descriptor parameter is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 1, "The runtime-call private result count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7E, "The runtime-call descriptor result is invalid.");
        Reader.Require(Reader.Position == Typeˉend, "The runtime-call type section has trailing bytes.");

        var Functionˉend = Reader.Readˉsection(3);
        Reader.Require(
            Reader.Readˉuleb32() == (uint)source.Functions.Length + 1u,
            "The runtime-call Wasm function count is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 0, "The runtime-call wrapper type index is invalid.");
        for (var Functionˉindex = 0; Functionˉindex < source.Functions.Length;
            Functionˉindex++)
        {
            Reader.Require(Reader.Readˉuleb32() == 1, "A runtime-call private type index is invalid.");
        }
        Reader.Require(Reader.Position == Functionˉend, "The runtime-call function section has trailing bytes.");

        var Memoryˉend = Reader.Readˉsection(5);
        Reader.Require(Reader.Readˉuleb32() == 1, "The runtime-call memory count is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 1, "The runtime-call memory is not fixed.");
        Reader.Require(Reader.Readˉuleb32() == 129, "The runtime-call memory minimum is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 129, "The runtime-call memory maximum is invalid.");
        Reader.Require(Reader.Position == Memoryˉend, "The runtime-call memory section has trailing bytes.");

        var Globalˉend = Reader.Readˉsection(6);
        Reader.Require(Reader.Readˉuleb32() == 11, "The runtime-call global count is invalid.");
        Reader.Readˉglobal(0, 3);
        Reader.Readˉglobal(0, 65_536);
        Reader.Readˉglobal(0, 4_194_304);
        Reader.Readˉglobal(0, 4_259_840);
        Reader.Readˉglobal(0, 4_194_304);
        Reader.Readˉglobal(1, 0);
        Reader.Readˉglobal(0, 1);
        Reader.Readˉglobal(1, 0);
        Reader.Readˉglobal(1, 0);
        Reader.Readˉglobal(1, 4_259_840);
        Reader.Readˉglobal(1, 0);
        Reader.Require(Reader.Position == Globalˉend, "The runtime-call global section has trailing bytes.");

        var Exportˉend = Reader.Readˉsection(7);
        Reader.Require(Reader.Readˉuleb32() == 10, "The runtime-call export count is invalid.");
        Reader.Readˉexport("Windvale.run", 0, 0);
        Reader.Readˉexport("Windvale.abi", 3, 0);
        Reader.Readˉexport("Windvale.memory", 2, 0);
        Reader.Readˉexport("Windvale.input_offset", 3, 1);
        Reader.Readˉexport("Windvale.input_capacity", 3, 2);
        Reader.Readˉexport("Windvale.output_offset", 3, 3);
        Reader.Readˉexport("Windvale.output_capacity", 3, 4);
        Reader.Readˉexport("Windvale.output_length", 3, 5);
        Reader.Readˉexport("Windvale.output_kind", 3, 6);
        Reader.Readˉexport("Windvale.instructions", 3, 7);
        Reader.Require(Reader.Position == Exportˉend, "The runtime-call export section has trailing bytes.");

        var Codeˉend = Reader.Readˉsection(10);
        Reader.Require(
            Reader.Readˉuleb32() == (uint)source.Functions.Length + 1u,
            "The runtime-call body count is invalid.");
        var Wrapperˉlength = Reader.Readˉuleb32();
        Reader.Require(Wrapperˉlength <= int.MaxValue, "The runtime-call wrapper is oversized.");
        var Wrapperˉend = Reader.Position + (int)Wrapperˉlength;
        Reader.Require(Reader.Readˉuleb32() == 2, "The runtime-call wrapper local groups are invalid.");
        Reader.Require(Reader.Readˉuleb32() == 2, "The runtime-call wrapper i32 local count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The runtime-call wrapper i32 local type is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 1, "The runtime-call wrapper descriptor count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7E, "The runtime-call wrapper descriptor type is invalid.");
        Reader.Skip(Wrapperˉend - Reader.Position);

        foreach (var Function in source.Functions)
        {
            var Bodyˉlength = Reader.Readˉuleb32();
            Reader.Require(Bodyˉlength <= int.MaxValue, "A runtime-call body is oversized.");
            var Bodyˉend = Reader.Position + (int)Bodyˉlength;
            Reader.Require(
                Reader.Readˉuleb32() == (uint)Function.Declaration.Localˉtypes.Length + 2u,
                "A runtime-call private local group count is invalid.");
            foreach (var Type in Function.Declaration.Localˉtypes)
            {
                Reader.Require(Reader.Readˉuleb32() == 1, "A runtime-call local is not singular.");
                Reader.Require(
                    Reader.Readˉbyte() == (Type.Kind == Valueˉtype.Bytes ? 0x7E : 0x7F),
                    "A runtime-call private local type changed.");
            }
            Reader.Require(Reader.Readˉuleb32() == 6, "The runtime-call i32 scratch count is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x7F, "The runtime-call i32 scratch type is invalid.");
            Reader.Require(Reader.Readˉuleb32() == 3, "The runtime-call descriptor scratch count is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x7E, "The runtime-call descriptor scratch type is invalid.");
            Reader.Skip(Bodyˉend - Reader.Position);
        }
        Reader.Require(Reader.Position == Codeˉend, "The runtime-call code section has trailing bytes.");
        Reader.Require(Reader.Position == Reader.Length, "The runtime-call module has trailing bytes.");
    }

    private static void Validateˉruntimeˉwebassembly(
        ReadOnlySpan<byte> module,
        Verifiedˉmodule source)
    {
        Equal(1, source.Functions.Length);
        var Function = source.Functions[0];
        Equal("Main", Function.Declaration.Name);
        Equal(1, Function.Declaration.Parameterˉtypes.Length);
        Equal(Valueˉtype.Bytes, Function.Declaration.Parameterˉtypes[0].Kind);
        Equal(Valueˉtype.Bytes, Function.Declaration.Returnˉtype.Kind);
        True(
            Function.Declaration.Localˉtypes.Length is >= 0 and <= 8_191,
            "The runtime-value local count is outside the profile.");
        True(
            Function.Declaration.Localˉtypes.All(Type =>
                Type.Kind is Valueˉtype.I32 or Valueˉtype.Bool or Valueˉtype.U8 or
                    Valueˉtype.U32 or Valueˉtype.Text or Valueˉtype.Bytes),
            "The runtime-value source contains a local type outside the profile.");
        var Hasˉcontrol = Function.Instructions.Any(Instruction =>
            Instruction.Opcode is Opcode.Jump or Opcode.Branchˉfalse);
        var Hasˉsha256 = Function.Instructions.Any(Instruction =>
            Instruction.Opcode == Opcode.Bytesˉsha256ˉhex);
        True(
            Function.Instructions.Length is >= 1 and <= 100_000 &&
                Function.Instructions.Any(Instruction =>
                    Instruction.Opcode == Opcode.Return) &&
                Function.Instructions[^1].Opcode is
                    Opcode.Jump or Opcode.Branchˉfalse or Opcode.Return,
            "The runtime-value source instruction shape is invalid.");
        True(
            Function.Instructions.All(Instruction => Instruction.Opcode is
                Opcode.I32ˉconst or Opcode.Boolˉconst or Opcode.U8ˉconst or
                Opcode.U32ˉconst or Opcode.Localˉload or Opcode.Localˉstore or
                Opcode.I32ˉadd or Opcode.I32ˉsubtract or Opcode.I32ˉmultiply or
                Opcode.I32ˉnegate or Opcode.I32ˉequal or Opcode.I32ˉnotˉequal or
                Opcode.I32ˉless or Opcode.I32ˉlessˉequal or
                Opcode.I32ˉgreater or Opcode.I32ˉgreaterˉequal or
                Opcode.Bytesˉlength or Opcode.Bytesˉslice or Opcode.Bytesˉreadˉu8 or
                Opcode.Bytesˉreadˉu16ˉlittle or Opcode.Bytesˉreadˉu32ˉlittle or
                Opcode.Bytesˉreadˉi32ˉlittle or Opcode.U32ˉfromˉu8 or
                Opcode.U32ˉadd or Opcode.U32ˉsubtract or Opcode.U32ˉmultiply or
                Opcode.U32ˉdivide or Opcode.U32ˉremainder or
                Opcode.U32ˉbitwiseˉand or Opcode.U32ˉbitwiseˉor or
                Opcode.U32ˉbitwiseˉxor or Opcode.U32ˉbitwiseˉnot or
                Opcode.U32ˉshiftˉleft or Opcode.U32ˉshiftˉright or
                Opcode.U32ˉequal or Opcode.U32ˉnotˉequal or
                Opcode.U32ˉless or Opcode.U32ˉlessˉequal or
                Opcode.U32ˉgreater or Opcode.U32ˉgreaterˉequal or
                Opcode.U8ˉequal or Opcode.U8ˉnotˉequal or
                Opcode.Bytesˉconcat or Opcode.Bytesˉfromˉu8 or
                Opcode.Bytesˉfromˉu16ˉlittle or Opcode.Bytesˉfromˉu32ˉlittle or
                Opcode.Bytesˉfromˉi32ˉlittle or Opcode.Textˉtoˉutf8 or
                Opcode.Bytesˉsha256ˉhex or Opcode.Jump or
                Opcode.Branchˉfalse or Opcode.Pop or Opcode.Return),
            "The runtime-value source opcode is outside the profile.");
        if (Hasˉcontrol)
        {
            var Boundaries = Function.Instructions
                .Select(Instruction => (uint)Instruction.Offset)
                .ToHashSet();
            foreach (var Control in Function.Instructions.Where(Instruction =>
                Instruction.Opcode is Opcode.Jump or Opcode.Branchˉfalse))
            {
                True(
                    Boundaries.Contains(Control.Unsignedˉoperand),
                    "A runtime-value control target is not an instruction boundary.");
                if (Control.Unsignedˉoperand != 0)
                {
                    var Previous = Function.Instructions.Last(Instruction =>
                        (uint)(Instruction.Offset + Instruction.Size) ==
                            Control.Unsignedˉoperand);
                    True(
                        Previous.Opcode is Opcode.Jump or Opcode.Branchˉfalse or
                            Opcode.Return,
                        "A runtime-value control target does not follow a terminator.");
                }
            }
        }

        var Reader = new WebAssemblyˉtestˉreader(module);
        Reader.Readˉheader();

        var Typeˉend = Reader.Readˉsection(1);
        Reader.Require(Reader.Readˉuleb32() == 3, "The runtime-value type count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x60, "The runtime-value function type is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 2, "The runtime-value parameter count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The runtime-value budget type is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The runtime-value input-length type is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 1, "The runtime-value result count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The runtime-value status type is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x60, "The runtime allocator type is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 1, "The runtime allocator arity is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The runtime allocator length type is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 1, "The runtime allocator result arity is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The runtime allocator pointer type is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x60, "The runtime reference type is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 2, "The runtime reference arity is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7E, "The runtime reference descriptor type is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The runtime reference action type is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 0, "The runtime reference result arity is invalid.");
        Reader.Require(Reader.Position == Typeˉend, "The runtime-value type section has trailing bytes.");

        var Functionˉend = Reader.Readˉsection(3);
        Reader.Require(Reader.Readˉuleb32() == 3, "The runtime-value function count is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 0, "The runtime-value type index is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 1, "The runtime allocator type index is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 2, "The runtime reference type index is invalid.");
        Reader.Require(Reader.Position == Functionˉend, "The runtime-value function section has trailing bytes.");

        var Memoryˉend = Reader.Readˉsection(5);
        Reader.Require(Reader.Readˉuleb32() == 1, "The runtime-value memory count is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 1, "The runtime-value memory is not fixed.");
        Reader.Require(Reader.Readˉuleb32() == 129, "The runtime-value memory minimum is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 129, "The runtime-value memory maximum is invalid.");
        Reader.Require(Reader.Position == Memoryˉend, "The runtime-value memory section has trailing bytes.");

        var Globalˉend = Reader.Readˉsection(6);
        Reader.Require(Reader.Readˉuleb32() == 8, "The runtime-value global count is invalid.");
        Reader.Readˉglobal(0, 3);
        Reader.Readˉglobal(0, 65_536);
        Reader.Readˉglobal(0, 4_194_304);
        Reader.Readˉglobal(0, 4_259_840);
        Reader.Readˉglobal(0, 4_194_304);
        Reader.Readˉglobal(1, 0);
        Reader.Readˉglobal(0, 1);
        Reader.Readˉglobal(1, 0);
        Reader.Require(Reader.Position == Globalˉend, "The runtime-value global section has trailing bytes.");

        var Exportˉend = Reader.Readˉsection(7);
        Reader.Require(Reader.Readˉuleb32() == 10, "The runtime-value export count is invalid.");
        Reader.Readˉexport("Windvale.run", 0, 0);
        Reader.Readˉexport("Windvale.abi", 3, 0);
        Reader.Readˉexport("Windvale.memory", 2, 0);
        Reader.Readˉexport("Windvale.input_offset", 3, 1);
        Reader.Readˉexport("Windvale.input_capacity", 3, 2);
        Reader.Readˉexport("Windvale.output_offset", 3, 3);
        Reader.Readˉexport("Windvale.output_capacity", 3, 4);
        Reader.Readˉexport("Windvale.output_length", 3, 5);
        Reader.Readˉexport("Windvale.output_kind", 3, 6);
        Reader.Readˉexport("Windvale.instructions", 3, 7);
        Reader.Require(Reader.Position == Exportˉend, "The runtime-value export section has trailing bytes.");

        var Codeˉend = Reader.Readˉsection(10);
        Reader.Require(Reader.Readˉuleb32() == 3, "The runtime-value body count is invalid.");
        var Bodyˉlength = Reader.Readˉuleb32();
        Reader.Require(Bodyˉlength <= int.MaxValue, "The runtime-value body is oversized.");
        var Bodyˉend = Reader.Position + (int)Bodyˉlength;
        Reader.Require(Bodyˉend < Codeˉend, "The runtime-value body extent is invalid.");
        Reader.Require(
            Reader.Readˉuleb32() ==
                (uint)(Function.Declaration.Parameterˉtypes.Length +
                    Function.Declaration.Localˉtypes.Length + 2),
            "The runtime-value local group count is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 1, "The runtime-value parameter local is not singular.");
        Reader.Require(Reader.Readˉbyte() == 0x7E, "The runtime-value parameter descriptor type is invalid.");
        foreach (var Type in Function.Declaration.Localˉtypes)
        {
            Reader.Require(Reader.Readˉuleb32() == 1, "A runtime-value local group is not singular.");
            Reader.Require(
                Reader.Readˉbyte() ==
                    (Type.Kind is Valueˉtype.Text or Valueˉtype.Bytes ? 0x7E : 0x7F),
                "A runtime-value Wasm local type changed.");
        }
        Reader.Require(
            Reader.Readˉuleb32() == (Hasˉcontrol ? 6u : 5u),
            "The runtime-value i32 scratch count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The runtime-value i32 scratch type is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 3, "The runtime-value descriptor scratch count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7E, "The runtime-value descriptor scratch type is invalid.");

        var Depth = 0;
        var Meterˉglobalˉreads = 0;
        var Outputˉlengthˉwrites = 0;
        var Memoryˉcopies = 0;
        var Memoryˉfills = 0;
        var Allocatorˉcalls = 0;
        var Referenceˉcalls = 0;
        var Memoryˉreads = 0;
        var Memoryˉwrites = 0;
        var Sha256ˉrotates = 0;
        var Sha256ˉselects = 0;
        var Blockˉcount = 0;
        var Loopˉcount = 0;
        var Elseˉcount = 0;
        var Branchˉcount = 0;
        var Programˉcounterˉaccesses = 0;
        var Programˉcounter =
            (uint)Function.Declaration.Allˉlocalˉtypes.Length + 7u;
        var Terminated = false;
        while (Reader.Position < Bodyˉend)
        {
            var Opcodeˉvalue = Reader.Readˉbyte();
            switch (Opcodeˉvalue)
            {
                case 0x02:
                    Reader.Require(Reader.Readˉbyte() == 0x40, "A runtime-value block type is invalid.");
                    Blockˉcount++;
                    Depth++;
                    break;
                case 0x03:
                    Reader.Require(Reader.Readˉbyte() == 0x40, "A runtime-value loop type is invalid.");
                    Loopˉcount++;
                    Depth++;
                    break;
                case 0x04:
                    Reader.Require(Reader.Readˉbyte() == 0x40, "A runtime-value if block type is invalid.");
                    Depth++;
                    break;
                case 0x05:
                    Reader.Require(Depth > 0, "A runtime-value else appears outside a block.");
                    Elseˉcount++;
                    break;
                case 0x0B:
                    if (Depth == 0)
                    {
                        Reader.Require(Reader.Position == Bodyˉend, "The runtime-value body ended early.");
                        Terminated = true;
                    }
                    else
                    {
                        Depth--;
                    }
                    break;
                case 0x0F:
                case 0x1A:
                case 0x45:
                case 0x46:
                case 0x47:
                case 0x48:
                case 0x49:
                case 0x4A:
                case 0x4B:
                case 0x4C:
                case 0x4D:
                case 0x4E:
                case 0x4F:
                case 0x52:
                case 0x56:
                case 0x6A:
                case 0x6B:
                case 0x6C:
                case 0x6E:
                case 0x70:
                case 0x71:
                case 0x72:
                case 0x73:
                case 0x74:
                case 0x76:
                case 0x7E:
                case 0x84:
                case 0x86:
                case 0x88:
                case 0xA7:
                case 0xAC:
                case 0xAD:
                    break;
                case 0x1B:
                    Sha256ˉselects++;
                    break;
                case 0x78:
                    Sha256ˉrotates++;
                    break;
                case 0x20:
                case 0x21:
                case 0x22:
                    if (Reader.Readˉuleb32() == Programˉcounter)
                    {
                        Programˉcounterˉaccesses++;
                    }
                    break;
                case 0x0C:
                    Reader.Readˉuleb32();
                    Branchˉcount++;
                    break;
                case 0x0D:
                    Reader.Readˉuleb32();
                    break;
                case 0x10:
                    var Calledˉfunction = Reader.Readˉuleb32();
                    if (Calledˉfunction == 1) Allocatorˉcalls++;
                    if (Calledˉfunction == 2) Referenceˉcalls++;
                    Reader.Require(
                        Calledˉfunction is 1 or 2,
                        "The runtime-value body calls an unexpected function.");
                    break;
                case 0x23:
                    if (Reader.Readˉuleb32() == 7) Meterˉglobalˉreads++;
                    break;
                case 0x24:
                    if (Reader.Readˉuleb32() == 5) Outputˉlengthˉwrites++;
                    break;
                case 0x28:
                case 0x2D:
                case 0x2F:
                    Reader.Readˉuleb32();
                    Reader.Readˉuleb32();
                    Memoryˉreads++;
                    break;
                case 0x36:
                case 0x3A:
                case 0x3B:
                    Reader.Readˉuleb32();
                    Reader.Readˉuleb32();
                    Memoryˉwrites++;
                    break;
                case 0x41:
                    Reader.Readˉsleb32();
                    break;
                case 0x42:
                    Reader.Readˉsleb64();
                    break;
                case 0xFC:
                    var Bulkˉopcode = Reader.Readˉuleb32();
                    if (Bulkˉopcode == 10)
                    {
                        Reader.Require(Reader.Readˉuleb32() == 0, "A runtime-value copy target memory is invalid.");
                        Reader.Require(Reader.Readˉuleb32() == 0, "A runtime-value copy source memory is invalid.");
                        Memoryˉcopies++;
                    }
                    else
                    {
                        Reader.Require(Bulkˉopcode == 11, "A runtime-value bulk-memory opcode is invalid.");
                        Reader.Require(Reader.Readˉuleb32() == 0, "A runtime-value fill memory is invalid.");
                        Memoryˉfills++;
                    }
                    break;
                default:
                    throw new InvalidDataException(
                        $"Unsupported runtime-value Wasm opcode 0x{Opcodeˉvalue:X2}.");
            }
        }
        Reader.Require(Terminated && Depth == 0, "The runtime-value body is unterminated.");
        Reader.Require(
            Meterˉglobalˉreads == Function.Instructions.Length * 2,
            "The runtime-value instruction meter count changed.");
        var Returnˉcount = Function.Instructions.Count(Instruction =>
            Instruction.Opcode == Opcode.Return);
        Reader.Require(
            Outputˉlengthˉwrites == Returnˉcount + 1,
            "The runtime-value output publication count changed.");
        Reader.Require(
            Memoryˉcopies >= Returnˉcount,
            "The runtime-value body does not publish each return through memory copy.");
        Reader.Require(
            Memoryˉfills == 1,
            "The runtime-value allocator metadata is not reset exactly once.");
        Reader.Require(
            Allocatorˉcalls > 0 ||
                !Function.Instructions.Any(Instruction => Instruction.Opcode is
                    Opcode.Bytesˉconcat or Opcode.Bytesˉfromˉu8 or
                    Opcode.Bytesˉfromˉu16ˉlittle or
                    Opcode.Bytesˉfromˉu32ˉlittle or
                    Opcode.Bytesˉfromˉi32ˉlittle or
                    Opcode.Bytesˉsha256ˉhex),
            "The runtime-value dynamic allocator is not called by an allocating opcode.");
        Reader.Require(
            Referenceˉcalls > 0 ||
                !Function.Declaration.Allˉlocalˉtypes.Any(Type =>
                    Type.Kind is Valueˉtype.Text or Valueˉtype.Bytes),
            "The runtime-value descriptor reference function is not used.");
        Reader.Require(
            !Hasˉsha256 ||
                (Blockˉcount >= 3 && Loopˉcount >= 4 &&
                    Memoryˉreads >= 1_000 && Memoryˉwrites >= 700 &&
                    Sha256ˉrotates >= 388 && Sha256ˉselects >= 64),
            "The runtime-value SHA-256 lowering evidence changed.");
        Reader.Require(
            !Hasˉcontrol ||
                ((!Hasˉsha256 && Loopˉcount == 1 &&
                    Elseˉcount >= Function.Instructions.Count(Instruction =>
                        Instruction.Opcode == Opcode.Branchˉfalse) &&
                    Branchˉcount >= Function.Instructions.Count(Instruction =>
                        Instruction.Opcode is Opcode.Jump or Opcode.Branchˉfalse) &&
                    Programˉcounterˉaccesses >= Branchˉcount) ||
                (Hasˉsha256 &&
                    Elseˉcount >= Function.Instructions.Count(Instruction =>
                        Instruction.Opcode == Opcode.Branchˉfalse) &&
                    Programˉcounterˉaccesses >= Function.Instructions.Count(Instruction =>
                        Instruction.Opcode is Opcode.Jump or Opcode.Branchˉfalse))),
            "The runtime-value control dispatcher evidence changed.");
        Reader.Require(Reader.Position == Bodyˉend, "The runtime-value wrapper has trailing bytes.");

        var Allocatorˉlength = Reader.Readˉuleb32();
        Reader.Require(Allocatorˉlength is >= 128 and <= 2_048, "The runtime allocator body extent is invalid.");
        var Allocatorˉend = Reader.Position + checked((int)Allocatorˉlength);
        Reader.Require(Reader.Readˉuleb32() == 1, "The runtime allocator local groups are invalid.");
        Reader.Require(Reader.Readˉuleb32() == 8, "The runtime allocator local count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The runtime allocator local type is invalid.");
        Reader.Skip(Allocatorˉend - Reader.Position - 1);
        Reader.Require(Reader.Readˉbyte() == 0x0B, "The runtime allocator body is unterminated.");

        var Referenceˉlength = Reader.Readˉuleb32();
        Reader.Require(Referenceˉlength is >= 128 and <= 2_048, "The runtime reference body extent is invalid.");
        var Referenceˉend = Reader.Position + checked((int)Referenceˉlength);
        Reader.Require(Reader.Readˉuleb32() == 1, "The runtime reference local groups are invalid.");
        Reader.Require(Reader.Readˉuleb32() == 9, "The runtime reference local count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The runtime reference local type is invalid.");
        Reader.Skip(Referenceˉend - Reader.Position - 1);
        Reader.Require(Reader.Readˉbyte() == 0x0B, "The runtime reference body is unterminated.");
        Reader.Require(Reader.Position == Codeˉend, "The runtime-value code section has trailing bytes.");
        Reader.Require(Reader.Position == Reader.Length, "The runtime-value module has trailing bytes.");
    }

    private static void Validateˉboundedˉcallˉwebassembly(
        ReadOnlySpan<byte> module,
        Verifiedˉmodule source)
    {
        True(
            source.Functions.Length is >= 2 and <= 8,
            "The bounded-call source function count is invalid.");
        var Mainˉexport = source.Module.Exports.Single(Export => Export.Name == "Main");
        Equal(source.Functions.Length - 1, Mainˉexport.Targetˉindex);
        True(
            source.Functions.All(Function =>
                Function.Declaration.Parameterˉtypes.Length <= 2 &&
                Function.Declaration.Parameterˉtypes.All(Type => Type.Kind == Valueˉtype.I32) &&
                Function.Declaration.Localˉtypes.All(Type =>
                    Type.Kind is Valueˉtype.I32 or Valueˉtype.Bool) &&
                Function.Declaration.Returnˉtype.Kind == Valueˉtype.I32),
            "The bounded-call source contains a type outside the profile.");

        var Reader = new WebAssemblyˉtestˉreader(module);
        Reader.Readˉheader();

        var Typeˉend = Reader.Readˉsection(1);
        Reader.Require(
            Reader.Readˉuleb32() == (uint)source.Functions.Length + 1,
            "The bounded-call type count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x60, "The bounded-call wrapper type is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 1, "The bounded-call budget arity is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The bounded-call budget type is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 1, "The bounded-call status arity is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The bounded-call status type is invalid.");
        foreach (var Function in source.Functions)
        {
            Reader.Require(Reader.Readˉbyte() == 0x60, "A bounded-call function type is invalid.");
            Reader.Require(
                Reader.Readˉuleb32() == (uint)Function.Declaration.Parameterˉtypes.Length,
                "A bounded-call parameter count changed.");
            foreach (var _ in Function.Declaration.Parameterˉtypes)
            {
                Reader.Require(Reader.Readˉbyte() == 0x7F, "A bounded-call parameter type changed.");
            }
            Reader.Require(Reader.Readˉuleb32() == 1, "A bounded-call result arity is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x7F, "A bounded-call result type changed.");
        }
        Reader.Require(Reader.Position == Typeˉend, "The bounded-call type section has trailing bytes.");

        var Functionˉend = Reader.Readˉsection(3);
        Reader.Require(
            Reader.Readˉuleb32() == (uint)source.Functions.Length + 1,
            "The bounded-call function count is invalid.");
        for (var Index = 0; Index <= source.Functions.Length; Index++)
        {
            Reader.Require(
                Reader.Readˉuleb32() == (uint)Index,
                "A bounded-call function type index is invalid.");
        }
        Reader.Require(
            Reader.Position == Functionˉend,
            "The bounded-call function section has trailing bytes.");

        var Globalˉend = Reader.Readˉsection(6);
        Reader.Require(Reader.Readˉuleb32() == 5, "The bounded-call global count is invalid.");
        Reader.Readˉglobal(0, 2);
        Reader.Readˉglobal(1, 0);
        Reader.Readˉglobal(1, 0);
        Reader.Readˉglobal(1, 0);
        Reader.Readˉglobal(1, 0);
        Reader.Require(
            Reader.Position == Globalˉend,
            "The bounded-call global section has trailing bytes.");

        var Exportˉend = Reader.Readˉsection(7);
        Reader.Require(Reader.Readˉuleb32() == 4, "The bounded-call export count is invalid.");
        Reader.Readˉexport("Windvale.run", 0, 0);
        Reader.Readˉexport("Windvale.abi", 3, 0);
        Reader.Readˉexport("Windvale.result", 3, 1);
        Reader.Readˉexport("Windvale.instructions", 3, 2);
        Reader.Require(
            Reader.Position == Exportˉend,
            "The bounded-call export section has trailing bytes.");

        var Codeˉend = Reader.Readˉsection(10);
        Reader.Require(
            Reader.Readˉuleb32() == (uint)source.Functions.Length + 1,
            "The bounded-call body count is invalid.");
        var Wrapperˉlength = Reader.Readˉuleb32();
        Reader.Require(Wrapperˉlength <= int.MaxValue, "The bounded-call wrapper is oversized.");
        var Wrapperˉend = Reader.Position + (int)Wrapperˉlength;
        Reader.Require(Reader.Readˉuleb32() == 1, "The bounded-call wrapper local groups are invalid.");
        Reader.Require(Reader.Readˉuleb32() == 1, "The bounded-call wrapper local count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The bounded-call wrapper local type is invalid.");
        Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The bounded-call result reset is invalid.");
        Reader.Readˉindexed(0x24, 1);
        Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The bounded-call counter reset is invalid.");
        Reader.Readˉindexed(0x24, 2);
        Reader.Readˉindexed(0x20, 0);
        Reader.Readˉindexed(0x24, 3);
        Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The bounded-call status reset is invalid.");
        Reader.Readˉindexed(0x24, 4);
        Reader.Readˉindexed(0x10, (uint)Mainˉexport.Targetˉindex + 1);
        Reader.Readˉindexed(0x21, 1);
        Reader.Readˉindexed(0x23, 4);
        Reader.Require(Reader.Readˉbyte() == 0x45, "The bounded-call success check is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x04, "The bounded-call success branch is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x40, "The bounded-call success block type is invalid.");
        Reader.Readˉindexed(0x20, 1);
        Reader.Readˉindexed(0x24, 1);
        Reader.Require(Reader.Readˉbyte() == 0x0B, "The bounded-call success branch is unterminated.");
        Reader.Readˉindexed(0x23, 4);
        Reader.Require(Reader.Readˉbyte() == 0x0B, "The bounded-call wrapper is unterminated.");
        Reader.Require(Reader.Position == Wrapperˉend, "The bounded-call wrapper has trailing bytes.");

        void Readˉmeter()
        {
            Reader.Readˉindexed(0x23, 2);
            Reader.Readˉindexed(0x23, 3);
            Reader.Require(Reader.Readˉbyte() == 0x4F, "The bounded-call budget comparison is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x04, "The bounded-call exhaustion branch is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x40, "The bounded-call exhaustion block type is invalid.");
            Reader.Require(Reader.Readˉi32ˉconstant() == 3011, "The bounded-call exhaustion status is invalid.");
            Reader.Readˉindexed(0x24, 4);
            Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The bounded-call exhaustion result is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x0F, "The bounded-call exhaustion return is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x0B, "The bounded-call exhaustion branch is unterminated.");
            Reader.Readˉindexed(0x23, 2);
            Reader.Require(Reader.Readˉi32ˉconstant() == 1, "The bounded-call charge is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x6A, "The bounded-call charge addition is invalid.");
            Reader.Readˉindexed(0x24, 2);
        }

        void Readˉoverflowˉreturn()
        {
            Reader.Require(Reader.Readˉbyte() == 0x04, "The bounded-call overflow branch is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x40, "The bounded-call overflow block type is invalid.");
            Reader.Require(Reader.Readˉi32ˉconstant() == 3007, "The bounded-call overflow status is invalid.");
            Reader.Readˉindexed(0x24, 4);
            Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The bounded-call overflow result is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x0F, "The bounded-call overflow return is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x0B, "The bounded-call overflow branch is unterminated.");
        }

        void Readˉcheckedˉadd(uint Left, uint Right, uint Result)
        {
            Reader.Readˉindexed(0x21, Right);
            Reader.Readˉindexed(0x21, Left);
            Reader.Readˉindexed(0x20, Left);
            Reader.Readˉindexed(0x20, Right);
            Reader.Require(Reader.Readˉbyte() == 0x6A, "The bounded-call checked add is invalid.");
            Reader.Readˉindexed(0x22, Result);
            Reader.Readˉindexed(0x20, Left);
            Reader.Require(Reader.Readˉbyte() == 0x73, "The bounded-call checked add xor is invalid.");
            Reader.Readˉindexed(0x20, Result);
            Reader.Readˉindexed(0x20, Right);
            Reader.Require(Reader.Readˉbyte() == 0x73, "The bounded-call checked add xor is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x71, "The bounded-call checked add mask is invalid.");
            Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The bounded-call checked add sign is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x48, "The bounded-call checked add comparison is invalid.");
            Readˉoverflowˉreturn();
            Reader.Readˉindexed(0x20, Result);
        }

        void Readˉcheckedˉsubtract(uint Left, uint Right, uint Result)
        {
            Reader.Readˉindexed(0x21, Right);
            Reader.Readˉindexed(0x21, Left);
            Reader.Readˉindexed(0x20, Left);
            Reader.Readˉindexed(0x20, Right);
            Reader.Require(Reader.Readˉbyte() == 0x6B, "The bounded-call checked subtraction is invalid.");
            Reader.Readˉindexed(0x22, Result);
            Reader.Readˉindexed(0x20, Left);
            Reader.Require(Reader.Readˉbyte() == 0x73, "The bounded-call checked subtraction xor is invalid.");
            Reader.Readˉindexed(0x20, Left);
            Reader.Readˉindexed(0x20, Right);
            Reader.Require(Reader.Readˉbyte() == 0x73, "The bounded-call checked subtraction xor is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x71, "The bounded-call checked subtraction mask is invalid.");
            Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The bounded-call checked subtraction sign is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x48, "The bounded-call checked subtraction comparison is invalid.");
            Readˉoverflowˉreturn();
            Reader.Readˉindexed(0x20, Result);
        }

        void Readˉcheckedˉmultiply(uint Left, uint Right, uint Result, uint Wide)
        {
            Reader.Readˉindexed(0x21, Right);
            Reader.Readˉindexed(0x21, Left);
            Reader.Readˉindexed(0x20, Left);
            Reader.Require(Reader.Readˉbyte() == 0xAC, "The bounded-call multiply extension is invalid.");
            Reader.Readˉindexed(0x20, Right);
            Reader.Require(Reader.Readˉbyte() == 0xAC, "The bounded-call multiply extension is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x7E, "The bounded-call multiply is invalid.");
            Reader.Readˉindexed(0x22, Wide);
            Reader.Require(Reader.Readˉbyte() == 0xA7, "The bounded-call multiply wrap is invalid.");
            Reader.Readˉindexed(0x22, Result);
            Reader.Require(Reader.Readˉbyte() == 0xAC, "The bounded-call multiply result extension is invalid.");
            Reader.Readˉindexed(0x20, Wide);
            Reader.Require(Reader.Readˉbyte() == 0x52, "The bounded-call multiply comparison is invalid.");
            Readˉoverflowˉreturn();
            Reader.Readˉindexed(0x20, Result);
        }

        void Readˉcheckedˉnegate(uint Value)
        {
            Reader.Readˉindexed(0x21, Value);
            Reader.Readˉindexed(0x20, Value);
            Reader.Require(Reader.Readˉi32ˉconstant() == int.MinValue, "The bounded-call negate minimum is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x46, "The bounded-call negate comparison is invalid.");
            Readˉoverflowˉreturn();
            Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The bounded-call negate zero is invalid.");
            Reader.Readˉindexed(0x20, Value);
            Reader.Require(Reader.Readˉbyte() == 0x6B, "The bounded-call negate subtraction is invalid.");
        }

        for (var Functionˉindex = 0; Functionˉindex < source.Functions.Length; Functionˉindex++)
        {
            var Function = source.Functions[Functionˉindex];
            var Loopˉheaders = new HashSet<uint>();
            var Loopˉbranches = new HashSet<int>();
            var Conditionalˉends = new HashSet<uint>();
            var Elseˉjumps = new HashSet<int>();
            foreach (var Branch in Function.Instructions.Where(Instruction =>
                Instruction.Opcode == Opcode.Branchˉfalse))
            {
                var Falseˉtarget = Branch.Unsignedˉoperand;
                var Regionˉinstructions = Function.Instructions.Where(Instruction =>
                    Instruction.Offset >= Branch.Offset + Branch.Size &&
                    (uint)Instruction.Offset < Falseˉtarget).ToArray();
                var Backwardˉjumps = Regionˉinstructions.Where(Instruction =>
                    Instruction.Opcode == Opcode.Jump &&
                    Instruction.Unsignedˉoperand < (uint)Instruction.Offset).ToArray();
                var Forwardˉjumps = Regionˉinstructions.Where(Instruction =>
                    Instruction.Opcode == Opcode.Jump &&
                    Instruction.Unsignedˉoperand >
                        (uint)(Instruction.Offset + Instruction.Size)).ToArray();
                True(
                    Backwardˉjumps.Length <= 1 && Forwardˉjumps.Length <= 1,
                    "A bounded-call control region is not sequential.");
                True(
                    Backwardˉjumps.Length == 0 || Forwardˉjumps.Length == 0,
                    "A bounded-call control region mixes loop and conditional exits.");
                if (Backwardˉjumps.Length == 1)
                {
                    Loopˉheaders.Add(Backwardˉjumps[0].Unsignedˉoperand);
                    Loopˉbranches.Add(Branch.Offset);
                }
                else if (Forwardˉjumps.Length == 1)
                {
                    Elseˉjumps.Add(Forwardˉjumps[0].Offset);
                    Conditionalˉends.Add(Forwardˉjumps[0].Unsignedˉoperand);
                }
                else
                {
                    Conditionalˉends.Add(Falseˉtarget);
                }
            }
            var Bodyˉlength = Reader.Readˉuleb32();
            Reader.Require(Bodyˉlength <= int.MaxValue, "A bounded-call body is oversized.");
            var Bodyˉend = Reader.Position + (int)Bodyˉlength;
            var Localˉcount = Function.Declaration.Allˉlocalˉtypes.Length;
            var Scratchˉleft = (uint)Localˉcount;
            var Scratchˉright = Scratchˉleft + 1;
            var Scratchˉresult = Scratchˉleft + 2;
            var Scratchˉwide = Scratchˉleft + 3;
            Reader.Require(Reader.Readˉuleb32() == 2, "A bounded-call local group count is invalid.");
            Reader.Require(
                Reader.Readˉuleb32() == (uint)Function.Declaration.Localˉtypes.Length + 3,
                "A bounded-call i32 local count is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x7F, "A bounded-call local type is invalid.");
            Reader.Require(Reader.Readˉuleb32() == 1, "A bounded-call i64 local count is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x7E, "A bounded-call wide local type is invalid.");

            foreach (var Instruction in Function.Instructions)
            {
                if (Conditionalˉends.Contains((uint)Instruction.Offset))
                {
                    Reader.Require(
                        Reader.Readˉbyte() == 0x0B,
                        "A bounded-call conditional is unterminated.");
                }
                if (Loopˉheaders.Contains((uint)Instruction.Offset))
                {
                    Reader.Require(
                        Reader.Readˉbyte() == 0x02,
                        "A bounded-call loop block is missing.");
                    Reader.Require(
                        Reader.Readˉbyte() == 0x40,
                        "A bounded-call loop block type is invalid.");
                    Reader.Require(
                        Reader.Readˉbyte() == 0x03,
                        "A bounded-call loop is missing.");
                    Reader.Require(
                        Reader.Readˉbyte() == 0x40,
                        "A bounded-call loop type is invalid.");
                }
                Readˉmeter();
                switch (Instruction.Opcode)
                {
                    case Opcode.I32ˉconst:
                        Reader.Require(
                            Reader.Readˉi32ˉconstant() == Instruction.Signedˉoperand,
                            "A bounded-call constant changed value.");
                        break;
                    case Opcode.Localˉload:
                        Reader.Readˉindexed(0x20, Instruction.Unsignedˉoperand);
                        break;
                    case Opcode.Localˉstore:
                        Reader.Readˉindexed(0x21, Instruction.Unsignedˉoperand);
                        break;
                    case Opcode.I32ˉadd:
                        Readˉcheckedˉadd(Scratchˉleft, Scratchˉright, Scratchˉresult);
                        break;
                    case Opcode.I32ˉsubtract:
                        Readˉcheckedˉsubtract(Scratchˉleft, Scratchˉright, Scratchˉresult);
                        break;
                    case Opcode.I32ˉmultiply:
                        Readˉcheckedˉmultiply(
                            Scratchˉleft,
                            Scratchˉright,
                            Scratchˉresult,
                            Scratchˉwide);
                        break;
                    case Opcode.I32ˉnegate:
                        Readˉcheckedˉnegate(Scratchˉleft);
                        break;
                    case Opcode.I32ˉequal:
                        Reader.Require(Reader.Readˉbyte() == 0x46, "A bounded-call equality changed.");
                        break;
                    case Opcode.I32ˉnotˉequal:
                        Reader.Require(Reader.Readˉbyte() == 0x47, "A bounded-call inequality changed.");
                        break;
                    case Opcode.I32ˉless:
                        Reader.Require(Reader.Readˉbyte() == 0x48, "A bounded-call less-than changed.");
                        break;
                    case Opcode.I32ˉlessˉequal:
                        Reader.Require(Reader.Readˉbyte() == 0x4C, "A bounded-call less-or-equal changed.");
                        break;
                    case Opcode.I32ˉgreater:
                        Reader.Require(Reader.Readˉbyte() == 0x4A, "A bounded-call greater-than changed.");
                        break;
                    case Opcode.I32ˉgreaterˉequal:
                        Reader.Require(Reader.Readˉbyte() == 0x4E, "A bounded-call greater-or-equal changed.");
                        break;
                    case Opcode.Jump:
                        if (Instruction.Unsignedˉoperand < (uint)Instruction.Offset)
                        {
                            Reader.Readˉindexed(0x0C, 0);
                            Reader.Require(Reader.Readˉbyte() == 0x0B, "A bounded-call loop is unterminated.");
                            Reader.Require(Reader.Readˉbyte() == 0x0B, "A bounded-call loop block is unterminated.");
                        }
                        else if (Elseˉjumps.Contains(Instruction.Offset))
                        {
                            Reader.Require(Reader.Readˉbyte() == 0x05, "A bounded-call else marker is missing.");
                        }
                        break;
                    case Opcode.Branchˉfalse:
                        if (Loopˉbranches.Contains(Instruction.Offset))
                        {
                            Reader.Require(Reader.Readˉbyte() == 0x45, "A bounded-call loop condition is not inverted.");
                            Reader.Readˉindexed(0x0D, 1);
                        }
                        else
                        {
                            Reader.Require(Reader.Readˉbyte() == 0x04, "A bounded-call conditional is missing.");
                            Reader.Require(Reader.Readˉbyte() == 0x40, "A bounded-call conditional type is invalid.");
                        }
                        break;
                    case Opcode.Call:
                        True(
                            Instruction.Unsignedˉoperand < (uint)Functionˉindex,
                            "The bounded-call source contains a forward call.");
                        Reader.Readˉindexed(0x10, Instruction.Unsignedˉoperand + 1);
                        Reader.Readˉindexed(0x21, Scratchˉleft);
                        Reader.Readˉindexed(0x23, 4);
                        Reader.Require(Reader.Readˉbyte() == 0x04, "The bounded-call status branch is invalid.");
                        Reader.Require(Reader.Readˉbyte() == 0x40, "The bounded-call status block type is invalid.");
                        Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The bounded-call propagated result is invalid.");
                        Reader.Require(Reader.Readˉbyte() == 0x0F, "The bounded-call status return is invalid.");
                        Reader.Require(Reader.Readˉbyte() == 0x0B, "The bounded-call status branch is unterminated.");
                        Reader.Readˉindexed(0x20, Scratchˉleft);
                        break;
                    case Opcode.Pop:
                        Reader.Require(Reader.Readˉbyte() == 0x1A, "The bounded-call drop opcode is invalid.");
                        break;
                    case Opcode.Return:
                        Reader.Require(Reader.Readˉbyte() == 0x0F, "The bounded-call return opcode is invalid.");
                        break;
                    default:
                        throw new InvalidDataException(
                            $"Unsupported bounded-call source opcode {Instruction.Opcode}.");
                }
            }
            Reader.Require(Reader.Readˉbyte() == 0x0B, "A bounded-call body is unterminated.");
            Reader.Require(Reader.Position == Bodyˉend, "A bounded-call body has trailing bytes.");
        }
        Reader.Require(Reader.Position == Codeˉend, "The bounded-call code section has trailing bytes.");
        Reader.Require(Reader.Position == Reader.Length, "The bounded-call module has trailing bytes.");
    }

    private static void Validateˉmeteredˉcontrolˉwebassembly(
        ReadOnlySpan<byte> module,
        Verifiedˉmodule source)
    {
        Equal(1, source.Functions.Length);
        var Function = source.Functions[0];
        Equal("Main", Function.Declaration.Name);
        Equal(Valueˉtype.I32, Function.Declaration.Returnˉtype.Kind);
        True(
            Function.Declaration.Localˉtypes.All(Type =>
                Type.Kind is Valueˉtype.I32 or Valueˉtype.Bool),
            "The metered-loop fixture contains an unsupported local type.");
        var Loopˉheaders = new HashSet<uint>();
        var Loopˉbranches = new HashSet<int>();
        var Conditionalˉends = new HashSet<uint>();
        var Elseˉjumps = new HashSet<int>();
        foreach (var Branch in Function.Instructions.Where(Instruction =>
            Instruction.Opcode == Opcode.Branchˉfalse))
        {
            var Falseˉtarget = Branch.Unsignedˉoperand;
            var Regionˉinstructions = Function.Instructions.Where(Instruction =>
                Instruction.Offset >= Branch.Offset + Branch.Size &&
                (uint)Instruction.Offset < Falseˉtarget).ToArray();
            var Backwardˉjumps = Regionˉinstructions.Where(Instruction =>
                Instruction.Opcode == Opcode.Jump &&
                Instruction.Unsignedˉoperand < (uint)Instruction.Offset).ToArray();
            var Forwardˉjumps = Regionˉinstructions.Where(Instruction =>
                Instruction.Opcode == Opcode.Jump &&
                Instruction.Unsignedˉoperand > (uint)(Instruction.Offset + Instruction.Size)).ToArray();
            True(
                Backwardˉjumps.Length <= 1 && Forwardˉjumps.Length <= 1,
                "The metered-control source region is not sequential.");
            True(
                Backwardˉjumps.Length == 0 || Forwardˉjumps.Length == 0,
                "The metered-control source region mixes loop and conditional exits.");
            if (Backwardˉjumps.Length == 1)
            {
                Loopˉheaders.Add(Backwardˉjumps[0].Unsignedˉoperand);
                Loopˉbranches.Add(Branch.Offset);
            }
            else if (Forwardˉjumps.Length == 1)
            {
                Elseˉjumps.Add(Forwardˉjumps[0].Offset);
                Conditionalˉends.Add(Forwardˉjumps[0].Unsignedˉoperand);
            }
            else
            {
                Conditionalˉends.Add(Falseˉtarget);
            }
        }

        var Reader = new WebAssemblyˉtestˉreader(module);
        Reader.Readˉheader();

        var Typeˉend = Reader.Readˉsection(1);
        Reader.Require(Reader.Readˉuleb32() == 1, "The metered-loop type count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x60, "The metered-loop function type is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 1, "The metered-loop parameter count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The metered-loop budget type is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 1, "The metered-loop result count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The metered-loop result type is invalid.");
        Reader.Require(Reader.Position == Typeˉend, "The metered-loop type section has trailing bytes.");

        var Functionˉend = Reader.Readˉsection(3);
        Reader.Require(Reader.Readˉuleb32() == 1, "The metered-loop function count is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 0, "The metered-loop type index is invalid.");
        Reader.Require(Reader.Position == Functionˉend, "The metered-loop function section has trailing bytes.");

        var Globalˉend = Reader.Readˉsection(6);
        Reader.Require(Reader.Readˉuleb32() == 3, "The metered-loop global count is invalid.");
        Reader.Readˉglobal(0, 2);
        Reader.Readˉglobal(1, 0);
        Reader.Readˉglobal(1, 0);
        Reader.Require(Reader.Position == Globalˉend, "The metered-loop global section has trailing bytes.");

        var Exportˉend = Reader.Readˉsection(7);
        Reader.Require(Reader.Readˉuleb32() == 4, "The metered-loop export count is invalid.");
        Reader.Readˉexport("Windvale.run", 0, 0);
        Reader.Readˉexport("Windvale.abi", 3, 0);
        Reader.Readˉexport("Windvale.result", 3, 1);
        Reader.Readˉexport("Windvale.instructions", 3, 2);
        Reader.Require(Reader.Position == Exportˉend, "The metered-loop export section has trailing bytes.");

        var Codeˉend = Reader.Readˉsection(10);
        Reader.Require(Reader.Readˉuleb32() == 1, "The metered-loop body count is invalid.");
        var Bodyˉlength = Reader.Readˉuleb32();
        Reader.Require(Bodyˉlength <= int.MaxValue, "The metered-loop body is oversized.");
        Reader.Require(
            Reader.Position <= Codeˉend - (int)Bodyˉlength,
            "The metered-loop body is truncated.");
        var Bodyˉend = Reader.Position + (int)Bodyˉlength;

        var Localˉcount = Function.Declaration.Localˉtypes.Length;
        var Scratchˉleft = (uint)Localˉcount + 1;
        var Scratchˉright = Scratchˉleft + 1;
        var Scratchˉresult = Scratchˉleft + 2;
        var Scratchˉwide = Scratchˉleft + 3;
        Reader.Require(Reader.Readˉuleb32() == 2, "The metered-loop local group count is invalid.");
        Reader.Require(
            Reader.Readˉuleb32() == (uint)Localˉcount + 3,
            "The metered-loop i32 local count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7F, "The metered-loop local type is invalid.");
        Reader.Require(Reader.Readˉuleb32() == 1, "The metered-loop i64 local count is invalid.");
        Reader.Require(Reader.Readˉbyte() == 0x7E, "The metered-loop wide local type is invalid.");
        Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The metered-loop result reset is invalid.");
        Reader.Readˉindexed(0x24, 1);
        Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The metered-loop counter reset is invalid.");
        Reader.Readˉindexed(0x24, 2);

        void Readˉmeter()
        {
            Reader.Readˉindexed(0x23, 2);
            Reader.Readˉindexed(0x20, 0);
            Reader.Require(Reader.Readˉbyte() == 0x4F, "The metered-loop budget comparison is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x04, "The metered-loop exhaustion branch is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x40, "The metered-loop exhaustion block type is invalid.");
            Reader.Require(Reader.Readˉi32ˉconstant() == 3011, "The metered-loop exhaustion status is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x0F, "The metered-loop exhaustion return is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x0B, "The metered-loop exhaustion branch is unterminated.");
            Reader.Readˉindexed(0x23, 2);
            Reader.Require(Reader.Readˉi32ˉconstant() == 1, "The metered-loop charge is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x6A, "The metered-loop charge addition is invalid.");
            Reader.Readˉindexed(0x24, 2);
        }

        void Readˉoverflowˉreturn()
        {
            Reader.Require(Reader.Readˉbyte() == 0x04, "The metered-loop overflow branch is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x40, "The metered-loop overflow block type is invalid.");
            Reader.Require(Reader.Readˉi32ˉconstant() == 3007, "The metered-loop overflow status is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x0F, "The metered-loop overflow return is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x0B, "The metered-loop overflow branch is unterminated.");
        }

        void Readˉcheckedˉadd()
        {
            Reader.Readˉindexed(0x21, Scratchˉright);
            Reader.Readˉindexed(0x21, Scratchˉleft);
            Reader.Readˉindexed(0x20, Scratchˉleft);
            Reader.Readˉindexed(0x20, Scratchˉright);
            Reader.Require(Reader.Readˉbyte() == 0x6A, "The metered-loop checked add is invalid.");
            Reader.Readˉindexed(0x22, Scratchˉresult);
            Reader.Readˉindexed(0x20, Scratchˉleft);
            Reader.Require(Reader.Readˉbyte() == 0x73, "The metered-loop checked add xor is invalid.");
            Reader.Readˉindexed(0x20, Scratchˉresult);
            Reader.Readˉindexed(0x20, Scratchˉright);
            Reader.Require(Reader.Readˉbyte() == 0x73, "The metered-loop checked add xor is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x71, "The metered-loop checked add mask is invalid.");
            Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The metered-loop checked add sign is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x48, "The metered-loop checked add comparison is invalid.");
            Readˉoverflowˉreturn();
            Reader.Readˉindexed(0x20, Scratchˉresult);
        }

        void Readˉcheckedˉmultiply()
        {
            Reader.Readˉindexed(0x21, Scratchˉright);
            Reader.Readˉindexed(0x21, Scratchˉleft);
            Reader.Readˉindexed(0x20, Scratchˉleft);
            Reader.Require(Reader.Readˉbyte() == 0xAC, "The metered-loop multiply extension is invalid.");
            Reader.Readˉindexed(0x20, Scratchˉright);
            Reader.Require(Reader.Readˉbyte() == 0xAC, "The metered-loop multiply extension is invalid.");
            Reader.Require(Reader.Readˉbyte() == 0x7E, "The metered-loop multiply is invalid.");
            Reader.Readˉindexed(0x22, Scratchˉwide);
            Reader.Require(Reader.Readˉbyte() == 0xA7, "The metered-loop multiply wrap is invalid.");
            Reader.Readˉindexed(0x22, Scratchˉresult);
            Reader.Require(Reader.Readˉbyte() == 0xAC, "The metered-loop multiply result extension is invalid.");
            Reader.Readˉindexed(0x20, Scratchˉwide);
            Reader.Require(Reader.Readˉbyte() == 0x52, "The metered-loop multiply comparison is invalid.");
            Readˉoverflowˉreturn();
            Reader.Readˉindexed(0x20, Scratchˉresult);
        }

        foreach (var Instruction in Function.Instructions)
        {
            if (Conditionalˉends.Contains((uint)Instruction.Offset))
            {
                Reader.Require(Reader.Readˉbyte() == 0x0B, "The metered conditional is unterminated.");
            }
            if (Loopˉheaders.Contains((uint)Instruction.Offset))
            {
                Reader.Require(Reader.Readˉbyte() == 0x02, "The metered-loop block is missing.");
                Reader.Require(Reader.Readˉbyte() == 0x40, "The metered-loop block type is invalid.");
                Reader.Require(Reader.Readˉbyte() == 0x03, "The metered-loop loop is missing.");
                Reader.Require(Reader.Readˉbyte() == 0x40, "The metered-loop loop type is invalid.");
            }
            Readˉmeter();
            switch (Instruction.Opcode)
            {
                case Opcode.I32ˉconst:
                    Reader.Require(
                        Reader.Readˉi32ˉconstant() == Instruction.Signedˉoperand,
                        "The metered-loop constant changed value.");
                    break;
                case Opcode.Localˉload:
                    Reader.Readˉindexed(0x20, Instruction.Unsignedˉoperand + 1);
                    break;
                case Opcode.Localˉstore:
                    Reader.Readˉindexed(0x21, Instruction.Unsignedˉoperand + 1);
                    break;
                case Opcode.I32ˉadd:
                    Readˉcheckedˉadd();
                    break;
                case Opcode.I32ˉmultiply:
                    Readˉcheckedˉmultiply();
                    break;
                case Opcode.I32ˉequal:
                    Reader.Require(Reader.Readˉbyte() == 0x46, "The metered-loop equality is invalid.");
                    break;
                case Opcode.I32ˉnotˉequal:
                    Reader.Require(Reader.Readˉbyte() == 0x47, "The metered-loop inequality is invalid.");
                    break;
                case Opcode.I32ˉless:
                    Reader.Require(Reader.Readˉbyte() == 0x48, "The metered-loop less-than is invalid.");
                    break;
                case Opcode.I32ˉlessˉequal:
                    Reader.Require(Reader.Readˉbyte() == 0x4C, "The metered-loop less-equal is invalid.");
                    break;
                case Opcode.I32ˉgreater:
                    Reader.Require(Reader.Readˉbyte() == 0x4A, "The metered-loop greater-than is invalid.");
                    break;
                case Opcode.I32ˉgreaterˉequal:
                    Reader.Require(Reader.Readˉbyte() == 0x4E, "The metered-loop greater-equal is invalid.");
                    break;
                case Opcode.Jump when Instruction.Unsignedˉoperand < (uint)Instruction.Offset:
                    Reader.Readˉindexed(0x0C, 0);
                    Reader.Require(Reader.Readˉbyte() == 0x0B, "The metered loop is unterminated.");
                    Reader.Require(Reader.Readˉbyte() == 0x0B, "The metered outer block is unterminated.");
                    break;
                case Opcode.Jump when Elseˉjumps.Contains(Instruction.Offset):
                    Reader.Require(Reader.Readˉbyte() == 0x05, "The metered conditional else marker is missing.");
                    break;
                case Opcode.Jump:
                    break;
                case Opcode.Branchˉfalse:
                    if (Loopˉbranches.Contains(Instruction.Offset))
                    {
                        Reader.Require(Reader.Readˉbyte() == 0x45, "The metered-loop false test is invalid.");
                        Reader.Readˉindexed(0x0D, 1);
                    }
                    else
                    {
                        Reader.Require(Reader.Readˉbyte() == 0x04, "The metered conditional is missing.");
                        Reader.Require(Reader.Readˉbyte() == 0x40, "The metered conditional type is invalid.");
                    }
                    break;
                case Opcode.Pop:
                    Reader.Require(Reader.Readˉbyte() == 0x1A, "The metered-loop drop is invalid.");
                    break;
                case Opcode.Return:
                    Reader.Readˉindexed(0x24, 1);
                    Reader.Require(Reader.Readˉi32ˉconstant() == 0, "The metered-loop success status is invalid.");
                    Reader.Require(Reader.Readˉbyte() == 0x0F, "The metered-loop success return is invalid.");
                    break;
                default:
                    throw new InvalidDataException(
                        $"Unsupported metered-loop source opcode {Instruction.Opcode}.");
            }
        }

        Reader.Require(Reader.Readˉbyte() == 0x0B, "The metered-loop body is unterminated.");
        Reader.Require(Reader.Position == Bodyˉend, "The metered-loop body has trailing bytes.");
        Reader.Require(Reader.Position == Codeˉend, "The metered-loop code section has trailing bytes.");
        Reader.Require(Reader.Position == Reader.Length, "The metered-loop module has trailing bytes.");
    }

    private static WebAssemblyˉexecutionˉresult Executeˉcheckedˉaddˉwebassembly(
        ReadOnlySpan<byte> module)
    {
        var Bytes = module.ToArray();
        var Cursor = 0;

        void Require(bool condition, string message)
        {
            if (!condition)
            {
                throw new InvalidDataException(message);
            }
        }

        byte Readˉbyte()
        {
            Require(Cursor < Bytes.Length, "The checked-add WebAssembly module is truncated.");
            return Bytes[Cursor++];
        }

        uint Readˉuleb32()
        {
            uint Result = 0;
            for (var Index = 0; Index < 5; Index++)
            {
                var Value = Readˉbyte();
                var Payload = (uint)(Value & 0x7F);
                if (Index == 4)
                {
                    Require(Payload <= 0x0F, "The checked-add u32 LEB128 value exceeds 32 bits.");
                }
                Result |= Payload << (Index * 7);
                if ((Value & 0x80) == 0)
                {
                    return Result;
                }
            }
            throw new InvalidDataException("The checked-add u32 LEB128 value is unterminated.");
        }

        int Readˉsleb32()
        {
            long Result = 0;
            for (var Index = 0; Index < 5; Index++)
            {
                var Value = Readˉbyte();
                var Payload = Value & 0x7F;
                Result |= (long)Payload << (Index * 7);
                if ((Value & 0x80) != 0)
                {
                    continue;
                }

                if (Index == 4)
                {
                    var Negative = (Payload & 0x08) != 0;
                    Require(
                        Negative
                            ? (Payload & 0x70) == 0x70
                            : (Payload & 0x70) == 0,
                        "The checked-add i32 LEB128 value has invalid unused bits.");
                    return unchecked((int)(uint)Result);
                }

                var Shift = (Index + 1) * 7;
                if ((Value & 0x40) != 0)
                {
                    Result |= -1L << Shift;
                }
                Require(Result is >= int.MinValue and <= int.MaxValue,
                    "The checked-add signed LEB128 value exceeds i32.");
                return (int)Result;
            }
            throw new InvalidDataException("The checked-add i32 LEB128 value is unterminated.");
        }

        int Readˉsection(byte expectedˉkind)
        {
            Require(Readˉbyte() == expectedˉkind, "The checked-add section order is invalid.");
            var Length = Readˉuleb32();
            Require(Length <= int.MaxValue, "The checked-add section is oversized.");
            Require(Cursor <= Bytes.Length - (int)Length, "The checked-add section is truncated.");
            return Cursor + (int)Length;
        }

        void Readˉindexed(byte opcode, uint index)
        {
            Require(Readˉbyte() == opcode, "The checked-add indexed opcode is invalid.");
            Require(Readˉuleb32() == index, "The checked-add instruction index is invalid.");
        }

        int Readˉi32ˉconstant()
        {
            Require(Readˉbyte() == 0x41, "The checked-add i32 constant opcode is invalid.");
            return Readˉsleb32();
        }

        void Readˉglobal(byte mutable, int initial)
        {
            Require(Readˉbyte() == 0x7F, "The checked-add global type is invalid.");
            Require(Readˉbyte() == mutable, "The checked-add global mutability is invalid.");
            Require(Readˉi32ˉconstant() == initial, "The checked-add global initializer is invalid.");
            Require(Readˉbyte() == 0x0B, "The checked-add global initializer is unterminated.");
        }

        void Readˉexport(string name, byte kind, uint index)
        {
            Require(Readˉuleb32() == name.Length, "The checked-add export name length is invalid.");
            foreach (var Character in name)
            {
                Require(Readˉbyte() == (byte)Character, "The checked-add export name is invalid.");
            }
            Require(Readˉbyte() == kind, "The checked-add export kind is invalid.");
            Require(Readˉuleb32() == index, "The checked-add export index is invalid.");
        }

        Require(Bytes.Length >= 8, "The checked-add WebAssembly header is truncated.");
        Require(Readˉbyte() == 0x00, "The checked-add WebAssembly magic is invalid.");
        Require(Readˉbyte() == 0x61, "The checked-add WebAssembly magic is invalid.");
        Require(Readˉbyte() == 0x73, "The checked-add WebAssembly magic is invalid.");
        Require(Readˉbyte() == 0x6D, "The checked-add WebAssembly magic is invalid.");
        Require(Readˉbyte() == 0x01, "The checked-add WebAssembly version is invalid.");
        Require(Readˉbyte() == 0x00, "The checked-add WebAssembly version is invalid.");
        Require(Readˉbyte() == 0x00, "The checked-add WebAssembly version is invalid.");
        Require(Readˉbyte() == 0x00, "The checked-add WebAssembly version is invalid.");

        var Typeˉend = Readˉsection(1);
        Require(Readˉuleb32() == 1, "The checked-add type count is invalid.");
        Require(Readˉbyte() == 0x60, "The checked-add function type is invalid.");
        Require(Readˉuleb32() == 0, "The checked-add parameter count is invalid.");
        Require(Readˉuleb32() == 1, "The checked-add result count is invalid.");
        Require(Readˉbyte() == 0x7F, "The checked-add result type is invalid.");
        Require(Cursor == Typeˉend, "The checked-add type section has trailing bytes.");

        var Functionˉend = Readˉsection(3);
        Require(Readˉuleb32() == 1, "The checked-add function count is invalid.");
        Require(Readˉuleb32() == 0, "The checked-add type index is invalid.");
        Require(Cursor == Functionˉend, "The checked-add function section has trailing bytes.");

        var Globalˉend = Readˉsection(6);
        Require(Readˉuleb32() == 3, "The checked-add global count is invalid.");
        Readˉglobal(0, 1);
        Readˉglobal(1, 0);
        Readˉglobal(1, 0);
        Require(Cursor == Globalˉend, "The checked-add global section has trailing bytes.");

        var Exportˉend = Readˉsection(7);
        Require(Readˉuleb32() == 4, "The checked-add export count is invalid.");
        Readˉexport("Windvale.run", 0, 0);
        Readˉexport("Windvale.abi", 3, 0);
        Readˉexport("Windvale.result", 3, 1);
        Readˉexport("Windvale.instructions", 3, 2);
        Require(Cursor == Exportˉend, "The checked-add export section has trailing bytes.");

        var Codeˉend = Readˉsection(10);
        Require(Readˉuleb32() == 1, "The checked-add body count is invalid.");
        var Bodyˉlength = Readˉuleb32();
        Require(Bodyˉlength <= int.MaxValue, "The checked-add body is oversized.");
        Require(Cursor <= Codeˉend - (int)Bodyˉlength, "The checked-add body is truncated.");
        var Bodyˉend = Cursor + (int)Bodyˉlength;
        Require(Readˉuleb32() == 1, "The checked-add local group count is invalid.");
        Require(Readˉuleb32() == 1, "The checked-add local count is invalid.");
        Require(Readˉbyte() == 0x7F, "The checked-add local type is invalid.");

        Require(Readˉi32ˉconstant() == 0, "The checked-add result reset is invalid.");
        Readˉindexed(0x24, 1);
        Require(Readˉi32ˉconstant() == 0, "The checked-add step reset is invalid.");
        Readˉindexed(0x24, 2);

        var Left = Readˉi32ˉconstant();
        var Right = Readˉi32ˉconstant();
        Require(Readˉbyte() == 0x6A, "The checked-add addition opcode is invalid.");
        Readˉindexed(0x22, 0);
        Require(Readˉi32ˉconstant() == Left, "The checked-add left overflow probe changed.");
        Require(Readˉbyte() == 0x73, "The checked-add first xor opcode is invalid.");
        Readˉindexed(0x20, 0);
        Require(Readˉi32ˉconstant() == Right, "The checked-add right overflow probe changed.");
        Require(Readˉbyte() == 0x73, "The checked-add second xor opcode is invalid.");
        Require(Readˉbyte() == 0x71, "The checked-add and opcode is invalid.");
        Require(Readˉi32ˉconstant() == 0, "The checked-add sign comparison constant is invalid.");
        Require(Readˉbyte() == 0x48, "The checked-add signed comparison opcode is invalid.");
        Require(Readˉbyte() == 0x04, "The checked-add if opcode is invalid.");
        Require(Readˉbyte() == 0x40, "The checked-add if block type is invalid.");

        Require(Readˉi32ˉconstant() == 7, "The checked-add overflow step count is invalid.");
        Readˉindexed(0x24, 2);
        Require(Readˉi32ˉconstant() == 3007, "The checked-add overflow status is invalid.");
        Require(Readˉbyte() == 0x0F, "The checked-add overflow return is invalid.");
        Require(Readˉbyte() == 0x0B, "The checked-add overflow branch is unterminated.");

        Readˉindexed(0x20, 0);
        Readˉindexed(0x24, 1);
        Require(Readˉi32ˉconstant() == 10, "The checked-add success step count is invalid.");
        Readˉindexed(0x24, 2);
        Require(Readˉi32ˉconstant() == 0, "The checked-add success status is invalid.");
        Require(Readˉbyte() == 0x0B, "The checked-add body end is invalid.");
        Require(Cursor == Bodyˉend, "The checked-add body has trailing bytes.");
        Require(Cursor == Codeˉend, "The checked-add code section has trailing bytes.");
        Require(Cursor == Bytes.Length, "The checked-add module has trailing bytes.");

        var Sum = unchecked(Left + Right);
        var Overflow = ((Left ^ Sum) & (Right ^ Sum)) < 0;
        return Overflow
            ? new(3007, 0, 7)
            : new(0, Sum, 10);
    }

    private static int Executeˉconstantˉwebassembly(ReadOnlySpan<byte> module)
    {
        var Bytes = module.ToArray();
        var Cursor = 0;

        void Require(bool condition, string message)
        {
            if (!condition)
            {
                throw new InvalidDataException(message);
            }
        }

        byte Readˉbyte()
        {
            Require(Cursor < Bytes.Length, "The WebAssembly module is truncated.");
            return Bytes[Cursor++];
        }

        uint Readˉuleb32()
        {
            uint Result = 0;
            for (var Index = 0; Index < 5; Index++)
            {
                var Value = Readˉbyte();
                var Payload = (uint)(Value & 0x7F);
                if (Index == 4)
                {
                    Require(Payload <= 0x0F, "The u32 LEB128 value exceeds 32 bits.");
                }
                Result |= Payload << (Index * 7);
                if ((Value & 0x80) == 0)
                {
                    return Result;
                }
            }
            throw new InvalidDataException("The u32 LEB128 value is unterminated.");
        }

        int Readˉsleb32()
        {
            long Result = 0;
            for (var Index = 0; Index < 5; Index++)
            {
                var Value = Readˉbyte();
                var Payload = Value & 0x7F;
                Result |= (long)Payload << (Index * 7);
                if ((Value & 0x80) != 0)
                {
                    continue;
                }

                if (Index == 4)
                {
                    var Negative = (Payload & 0x08) != 0;
                    Require(
                        Negative
                            ? (Payload & 0x70) == 0x70
                            : (Payload & 0x70) == 0,
                        "The i32 LEB128 value has invalid unused bits.");
                    return unchecked((int)(uint)Result);
                }

                var Shift = (Index + 1) * 7;
                if ((Value & 0x40) != 0)
                {
                    Result |= -1L << Shift;
                }
                Require(Result is >= int.MinValue and <= int.MaxValue,
                    "The signed LEB128 value exceeds i32.");
                return (int)Result;
            }
            throw new InvalidDataException("The i32 LEB128 value is unterminated.");
        }

        int Readˉsection(byte expectedˉkind)
        {
            Require(Readˉbyte() == expectedˉkind, "The WebAssembly section order is invalid.");
            var Length = Readˉuleb32();
            Require(Length <= int.MaxValue, "The WebAssembly section is oversized.");
            Require(Cursor <= Bytes.Length - (int)Length, "The WebAssembly section is truncated.");
            return Cursor + (int)Length;
        }

        Require(Bytes.Length >= 8, "The WebAssembly header is truncated.");
        Require(Readˉbyte() == 0x00, "The WebAssembly magic is invalid.");
        Require(Readˉbyte() == 0x61, "The WebAssembly magic is invalid.");
        Require(Readˉbyte() == 0x73, "The WebAssembly magic is invalid.");
        Require(Readˉbyte() == 0x6D, "The WebAssembly magic is invalid.");
        Require(Readˉbyte() == 0x01, "The WebAssembly version is invalid.");
        Require(Readˉbyte() == 0x00, "The WebAssembly version is invalid.");
        Require(Readˉbyte() == 0x00, "The WebAssembly version is invalid.");
        Require(Readˉbyte() == 0x00, "The WebAssembly version is invalid.");

        var Typeˉend = Readˉsection(1);
        Require(Readˉuleb32() == 1, "The WebAssembly type count is invalid.");
        Require(Readˉbyte() == 0x60, "The WebAssembly function type is invalid.");
        Require(Readˉuleb32() == 0, "The WebAssembly parameter count is invalid.");
        Require(Readˉuleb32() == 1, "The WebAssembly result count is invalid.");
        Require(Readˉbyte() == 0x7F, "The WebAssembly result type is invalid.");
        Require(Cursor == Typeˉend, "The WebAssembly type section has trailing bytes.");

        var Functionˉend = Readˉsection(3);
        Require(Readˉuleb32() == 1, "The WebAssembly function count is invalid.");
        Require(Readˉuleb32() == 0, "The WebAssembly type index is invalid.");
        Require(Cursor == Functionˉend, "The WebAssembly function section has trailing bytes.");

        var Exportˉend = Readˉsection(7);
        Require(Readˉuleb32() == 1, "The WebAssembly export count is invalid.");
        Require(Readˉuleb32() == 4, "The WebAssembly export name length is invalid.");
        Require(Readˉbyte() == (byte)'M', "The WebAssembly export name is invalid.");
        Require(Readˉbyte() == (byte)'a', "The WebAssembly export name is invalid.");
        Require(Readˉbyte() == (byte)'i', "The WebAssembly export name is invalid.");
        Require(Readˉbyte() == (byte)'n', "The WebAssembly export name is invalid.");
        Require(Readˉbyte() == 0, "The WebAssembly export kind is invalid.");
        Require(Readˉuleb32() == 0, "The WebAssembly export index is invalid.");
        Require(Cursor == Exportˉend, "The WebAssembly export section has trailing bytes.");

        var Codeˉend = Readˉsection(10);
        Require(Readˉuleb32() == 1, "The WebAssembly body count is invalid.");
        var Bodyˉlength = Readˉuleb32();
        Require(Bodyˉlength <= int.MaxValue, "The WebAssembly body is oversized.");
        Require(Cursor <= Codeˉend - (int)Bodyˉlength, "The WebAssembly body is truncated.");
        var Bodyˉend = Cursor + (int)Bodyˉlength;
        Require(Readˉuleb32() == 0, "The WebAssembly local group count is invalid.");
        Require(Readˉbyte() == 0x41, "The WebAssembly body opcode is invalid.");
        var Result = Readˉsleb32();
        Require(Readˉbyte() == 0x0B, "The WebAssembly body end is invalid.");
        Require(Cursor == Bodyˉend, "The WebAssembly body has trailing bytes.");
        Require(Cursor == Codeˉend, "The WebAssembly code section has trailing bytes.");
        Require(Cursor == Bytes.Length, "The WebAssembly module has trailing bytes.");
        return Result;
    }

    private static int Runˉportable(string source)
    {
        var Module = Moduleˉcodec.Readˉandˉverify(Compileˉsuccess(source));
        return new Referenceˉruntime(
            Module,
            new Referenceˉcapabilityˉhost(new StringWriter()),
            Runtimeˉoptions.Portableˉdefaults).Runˉmain().Exitˉcode;
    }

    private static byte[] Compileˉsuccess(string source)
    {
        var Result = Seedˉcompiler.Compile(source);
        if (!Result.Success)
        {
            throw new InvalidOperationException(
                "Compilation failed: " + string.Join(" | ", Result.Diagnostics));
        }

        return Result.Moduleˉbytes.ToArray();
    }

