    private static void Nativeˉshapesˉmatchˉverifiedˉwvb(
        Verifiedˉmodule verified,
        Nativeˉcompilation compilation)
    {
        Equal(verified.Functions.Length, compilation.Module.Functions.Length);
        for (var Functionˉindex = 0; Functionˉindex < verified.Functions.Length; Functionˉindex++)
        {
            var Verifiedˉfunction = verified.Functions[Functionˉindex].Declaration;
            var Nativeˉfunction = compilation.Module.Functions[Functionˉindex];
            Equal(
                Verifiedˉfunction.Returnˉtype.Nominalˉtypeˉindex,
                Nativeˉfunction.Returnˉnominalˉtypeˉindex);
            Sequenceˉequal(
                Verifiedˉfunction.Allˉlocalˉtypes
                    .Select(Type => Type.Nominalˉtypeˉindex)
                    .ToImmutableArray(),
                Nativeˉfunction.Allˉlocalˉnominalˉtypeˉindices);
            Equal(
                Nativeˉfunction.Valueˉtypes.Length,
                Nativeˉfunction.Valueˉnominalˉtypeˉindices.Length);

            for (var Value = 0; Value < Nativeˉfunction.Valueˉtypes.Length; Value++)
            {
                var Nominalˉtypeˉindex = Nativeˉfunction.Valueˉnominalˉtypeˉindices[Value];
                switch (Nativeˉfunction.Valueˉtypes[Value])
                {
                    case Nativeˉvalueˉtype.Record:
                        True(
                            (uint)Nominalˉtypeˉindex < (uint)compilation.Module.Types.Length &&
                            compilation.Module.Types[Nominalˉtypeˉindex] is Recordˉtypeˉdeclaration,
                            "Native record value omitted its record identity.");
                        break;
                    case Nativeˉvalueˉtype.Enum:
                        True(
                            (uint)Nominalˉtypeˉindex < (uint)compilation.Module.Types.Length &&
                            compilation.Module.Types[Nominalˉtypeˉindex] is Enumˉtypeˉdeclaration,
                            "Native enum value omitted its enum identity.");
                        break;
                    default:
                        Equal(-1, Nominalˉtypeˉindex);
                        break;
                }
            }

            foreach (var Block in Nativeˉfunction.Blocks)
            {
                foreach (var Operation in Block.Operations)
                {
                    switch (Operation)
                    {
                        case Nativeˉenumˉconstant Constant:
                            Equal(
                                Constant.Type,
                                Nativeˉfunction.Valueˉnominalˉtypeˉindices[Constant.Result]);
                            break;
                        case Nativeˉlocalˉload Load:
                            Equal(
                                Nativeˉfunction.Allˉlocalˉnominalˉtypeˉindices[Load.Local],
                                Nativeˉfunction.Valueˉnominalˉtypeˉindices[Load.Result]);
                            break;
                        case Nativeˉlocalˉstore Store:
                            Equal(
                                Nativeˉfunction.Allˉlocalˉnominalˉtypeˉindices[Store.Local],
                                Nativeˉfunction.Valueˉnominalˉtypeˉindices[Store.Value]);
                            break;
                        case Nativeˉenumˉcomparison Comparison:
                            Equal(
                                Nativeˉfunction.Valueˉnominalˉtypeˉindices[Comparison.Left],
                                Nativeˉfunction.Valueˉnominalˉtypeˉindices[Comparison.Right]);
                            break;
                        case Nativeˉenumˉname Name:
                            Equal(
                                Name.Type,
                                Nativeˉfunction.Valueˉnominalˉtypeˉindices[Name.Value]);
                            break;
                        case Nativeˉrecordˉcreate Create:
                            var Record = (Recordˉtypeˉdeclaration)compilation.Module.Types[Create.Type];
                            Equal(
                                Create.Type,
                                Nativeˉfunction.Valueˉnominalˉtypeˉindices[Create.Result]);
                            for (var Field = 0; Field < Create.Fields.Length; Field++)
                            {
                                Equal(
                                    Record.Fields[Field].Type.Nominalˉtypeˉindex,
                                    Nativeˉfunction.Valueˉnominalˉtypeˉindices[
                                        Create.Fields[Field]]);
                            }
                            break;
                        case Nativeˉrecordˉfield Field:
                            var Fieldˉrecord =
                                (Recordˉtypeˉdeclaration)compilation.Module.Types[Field.Type];
                            Equal(
                                Field.Type,
                                Nativeˉfunction.Valueˉnominalˉtypeˉindices[Field.Record]);
                            Equal(
                                Fieldˉrecord.Fields[Field.Field].Type.Nominalˉtypeˉindex,
                                Nativeˉfunction.Valueˉnominalˉtypeˉindices[Field.Result]);
                            break;
                        case Nativeˉcall Call:
                            var Called = compilation.Module.Functions[Call.Function];
                            Equal(
                                Called.Returnˉnominalˉtypeˉindex,
                                Nativeˉfunction.Valueˉnominalˉtypeˉindices[Call.Result]);
                            for (var Argument = 0; Argument < Call.Arguments.Length; Argument++)
                            {
                                Equal(
                                    Called.Allˉlocalˉnominalˉtypeˉindices[Argument],
                                    Nativeˉfunction.Valueˉnominalˉtypeˉindices[
                                        Call.Arguments[Argument]]);
                            }
                            break;
                        case Nativeˉvoidˉcall Call:
                            var Calledˉvoid = compilation.Module.Functions[Call.Function];
                            for (var Argument = 0; Argument < Call.Arguments.Length; Argument++)
                            {
                                Equal(
                                    Calledˉvoid.Allˉlocalˉnominalˉtypeˉindices[Argument],
                                    Nativeˉfunction.Valueˉnominalˉtypeˉindices[
                                        Call.Arguments[Argument]]);
                            }
                            break;
                    }
                }

                if (Block.Terminator is Nativeˉreturn Return)
                {
                    Equal(
                        Nativeˉfunction.Returnˉnominalˉtypeˉindex,
                        Nativeˉfunction.Valueˉnominalˉtypeˉindices[Return.Value]);
                }
            }
        }
    }

    private static void Nativeˉrecordˉstorageˉisˉvalid(
        Nativeˉmodule module,
        ImmutableArray<Nativeˉfunctionˉrecordˉstorage> storage)
    {
        Equal(module.Functions.Length, storage.Length);
        for (var Functionˉindex = 0; Functionˉindex < module.Functions.Length; Functionˉindex++)
        {
            var Function = module.Functions[Functionˉindex];
            var Plan = storage[Functionˉindex];
            Equal(Functionˉindex, Plan.Functionˉindex);
            Equal(Function.Name, Plan.Functionˉname);
            Equal(Function.Allˉlocalˉtypes.Length, Plan.Localˉrecordˉfieldˉoffsets.Length);
            Equal(Function.Valueˉtypes.Length, Plan.Valueˉrecordˉfieldˉoffsets.Length);
            Equal(Plan.Existingˉframeˉcells, Plan.Persistentˉrecordˉbaseˉcell);
            Equal(
                checked(Plan.Persistentˉrecordˉbaseˉcell + Plan.Persistentˉrecordˉfieldˉcells),
                Plan.Scratchˉrecordˉbaseˉcell);
            Equal(
                checked(
                    Plan.Scratchˉrecordˉbaseˉcell +
                    Plan.Scratchˉrecordˉfieldˉcells +
                    (Plan.Returnsˉrecord ? 1 : 0)),
                Plan.Projectedˉframeˉcells);
            Equal(
                Plan.Returnsˉrecord
                    ? checked(Plan.Projectedˉframeˉcells - 1)
                    : -1,
                Plan.Recordˉreturnˉpointerˉcell);

            var Assignedˉrecordˉparameters = Function.Blocks
                .SelectMany(Block => Block.Operations)
                .OfType<Nativeˉlocalˉstore>()
                .Where(Store =>
                    Store.Local >= 0 &&
                    Store.Local < Function.Parameterˉtypes.Length &&
                    Store.Type == Nativeˉvalueˉtype.Record)
                .Select(Store => Store.Local)
                .ToHashSet();
            Equal(Assignedˉrecordˉparameters.Count, Plan.Assignedˉrecordˉparameterˉbindings);

            bool Isˉbackedˉrecordˉlocal(int local) =>
                Function.Allˉlocalˉtypes[local] == Nativeˉvalueˉtype.Record &&
                (local >= Function.Parameterˉtypes.Length ||
                    Assignedˉrecordˉparameters.Contains(local));

            int Localˉwidth(int local) => Nativeˉtestˉrecordˉwidth(
                module,
                Function.Allˉlocalˉnominalˉtypeˉindices[local]);

            var Maximumˉpersistentˉend = Plan.Persistentˉrecordˉbaseˉcell;
            for (var Local = 0; Local < Function.Allˉlocalˉtypes.Length; Local++)
            {
                var Offset = Plan.Localˉrecordˉfieldˉoffsets[Local];
                if (!Isˉbackedˉrecordˉlocal(Local))
                {
                    Equal(-1, Offset);
                    continue;
                }
                if (Offset >= 0)
                {
                    True(
                        Offset >= Plan.Persistentˉrecordˉbaseˉcell,
                        "Native record-local storage begins before its persistent region.");
                    var End = checked(Offset + Localˉwidth(Local));
                    True(
                        End <= Plan.Scratchˉrecordˉbaseˉcell,
                        "Native record-local storage exceeds its persistent region.");
                    Maximumˉpersistentˉend = Math.Max(Maximumˉpersistentˉend, End);
                }
            }
            Equal(
                Plan.Persistentˉrecordˉfieldˉcells,
                checked(Maximumˉpersistentˉend - Plan.Persistentˉrecordˉbaseˉcell));

            var Blockˉindices = Function.Blocks
                .Select((Block, Index) => (Block.Id, Index))
                .ToDictionary(Entry => Entry.Id, Entry => Entry.Index);
            var Uses = new HashSet<int>[Function.Blocks.Length];
            var Definitions = new HashSet<int>[Function.Blocks.Length];
            var Successors = new int[Function.Blocks.Length][];
            for (var Blockˉindex = 0; Blockˉindex < Function.Blocks.Length; Blockˉindex++)
            {
                var Use = new HashSet<int>();
                var Definition = new HashSet<int>();
                foreach (var Operation in Function.Blocks[Blockˉindex].Operations)
                {
                    switch (Operation)
                    {
                        case Nativeˉlocalˉload Load when Isˉbackedˉrecordˉlocal(Load.Local):
                            if (!Definition.Contains(Load.Local))
                            {
                                Use.Add(Load.Local);
                            }
                            break;
                        case Nativeˉlocalˉstore Store when Isˉbackedˉrecordˉlocal(Store.Local):
                            Definition.Add(Store.Local);
                            break;
                    }
                }
                Uses[Blockˉindex] = Use;
                Definitions[Blockˉindex] = Definition;
                Successors[Blockˉindex] = Function.Blocks[Blockˉindex].Terminator switch
                {
                    Nativeˉjump Jump => [Blockˉindices[Jump.Targetˉblock]],
                    Nativeˉbranch Branch =>
                    [
                        Blockˉindices[Branch.Trueˉblock],
                        Blockˉindices[Branch.Falseˉblock],
                    ],
                    _ => [],
                };
            }

            var Liveˉin = Enumerable.Range(0, Function.Blocks.Length)
                .Select(_ => new HashSet<int>())
                .ToArray();
            var Liveˉout = Enumerable.Range(0, Function.Blocks.Length)
                .Select(_ => new HashSet<int>())
                .ToArray();
            bool Changed;
            do
            {
                Changed = false;
                for (var Blockˉindex = Function.Blocks.Length - 1; Blockˉindex >= 0; Blockˉindex--)
                {
                    var Newˉout = new HashSet<int>();
                    foreach (var Successor in Successors[Blockˉindex])
                    {
                        Newˉout.UnionWith(Liveˉin[Successor]);
                    }
                    var Newˉin = new HashSet<int>(Newˉout);
                    Newˉin.ExceptWith(Definitions[Blockˉindex]);
                    Newˉin.UnionWith(Uses[Blockˉindex]);
                    if (!Newˉout.SetEquals(Liveˉout[Blockˉindex]) ||
                        !Newˉin.SetEquals(Liveˉin[Blockˉindex]))
                    {
                        Liveˉout[Blockˉindex] = Newˉout;
                        Liveˉin[Blockˉindex] = Newˉin;
                        Changed = true;
                    }
                }
            }
            while (Changed);

            void Requireˉlocalˉseparation(HashSet<int> live)
            {
                foreach (var Local in live)
                {
                    True(
                        Plan.Localˉrecordˉfieldˉoffsets[Local] >= 0,
                        "A live record local omitted its persistent offset.");
                }
                var Ordered = live.Order().ToArray();
                for (var Left = 0; Left < Ordered.Length; Left++)
                {
                    for (var Right = Left + 1; Right < Ordered.Length; Right++)
                    {
                        True(
                            !Nativeˉstorageˉrangesˉoverlap(
                                Plan.Localˉrecordˉfieldˉoffsets[Ordered[Left]],
                                Localˉwidth(Ordered[Left]),
                                Plan.Localˉrecordˉfieldˉoffsets[Ordered[Right]],
                                Localˉwidth(Ordered[Right])),
                            "Simultaneously live record locals share persistent storage.");
                    }
                }
            }

            for (var Blockˉindex = 0; Blockˉindex < Function.Blocks.Length; Blockˉindex++)
            {
                var Live = new HashSet<int>(Liveˉout[Blockˉindex]);
                Requireˉlocalˉseparation(Live);
                var Operations = Function.Blocks[Blockˉindex].Operations;
                for (var Operationˉindex = Operations.Length - 1; Operationˉindex >= 0; Operationˉindex--)
                {
                    switch (Operations[Operationˉindex])
                    {
                        case Nativeˉlocalˉstore Store when Isˉbackedˉrecordˉlocal(Store.Local):
                            Live.Remove(Store.Local);
                            break;
                        case Nativeˉlocalˉload Load when Isˉbackedˉrecordˉlocal(Load.Local):
                            Live.Add(Load.Local);
                            break;
                    }
                    Requireˉlocalˉseparation(Live);
                }
            }

            var Maximumˉscratchˉend = Plan.Scratchˉrecordˉbaseˉcell;
            for (var Value = 0; Value < Function.Valueˉtypes.Length; Value++)
            {
                var Offset = Plan.Valueˉrecordˉfieldˉoffsets[Value];
                if (Function.Valueˉtypes[Value] != Nativeˉvalueˉtype.Record)
                {
                    Equal(-1, Offset);
                    continue;
                }
                True(
                    Offset >= Plan.Scratchˉrecordˉbaseˉcell,
                    "Native record-result storage begins before its scratch region.");
                var End = checked(
                    Offset + Nativeˉtestˉrecordˉwidth(
                        module,
                        Function.Valueˉnominalˉtypeˉindices[Value]));
                True(
                    End <= checked(
                        Plan.Scratchˉrecordˉbaseˉcell +
                        Plan.Scratchˉrecordˉfieldˉcells),
                    "Native record-result storage exceeds its scratch region.");
                Maximumˉscratchˉend = Math.Max(Maximumˉscratchˉend, End);
            }
            Equal(
                Plan.Scratchˉrecordˉfieldˉcells,
                checked(Maximumˉscratchˉend - Plan.Scratchˉrecordˉbaseˉcell));

            var Definedˉrecordˉvalues = new HashSet<int>();
            foreach (var Block in Function.Blocks)
            {
                var Lastˉuses = new Dictionary<int, int>();
                for (var Operationˉindex = 0;
                    Operationˉindex < Block.Operations.Length;
                    Operationˉindex++)
                {
                    foreach (var Value in Nativeˉtestˉrecordˉuses(
                        Function,
                        Block.Operations[Operationˉindex]))
                    {
                        Lastˉuses[Value] = Operationˉindex;
                    }
                }
                foreach (var Value in Nativeˉtestˉrecordˉuses(Function, Block.Terminator))
                {
                    Lastˉuses[Value] = Block.Operations.Length;
                }

                var Live = new HashSet<int>();
                for (var Operationˉindex = 0;
                    Operationˉindex < Block.Operations.Length;
                    Operationˉindex++)
                {
                    var Operation = Block.Operations[Operationˉindex];
                    var Result = Nativeˉtestˉrecordˉresult(Function, Operation);
                    if (Result >= 0)
                    {
                        True(
                            Definedˉrecordˉvalues.Add(Result),
                            "Native record result is defined more than once.");
                        foreach (var Other in Live)
                        {
                            True(
                                !Nativeˉstorageˉrangesˉoverlap(
                                    Plan.Valueˉrecordˉfieldˉoffsets[Result],
                                    Nativeˉtestˉrecordˉvalueˉwidth(module, Function, Result),
                                    Plan.Valueˉrecordˉfieldˉoffsets[Other],
                                    Nativeˉtestˉrecordˉvalueˉwidth(module, Function, Other)),
                                "Simultaneously live record results share scratch storage.");
                        }
                        Live.Add(Result);
                    }

                    foreach (var Value in Nativeˉtestˉrecordˉuses(Function, Operation).Distinct())
                    {
                        True(Live.Contains(Value), "Native record operand is not live at its use.");
                        if (Lastˉuses[Value] == Operationˉindex)
                        {
                            Live.Remove(Value);
                        }
                    }
                    if (Result >= 0 && !Lastˉuses.ContainsKey(Result))
                    {
                        Live.Remove(Result);
                    }
                }

                foreach (var Value in Nativeˉtestˉrecordˉuses(Function, Block.Terminator))
                {
                    True(Live.Contains(Value), "Native record return is not live at its terminator.");
                    Live.Remove(Value);
                }
                Equal(0, Live.Count);
            }
            Equal(
                Function.Valueˉtypes.Count(Type => Type == Nativeˉvalueˉtype.Record),
                Definedˉrecordˉvalues.Count);
        }
    }

    private static int Nativeˉtestˉrecordˉresult(
        Nativeˉfunction function,
        Nativeˉoperation operation)
    {
        var Result = operation switch
        {
            Nativeˉlocalˉload Load => Load.Result,
            Nativeˉrecordˉcreate Create => Create.Result,
            Nativeˉrecordˉfield Field => Field.Result,
            Nativeˉcall Call => Call.Result,
            _ => -1,
        };
        return Result >= 0 && function.Valueˉtypes[Result] == Nativeˉvalueˉtype.Record
            ? Result
            : -1;
    }

    private static IEnumerable<int> Nativeˉtestˉrecordˉuses(
        Nativeˉfunction function,
        Nativeˉoperation operation)
    {
        IEnumerable<int> Values = operation switch
        {
            Nativeˉlocalˉstore Store => [Store.Value],
            Nativeˉrecordˉcreate Create => Create.Fields,
            Nativeˉrecordˉfield Field => [Field.Record],
            Nativeˉcall Call => Call.Arguments,
            Nativeˉvoidˉcall Call => Call.Arguments,
            _ => [],
        };
        return Values.Where(Value => function.Valueˉtypes[Value] == Nativeˉvalueˉtype.Record);
    }

    private static IEnumerable<int> Nativeˉtestˉrecordˉuses(
        Nativeˉfunction function,
        Nativeˉterminator terminator) =>
        terminator is Nativeˉreturn Return &&
            function.Valueˉtypes[Return.Value] == Nativeˉvalueˉtype.Record
                ? [Return.Value]
                : [];

    private static int Nativeˉtestˉrecordˉvalueˉwidth(
        Nativeˉmodule module,
        Nativeˉfunction function,
        int value) =>
        Nativeˉtestˉrecordˉwidth(
            module,
            function.Valueˉnominalˉtypeˉindices[value]);

    private static int Nativeˉtestˉrecordˉwidth(
        Nativeˉmodule module,
        int typeˉindex) =>
        ((Recordˉtypeˉdeclaration)module.Types[typeˉindex]).Fields.Length;

    private static bool Nativeˉstorageˉrangesˉoverlap(
        int leftˉoffset,
        int leftˉwidth,
        int rightˉoffset,
        int rightˉwidth) =>
        leftˉwidth > 0 &&
        rightˉwidth > 0 &&
        leftˉoffset < checked(rightˉoffset + rightˉwidth) &&
        rightˉoffset < checked(leftˉoffset + leftˉwidth);

    private static string Nativeˉrecordˉstorageˉdigest(
        ImmutableArray<Nativeˉfunctionˉrecordˉstorage> storage)
    {
        using var Hash = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
        foreach (var Function in storage)
        {
            Appendˉi32(Hash, Function.Functionˉindex);
            var Name = Encoding.UTF8.GetBytes(Function.Functionˉname);
            Appendˉi32(Hash, Name.Length);
            Hash.AppendData(Name);
            Appendˉi32(Hash, Function.Existingˉframeˉcells);
            Appendˉi32(Hash, Function.Recordˉparameterˉbindings);
            Appendˉi32(Hash, Function.Assignedˉrecordˉparameterˉbindings);
            Appendˉi32(Hash, Function.Recordˉlocalˉbindings);
            Appendˉi32(Hash, Function.Declaredˉrecordˉlocalˉfieldˉcells);
            Appendˉi32(Hash, Function.Persistentˉrecordˉbaseˉcell);
            Appendˉi32(Hash, Function.Persistentˉrecordˉfieldˉcells);
            Appendˉoffsets(Hash, Function.Localˉrecordˉfieldˉoffsets);
            Appendˉi32(Hash, Function.Recordˉvalueˉidentifiers);
            Appendˉi32(Hash, Function.Recordˉvalueˉslots);
            Appendˉi32(Hash, Function.Blockˉrecordˉfieldˉcells);
            Appendˉi32(Hash, Function.Peakˉliveˉrecordˉfieldˉcells);
            Appendˉi32(Hash, Function.Scratchˉrecordˉbaseˉcell);
            Appendˉi32(Hash, Function.Scratchˉrecordˉfieldˉcells);
            Appendˉoffsets(Hash, Function.Valueˉrecordˉfieldˉoffsets);
            Appendˉi32(Hash, Function.Returnsˉrecord ? 1 : 0);
            Appendˉi32(Hash, Function.Recordˉreturnˉfieldˉcells);
            Appendˉi32(Hash, Function.Recordˉreturnˉpointerˉcell);
            Appendˉi32(Hash, Function.Projectedˉframeˉcells);
            Appendˉi32(Hash, Function.Maximumˉrecordˉfieldˉcells);
            Appendˉi32(Hash, Function.Containsˉnestedˉrecordˉfields ? 1 : 0);
        }
        return Convert.ToHexString(Hash.GetHashAndReset()).ToLowerInvariant();
    }

    private static string Nativeˉdescriptorˉownershipˉdigest(
        Nativeˉdescriptorˉownershipˉplan plan)
    {
        using var Hash = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
        Appendˉi32(Hash, checked((int)plan.Formatˉversion));
        Appendˉi32(Hash, plan.Terminalˉfailureˉdiscardsˉarena ? 1 : 0);
        Appendˉi32(Hash, plan.Totalˉactions);
        Appendˉi32(Hash, plan.Functions.Length);
        foreach (var Function in plan.Functions)
        {
            Appendˉi32(Hash, Function.Functionˉindex);
            var Name = Encoding.UTF8.GetBytes(Function.Functionˉname);
            Appendˉi32(Hash, Name.Length);
            Hash.AppendData(Name);
            Appendˉi32(Hash, Function.Descriptorˉparameterˉbindings);
            Appendˉi32(Hash, Function.Assignedˉdescriptorˉparameterˉbindings);
            Appendˉi32(Hash, Function.Descriptorˉlocalˉbindings);
            Appendˉi32(Hash, Function.Recordˉparameterˉdescriptorˉfields);
            Appendˉi32(Hash, Function.Assignedˉrecordˉparameterˉdescriptorˉfields);
            Appendˉi32(Hash, Function.Recordˉlocalˉdescriptorˉfields);
            Appendˉi32(Hash, Function.Descriptorˉvalueˉidentifiers);
            Appendˉi32(Hash, Function.Recordˉvalueˉdescriptorˉfields);
            Appendˉi32(Hash, Function.Acquireˉactions);
            Appendˉi32(Hash, Function.Borrowˉactions);
            Appendˉi32(Hash, Function.Retainˉactions);
            Appendˉi32(Hash, Function.Releaseˉactions);
            Appendˉi32(Hash, Function.Callˉborrowˉactions);
            Appendˉi32(Hash, Function.Acceptedˉreturnˉactions);
            Appendˉi32(Hash, Function.Transferredˉreturnˉactions);
            Appendˉi32(Hash, Function.Actions.Length);
            foreach (var Action in Function.Actions)
            {
                Appendˉi32(Hash, Action.Block);
                Appendˉi32(Hash, Action.Operation);
                Appendˉi32(Hash, (int)Action.Kind);
                Appendˉdescriptorˉcarrier(Hash, Action.Target);
                Appendˉdescriptorˉcarrier(Hash, Action.Source);
            }
        }
        return Convert.ToHexString(Hash.GetHashAndReset()).ToLowerInvariant();
    }

    private static string Nativeˉdescriptorˉallocatorˉemissionˉdigest(
        Nativeˉdescriptorˉallocatorˉemissionˉplan plan)
    {
        using var Hash = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
        Appendˉi32(Hash, checked((int)plan.Formatˉversion));
        Appendˉi32(Hash, checked((int)plan.Candidateˉcontextˉformatˉversion));
        Appendˉi32(Hash, checked((int)plan.Candidateˉcontextˉsize));
        Appendˉi32(Hash, plan.Allocatorˉstateˉpointerˉoffset);
        Appendˉi32(Hash, plan.Allocatorˉleafˉpointerˉoffset);
        Appendˉi32(Hash, plan.Requestˉframeˉcells);
        Appendˉi32(Hash, plan.Ownershipˉactions);
        Appendˉi32(Hash, plan.Allocatorˉleafˉinvocations);
        Appendˉi32(Hash, plan.Ownershipˉmovementˉactions);
        Appendˉi32(Hash, plan.Functions.Length);
        foreach (var Function in plan.Functions)
        {
            Appendˉi32(Hash, Function.Functionˉindex);
            var Name = Encoding.UTF8.GetBytes(Function.Functionˉname);
            Appendˉi32(Hash, Name.Length);
            Hash.AppendData(Name);
            Appendˉi32(Hash, Function.Ownershipˉactions);
            Appendˉi32(Hash, Function.Allocatorˉleafˉinvocations);
            Appendˉi32(Hash, Function.Generatedˉcodeˉinvocations);
            Appendˉi32(Hash, Function.Runtimeˉserviceˉinvocations);
            Appendˉi32(Hash, Function.Requestˉbaseˉcell);
            Appendˉi32(Hash, Function.Existingˉframeˉcells);
            Appendˉi32(Hash, Function.Projectedˉframeˉcells);
            Appendˉi32(Hash, Function.Preservesˉinstructionˉbudget ? 1 : 0);
            Appendˉi32(Hash, Function.Preservesˉcallˉdepth ? 1 : 0);
            Appendˉi32(Hash, Function.Emissions.Length);
            foreach (var Emission in Function.Emissions)
            {
                Appendˉi32(Hash, Emission.Ownershipˉactionˉindex);
                Appendˉi32(Hash, Emission.Block);
                Appendˉi32(Hash, Emission.Operation);
                Appendˉi32(Hash, (int)Emission.Ownershipˉkind);
                Appendˉi32(Hash, (int)Emission.Allocatorˉoperation);
                Appendˉi32(Hash, (int)Emission.Phase);
                Appendˉi32(Hash, (int)Emission.Invocationˉsite);
                Appendˉdescriptorˉownerˉlocation(Hash, Emission.Target);
                Appendˉdescriptorˉownerˉlocation(Hash, Emission.Source);
            }
        }
        return Convert.ToHexString(Hash.GetHashAndReset()).ToLowerInvariant();
    }

    private static void Appendˉdescriptorˉownerˉlocation(
        IncrementalHash hash,
        Nativeˉdescriptorˉownerˉlocation location)
    {
        Appendˉi32(hash, (int)location.Addressing);
        Appendˉi32(hash, location.Baseˉframeˉcell);
        Appendˉi32(hash, location.Ownerˉbyteˉdisplacement);
    }

    private static void Appendˉdescriptorˉcarrier(
        IncrementalHash hash,
        Nativeˉdescriptorˉcarrier carrier)
    {
        Appendˉi32(hash, (int)carrier.Kind);
        Appendˉi32(hash, carrier.Function);
        Appendˉi32(hash, carrier.Binding);
        Appendˉi32(hash, carrier.Field);
    }

    private static void Appendˉoffsets(
        IncrementalHash hash,
        ImmutableArray<int> offsets)
    {
        Appendˉi32(hash, offsets.Length);
        foreach (var Offset in offsets)
        {
            Appendˉi32(hash, Offset);
        }
    }

    private static void Appendˉi32(IncrementalHash hash, int value)
    {
        Span<byte> Bytes = stackalloc byte[sizeof(int)];
        BinaryPrimitives.WriteInt32LittleEndian(Bytes, value);
        hash.AppendData(Bytes);
    }

    private sealed class Nativeˉoutputˉcapture : IDisposable
    {
        private readonly string Pathˉname;
        private readonly FileStream Stream;
        private bool Isˉdisposed;

        public Nativeˉoutputˉcapture()
        {
            Pathˉname = Path.Combine(
                Path.GetTempPath(),
                $"windvale-native-output-{Guid.NewGuid():N}.tmp");
            Stream = new FileStream(
                Pathˉname,
                FileMode.CreateNew,
                FileAccess.ReadWrite,
                FileShare.ReadWrite | FileShare.Delete);
            Channel = Nativeˉoutputˉchannel.Fromˉfileˉhandle(Stream.SafeFileHandle);
        }

        public Nativeˉoutputˉchannel Channel { get; }

        public string Readˉtext()
        {
            Stream.Flush(flushToDisk: true);
            Stream.Position = 0;
            var Bytes = new byte[checked((int)Stream.Length)];
            Stream.ReadExactly(Bytes);
            Stream.Position = Stream.Length;
            return new System.Text.UTF8Encoding(
                encoderShouldEmitUTF8Identifier: false,
                throwOnInvalidBytes: true).GetString(Bytes);
        }

        public void Dispose()
        {
            if (Isˉdisposed)
            {
                return;
            }
            Isˉdisposed = true;
            Stream.Dispose();
            File.Delete(Pathˉname);
        }
    }

    private sealed class Failingˉtextˉwriter : TextWriter
    {
        public override System.Text.Encoding Encoding => System.Text.Encoding.UTF8;

        public override void Write(string? value) =>
            throw new IOException("Deliberate output failure.");
    }

    private static void Writeˉreport(string path)
    {
        var Report = new Conformanceˉreport(
            Contract ?? throw new InvalidOperationException("The golden contract test did not run."),
            new(
                Getˉosˉfamily(),
                RuntimeInformation.OSDescription,
                RuntimeInformation.OSArchitecture.ToString(),
                RuntimeInformation.FrameworkDescription));
        var Options = new JsonSerializerOptions
        {
            PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
            WriteIndented = true,
        };
        var Fullˉpath = Path.GetFullPath(path);
        Directory.CreateDirectory(Path.GetDirectoryName(Fullˉpath)!);
        File.WriteAllText(Fullˉpath, JsonSerializer.Serialize(Report, Options) + Environment.NewLine);
        Console.WriteLine($"Conformance report: {Fullˉpath}");
    }

    private static void Writeˉtimingˉreport(
        string path,
        string? filter,
        ImmutableHashSet<string> areas,
        bool failˉfast,
        bool excludeˉextended,
        int extendedˉexcluded,
        int selected,
        long elapsedˉmilliseconds,
        List<Testˉtimingˉentry> tests)
    {
        Validateˉgoldenˉphaseˉtimings(tests);
        var Report = new Testˉtimingˉreport(
            filter,
            [.. areas.Order(StringComparer.Ordinal)],
            failˉfast,
            excludeˉextended,
            extendedˉexcluded,
            selected,
            tests.Count,
            elapsedˉmilliseconds,
            tests,
            [.. GOLDEN_PHASE_TIMINGS]);
        var Options = new JsonSerializerOptions { WriteIndented = true };
        var Fullˉpath = Path.GetFullPath(path);
        Directory.CreateDirectory(Path.GetDirectoryName(Fullˉpath)!);
        File.WriteAllText(Fullˉpath, JsonSerializer.Serialize(Report, Options) + Environment.NewLine);
        Console.WriteLine($"Timing report: {Fullˉpath}");
    }

    private static void Validateˉgoldenˉphaseˉtimings(List<Testˉtimingˉentry> tests)
    {
        var Goldenˉtest = tests.SingleOrDefault(
            Test => StringComparer.Ordinal.Equals(Test.Name, GOLDEN_TEST_NAME));
        if (Goldenˉtest is null)
        {
            if (GOLDEN_PHASE_TIMINGS.Count != 0)
            {
                throw new InvalidOperationException(
                    "Golden phase timings were recorded without executing the golden test.");
            }

            return;
        }

        if (
            GOLDEN_PHASE_TIMINGS.Count > GOLDEN_PHASE_NAMES.Length ||
            !GOLDEN_PHASE_TIMINGS
                .Select(Phase => Phase.Name)
                .SequenceEqual(GOLDEN_PHASE_NAMES.Take(GOLDEN_PHASE_TIMINGS.Count), StringComparer.Ordinal)
        )
        {
            throw new InvalidOperationException("Golden phase timings are incomplete or out of canonical order.");
        }

        if (Goldenˉtest.Outcome == "passed" && GOLDEN_PHASE_TIMINGS.Count != GOLDEN_PHASE_NAMES.Length)
        {
            throw new InvalidOperationException("A passing golden test did not record every timing phase.");
        }

        if (GOLDEN_PHASE_TIMINGS.Any(Phase =>
            Phase.Elapsedˉmilliseconds < 0 ||
            Phase.Executedˉinstructions < 0 ||
            Phase.Allocatedˉbytes < 0 ||
            Phase.Generation0ˉcollections < 0 ||
            Phase.Generation1ˉcollections < 0 ||
            Phase.Generation2ˉcollections < 0))
        {
            throw new InvalidOperationException("Golden phase timings contain a negative metric.");
        }
    }

    private static int Compareˉreports(string firstˉpath, string secondˉpath)
    {
        var Options = new JsonSerializerOptions { PropertyNameCaseInsensitive = true };
        var First = JsonSerializer.Deserialize<Conformanceˉreport>(File.ReadAllText(firstˉpath), Options)
            ?? throw new InvalidOperationException("The first report is invalid.");
        var Second = JsonSerializer.Deserialize<Conformanceˉreport>(File.ReadAllText(secondˉpath), Options)
            ?? throw new InvalidOperationException("The second report is invalid.");
        if (First.Contract != Second.Contract)
        {
            Console.Error.WriteLine("Cross-host conformance contracts differ.");
            Console.Error.WriteLine($"First:  {JsonSerializer.Serialize(First.Contract)}");
            Console.Error.WriteLine($"Second: {JsonSerializer.Serialize(Second.Contract)}");
            return 1;
        }

        var Hostˉfamilies = new HashSet<string>(StringComparer.Ordinal)
        {
            First.Host.Operatingˉsystemˉfamily,
            Second.Host.Operatingˉsystemˉfamily,
        };
        if (!Hostˉfamilies.SetEquals(["windows", "linux"]))
        {
            Console.Error.WriteLine(
                "Cross-host comparison requires one Windows report and one Linux report.");
            return 1;
        }

        Console.WriteLine("Cross-host conformance contracts match.");
        Console.WriteLine($"First host:  {First.Host.Operatingˉsystem} / {First.Host.Architecture}");
        Console.WriteLine($"Second host: {Second.Host.Operatingˉsystem} / {Second.Host.Architecture}");
        return 0;
    }

    private static string Getˉosˉfamily()
    {
        if (RuntimeInformation.IsOSPlatform(OSPlatform.Windows))
        {
            return "windows";
        }

        if (RuntimeInformation.IsOSPlatform(OSPlatform.Linux))
        {
            return "linux";
        }

        return "other";
    }

    private static void Equal<T>(T expected, T actual)
    {
        if (!EqualityComparer<T>.Default.Equals(expected, actual))
        {
            throw new InvalidOperationException($"Expected '{expected}', found '{actual}'.");
        }
    }

    private static void Sequenceˉequal<T>(IEnumerable<T> expected, IEnumerable<T> actual)
    {
        if (!expected.SequenceEqual(actual))
        {
            throw new InvalidOperationException(
                $"Sequences differ. Expected [{string.Join(", ", expected)}], " +
                $"found [{string.Join(", ", actual)}].");
        }
    }

    private static void Contains(string value, string expectedˉfragment)
    {
        if (!value.Contains(expectedˉfragment, StringComparison.Ordinal))
        {
            throw new InvalidOperationException($"Text does not contain '{expectedˉfragment}'.");
        }
    }

    private static string Readˉembeddedˉsource(string name)
    {
        using var Stream = typeof(Program).Assembly.GetManifestResourceStream(name)
            ?? throw new InvalidOperationException($"Embedded source '{name}' was not found.");
        using var Reader = new StreamReader(Stream);
        return Reader.ReadToEnd();
    }

    private static void True(bool condition, string message)
    {
        if (!condition)
        {
            throw new InvalidOperationException(message);
        }
    }

    private static void False(bool condition, string message)
    {
        True(!condition, message);
    }

